/* MADRE — a conversation, not a log.
   iMessage for the dialogue, a terminal for the metadata, MOTHER for the mood. */

/* The brand's two typefaces, from the brand kit (SIL OFL 1.1; licences in /assets/brand). Sora for
   what is read, JetBrains Mono for labels, data and commands. Served by this room, never fetched. */
@font-face { font-family: 'Sora'; font-style: normal; font-weight: 300 800; font-display: swap; src: url('/assets/brand/Sora-latin.woff2') format('woff2'); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: 'Sora'; font-style: normal; font-weight: 300 800; font-display: swap; src: url('/assets/brand/Sora-latin-ext.woff2') format('woff2'); unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF; }
/* Geist, the reading face: what the crew and the human say, and the chips that quote it. Sora is
   wide and its paragraphs read heavy; Geist keeps the same round geometry about 10% narrower. */
@font-face { font-family: 'Geist'; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/assets/brand/Geist-latin.woff2') format('woff2'); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: 'Geist'; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/assets/brand/Geist-latin-ext.woff2') format('woff2'); unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF; }
@font-face { font-family: 'JetBrains Mono'; font-style: normal; font-weight: 400 700; font-display: swap; src: url('/assets/brand/JetBrainsMono-latin.woff2') format('woff2'); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: 'JetBrains Mono'; font-style: normal; font-weight: 400 700; font-display: swap; src: url('/assets/brand/JetBrainsMono-latin-ext.woff2') format('woff2'); unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF; }
/* Geist Mono, the room's labels, chips, lines and code: Geist's own mono, round where JetBrains is
   square, so the small print reads like the same hand as the answers it sits beside. JetBrains
   Mono stays the voice of the ship's terminal, MU/TH/UR and NOSTROMO. */
@font-face { font-family: 'Geist Mono'; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/assets/brand/GeistMono-latin.woff2') format('woff2'); unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD; }
@font-face { font-family: 'Geist Mono'; font-style: normal; font-weight: 100 900; font-display: swap; src: url('/assets/brand/GeistMono-latin-ext.woff2') format('woff2'); unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF; }

:root {
  color-scheme: dark;
  --sans: "Sora", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --mono: "Geist Mono", "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  /* Reading: messages, answers, the chips that quote them and the line you write on. 15 px, 300. */
  --read: "Geist", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --read-weight: 300;
  font-family: var(--sans);
  /* The logo's two inks (brand kit §3.3): the pulse is phosphor, the word is white. On light
     backgrounds the kit's light version: a darker green and near-black letters. */
  --brand-pulse: #9bff66;
  --brand-word: #eef1ea;

  --bg: #050605;
  --bg-2: #0b0d0b;
  --panel: #101310;
  --panel-2: #171b17;
  --line: rgba(255, 255, 255, .07);
  --line-2: rgba(255, 255, 255, .13);
  --text: #eef1ea;
  --text-2: #9aa197;
  --text-3: #626a5f;

  --phosphor: #9bff66;           /* MOTHER */
  /* MADRE's own green, which an accent never repaints: the copilot wears it (2026-10-14). */
  --madre-green: #9bff66;
  --madre-green-ink: #0a1405;
  --brew: #28fe14;               /* Terminal.app 'Homebrew' green */
  --brew-ink: #041004;
  --phosphor-ink: #0a1405;
  --accent: var(--phosphor);
  --accent-ink: var(--phosphor-ink);

  --bubble: #1c201c;             /* agent bubble */
  --bubble-ink: #eef1ea;
  --user: var(--phosphor);       /* user bubble */
  --user-ink: var(--phosphor-ink);

  --danger: #ff7b72;
  --warn: #ffd166; --warn-ink: #1a1403;
  --crit: #ff8a7a;
  --terror: #ff2a1f;             /* MOTHER, when she stops being polite */
  --shadow: 0 1px 0 rgba(255,255,255,.03) inset, 0 12px 40px rgba(0,0,0,.45);
  /* Depth without neon. Elevation is a neutral shadow; colour only rings an edge, thin and low.
     --glow-a caps the alpha of the few coloured halos that carry meaning (live, active, armed). */
  --lift-1: 0 1px 2px rgba(0,0,0,.32), 0 3px 10px rgba(0,0,0,.22);
  --ring-soft: 0 0 0 3px color-mix(in srgb, var(--phosphor) 12%, transparent);
  --glow-a: 18%;

  /* Permission modes: one colour each, read by the chip, the field, the send button and the menu. */
  --mode-0: #8d978c; --mode-0-ink: #0b0d0b;        /* GHOST · smoke */
  --mode-1: var(--phosphor); --mode-1-ink: var(--phosphor-ink);   /* EXCHANGE · phosphor */
  --mode-2: #ffb000; --mode-2-ink: #1a1000;        /* CREATE · amber phosphor */
  --mode-3: var(--terror); --mode-3-ink: #fff3f1;  /* CONTROL · the red screen */
  --mode-4: #8fd3ff; --mode-4-ink: #04131c;        /* AIRLOCK · the cold outside */
  --module-electric: #b44cff; --module-electric-ink: #12001d; /* MODULE · MADRE electric purple */

  /* Motion: one curve and three lengths for everything that answers a hand — fast out, soft in. */
  --ease-out: cubic-bezier(.2, .8, .2, 1);
  /* The motion engine's one dial. Every transition and every arrival or departure of the interface
     is written at its old length and multiplied by this, so the room moves quicker as one, with the
     same curves: fast, never abrupt. Brand moments (MOTHER switching on, the logo's beat, a cursor
     blinking, the red screen) keep their own time. app.js reads the same dial (motion()). */
  --motion-scale: .7;
  --motion-fast: calc(160ms * var(--motion-scale));
  --motion: calc(220ms * var(--motion-scale));
  --motion-slow: calc(280ms * var(--motion-scale));
  /* What moves the room itself — a panel arriving, the column making way, a conversation taking
     the place of another — glides longer, on a curve that settles instead of stopping. */
  --glide: calc(380ms * var(--motion-scale));
  --ease-glide: cubic-bezier(.22, 1, .36, 1);
  --ease-leave: cubic-bezier(.4, 0, 1, 1);
  /* The icons' one hand: the stroke at rest, under the pointer, and when what it opens is open. */
  --icon-stroke: 1.6;
  --icon-stroke-hover: 1.8;
  --icon-stroke-on: 2.05;
  /* The icons' sizes (1.0.3): four, and which one a drawing takes is said by what holds it, never
     by the drawing. A mark inside a pill, a tab or a badge (×, ⌄, ✓); a key of 22 to 30 px, or a
     drawing beside a word; a square key of 34 px (the narrow bar, the house's keys, the box); a
     round key that floats (40 to 44 px). */
  --ico-xs: 12px;
  --ico-sm: 15px;
  --ico-md: 18px;
  --ico-lg: 22px;
}
/* Reading code, in whichever ground the room is standing on. These were picked for phosphor on
   black; on white the same green and yellow disappear, so each one has a light value of its own. */
:root {
  --syn-keyword: #9bb8ff;
  --syn-string: #9bff66;
  --syn-comment: color-mix(in srgb, var(--text-3) 88%, transparent);
  --syn-number: #ffd166;
  --syn-literal: #ff9ecd;
  --syn-regex: #7ce0d3;
}

