* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { height: 100%; }
body {
  margin: 0;
  color: var(--text);
  background:
    linear-gradient(rgba(155,255,102,.035) 1px, transparent 1px) 0 0 / 100% 3px,
    radial-gradient(ellipse at 50% -20%, var(--bg-2), var(--bg) 55%);
  -webkit-font-smoothing: antialiased;
}
@media (prefers-color-scheme: light) { body { background: radial-gradient(ellipse at 50% -20%, var(--bg-2), var(--bg) 55%); } }

/* The rails: how much of each edge the column may not use. 20px of window gutter at rest; a
   docked panel's width and its gap beside it when one is open. They change in one step: the column
   takes its new width once, and the page draws it gliding from where it stood (layoutPanels). An
   animated width re-wrapped every line of the thread on every frame, which is what made the
   bubbles shiver while a panel slid in. */

.shell {
  --rail-l: 20px;
  --rail-r: 20px;
  --column: min(960px, 100% - var(--rail-l) - var(--rail-r));
  /* Centred in the window while it can be; pushed off-centre only as far as a rail asks. */
  --column-left: clamp(var(--rail-l), (100% - var(--column)) / 2, 100% - var(--column) - var(--rail-r));
  --wide-column: min(1180px, 100% - var(--rail-l) - var(--rail-r));
  --wide-left: clamp(var(--rail-l), (100% - var(--wide-column)) / 2, 100% - var(--wide-column) - var(--rail-r));

  --gap: 12px;
  height: 100dvh;
  width: 100%;
  display: grid;
  /* A track that can shrink. Without it the one implicit column is as wide as its widest child's
     content, and on a phone the composer's chip row made the whole page 580px wide — the bar on
     top, the thread and every bubble with it. */
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto 1fr auto auto auto auto;
}
.bar, .onboarding, .composer, .safety, .colophon, .thread-inner { width: var(--column); margin-left: auto; margin-right: auto; }
.onboarding, .composer, .safety, .colophon, .thread-inner { margin-left: var(--column-left); margin-right: 0; }
/* The bar is the ship's console: wider than the thread so the project root, the crew and the alerts share one line. */
.shell > .bar { width: min(1440px, 100% - 40px); }
.shell > .bar { grid-row: 1; } .shell > .onboarding { grid-row: 2; } .shell > .thread { grid-row: 3; } .shell > .composer { grid-row: 4; } .shell > .safety { grid-row: 5; } .shell > .colophon { grid-row: 6; }
.shell > .bar, .shell > .onboarding, .shell > .thread, .shell > .composer, .shell > .safety, .shell > .colophon, .shell > .tree, .shell > .chats-button { grid-column: 1; }
.visually-hidden { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* ================= bar ================= */
.bar {
  display: flex; align-items: center; gap: 18px; min-width: 0;
  padding: 18px 0 14px;
  border-bottom: 1px solid var(--line);
  font-family: var(--mono); font-size: 11px; letter-spacing: .04em;
  color: var(--text-2);
}
.bar-left { display: flex; align-items: center; gap: 14px; min-width: 0; flex: 1 1 auto; }
.bar-left .project + .project { margin-left: -6px; }
.brand { display: flex; align-items: center; text-decoration: none; cursor: pointer; }
/* The kit's horizontal logo, its geometry untouched: pulse and word in one drawing, at the kit's
   own proportion. No glow, no recolouring of the letters (kit §3.5). It still draws itself in once. */
/* 16 px tall puts the word's capitals at the height of the bar's own labels, so the logo sits in
   the row instead of shouting over it. The kit's proportions are untouched; only the size. */
.brand-logo { display: block; height: 16px; width: auto; overflow: visible; }
.brand-icon { display: none; height: 16px; width: auto; overflow: visible; }
.brand-icon .pulse { stroke: var(--brand-pulse); }
.brand-icon .pulse .beat-dot { fill: var(--brand-pulse); }
.brand-logo .pulse { stroke: var(--brand-pulse); }
.brand-logo .pulse .beat-dot { fill: var(--brand-pulse); }
.brand-logo .word { stroke: var(--brand-word); }
.brand-logo .beat { stroke-dasharray: 100; stroke-dashoffset: 100; animation: beat-draw 1.1s cubic-bezier(.2, .7, .2, 1) .15s forwards; }
.brand-logo .beat-dot { opacity: 0; transform-origin: center; transform-box: fill-box; animation: beat-dot 1s ease-out 1.05s forwards; }
/* Opacity only: a CSS transform here would replace the word's own placement in the drawing. */
.brand-logo .word { opacity: 0; animation: logo-word-in .6s ease-out 1.35s forwards; }
@keyframes logo-word-in { to { opacity: 1; } }
@keyframes beat-draw { to { stroke-dashoffset: 0; } }
@keyframes beat-dot { 0% { opacity: 0; transform: scale(.2); } 35% { opacity: 1; transform: scale(1.9); } 100% { opacity: 1; transform: scale(1); } }
@keyframes beat-idle { 0%, 100% { opacity: 1; transform: scale(1); } 14% { transform: scale(1.35); } 28% { transform: scale(1); } 42% { transform: scale(1.2); } 56% { transform: scale(1); } }
@keyframes word-in { to { opacity: 1; transform: none; } }
:root.logo-still .brand-logo .beat { animation: none; stroke-dashoffset: 0; }
:root.logo-still .brand-logo .beat-dot, :root.logo-still .brand-logo .word { animation: none; opacity: 1; }
/* The page's own reload, for windows that show no browser chrome around the room. */
.reload-button svg { transition: transform var(--motion-slow) var(--ease-glide); }
.reload-button:hover svg { transform: rotate(-40deg); }
.reload-button:active svg { transform: rotate(-200deg); transition-duration: calc(90ms * var(--motion-scale)); }
@media (prefers-reduced-motion: reduce) {
  .brand-logo .beat { animation: none; stroke-dashoffset: 0; }
  .brand-logo .beat-dot { animation: none; opacity: 1; }
  .brand-logo .word { animation: none; opacity: 1; }
}
/* Two names sit here and only one of them tells you where you are. The project never gives way:
   a room whose project reads `pul…` has stopped saying which project it is. The conversation is
   the one that shrinks — it has a panel of its own where its whole name is written. */
.project { flex: 0 0 auto; max-width: 24ch; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-3); }
.project.chat-here { flex: 0 1 auto; min-width: 3ch; max-width: none; }
.mother-section.update .update-link { color: var(--ph); }
.update-link { display: inline-block; margin: 2px 0 8px; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--phosphor); }
.project::before { content: "/ "; }
/* 3px of ring on each side plus air between them: anything under 10px and the neighbours clip
   each other's arc. The padding is the same 3px, so the row's box contains the rings it draws —
   without it the first and last ring hang outside and collide with whatever sits beside them. */
.agents { display: flex; gap: 12px; padding: 0 3px; margin-left: 0; flex: none; }
.connection { display: inline-flex; flex: 0 0 auto; white-space: nowrap; align-items: center; gap: 6px; color: var(--text-3); text-transform: uppercase; font-size: 10px; }
.connection-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--text-3); }
.connection[data-state="live"] .connection-dot { background: var(--phosphor); box-shadow: 0 0 0 2px color-mix(in srgb, var(--phosphor) var(--glow-a), transparent); }
.connection[data-state="reconnecting"] .connection-dot { background: var(--warn); animation: blink 1s infinite; }
@keyframes blink { 50% { opacity: .2; } }

/* ================= avatars ================= */
.avatar {
  --size: 28px; --pct: 0;
  position: relative; display: inline-grid; place-items: center;
  width: var(--size); height: var(--size); border-radius: 50%;
  color: var(--agent); background: color-mix(in srgb, var(--agent) 17%, transparent);
  flex: none;
}
.avatar svg { width: 58%; height: 58%; display: block; }
/* The ring is the agent's quota, drawn around it. Two things were wrong with it: it sits 3px
   outside the avatar's own box, so with a 6px gap the rings of neighbours overlapped and each
   arc came out flattened where the next one cut into it — the "cut bubbles" on screen. And the
   unused part of the arc was drawn in --line-2, a full-strength grey that outweighed the colour
   it was supposed to frame, so every agent read as a grey circle with a tint inside.

   Now the track is a whisper and the used arc is the only thing with weight. */
.avatar.ring::before {
  content: ""; position: absolute; inset: -3px; border-radius: 50%;
  background: conic-gradient(var(--agent) calc(var(--pct) * 1%), color-mix(in srgb, var(--text-3) 22%, transparent) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 2.5px), #000 calc(100% - 2px));
  mask: radial-gradient(farthest-side, transparent calc(100% - 2.5px), #000 calc(100% - 2px));
}
.avatar.ring.hot::before { background: conic-gradient(var(--crit) calc(var(--pct) * 1%), var(--line-2) 0); }
.avatar.offline { color: var(--text-3); background: transparent; border: 1px dashed var(--line-2); }
.avatar.detected { color: var(--text-2); background: transparent; border: 1px solid var(--line-2); }
.avatar.gradient svg { color: #fff; }
.avatar.gradient { background: var(--agent-gradient, var(--agent)); color: #fff; }
.agents .avatar { cursor: default; }

/* The spheres, in light mode. A tint of the agent's colour works on a near-black page because the
   colour is the only light in the circle; over a near-white page the same mix just walks back to
   the page. Measured: at 17% over #f4f5f2 the brightest agents came out at 1.06:1 and 1.03:1 —
   the disc was not faint, it was absent. Raising the percentage does not fix it either, because
   mixing a bright yellow into white stays white (40% only reached 1.17:1).

   So on light the disc keeps its tint and gains an edge and a glyph in the agent's colour taken
   DOWN instead of up. One colour, two directions, and every agent reads at its own hue. */
:root:not([data-theme="dark"]) .avatar:not(.gradient):not(.offline):not(.detected),
:root[data-theme="light"] .avatar:not(.gradient):not(.offline):not(.detected) {
  --agent-ink: color-mix(in srgb, var(--agent) 58%, #11210f);
  background: color-mix(in srgb, var(--agent) 22%, transparent);
  box-shadow: inset 0 0 0 1.5px var(--agent-ink);
  color: var(--agent-ink);
}

/* ================= thread ================= */
.thread {
  overflow-y: auto;
  scroll-behavior: smooth;
  overscroll-behavior: contain;
}
.thread-inner {
  min-height: 100%;
  display: flex; flex-direction: column; gap: var(--gap);
  padding: 36px 0 28px;
}
.empty { margin: auto; text-align: center; color: var(--text-3); display: grid; gap: 10px; max-width: 420px; justify-items: center; }
.empty-mark { width: 144px; height: 40px; color: var(--brand-pulse); margin-bottom: 6px; overflow: visible; }
.empty-mark .beat { stroke-dasharray: 100; stroke-dashoffset: 100; animation: beat-draw 1.1s cubic-bezier(.2, .7, .2, 1) .15s forwards; }
.empty-mark .beat-dot { opacity: 0; transform-origin: 60px 10px; transform-box: view-box; animation: beat-dot 1s ease-out 1.05s forwards, beat-idle 2.6s ease-in-out 2.4s infinite; }
.empty strong { color: var(--text); font-size: 17px; letter-spacing: -.01em; font-weight: 600; }
.empty span { font-size: 13px; line-height: 1.5; }
code { font-family: var(--mono); font-size: .9em; color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); padding: 2px 5px; border-radius: 5px; }

/* rows */
.row { display: grid; grid-template-columns: 28px 1fr; gap: 12px; align-items: end; max-width: 76%; margin-top: 14px; }
/* Wider for reading: a reply is most of what the room is for, and three quarters of the column
   broke its paragraphs and its code into a narrow strip. The column grew with it, and still gives
   way to the panels and to the window long before the bubble does. */
.row { max-width: min(88%, 860px); }
.row.compact { margin-top: 0; }
.row.compact .avatar { visibility: hidden; }
.row.user { grid-template-columns: 1fr; align-self: flex-end; justify-items: end; }
/* The column's one track never grows past the column: Safari sized an implicit track to a message's
   widest line (a table, a block of code) and the bubble ran past the screen, cut off (2026-10-11). */
.row .col { display: grid; grid-template-columns: minmax(0, 1fr); gap: 6px; min-width: 0; }
.who { font-family: var(--mono); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--agent, var(--text-2)); margin: 0 0 2px 12px; display: flex; gap: 10px; align-items: baseline; min-width: 0; }
/* The quoted line gives way first: the cost and who spoke are short and must not be pushed out. */
.who .reply { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.user .who { color: var(--text-3); margin: 0 12px 2px 0; justify-content: flex-end; }
.user .who b { color: var(--phosphor); font-weight: 600; }
.user.expendable .who b { color: var(--crit); }
.who .reply { color: var(--text-3); letter-spacing: 0; text-transform: none; font-style: italic; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 320px; }
.who .badge { color: var(--text-3); border: 1px solid var(--line-2); border-radius: 999px; padding: 1px 6px; letter-spacing: .08em; }

.bubble {
  position: relative;
  line-height: 1.5; font-size: 15px;
  color: var(--bubble-ink); background: var(--bubble);
  border-radius: 20px; padding: 12px 16px;
  overflow-wrap: anywhere;
  box-shadow: var(--lift-1);
}
.assistant .bubble { border-bottom-left-radius: 6px; }
.user .bubble { background: var(--user); color: var(--user-ink); border-bottom-right-radius: 6px; white-space: pre-wrap; box-shadow: var(--lift-1); }
.bubble > :first-child { margin-top: 0; }
.bubble > :last-child { margin-bottom: 0; }
.bubble p { margin: 0 0 9px; }
.bubble h1, .bubble h2, .bubble h3, .bubble h4 { margin: 12px 0 6px; font-size: 1em; font-weight: 650; letter-spacing: -.01em; }
.bubble h1 { font-size: 1.1em; }
.bubble ul, .bubble ol { margin: 0 0 9px; padding-left: 20px; }
.bubble li { margin: 3px 0; }
.bubble blockquote { margin: 0 0 9px; padding: 2px 12px; border-left: 2px solid var(--line-2); color: var(--text-2); }
.bubble a { color: var(--agent, var(--phosphor)); text-decoration-thickness: 1px; }
.bubble hr { border: 0; border-top: 1px solid var(--line-2); margin: 10px 0; }
.bubble code { color: var(--agent, var(--phosphor)); background: color-mix(in srgb, var(--agent, var(--phosphor)) 12%, transparent); }
.user .bubble code { color: inherit; background: rgba(0,0,0,.12); }

/* code blocks: the terminal inside the message */
.codeblock { position: relative; margin: 6px -6px 9px; border-radius: 12px; background: var(--bg); border: 1px solid var(--line-2); overflow: hidden; }
.codeblock pre { margin: 0; padding: 12px 14px; overflow-x: auto; font-family: var(--mono); font-size: 12.5px; line-height: 1.55; color: var(--phosphor); }
.codeblock code { background: transparent; color: inherit; padding: 0; font-size: inherit; }
.codeblock .lang { position: absolute; top: 7px; left: 12px; font-family: var(--mono); font-size: 9.5px; color: var(--text-3); letter-spacing: .14em; text-transform: uppercase; }
.codeblock .copy { position: absolute; top: 5px; right: 6px; height: 22px; padding: 0 8px; font-family: var(--mono); font-size: 10px; letter-spacing: .06em; border-radius: 6px; background: transparent; color: var(--text-3); border: 1px solid var(--line-2); cursor: pointer; }
.codeblock .copy:hover { color: var(--text); border-color: var(--text-3); }
.codeblock.has-lang pre { padding-top: 26px; }

/* delivery line under a bubble */
.stamp { font-family: var(--mono); font-size: 10px; color: var(--text-3); letter-spacing: .04em; display: flex; gap: 12px; margin: 2px 12px 0; }
.user.expendable .stamp .to { color: var(--crit); }
.user.expendable .bubble { animation: phosphor-flicker 1.1s steps(2, end) 1; }
@keyframes phosphor-flicker { 0%, 100% { filter: none; } 20% { filter: brightness(1.6) saturate(.4); } 40% { filter: brightness(.7); } 60% { filter: brightness(1.3); } }
.user .stamp { justify-content: flex-end; }
.stamp .to { color: var(--agent, var(--text-3)); }

/* typing indicator */
.row.thinking .bubble { display: inline-flex; gap: 5px; padding: 10px 14px; width: max-content; max-width: 100%; align-items: center; }
.row.thinking .status { font-size: 13.5px; color: var(--text-2); margin-left: 8px; font-style: italic; animation: status-in calc(350ms * var(--motion-scale)) ease; white-space: nowrap; }
.row.thinking .status::after { content: ''; display: inline-block; width: 2px; height: 14px; margin-left: 3px; vertical-align: -2px; background: var(--agent, var(--text-2)); animation: cursor-blink 1s steps(1) infinite; }
@keyframes status-in { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
@keyframes cursor-blink { 50% { opacity: 0; } }
.row.thinking .elapsed { font-family: var(--mono); font-size: 10px; letter-spacing: .08em; color: var(--text-3); margin-left: 8px; }
/* What a turn is reading, while it reads it, and what it was charged once it is done. */
.row.thinking .tokens { font-family: var(--mono); font-size: 10px; letter-spacing: .08em; color: var(--text-3); margin-left: 8px; opacity: .75; }
/* What a reply cost, on the same line as everything else above the bubble: no pill, no wrap. */
.who .spent { flex: none; margin-left: auto; padding: 0; border: 0; background: none; font-family: var(--mono); font-size: 10px; letter-spacing: .04em; color: var(--text-3); white-space: nowrap; }
.who .spent.ash { color: var(--brew); }
.stamp .uncharged { color: var(--brew); }
.economy-headline { font-family: var(--mono); font-size: clamp(38px, 5vw, 56px); line-height: 1.1; letter-spacing: -.01em; color: var(--ph); margin: 2px 0 12px; }
.card-icon { width: 12px; height: 12px; opacity: .85; }

/* The room in six figures, read across before anything is read down. */
.economy-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; margin: 0 0 4px; padding: 0; border: 0; }
.economy-stat {
  display: grid; gap: 5px; align-content: start; min-width: 0;
  padding: 14px 16px; border: 1px solid var(--ph-faint); border-radius: 10px;
  background: color-mix(in srgb, var(--ph) 4%, transparent);
}
.economy-stat b { font-family: var(--mono); font-size: 22px; font-weight: 600; line-height: 1.1; color: var(--ph); }
.economy-stat span { font-family: var(--mono); font-size: 8.5px; letter-spacing: .18em; color: var(--ph-dim); }

/* A table is read by looking one row up, so the grid stays recessive and the numbers line up. */
.economy-table { width: 100%; border-collapse: collapse; font-family: var(--mono); font-size: 11px; }
.economy-table th, .economy-table td { padding: 7px 10px; text-align: right; border-bottom: 1px solid var(--ph-faint); white-space: nowrap; }
.economy-table thead th { font-size: 8.5px; font-weight: 400; letter-spacing: .18em; color: var(--ph-dim); border-bottom-color: var(--ph-dim); }
.economy-table tbody th { text-align: left; font-weight: 600; letter-spacing: .14em; color: var(--ph-dim); }
.economy-table td { color: var(--ph); }
.economy-table tbody tr:last-child th, .economy-table tbody tr:last-child td { border-bottom: 0; }

/* One agent, two bars, one scale: the shorter bar is the shorter answer. */
.ash-compare { display: grid; gap: 20px; }
.ash-agent { display: grid; gap: 6px; }
.ash-agent > b { font-family: var(--mono); font-size: 10px; font-weight: 600; letter-spacing: .2em; color: var(--ph-dim); text-shadow: none; }
.ash-bar { display: grid; grid-template-columns: 76px minmax(80px, 560px) auto; gap: 14px; align-items: center; }
.ash-bar .ash-side { font-family: var(--mono); font-size: 10px; letter-spacing: .12em; color: var(--ph-dim); text-shadow: none; }
.ash-bar .ash-figure { font-family: var(--mono); font-size: 10px; letter-spacing: .08em; color: var(--ph-dim); white-space: nowrap; text-shadow: none; }
.ash-bar i { height: 9px; background: var(--ph-faint); position: relative; }
.ash-bar i::after { content: ''; position: absolute; inset: 0 auto 0 0; width: var(--fill, 0%); background: color-mix(in srgb, var(--ph) 30%, transparent); }
.ash-bar.on i::after { background: var(--ph); }
.ash-bar.on .ash-figure, .ash-bar.on .ash-side { color: var(--ph); }
.ash-verdict { margin: 4px 0 0; font-family: var(--mono); font-size: 10px; line-height: 1.5; letter-spacing: .06em; color: var(--ph); text-shadow: none; }
.ash-verdict.noise { color: var(--ph-dim); }
.ash-waiting { margin: 0; font-family: var(--mono); font-size: 10px; letter-spacing: .08em; color: var(--ph-dim); text-shadow: none; }
@container console (max-width: 650px) { .ash-bar { grid-template-columns: 1fr; } .ash-bar i { display: none; } }
.row.thinking .elapsed.late { color: var(--warn); }
.row.thinking i { width: 7px; height: 7px; border-radius: 50%; background: var(--agent, var(--text-2)); animation: bounce 1.2s infinite; opacity: .5; }
.row.thinking i:nth-child(2) { animation-delay: calc(180ms * var(--motion-scale)); } .row.thinking i:nth-child(3) { animation-delay: calc(360ms * var(--motion-scale)); }
@keyframes bounce { 0%, 80%, 100% { transform: translateY(0); opacity: .35; } 40% { transform: translateY(-4px); opacity: 1; } }

/* system lines: handoffs, sentinel, failures — MOTHER speaks in small caps */
/* A line of the room talking about itself. Three things keep it orderly:

   · a measure. Running the full column turns one sentence into a ragged staircase, and these are
     read at a glance or not at all.
   · balanced wrapping, so two lines come out the same length instead of a long one and a word.
   · the label on its own line. CONTROL, MEMORY, MODULES name what follows; leaving them inline
     let the break land anywhere and the eye lost which part was the heading. */
.system {
  /* A definite width, not shrink-to-fit. Sized to its content, the box is as wide as its widest
     line, so the heading centred in one box and the body wrapped inside another — which is why
     the agent's name never lined up with the sentence under it. */
  align-self: center; text-align: center; width: min(92%, 58ch);
  /* `pretty`, not `balance`: balance evens the line lengths and in doing so kept pushing the
     agent's name onto a line of its own, away from the sentence it begins. `pretty` only avoids
     orphans, which is the actual problem these rows had. */
  overflow-wrap: anywhere; text-wrap: pretty;
  margin: 22px 0 8px;
  font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase;
  color: var(--sys-ink, var(--text-3)); line-height: 1.7;
}
.system > b:first-child:not(.inline) { display: block; margin-bottom: 3px; color: var(--sys-head, var(--text-3)); letter-spacing: .2em; }
/* Everything after the heading is one sentence and has to wrap as one: a code chip that becomes
   a block breaks the line in front of it and leaves the agent's name stranded. */
.system code { display: inline-block; vertical-align: baseline; }
/* `.who` belongs to a message's header, where it is a flex row with a left margin. Inside a
   system line it is a word in a sentence, and inheriting that rule is what put every agent's
   name alone on a line, indented, away from the clause it opens. */
.system .who { display: inline; margin: 0; white-space: nowrap; }
.system .who { color: var(--agent, var(--text-2)); }
.system b { font-weight: 600; color: var(--text-2); }
.system .from { color: var(--from, var(--text-2)); } .system .to { color: var(--to, var(--text-2)); }
/* A claim: «KIND · @agent» as the title, what happened as one plain sentence, what to do about it
   as buttons on their own row, and the caveat last and quietest. Three tiers the eye can find
   without reading, where one long uppercase sentence broke wherever the width fell. */
.system.claim { display: grid; justify-items: center; gap: 6px; width: min(92%, 580px); line-height: 1.5; }
.system.claim > .claim-head { margin-bottom: 0; font-size: 10px; }
.system.claim > .claim-head .who { color: var(--agent, var(--text-2)); }
.system.claim .claim-body { overflow-wrap: normal; font-family: var(--read); font-weight: 400; font-size: 13px; letter-spacing: 0; text-transform: none; color: var(--text-2); }
.system.claim .claim-body .file-link { display: inline-block; max-width: 100%; vertical-align: bottom; font-family: var(--mono); font-size: 12px; color: var(--phosphor); text-underline-offset: 3px; text-decoration-thickness: 1px; overflow-wrap: anywhere; }
.system.claim .claim-acts { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-top: 4px; }
.system.claim .claim-act { height: 28px; padding: 0 12px; border: 1px solid color-mix(in srgb, var(--phosphor) 45%, var(--line-2)); border-radius: 999px; background: color-mix(in srgb, var(--phosphor) 8%, transparent); color: var(--phosphor); font: inherit; font-size: 9.5px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; cursor: pointer; transition: background var(--motion-fast) var(--ease-out), border-color var(--motion-fast) var(--ease-out); }
.system.claim .claim-act:hover { background: color-mix(in srgb, var(--phosphor) 16%, transparent); border-color: var(--phosphor); }
.system.claim .claim-act:focus-visible { outline: 2px solid var(--phosphor); outline-offset: 2px; }
.system.claim .claim-act:disabled { opacity: .45; cursor: default; }
.system.claim .claim-note { max-width: 52ch; font-family: var(--read); font-size: 11.5px; letter-spacing: 0; text-transform: none; color: var(--text-3); }
.system.claim.privacy > .claim-head { color: var(--warn); }
.system.claim.warn > .claim-head { color: var(--warn); }
.system.claim.privacy .claim-body { color: color-mix(in srgb, var(--warn) 70%, var(--text-2)); }
.system.warn { color: var(--warn); }
.system.memory { color: var(--text-3); } .system.memory .who { color: var(--agent, var(--text-2)); }
.system.memory .brief { text-transform: none; letter-spacing: 0; color: var(--text-2); }

/* NOSTROMO: the archive as a small solar system. One colour per kind of memory. */
:root { --mem-decision: #ffdc3c; --mem-fact: #dfeeff; --mem-preference: #5cf07a; --mem-question: #3dc6ff; --mem-aberration: #b14cff; --nostromo-sun: #ff2a1f; }
.nostromo-button { color: var(--terror); border-color: color-mix(in srgb, var(--terror) 55%, transparent); }
.nostromo-button:hover { background: color-mix(in srgb, var(--terror) 14%, transparent); }
dialog.nostromo { color: #eef1ea; }
dialog.nostromo::backdrop { background: #000; }
.nostromo-frame { --ph: #ffb4ad; --ph-dim: rgba(255, 42, 31, .55); --ph-faint: rgba(255, 42, 31, .16); position: relative; height: 100%; background: #030203; font-family: var(--mono); overflow: hidden; display: grid; grid-template-rows: auto 1fr; }
.nostromo-head { display: grid; grid-template-columns: minmax(max-content, 1fr) auto; grid-template-areas: "title actions" "sub legend"; gap: 8px 18px; align-items: center; padding: 18px 26px 14px; border-bottom: 1px solid var(--ph-faint); color: var(--ph); position: relative; z-index: 2; }
.nostromo-head .mother-title { color: var(--nostromo-sun); text-shadow: 0 0 3px color-mix(in srgb, var(--nostromo-sun) 25%, transparent); }
.nostromo-head .mother-sub { color: var(--ph-dim); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* Two rows, as in every console header: the title over what NOSTROMO is reading, and on the right
   the buttons over the legend of the dwarfs — each lower line in tune with the one beside it. */
.nostromo-head > .mother-title { grid-area: title; align-self: end; }
.nostromo-head > .mother-sub { grid-area: sub; align-self: start; contain: inline-size; }
.nostromo-head > .nostromo-actions { grid-area: actions; display: flex; justify-content: flex-end; align-items: center; gap: 10px; }
.nostromo-head > .nostromo-legend { grid-area: legend; justify-content: flex-end; flex-wrap: wrap; row-gap: 6px; align-self: start; }
.nostromo-actions .mother-close { white-space: nowrap; }
.nostromo-legend { display: flex; gap: 16px; align-items: center; }
.nostromo-legend .k { display: inline-flex; align-items: center; gap: 6px; font-size: 9px; letter-spacing: .16em; }
.nostromo-legend .k canvas { display: block; }
.nostromo-legend .k i { font-style: normal; }
.nostromo-legend .k.decision { color: var(--mem-decision); } .nostromo-legend .k.fact { color: var(--mem-fact); } .nostromo-legend .k.preference { color: var(--mem-preference); } .nostromo-legend .k.question { color: var(--mem-question); } .nostromo-legend .k.aberration { color: var(--mem-aberration); }
.nostromo-frame .mother-close { color: var(--ph); border-color: var(--ph-dim); }
.nostromo-frame .mother-close:hover { background: var(--ph-faint); }
.nostromo-canvas { display: block; width: 100%; height: 100%; cursor: crosshair; }
/* The map takes focus when NOSTROMO opens, so that Enter does not land on LEAVE. It is not in
   the tab order (tabindex="-1"), so the ring the browser draws around it points at nothing and
   boxes the constellation in blue. Nothing is hidden by removing it: there is nowhere to tab. */
.nostromo-canvas:focus, .nostromo-canvas:focus-visible { outline: none; }
.nostromo-canvas.over { cursor: pointer; }
.nostromo-canvas.dragging { cursor: grabbing; }
.nostromo-help { position: absolute; left: 26px; bottom: 16px; margin: 0; font-size: 9px; letter-spacing: .2em; color: var(--ph-dim); pointer-events: none; }
.nostromo-frame.shake { animation: override-shake .45s ease 2; }
/* MOTHER's answer when touched: a klaxon over everything, then silence. */
.nostromo-alert { position: absolute; inset: 0; z-index: 5; display: grid; place-items: center; cursor: pointer; }
.nostromo-alert .klaxon { position: absolute; inset: 0; background: radial-gradient(ellipse at center, rgba(255, 42, 31, .0) 30%, rgba(255, 42, 31, .32) 100%); animation: klaxon .55s steps(2) infinite; }
.nostromo-alert .panel { position: relative; padding: 30px 46px; border: 2px solid var(--nostromo-sun); background: rgba(20, 0, 2, .92); box-shadow: 0 0 0 4px rgba(255, 42, 31, .16), 0 24px 70px rgba(0, 0, 0, .6); text-align: center; display: grid; gap: 10px; animation: alert-in calc(250ms * var(--motion-scale)) ease-out; max-width: min(720px, 92vw); }
.nostromo-alert .warn { font-size: clamp(22px, 4vw, 40px); font-weight: 700; letter-spacing: .32em; color: var(--nostromo-sun); text-shadow: 0 0 3px color-mix(in srgb, var(--nostromo-sun) 30%, transparent); animation: klaxon .55s steps(2) infinite; }
.nostromo-alert .line { font-size: clamp(13px, 1.8vw, 18px); letter-spacing: .24em; color: #ffd9d4; }
.nostromo-alert .line.big { font-size: clamp(16px, 2.4vw, 24px); font-weight: 700; color: #fff; text-shadow: 0 0 3px color-mix(in srgb, var(--nostromo-sun) 30%, transparent); margin-top: 6px; }
.nostromo-alert .sub { margin-top: 8px; font-size: 9.5px; letter-spacing: .28em; color: var(--ph-dim); }
@keyframes klaxon { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
@keyframes alert-in { from { transform: scale(.92); opacity: 0; } to { transform: none; opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .nostromo-alert .klaxon, .nostromo-alert .warn, .nostromo-frame.shake { animation: none; } }
.nostromo-card { position: absolute; right: 26px; top: 96px; width: min(380px, calc(100vw - 52px)); padding: 18px 20px 16px; background: rgba(6, 3, 4, .92); border: 1px solid var(--kind, var(--ph-dim)); box-shadow: 0 0 0 1px rgba(0,0,0,.6), 0 16px 40px rgba(0, 0, 0, .5); backdrop-filter: blur(8px); display: grid; gap: 12px; z-index: 3; animation: mother-on .3s ease; }
.nostromo-card header { display: flex; justify-content: space-between; align-items: center; }
.nostromo-card .kind { font-size: 10px; letter-spacing: .22em; color: var(--kind, var(--ph)); text-shadow: none; }
.nostromo-card .text { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", Inter, sans-serif; font-size: 14px; line-height: 1.5; color: #eef1ea; }
.nostromo-card .meta { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; font-size: 10px; letter-spacing: .1em; }
.nostromo-card .meta dt { color: var(--ph-dim); } .nostromo-card .meta dd { margin: 0; color: #c9c2bf; }
/* What this memory is wired to, and what has actually passed between it and the room. The list
   is the same set of wires the map draws: hovering a row lights its filament out there. */
.nostromo-card .wire { display: grid; gap: 7px; border-top: 1px solid rgba(255, 255, 255, .08); padding-top: 11px; }
.nostromo-card .wire h6 { margin: 0; font-size: 9px; font-weight: 400; letter-spacing: .22em; color: var(--ph-dim); display: flex; align-items: center; gap: 8px; }
.nostromo-card .wire h6 .n { color: #c9c2bf; }
.nostromo-card .wire h6 .live { color: var(--kind, var(--ph)); font-size: 7px; animation: blink 2.4s steps(1) infinite; margin-left: auto; }
.nostromo-card .exchange { margin: 0; white-space: pre-line; font-size: 10.5px; line-height: 1.6; letter-spacing: .06em; color: #c9c2bf; }
.nostromo-card .wires { margin: 0; padding: 0; list-style: none; display: grid; gap: 4px; max-height: 148px; overflow-y: auto; }
.nostromo-card .wires .none { font-size: 10px; letter-spacing: .08em; color: var(--ph-dim); padding: 2px 0; }
.nostromo-card .wire-row { display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 4px 6px 4px 2px; cursor: pointer; border: 1px solid transparent; }
.nostromo-card .wire-row:hover { border-color: rgba(255, 255, 255, .16); background: rgba(255, 255, 255, .04); }
.nostromo-card .wire-row i { width: 7px; height: 7px; border-radius: 50%; background: var(--kind, var(--ph)); box-shadow: 0 0 0 2px color-mix(in srgb, var(--kind, var(--ph)) var(--glow-a), transparent); }
.nostromo-card .wire-row .what { font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", Inter, sans-serif; font-size: 11.5px; line-height: 1.4; color: #d7d2cf; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nostromo-card .wire-row b { font-family: var(--mono); font-size: 9px; font-weight: 600; letter-spacing: .08em; color: var(--ph-dim); }
.nostromo-card .wire-row.refuted b { color: var(--nostromo-sun); }
/* Company strong enough that recalling one now brings the other: the association is live. */
/* What to ask next: a panel on the other side of the map from the memory card, so the two can
   be open one after the other and never fight for the same corner. */
.nostromo-card.asks { right: auto; left: 26px; width: min(420px, calc(100vw - 52px)); border-color: rgba(255, 255, 255, .14); }
.nostromo-card.asks .kind { color: #d7d2cf; text-shadow: none; }
.nostromo-card.asks .foot { margin: 0; }
.asks-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 10px; max-height: min(58vh, 520px); overflow-y: auto; }
.asks-list .none { font-size: 11px; letter-spacing: .06em; color: var(--ph-dim); }
.asks-list .ask { display: grid; gap: 6px; padding: 11px 12px; border: 1px solid rgba(255, 255, 255, .1); border-left: 2px solid var(--well, rgba(255, 255, 255, .3)); background: rgba(255, 255, 255, .03); }
.asks-list .ask-open { --well: #3dc6ff; }
.asks-list .ask-cold { --well: #96b0c6; }
.asks-list .ask-thin { --well: #ffdc3c; }
.asks-list .ask .q { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", Inter, sans-serif; font-size: 13px; line-height: 1.5; color: #eef1ea; }
.asks-list .ask .why { margin: 0; font-family: var(--mono); font-size: 8.5px; letter-spacing: .12em; line-height: 1.5; color: var(--ph-dim); }
.asks-list .ask .actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 2px; }
.asks-list .ask button { border: 1px solid rgba(255, 255, 255, .22); background: transparent; color: #d7d2cf; font: inherit; font-size: 9px; letter-spacing: .16em; padding: 6px 10px; cursor: pointer; }
.asks-list .ask button.primary { border-color: var(--well); color: var(--well); }
.asks-list .ask button:hover { background: rgba(255, 255, 255, .06); }
.asks-list .ask button:disabled { opacity: .45; cursor: default; }
.nostromo-head .mother-close.ask { color: #d7d2cf; border-color: rgba(255, 255, 255, .28); }
.nostromo-head .mother-close.ask[aria-pressed="true"] { background: rgba(255, 255, 255, .12); color: #fff; }

/* ================= the core =================
   Inside the star, not looking at it: the field burns from the edges inward and breathes, and
   the console sits on top of it in the panel's own phosphor. Nothing here is a new language —
   the frame, the folds, the bars and the type are the ones MADRE already speaks. */
/* The core opens from inside NOSTROMO, on top of the star itself: the field behind this frame is
   the real one, still turning and still breathing. A second sun drawn here would be two. */
.core::backdrop { background: radial-gradient(circle at 50% 50%, rgba(30, 2, 0, .58), rgba(0, 0, 0, .86) 72%); }
.core .mother-frame { position: relative; z-index: 1; border-color: color-mix(in srgb, var(--nostromo-sun) 45%, var(--ph-dim)); box-shadow: 0 24px 60px rgba(0, 0, 0, .5), 0 0 0 1px rgba(0, 0, 0, .6); }
.core .mother-title { color: var(--nostromo-sun); text-shadow: 0 0 3px color-mix(in srgb, var(--nostromo-sun) 25%, transparent); }
.core .mother-foot a { color: var(--ph-dim); text-decoration: none; }
.core .mother-foot a:hover { color: var(--ph); }
.core .mother-frame { display: grid; grid-template-rows: auto auto 1fr; overflow: hidden; padding-bottom: 18px; }
.core .mother-boot { margin: 12px 0 6px; min-height: 2.4em; font-size: 11px; }
.core-body { display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; gap: 10px; min-height: 0; }
.core-body > .core-tabs { grid-row: 1; }
.core-body > .core-strip { grid-row: 2; }
.core-body > .core-panes { grid-row: 3; }
.core-body > .console-line { grid-row: 4; }

/* The strip: who it goes to, at what mode, and around what. One line each, never a paragraph. */
.core-strip { display: grid; gap: 6px; border-bottom: 1px solid var(--ph-faint); padding-bottom: 10px; }
.core-pick { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }
.core-pick .k, .core-asking .k { font-size: 8.5px; letter-spacing: .22em; color: var(--ph-dim); }
.core-agents { display: flex; flex-wrap: wrap; gap: 4px; }
.core-agent { border: 1px solid var(--ph-faint); background: transparent; color: var(--ph-dim); font: inherit; font-size: 10px; letter-spacing: .12em; padding: 3px 8px; cursor: pointer; }
.core-agent:hover { border-color: var(--ph-dim); color: var(--ph); }
.core-agent.on { border-color: var(--ph); color: var(--ph); background: var(--ph-faint); }
.core-agent.cold { opacity: .55; }
.core-pick select { border: 1px solid var(--ph-faint); background: #000; color: var(--ph); font: inherit; font-size: 10px; letter-spacing: .12em; padding: 3px 6px; }
.core-ceiling { font-family: var(--mono); font-size: 8.5px; letter-spacing: .14em; color: var(--warn); }
.core-asking { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; }
.core-asking textarea { width: 100%; resize: none; border: 0; border-bottom: 1px solid var(--ph-faint); background: transparent; color: var(--ph); font: inherit; font-family: var(--mono); font-size: 11.5px; line-height: 1.6; padding: 3px 0; }
.core-asking textarea::placeholder { color: var(--ph-dim); opacity: .7; }
.core-asking textarea:focus { outline: 0; border-bottom-color: var(--ph); }
.core-asking .note { font-size: 8px; letter-spacing: .14em; color: var(--ph-dim); white-space: nowrap; }

/* Four panes, one at a time, each tab carrying what is behind it. */
.core-tabs { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 2px; }
.core-tab { display: grid; gap: 1px; text-align: left; border: 1px solid transparent; border-bottom: 1px solid var(--ph-faint); background: transparent; color: var(--ph-dim); font: inherit; padding: 6px 12px; cursor: pointer; }
.core-tab b { font-size: 10px; font-weight: 600; letter-spacing: .18em; }
.core-tab .meta { font-size: 8.5px; letter-spacing: .1em; opacity: .8; }
.core-tab:hover { color: var(--ph); }
.core-tab.on { color: var(--ph); border-color: var(--ph-faint); border-bottom-color: transparent; background: transparent; }
.core-panes { overflow: auto; min-height: 0; padding: 4px 2px 8px; transition: opacity calc(180ms * var(--motion-scale)) ease; }
.core-panes.reading { opacity: .45; }
.core-pane { display: grid; gap: 10px; align-content: start; min-width: 0; }
.core-pane > *, .core-blocks, .core-block { min-width: 0; }

/* `==> TITLE   meta`, and facts in two columns: how the terminal this frame is dressed as prints. */
.brew-head { margin: 6px 0 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px; font-family: var(--mono); font-size: 9px; letter-spacing: .14em; text-transform: uppercase; }
.brew-head b { color: var(--nostromo-sun); text-shadow: none; letter-spacing: 0; }
.brew-head .title { color: var(--ph); font-size: 10px; letter-spacing: .2em; }
.brew-head .meta { color: var(--ph-dim); }
.brew-rows { display: grid; gap: 4px; }
.brew-row { display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 14px; align-items: baseline; }
.brew-row .k { font-family: var(--mono); font-size: 9px; letter-spacing: .14em; color: var(--ph-dim); text-transform: uppercase; }
.brew-row .v { font-family: var(--mono); font-size: 10.5px; line-height: 1.6; color: rgba(210, 255, 190, .88); text-shadow: none; }
.brew-row .v .where { color: var(--ph-dim); }

.core-doc, .core-launch, .core-outbound { display: grid; gap: 10px; }
.core-blocks { display: grid; gap: 1px; }
.core-block { border: 1px solid transparent; }
.core-block > summary { display: grid; grid-template-columns: 14px 148px 72px minmax(140px, 1.1fr) minmax(0, 1.4fr); gap: 14px; align-items: center; padding: 5px 6px; cursor: pointer; list-style: none; }
.core-block > summary::-webkit-details-marker { display: none; }
.core-block:hover { border-color: var(--ph-faint); }
.core-block[open] { border-color: var(--ph-faint); background: rgba(0, 0, 0, .35); }
.core-block > summary .sign { font-style: normal; font-size: 11px; color: var(--nostromo-sun); text-shadow: none; }
.core-block > summary b { font-size: 9.5px; font-weight: 600; letter-spacing: .16em; color: var(--ph); text-shadow: none; }
.core-block > summary .n { font-family: var(--mono); font-size: 9px; letter-spacing: .1em; color: var(--ph-dim); text-align: right; }
.core-block > summary .weigh { height: 6px; background: var(--ph-faint); position: relative; }
.core-block > summary .weigh::after { content: ''; position: absolute; inset: 0 auto 0 0; width: var(--fill, 0%); background: color-mix(in srgb, var(--nostromo-sun) 55%, var(--ph)); }
.core-block > summary .when { font-size: 8.5px; letter-spacing: .1em; color: var(--ph-dim); text-transform: uppercase; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.core-text { position: relative; padding: 4px 8px 12px; }
.core-from { margin: 0 0 8px; font-family: var(--mono); font-size: 9px; letter-spacing: .12em; line-height: 1.7; color: var(--ph-dim); text-transform: uppercase; }
.core-from b { color: var(--ph); letter-spacing: .2em; margin-right: 8px; }
.core-from .where { color: rgba(210, 255, 190, .72); }
.core-text pre { margin: 0; max-height: 40vh; overflow: auto; padding: 12px 14px; border: 1px solid var(--ph-faint); background: #000; font-family: var(--mono); font-size: 11.5px; line-height: 1.65; white-space: pre-wrap; overflow-wrap: anywhere; color: rgba(210, 255, 190, .92); text-shadow: none; }
.core-copy-one { position: absolute; top: 12px; right: 18px; border: 1px solid var(--ph-faint); background: #000; color: var(--ph-dim); font: inherit; font-size: 8.5px; letter-spacing: .16em; padding: 4px 8px; cursor: pointer; }
.core-copy-one:hover { color: var(--ph); border-color: var(--ph-dim); }
.core-fixed { margin: 0; font-family: var(--mono); font-size: 9px; letter-spacing: .12em; line-height: 1.7; color: var(--ph-dim); border-left: 2px solid color-mix(in srgb, var(--nostromo-sun) 60%, transparent); padding-left: 12px; }
.core-pane .note { margin: 0; font-size: 8.5px; letter-spacing: .12em; line-height: 1.7; color: var(--ph-dim); }

/* THE LAUNCH: the command under the document, printed as it would be run. */
.core-launch .mother-cmd { margin: 0; }
.core-launch .mother-cmd pre { max-height: 32vh; overflow: auto; font-size: 11px; color: rgba(210, 255, 190, .92); text-shadow: none; }
.core-server .tools { display: inline-flex; flex-wrap: wrap; gap: 4px; margin-left: 6px; vertical-align: middle; }
.core-server .tools i { font-style: normal; font-size: 8.5px; letter-spacing: .1em; color: var(--ph-dim); border: 1px solid var(--ph-faint); padding: 1px 5px; }

/* WHAT LEFT THIS MACHINE: the declaration, and the log that checks it. */
.core-egress { display: grid; gap: 2px; }
.egress { display: grid; grid-template-columns: 52px minmax(120px, 1fr) auto; gap: 4px 12px; align-items: baseline; padding: 8px; border: 1px solid transparent; }
.egress:hover { border-color: var(--ph-faint); background: rgba(0, 0, 0, .3); }
.egress .state { font-family: var(--mono); font-size: 8.5px; letter-spacing: .16em; color: var(--nostromo-sun); text-shadow: none; }
.egress.off .state { color: var(--ph-dim); }
.egress.local .state { color: #96b0c6; }
.egress > b { font-size: 10px; letter-spacing: .1em; color: var(--ph); text-shadow: none; }
.egress .n { font-family: var(--mono); font-size: 8.5px; letter-spacing: .12em; color: var(--ph-dim); text-align: right; white-space: nowrap; }
.egress .what, .egress .when { grid-column: 2 / -1; margin: 0; font-family: var(--mono); font-size: 10.5px; line-height: 1.6; color: rgba(210, 255, 190, .86); text-shadow: none; }
.egress .when { font-size: 9px; letter-spacing: .1em; color: var(--ph-dim); text-transform: uppercase; }
.egress .when i { font-style: normal; }
.egress .when .where { color: rgba(210, 255, 190, .72); }
.egress.off { opacity: .55; }
.egress.off:hover { opacity: 1; }
pre.core-egress-log { margin: 0; max-height: 34vh; overflow: auto; padding: 10px 12px; border: 1px solid var(--ph-faint); background: #000; font-family: var(--mono); font-size: 10.5px; line-height: 1.6; white-space: pre; color: rgba(210, 255, 190, .92); text-shadow: none; }

/* The prompt: always at the bottom, the way through all four panes. */
.console-log { margin: 0; font-family: var(--mono); font-size: 11.5px; line-height: 1.6; white-space: pre-wrap; overflow-wrap: anywhere; color: rgba(210, 255, 190, .92); text-shadow: none; }
.console-log .said { color: var(--ph-dim); }
.console-log .refused { color: var(--warn); }
.console-line { display: flex; align-items: center; gap: 8px; border-top: 1px solid var(--ph-dim); padding-top: 10px; }
.console-line .prompt { font-family: var(--mono); font-size: 13px; color: var(--nostromo-sun); text-shadow: none; }
.console-line input { flex: 1; min-width: 0; border: 0; background: transparent; color: var(--ph); font: inherit; font-family: var(--mono); font-size: 12px; letter-spacing: .06em; text-transform: uppercase; padding: 2px 0; }
.console-line input:focus { outline: 0; }
.console-line input::placeholder { color: var(--ph-dim); opacity: .7; letter-spacing: .14em; }
.console-line input:disabled { opacity: .4; }
.console-strikes { display: inline-flex; gap: 3px; }
.console-strikes i { font-style: normal; font-size: 9px; color: var(--ph-faint); }
.console-strikes i.on { color: var(--warn); }
.console-help { border: 1px solid var(--ph-faint); background: transparent; color: var(--ph-dim); font: inherit; font-size: 8.5px; letter-spacing: .16em; padding: 3px 8px; cursor: pointer; }
.console-help:hover { color: var(--ph); border-color: var(--ph-dim); }

@container console (max-width: 650px) {
  .core-block > summary { grid-template-columns: 14px 1fr auto; }
  .core-block > summary .weigh, .core-block > summary .when { display: none; }
  .brew-row { grid-template-columns: 1fr; gap: 2px; }
  .egress { grid-template-columns: 52px 1fr; }
  .egress .n { grid-column: 1 / -1; text-align: left; }
  .core-asking { grid-template-columns: 1fr; }
  .core-asking .note { display: none; }
}

/* The cold zone: a colour that is not a memory kind and not the sun, so it never reads as life. */
.nostromo-head .mother-close.cold { color: #96b0c6; border-color: color-mix(in srgb, #96b0c6 45%, transparent); }
.nostromo-head .mother-close.cold[aria-pressed="true"] { background: color-mix(in srgb, #96b0c6 16%, transparent); color: #cfe0ec; }
.nostromo-card .wire-row.carries b { color: var(--kind, var(--ph)); }
.nostromo-card .wire-row.carries b::after { content: ' ⇢'; }
.nostromo-card .forget { border: 1px solid var(--nostromo-sun); background: transparent; color: var(--nostromo-sun); font: inherit; font-size: 10px; letter-spacing: .18em; padding: 9px 12px; cursor: pointer; transition: background calc(200ms * var(--motion-scale)); }
.nostromo-card .forget:hover { background: color-mix(in srgb, var(--nostromo-sun) 14%, transparent); }
.nostromo-card .forget.confirm { background: var(--nostromo-sun); color: #fff3f1; animation: blink 1s steps(1) infinite; }
.nostromo-card .forget:disabled { opacity: .5; cursor: default; animation: none; }
.nostromo-card .foot { margin: 0; font-size: 9px; letter-spacing: .1em; color: var(--ph-dim); line-height: 1.5; }
.nostromo-empty { position: absolute; inset: 50% 0 auto 0; margin: 0; text-align: center; font-size: 11px; letter-spacing: .22em; color: var(--ph-dim); }
@media (max-width: 720px) { .nostromo-head { gap: 6px 10px; } .nostromo-legend { display: none; } .nostromo-card { right: 16px; left: 16px; width: auto; } }
.system.memory.forgotten { color: var(--terror); }
.system.memory.privacy { color: var(--warn); }
.system.mother-alert { display: grid; gap: 6px; justify-items: center; max-width: min(720px, 92%); padding: 12px 16px; border: 1px solid color-mix(in srgb, var(--terror) 60%, transparent); border-radius: 12px; background: color-mix(in srgb, var(--terror) 7%, transparent); color: var(--terror); text-shadow: none; }
.system.mother-alert .head b { color: var(--terror); font-weight: 700; }
.system.mother-alert .clear { color: var(--text); text-shadow: none; text-transform: none; letter-spacing: 0; font-size: 12px; }
.system.mother-alert .code { font-family: var(--mono); font-size: 10px; letter-spacing: .08em; color: color-mix(in srgb, var(--terror) 75%, var(--text-2)); text-shadow: none; text-transform: none; word-break: break-all; line-height: 1.6; opacity: .9; }
/* The hint under a bubble when its agent saved a memory on request. */
.memory-hint { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 6px 12px 0; animation: hint-in calc(600ms * var(--motion-scale)) cubic-bezier(.2, .7, .2, 1) 1; }
.memory-hint .lead { font-family: var(--mono); font-size: 9.5px; letter-spacing: .16em; text-transform: uppercase; color: var(--agent, var(--text-3)); }
.memory-hint .pill { display: inline-flex; align-items: center; gap: 6px; max-width: 100%; border: 1px solid color-mix(in srgb, var(--kind) 55%, transparent); background: color-mix(in srgb, var(--kind) 8%, transparent); color: var(--text-2); font: inherit; font-size: 11px; padding: 3px 10px; border-radius: 999px; cursor: pointer; text-align: left; box-shadow: 0 0 0 0 color-mix(in srgb, var(--kind) 45%, transparent); animation: hint-glow 2.4s ease-out 1; transition: background calc(200ms * var(--motion-scale)), color calc(200ms * var(--motion-scale)); }
.memory-hint .pill b { font-family: var(--mono); font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--kind); }
.memory-hint .pill:hover { background: color-mix(in srgb, var(--kind) 18%, transparent); color: var(--text); }
.memory-hint .more { font-family: var(--mono); font-size: 9.5px; color: var(--text-3); }
/* Memory used is not memory saved: saving is an event, using happens on most turns. Same shape so
   there is one thing to learn, quieter so it never competes with the answer it helped write. */
/* What the archive handed this turn: one indicator per line under its heading.
   Legibility first — opacity on the whole group used to fade text that was already pale, and the
   five kind colours belong to NOSTROMO's dark map, so here the colour is a dot and the text is
   the room's own. */
.memory-hint.used { flex-direction: column; align-items: flex-start; margin-top: 4px; gap: 5px; animation: none; }
.memory-hint.used .lead { font-size: 9px; letter-spacing: .14em; color: var(--text-3); }
.memory-hint.used .pill {
  gap: 7px; max-width: min(340px, 100%); padding: 3px 10px 3px 8px;
  border: 1px solid color-mix(in srgb, var(--text-3) 26%, transparent);
  background: color-mix(in srgb, var(--text-3) 7%, transparent);
  color: var(--text-2); font-size: 11px; line-height: 1.45;
  animation: none; box-shadow: none;
}
.memory-hint.used .pill .dot {
  flex: none; width: 7px; height: 7px; border-radius: 999px; background: var(--kind);
  /* The ring is what keeps a near-white kind visible on a near-white page. */
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--text-3) 45%, transparent);
}
.memory-hint.used .pill .what { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.memory-hint.used .pill:hover { background: color-mix(in srgb, var(--text-3) 14%, transparent); color: var(--text); border-color: color-mix(in srgb, var(--text-3) 42%, transparent); }
/* Carried along rather than matched: the dot is hollow, the way an indicator says "inherited". */
.memory-hint.used .pill.carried .dot { background: transparent; box-shadow: inset 0 0 0 2px var(--kind), 0 0 0 1px color-mix(in srgb, var(--text-3) 45%, transparent); }
.memory-hint.used .last { display: flex; align-items: center; gap: 6px; max-width: 100%; }
.memory-hint.used .last .pill { min-width: 0; }
.memory-hint.used .more { font-size: 9.5px; }
@keyframes hint-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
@keyframes hint-glow { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--kind) 35%, transparent); } 100% { box-shadow: 0 0 0 5px color-mix(in srgb, var(--kind) 0%, transparent); } }
@media (prefers-reduced-motion: reduce) { .memory-hint, .memory-hint .pill { animation: none; } }
.system.crit { color: var(--crit); }
.system.fail { color: var(--danger); text-transform: none; letter-spacing: 0; font-size: 11px; }
.system.fail .label { text-transform: uppercase; letter-spacing: .1em; font-size: 10px; display: block; opacity: .8; margin-bottom: 2px; }
.system.recovered { color: var(--text-3); }
.system.mother { color: var(--terror); text-shadow: none; letter-spacing: .16em; animation: terror-in 1.4s steps(3, end) 1; }
.system.mother b { color: var(--terror); }
@keyframes terror-in { 0% { opacity: 0; } 30% { opacity: 1; } 45% { opacity: .2; } 60% { opacity: 1; } 75% { opacity: .5; } 100% { opacity: 1; } }
.composer.expendable .crew-label { color: var(--terror); text-shadow: none; }
.composer.expendable textarea::placeholder { color: color-mix(in srgb, var(--terror) 75%, transparent); }
.user.expendable .who b, .user.expendable .stamp .to { color: var(--terror); }
.mother-button.arming { color: var(--terror); border-color: var(--terror); box-shadow: 0 0 0 3px color-mix(in srgb, var(--terror) 14%, transparent); transition: color 3s linear, border-color 3s linear; }
.system .gauge { display: block; width: 220px; max-width: 100%; height: 2px; margin: 8px auto 0; background: color-mix(in srgb, currentColor 22%, transparent); position: relative; overflow: hidden; }
.system .gauge .now { position: absolute; inset: 0 auto 0 0; background: currentColor; }
.system .gauge .next { position: absolute; inset: 0 auto 0 0; background: repeating-linear-gradient(90deg, currentColor 0 2px, transparent 2px 5px); opacity: .55; }

/* ================= onboarding ================= */
.onboarding { border: 1px solid var(--line-2); background: var(--panel); border-radius: 16px; padding: 22px 24px; margin-bottom: 12px; }
.onboarding-eyebrow { margin: 0 0 10px; font-family: var(--mono); font-size: 10px; letter-spacing: .18em; color: var(--phosphor); }
.onboarding h2 { margin: 0 0 6px; font-size: 18px; letter-spacing: -.01em; font-weight: 600; }
.onboarding p { margin: 0 0 14px; color: var(--text-2); font-size: 13px; line-height: 1.5; }
.onboarding .hint { margin: 0; font-size: 12px; color: var(--text-3); }

/* ================= composer ================= */
.composer { display: grid; gap: 12px; padding: 14px 0 0; }
.composer[aria-disabled="true"] { opacity: .45; pointer-events: none; }
/* One line, always. The spheres and the chips keep their size; the note is the only piece that
   gives way, because its whole sentence is in its tooltip anyway. */
.picker { display: flex; flex-wrap: nowrap; gap: 8px; align-items: center; padding: 0 4px; }
.picker .pick { --size: 30px; cursor: pointer; border: 1px solid transparent; background: color-mix(in srgb, var(--agent) 10%, transparent); transition: transform calc(120ms * var(--motion-scale)) ease, box-shadow calc(120ms * var(--motion-scale)) ease; }
.picker .pick:hover { transform: translateY(-1px); }
.picker .pick[aria-checked="true"] { box-shadow: 0 0 0 2px var(--bg), 0 0 0 3.5px var(--agent); background: color-mix(in srgb, var(--agent) 22%, transparent); }
.picker .pick-label { display: flex; align-items: center; gap: 10px; min-width: 0; font-family: var(--mono); font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--text-2); margin-left: 2px; }
.picker .pick-label > .mode-chip, .picker .pick-label > .model-chip { flex: 0 0 auto; }
.picker .pick-label b { color: var(--agent, var(--text)); font-weight: 600; }
.field { position: relative; display: grid; grid-template-columns: auto 1fr auto; gap: 10px; align-items: end; padding: 6px 6px 6px 18px; border: 1px solid var(--line-2); background: var(--panel); border-radius: 24px; }
.crew-label { align-self: center; font-family: var(--mono); font-size: 10px; letter-spacing: .18em; color: var(--text-3); white-space: nowrap; transition: color calc(400ms * var(--motion-scale)) ease; }
.field:focus-within .crew-label { color: var(--phosphor); }
.composer.expendable .crew-label { color: var(--crit); }
.composer.expendable textarea::placeholder { color: color-mix(in srgb, var(--crit) 70%, transparent); }
select, textarea, button { font: inherit; }
textarea { resize: none; min-height: 34px; max-height: 180px; padding: 7px 0; border: 0; outline: 0; color: var(--text); background: transparent; line-height: 1.4; font-size: 15px; }
textarea::placeholder { color: var(--text-3); }
.composer { --mode: var(--mode-1); --mode-ink: var(--mode-1-ink); }
.composer.m0 { --mode: var(--mode-0); --mode-ink: var(--mode-0-ink); }
.composer.m2 { --mode: var(--mode-2); --mode-ink: var(--mode-2-ink); }
.composer.m3 { --mode: var(--mode-3); --mode-ink: var(--mode-3-ink); }
.composer.m4 { --mode: var(--mode-4); --mode-ink: var(--mode-4-ink); }
/* Under the copilot #3 is MADRE's green, not EDIT's red: the chip, the send and the ring follow. */
.composer.m3.copilot { --mode: var(--madre-green); --mode-ink: var(--madre-green-ink); }
.composer.copilot .picker .mode-chip.m3 { --mode: var(--madre-green); }
.field button[type="submit"] { width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; background: var(--mode, var(--phosphor)); color: var(--mode-ink, var(--phosphor-ink)); cursor: pointer; display: grid; place-items: center; box-shadow: var(--lift-1); transition: background calc(250ms * var(--motion-scale)), box-shadow calc(250ms * var(--motion-scale)); }
.field button[type="submit"] svg { width: var(--ico-md); height: var(--ico-md); }
.field button[type="submit"]:hover { filter: brightness(1.06); }
.field button[type="submit"]:disabled { opacity: .4; cursor: default; box-shadow: none; }
.pick-label .pick-note { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; font-family: var(--mono); font-size: 9px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-3); white-space: nowrap; }
.safety { margin-top: 8px; margin-bottom: 4px; color: var(--text-2); font-family: var(--mono); font-size: 8.5px; line-height: 1.5; letter-spacing: .06em; text-transform: uppercase; text-align: center; opacity: .9; }
/* The signature, in the corner it belongs in: last in the page's order, and out of the way of
   everything that is actually used. */
/* The version and the way to support it: under the composer, in its own row with air above and
   below, never over the box or the send button. */
.colophon { display: block; margin-top: 12px; margin-bottom: 14px; text-align: center; font-family: var(--mono); font-size: 8.5px; letter-spacing: .1em; color: var(--brew); opacity: .68; user-select: none; transition: opacity calc(200ms * var(--motion-scale)); }
.colophon:hover { opacity: 1; }
@media (max-width: 720px) { .colophon { display: none; } }

/* toast */
/* A conversation that finished elsewhere: a card on the left, beside the conversations button and
   never over it. The brand's quiet card: graphite, a hairline, a mono label with its dot, the
   conversation's name as the thing to read, and phosphor only on the way there. No glow. */
.notices { position: fixed; top: var(--notice-top, 72px); left: var(--notice-left, 72px); z-index: 60; display: grid; gap: 10px; width: min(330px, calc(100vw - var(--notice-left, 72px) - 16px)); pointer-events: none; }
.notice { position: relative; pointer-events: auto; display: grid; gap: 8px; padding: 12px 14px 13px; border: 1px solid var(--line-2); border-radius: 16px; background: var(--panel-2, var(--panel)); box-shadow: 0 18px 40px -22px rgba(0, 0, 0, .55); cursor: pointer; overflow: hidden; animation: notice-in calc(300ms * var(--motion-scale)) cubic-bezier(.2, .8, .2, 1); transition: border-color calc(150ms * var(--motion-scale)); }
.notice:hover { border-color: color-mix(in srgb, var(--phosphor) 35%, var(--line-2)); }
.notice.leaving { animation: notice-out calc(220ms * var(--motion-scale)) ease forwards; }
.notice-top { display: flex; align-items: center; gap: 10px; }
.notice-state { display: inline-flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .16em; color: var(--text-2); }
.notice-state::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: var(--phosphor); }
.notice.failed .notice-state::before { background: var(--danger); }
.notice.failed .notice-state { color: var(--danger); }
.notice-time { margin-left: auto; font-family: var(--mono); font-size: 9.5px; letter-spacing: .08em; color: var(--text-3); }
.notice-close { width: 20px; height: 20px; margin-right: -4px; border: 0; border-radius: 50%; background: transparent; color: var(--text-3); font-size: 14px; line-height: 1; cursor: pointer; }
.notice-close:hover { background: color-mix(in srgb, var(--text-3) 16%, transparent); color: var(--text); }
.notice-chat { font-size: 14px; font-weight: 600; line-height: 1.35; color: var(--text); overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.notice-foot { display: flex; align-items: center; gap: 10px; }
.notice-by { display: inline-flex; align-items: center; gap: 7px; min-width: 0; font-size: 12px; color: var(--text-2); }
.notice-by .avatar { flex: none; }
.notice-by span:last-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.notice-open { margin-left: auto; flex: none; border: 0; background: transparent; padding: 2px 0; font-family: var(--mono); font-size: 10px; font-weight: 600; letter-spacing: .14em; color: var(--phosphor); cursor: pointer; }
.notice-open:hover { text-decoration: underline; text-underline-offset: 3px; }
/* The time it has left, as a hairline along the bottom. Held while the pointer is over the card. */
.notice-life { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: color-mix(in srgb, var(--phosphor) 55%, transparent); transform-origin: left; animation: notice-life linear forwards; }
.notice.failed .notice-life { background: color-mix(in srgb, var(--danger) 55%, transparent); }
.notice.held .notice-life { animation-play-state: paused; }
@keyframes notice-life { from { transform: scaleX(1); } to { transform: scaleX(0); } }
@keyframes notice-in { from { opacity: 0; transform: translateX(-14px); } to { opacity: 1; transform: none; } }
@keyframes notice-out { to { opacity: 0; transform: translateX(-10px); } }
@media (prefers-reduced-motion: reduce) { .notice, .notice.leaving { animation: none; } .notice-life { display: none; } }
@media (max-width: 560px) { .notices { left: 16px; top: auto; bottom: 120px; width: calc(100vw - 32px); } }
.toast { position: fixed; left: var(--composer-center, 50%); bottom: calc(100vh - var(--composer-top, 70vh) + 22px); transform: translateX(-50%); text-align: center; padding: 9px 14px; animation: toast-in calc(220ms * var(--motion-scale)) ease; z-index: 40; border-radius: 12px; border: 1px solid color-mix(in srgb, var(--danger) 40%, transparent); background: var(--panel); color: var(--danger); font-size: 13px; box-shadow: var(--shadow); max-width: min(560px, calc(100% - 32px)); overflow-wrap: anywhere; }

@keyframes toast-in { from { opacity: 0; transform: translate(-50%, 6px); } to { opacity: 1; transform: translate(-50%, 0); } }

@media (max-width: 680px) {
  .bar { flex-wrap: wrap; gap: 10px; }
  .project { display: none; }
  .row { max-width: 96%; }
  .who .reply { max-width: 150px; }
  .system .gauge { width: 160px; }
}
/* A conversation 680 px wide beside a docked panel reads as one in a 680 px window (app.js, roomWidth);
   the bar has its own container and folds by itself. */
:where(:root.room-680) .row { max-width: 96%; }
:where(:root.room-680) .who .reply { max-width: 150px; }
:where(:root.room-680) .system .gauge { width: 160px; }

/* ================= MU/TH/UR: troubleshooting ================= */
.mother-button {
  display: inline-flex; align-items: center; gap: 7px;
  height: 26px; padding: 0 10px; border-radius: 6px;
  border: 1px solid var(--line-2); background: transparent; color: var(--text-2);
  font-family: var(--mono); font-size: 10px; letter-spacing: .18em; cursor: pointer;
}
.mother-button:hover { color: var(--phosphor); border-color: var(--phosphor); box-shadow: var(--ring-soft); }
/* Light mode: a halo that reads as light on a dark ground reads as a smudge on a pale one. The
   border and the colour already say the button is live, so the light around it stays slight. */
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) .mother-button:hover,
  :root:not([data-theme="dark"]) .tree-button:hover,
  :root:not([data-theme="dark"]) .stop-all:hover,
  :root:not([data-theme="dark"]) .chats-button:hover { box-shadow: var(--ring-soft); }
}
:root[data-theme="light"] .mother-button:hover,
:root[data-theme="light"] .tree-button:hover,
:root[data-theme="light"] .stop-all:hover,
:root[data-theme="light"] .chats-button:hover { box-shadow: var(--ring-soft); }

.mother-glyph { width: 8px; height: 8px; border: 1px solid currentColor; }
/* Every count in the bar wears the same green. Red on a counter reads as an alarm, and the
   number of conditions MU/TH/UR is holding is not one. */
.mother-count { min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; display: inline-grid; place-items: center; background: var(--phosphor); color: var(--phosphor-ink); font-size: 9px; letter-spacing: 0; }

dialog.mother { border: 0; padding: 0; margin: 0; width: 100vw; max-width: 100vw; height: 100dvh; max-height: 100dvh; background: transparent; color: var(--brew); }
dialog.mother::backdrop { background: rgba(0, 0, 0, .82); backdrop-filter: blur(6px); }
.mother-frame {
  /* Terminal.app's Homebrew profile, which is what a room like this should read as. */
  --ph: #28fe14; --ph-dim: rgba(40, 254, 20, .52); --ph-faint: rgba(40, 254, 20, .13);
  position: relative; height: 100%; overflow-y: auto;
  padding: 26px clamp(16px, 5vw, 64px) 40px;
  background:
    linear-gradient(rgba(155, 255, 102, .05) 1px, transparent 1px) 0 0 / 100% 3px,
    radial-gradient(ellipse at 50% 0%, #0a1506, #020402 70%);
  font-family: var(--mono); color: var(--ph); letter-spacing: .04em;
  text-shadow: 0 0 3px rgba(155, 255, 102, .18);
  animation: mother-on .5s ease-out;
}
@keyframes mother-on { from { opacity: 0; transform: scaleY(.96); filter: brightness(2); } to { opacity: 1; transform: none; filter: none; } }
.mother-head { display: grid; grid-template-columns: auto 1fr auto; gap: 18px; align-items: baseline; padding-bottom: 14px; border-bottom: 1px solid var(--ph-dim); }
.mother-title { font-size: clamp(22px, 4vw, 34px); font-weight: 700; letter-spacing: .24em; }
.mother-sub { font-size: 10px; letter-spacing: .22em; color: var(--ph-dim); }
.mother-close { border: 1px solid var(--ph-dim); background: transparent; color: var(--ph); font: inherit; font-size: 10px; letter-spacing: .18em; padding: 6px 10px; cursor: pointer; }
.mother-close:hover { background: var(--ph-faint); }
.mother-boot { margin: 18px 0 8px; font: inherit; font-size: 12px; line-height: 1.7; white-space: pre-wrap; min-height: 3.4em; }
.mother-boot::after { content: "█"; animation: blink 1s steps(1) infinite; margin-left: 2px; }
.mother-query { display: grid; grid-template-columns: auto 1fr auto; gap: 12px; align-items: center; padding: 10px 0; border-top: 1px solid var(--ph-faint); border-bottom: 1px solid var(--ph-faint); }
.mother-prompt { font-size: 18px; }
.mother-query input { border: 0; outline: 0; background: transparent; color: var(--ph); font: inherit; font-size: 14px; letter-spacing: .08em; text-transform: uppercase; caret-color: var(--ph); }
.mother-query input::placeholder { color: var(--ph-dim); text-transform: none; letter-spacing: .04em; }
.mother-os { display: flex; gap: 1px; border: 1px solid var(--ph-dim); }
.mother-os button { border: 0; background: transparent; color: var(--ph-dim); font: inherit; font-size: 10px; letter-spacing: .16em; padding: 6px 10px; cursor: pointer; }
.mother-os button[aria-checked="true"] { background: var(--ph); color: #041004; text-shadow: none; }
.mother-answer { margin: 14px 0 6px; font-size: 12px; letter-spacing: .14em; min-height: 1.4em; }
.mother-section h3 { margin: 0 0 12px; font-size: 10px; letter-spacing: .28em; color: var(--ph-dim); font-weight: 400; }
/* Air between the blocks of one MU/TH/UR screen: every heading after the first starts a new block. */
.mother-section { margin-top: 34px; }
.mother-section h3:not(:first-child) { margin-top: 40px; padding-top: 22px; border-top: 1px solid var(--ph-faint); }
.mother-section h3.toggle:not(:first-child) { margin-top: 40px; }
.settings .conn-grid, .settings .mother-grid { margin-bottom: 8px; }
.mother-section h3::before { content: "▌ "; color: var(--ph); }
/* A folding block carries its own glyph, so the generic bar would be a second mark saying the
   same thing. And the rule above it goes with it: a line and an icon are two ways of announcing
   «a new block starts here», and one of them is enough. */
.mother-section .fold > summary h3::before { content: none; }
.mother-section .fold > summary h3 { font-size: 11px; letter-spacing: .22em; color: var(--ph); }
.mother-section .fold[open] > summary h3 { color: var(--ph); }
/* No frame around it: a badge was a second box saying what the drawing already says. Crisp edges
   because a pixel that gets antialiased into a curve stops being a pixel. */
.pixel-icon { flex: none; display: block; line-height: 0; color: var(--ph); }
.pixel-icon svg { display: block; width: 100%; height: 100%; shape-rendering: crispEdges; }
.fold-icon { width: 13px; height: 13px; opacity: .8; transition: opacity calc(150ms * var(--motion-scale)); }
.mother-section .fold > summary:hover .fold-icon { opacity: 1; }
.mother-section .fold { padding-top: 26px; margin-top: 10px; border-top: 1px solid var(--ph-faint); }
.mother-section .fold:first-of-type { border-top: 0; padding-top: 0; }

/* A section that folds. The summary carries the same header it always had, plus a mark on the
   right when there is something behind it worth opening. */
.mother-section .fold { margin: 0; }
.mother-section .fold + .fold { margin-top: 26px; }
.mother-section .fold > summary { display: flex; align-items: center; gap: 9px; cursor: pointer; list-style: none; }
.mother-section .fold > summary::-webkit-details-marker { display: none; }
/* The button is a word, not a glyph: the panel already said EXPAND and COLLAPSE elsewhere. */
.mother-section .fold > summary .caret { margin-left: auto; font-family: var(--mono); font-size: 9px; letter-spacing: .18em; color: var(--ph); white-space: nowrap; }
.mother-section .fold > summary:hover h3 { color: var(--ph); }
.mother-section .fold > summary h3 { margin: 0; }
.mother-section .fold > summary h3:not(:first-child) { margin-top: 0; padding-top: 0; border-top: 0; }
.mother-section .fold > .fold-body { padding-top: 14px; }
.fold-badge { font-family: var(--mono); font-size: 9px; letter-spacing: .12em; padding: 2px 7px; border-radius: 999px; border: 1px solid var(--ph-dim); color: var(--ph-dim); white-space: nowrap; }
/* Red, and only red, when there is something new: that is the whole message. */
.fold-badge.urgent { border-color: var(--danger); background: var(--danger); color: #fff; }
.fold-body { padding-top: 2px; }
.mother-section .note.lead { color: rgba(210, 255, 190, .9); letter-spacing: .12em; line-height: 1.7; }
.mother-grid { display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 380px), 1fr)); }
.mother-card { border: 1px solid var(--ph-dim); padding: 14px 16px; background: rgba(2, 6, 2, .6); display: grid; gap: 8px; align-content: start; }
.mother-card.hit { border-color: var(--ph); box-shadow: inset 0 0 0 1px var(--ph-faint); }
.mother-card .tags { display: flex; gap: 8px; flex-wrap: wrap; font-size: 9.5px; letter-spacing: .18em; color: var(--ph-dim); }
.mother-card .tags .agent { color: var(--agent, var(--ph)); }
.mother-card .tags .sev-blocking { color: #ff7b72; }
.mother-card .tags .sev-transient, .mother-card .tags .sev-tunable { color: #ffd166; }
.mother-card .tags .sev-fixed, .mother-card .tags .sev-informational { color: var(--ph-dim); }
.mother-card h4 { margin: 0; font-size: 14px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
.mother-card p { margin: 0; font-size: 12px; line-height: 1.6; color: rgba(210, 255, 190, .85); text-shadow: none; }
.mother-card p b { color: var(--ph); font-weight: 400; letter-spacing: .12em; font-size: 10px; display: block; margin-bottom: 2px; }
.mother-card p.remedy { color: #eaffdf; font-size: 13px; line-height: 1.65; padding: 10px 12px; border: 1px solid var(--ph); border-left-width: 4px; background: var(--ph-faint); text-shadow: none; }
.mother-card p.remedy b { color: var(--ph); font-weight: 700; letter-spacing: .2em; }
.mother-card .actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.mother-card .actions .act { border: 1px solid var(--ph); background: color-mix(in srgb, var(--ph) 12%, transparent); color: var(--ph); font: inherit; font-size: 10.5px; letter-spacing: .16em; padding: 8px 12px; cursor: pointer; text-shadow: none; }
.mother-card .actions .act:hover { background: color-mix(in srgb, var(--ph) 24%, transparent); }
.mother-card .actions .act:disabled { opacity: .6; cursor: default; }
.mother-card .actions .note { font-size: 9px; letter-spacing: .14em; color: var(--ph-dim); }
.mother-card.hit p.remedy { box-shadow: none; animation: remedy-in calc(600ms * var(--motion-scale)) ease; }
@keyframes remedy-in { from { background: rgba(155, 255, 102, .18); } to { background: var(--ph-faint); } }
.mother-cmd { position: relative; margin: 4px 0 0; border: 1px solid var(--ph-faint); background: #000; padding: 10px 12px; }
.mother-cmd pre { margin: 0; padding-right: 30px; font: inherit; font-size: 12px; line-height: 1.6; white-space: pre-wrap; overflow-wrap: anywhere; color: var(--ph); }
.mother-cmd .c { color: var(--ph-dim); }
.mother-cmd .copy { position: absolute; top: 6px; right: 6px; display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; border: 1px solid var(--ph-faint); border-radius: 3px; background: #000; color: var(--ph-dim); padding: 0; cursor: pointer; }
.mother-cmd .copy:hover { color: var(--ph); border-color: var(--ph-dim); }
.mother-cmd .copy.done { color: var(--ph); border-color: var(--ph); }
.mother-cmd .copy:hover { color: var(--ph); border-color: var(--ph); }
/* The copy key holds only its drawing: a button rule of a sheet or a card (13px each side) used to
   reach it and leave the drawing no room, an empty square beside the command (2026-10-18). */
.mother-cmd > .copy { padding: 0 !important; min-width: 26px; }
.mother-cmd > .copy svg { flex: none; width: 13px; height: 13px; }
.mother-record { display: grid; grid-template-columns: 64px 92px 1fr auto 20px; gap: 14px; align-items: baseline; padding: 10px 0; border-bottom: 1px solid var(--ph-faint); font-size: 12px; }
.mother-record .t { color: var(--ph-dim); }
.mother-record .a { color: var(--agent, var(--ph)); text-transform: uppercase; letter-spacing: .1em; }
.mother-record .e { color: rgba(210, 255, 190, .85); text-shadow: none; overflow-wrap: anywhere; }
.mother-record .k { display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.mother-record .k button { border: 1px solid var(--ph-dim); background: transparent; color: var(--ph); font: inherit; font-size: 9.5px; letter-spacing: .12em; padding: 3px 7px; cursor: pointer; text-transform: uppercase; }
.mother-record .k button:hover { background: var(--ph-faint); }
.mother-record .k .none { color: var(--ph-dim); font-size: 9.5px; letter-spacing: .12em; }
.mother-record .e.more { cursor: pointer; }
.mother-record .e.more::after { content: ' ▸'; color: var(--ph-dim); }
.mother-record .e.more.open { white-space: pre-wrap; color: #eaffdf; }
.mother-record .e.more.open::after { content: ' ▾'; }
.mother-record .e.more:hover, .mother-record .e.more:focus-visible { color: var(--ph); outline: none; }
.mother-section h3.toggle { display: block; }
.mother-section h3.toggle::before { content: none; }
.mother-section h3.toggle button::before { content: "▌ "; color: var(--ph); }
.mother-section h3.toggle button > :first-child { flex: 1; }
.mother-section h3.toggle button { display: flex; width: 100%; justify-content: space-between; gap: 12px; border: 0; background: transparent; color: var(--ph-dim); font: inherit; letter-spacing: .28em; padding: 0; cursor: pointer; text-align: left; }
.mother-section h3.toggle button:hover { color: var(--ph); }
.mother-section h3.toggle .caret { color: var(--ph); letter-spacing: .18em; }
.mother-section.collapsed h3 { margin-bottom: 0; }
.mother-foot { margin-top: 32px; padding-top: 12px; border-top: 1px solid var(--ph-faint); font-size: 9.5px; letter-spacing: .24em; color: var(--ph-dim); text-align: center; }
@container console (max-width: 610px) {
  .mother-head { grid-template-columns: 1fr auto; }
  .mother-sub { grid-column: 1 / -1; order: 3; }
  .mother-query { grid-template-columns: auto 1fr; }
  .mother-os { grid-column: 1 / -1; }
  .mother-record { grid-template-columns: 64px 1fr; }
  .mother-record .e, .mother-record .k { grid-column: 1 / -1; }
  .mother-record .k { justify-content: flex-start; }
}

/* ================= MODULES ================= */
.modules-glyph { border-radius: 50%; }
.modules-count { min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; display: inline-grid; place-items: center; background: var(--phosphor); color: var(--phosphor-ink); font-size: 9px; letter-spacing: 0; }
/* A module card is floors, not a stack of paragraphs: who it is, what it does, what it touches,
   what it lets you set, and the switch. Each floor owns its own padding and is separated by a
   hairline, so nothing can crowd anything else. The floors stack from the top and the switch is
   pushed to the bottom — as a stretched grid the card used to spread the spare height of the
   tallest card in the row between its own rows, which is why the text drifted apart on some
   cards and not on others. */
.module-card { border: 1px solid var(--ph-dim); background: rgba(2, 6, 2, .6); display: flex; flex-direction: column; padding: 0; max-width: 760px; min-width: 0; overflow-wrap: anywhere; }
/* The switch sits on the floor of the card, not wherever the text happens to end: cards in a row
   are the same height, so their buttons line up along the bottom edge. */
.module-card > .actions { margin-top: auto; }
.module-card:not(.dev-card) > * { padding: 16px 20px; }
.module-card:not(.dev-card) > * + * { border-top: 1px solid var(--ph-faint); }
.mother-grid > * { min-width: 0; }
.module-card .head { display: grid; gap: 7px; }
.module-card .head .top { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: baseline; }
.module-card h4 { margin: 0; font-size: 16px; letter-spacing: .1em; text-transform: uppercase; }
/* The state is a state, not a button: a word and a dot, never a box you want to press. */
.module-card .state { font-family: var(--mono); font-size: 9.5px; letter-spacing: .18em; color: var(--ph-dim); white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; }
.module-card .state::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .5; }
.module-card .state.on { color: var(--ph); }
.module-card .state.on::before { opacity: 1; box-shadow: 0 0 0 2px color-mix(in srgb, var(--ph) var(--glow-a), transparent); }
.module-card .state.running { color: #ffd166; animation: blink 1s infinite; }
/* Switched off, the whole card steps back — except the switch that turns it on again. */
.module-card.off { border-color: var(--ph-faint); }
.module-card.off > *:not(.actions) { opacity: .52; }
.module-card .detail { font-size: 10px; letter-spacing: .12em; color: var(--ph-dim); line-height: 1.5; }
.module-card p { margin: 0; font-size: 12.5px; line-height: 1.6; color: rgba(210, 255, 190, .85); text-shadow: none; }
.module-card ul { margin: 0; padding-left: 18px; font-size: 12px; line-height: 1.7; color: rgba(210, 255, 190, .8); text-shadow: none; }
.module-card .actions { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.module-card .actions button { border: 1px solid var(--ph); background: transparent; color: var(--ph); font: inherit; font-size: 10.5px; letter-spacing: .18em; padding: 8px 14px; cursor: pointer; }
.module-card .actions button.primary { background: var(--ph); color: #041004; text-shadow: none; }
.module-card .actions button.remove-module { border-color: color-mix(in srgb, var(--danger) 65%, transparent); color: var(--danger); }
.module-card .actions button.remove-module:hover { background: color-mix(in srgb, var(--danger) 12%, transparent); }
.module-card .actions button:disabled { opacity: .4; cursor: default; }
.module-card .actions .note { font-size: 10px; letter-spacing: .12em; color: var(--ph-dim); }
.module-card .confirm { border: 1px dashed var(--ph); padding: 12px 14px; display: grid; gap: 10px; }
.module-card .confirm .warn { color: #ffd166; font-size: 11px; letter-spacing: .12em; }
/* What an install printed, in the same box as the commands beside it (2026-10-18): the page's own
   ground and ink, in the code face. It was a black terminal painted with the theme's phosphor,
   which on the light theme is a dark green: dark grey on black, unreadable. */
.module-log { max-height: 260px; overflow-y: auto; margin: 0; padding: 10px 12px; border: 0; border-radius: 10px; background: color-mix(in srgb, var(--text) 5%, transparent); box-shadow: inset 0 1px 2px rgba(0, 0, 0, .14); font-family: var(--mono); font-size: 11.5px; line-height: 1.6; letter-spacing: 0; text-transform: none; white-space: pre-wrap; overflow-wrap: anywhere; color: var(--text-2); }
.module-log .err { color: var(--crit, #d93a3a); }
.system.module { color: var(--phosphor); }
.system.module .cmd { text-transform: none; letter-spacing: 0; color: var(--text-2); display: block; margin-top: 4px; }
.system.module.failed { color: var(--danger); }

/* ================= delegation ================= */
.plan-card { margin: 8px 0 4px; border: 1px dashed var(--line-2); border-radius: 12px; padding: 10px 12px 10px 14px; background: color-mix(in srgb, var(--panel) 70%, transparent); }
.plan-label { display: block; font-family: var(--mono); font-size: 9.5px; letter-spacing: .2em; text-transform: uppercase; color: var(--text-3); margin-bottom: 6px; }
.plan-card ol { margin: 0; padding-left: 18px; font-size: 13.5px; }
.plan-card li { margin: 4px 0; }
.plan-card li b { color: var(--agent); font-family: var(--mono); font-size: 11px; letter-spacing: .06em; }
.row.delegated .bubble { background: color-mix(in srgb, var(--bubble) 75%, transparent); border: 1px dashed var(--line-2); box-shadow: none; font-size: 14px; }
.who .to-agent { color: var(--agent); }
.system.plan .stop { margin-left: 10px; border: 1px solid var(--crit); background: transparent; color: var(--crit); font: inherit; font-size: 9.5px; letter-spacing: .16em; padding: 2px 8px; cursor: pointer; vertical-align: middle; }
.system.plan .stop:hover { background: color-mix(in srgb, var(--crit) 15%, transparent); }
.system.plan .stop:disabled { opacity: .4; cursor: default; }

/* ================= STOPALL ================= */
.stop-all { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 10px; white-space: nowrap; flex: none; border-radius: 6px; border: 1px solid var(--line-2); background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 10px; letter-spacing: .18em; cursor: default; opacity: .55; transition: color calc(300ms * var(--motion-scale)), border-color calc(300ms * var(--motion-scale)), opacity calc(300ms * var(--motion-scale)); }
.stop-all:disabled { cursor: default; }
.stop-all.armed { opacity: 1; cursor: pointer; border-color: var(--terror); background: color-mix(in srgb, var(--terror) 12%, transparent); color: var(--terror); text-shadow: none; animation: blink 1.4s infinite; }
.stop-all.armed:hover { background: var(--terror); color: #fff; text-shadow: none; animation: none; }
/* The version alert: an amber hairline, a soft fill, no glow. It should read as information, not alarm. */
.update-pill { opacity: 1; cursor: pointer; border-color: color-mix(in srgb, var(--warn) 45%, transparent); background: color-mix(in srgb, var(--warn) 9%, transparent); color: var(--warn); text-shadow: none; transition: background-color calc(220ms * var(--motion-scale)) ease, border-color calc(220ms * var(--motion-scale)) ease, color calc(220ms * var(--motion-scale)) ease, transform calc(160ms * var(--motion-scale)) ease; }
.update-pill:hover { background: color-mix(in srgb, var(--warn) 16%, transparent); border-color: color-mix(in srgb, var(--warn) 70%, transparent); }
.update-pill:active { transform: scale(.98); }
.update-pill:focus-visible { outline: 2px solid color-mix(in srgb, var(--warn) 60%, transparent); outline-offset: 2px; }
.update-pill .update-glyph { border-radius: 50%; opacity: .9; }
.system.alert { color: var(--terror); text-shadow: none; letter-spacing: .14em; animation: terror-in 1.4s steps(3, end) 1; }
.system.alert b { color: var(--terror); }
.system.alert .cmd { display: inline-block; margin-left: 8px; padding: 1px 8px; border: 1px solid var(--terror); letter-spacing: .2em; }
.system.halted { color: var(--terror); }
.composer.stopall textarea { color: var(--terror); letter-spacing: .12em; text-transform: uppercase; }

/* ================= connections & settings (inside MU/TH/UR) ================= */
.mother-actions { display: flex; gap: 8px; }
.mother-close[aria-pressed="true"] { background: var(--ph); color: #041004; text-shadow: none; }
.settings .conn-grid { display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 340px), 1fr)); }
.settings .conn-grid { align-items: stretch; }
.conn-card { border: 1px solid var(--ph-dim); padding: 16px 18px 18px; background: rgba(2, 6, 2, .6); display: grid; grid-template-rows: auto; gap: 14px; min-width: 0; overflow-wrap: anywhere; align-content: start; }
.conn-card .head { display: flex; align-items: center; gap: 10px; align-self: center; }
.conn-card .meta { align-self: start; }
.conn-card .row { align-self: start; padding-top: 4px; }
.conn-card .slot { min-height: 0; }
.conn-card .mother-cmd { margin: 0; } .conn-card .slot { display: grid; gap: 8px; }
.conn-card label { align-self: end; margin-top: 4px; }
.conn-card .head .avatar { --size: 26px; }
.conn-card h4 { margin: 0; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--agent, var(--ph)); }
.conn-card .vendor { font-size: 9.5px; letter-spacing: .16em; color: var(--ph-dim); }
.conn-card .meta { font-size: 11px; line-height: 1.6; color: rgba(210, 255, 190, .8); text-shadow: none; }
.conn-card .row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.conn-card button { border: 1px solid var(--ph-dim); background: transparent; color: var(--ph); font: inherit; font-size: 9.5px; letter-spacing: .16em; padding: 6px 10px; cursor: pointer; }
.conn-card button.primary { background: var(--ph); color: #041004; text-shadow: none; border-color: var(--ph); }
.conn-card button:disabled { opacity: .4; cursor: default; }
.conn-card label { display: grid; gap: 4px; font-size: 9.5px; letter-spacing: .16em; color: var(--ph-dim); }
/* A textarea is a field like any other here. It was left out of this rule, so what you typed
   into it was drawn in the page's own colour: invisible on this ground. */
.conn-card input, .conn-card select { border: 1px solid var(--ph-dim); background: #000; color: var(--ph); font: inherit; font-size: 12px; padding: 6px 8px; letter-spacing: .04em; min-width: 0; }
.conn-card input:focus { outline: 1px solid var(--ph); }
.conn-card .login-log { max-height: 140px; overflow-y: auto; border: 1px solid var(--ph-faint); background: #000; padding: 8px 10px; font-size: 11px; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere; }
.conn-card .login-log a { color: var(--ph); }
:is(.settings, .memory-panel) .note { font-size: 10px; letter-spacing: .1em; color: var(--ph-dim); }
.system.login { color: var(--phosphor); }
.system.login.failed { color: var(--danger); }

/* ================= agent popover (click on a sphere) ================= */
.agents .avatar { cursor: pointer; }
.agents .avatar.open { box-shadow: 0 0 0 2px var(--bg), 0 0 0 3.5px var(--agent); }
.agent-pop { position: fixed; z-index: 30; min-width: 250px; max-width: min(340px, calc(100vw - 32px)); padding: 12px 14px 12px; border: 1px solid var(--line-2); border-radius: 14px; background: var(--panel); color: var(--text); box-shadow: var(--shadow); font-family: var(--mono); font-size: 11px; letter-spacing: .04em; }
.agent-pop .head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.agent-pop .head b { color: var(--agent); letter-spacing: .14em; text-transform: uppercase; font-size: 11px; }
.agent-pop .head .vendor { color: var(--text-3); font-size: 10px; margin-left: auto; }
.agent-pop .big { font-size: 22px; letter-spacing: -.01em; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", Inter, sans-serif; font-weight: 600; color: var(--text); }
.agent-pop .big small { font-size: 10px; color: var(--text-3); letter-spacing: .12em; text-transform: uppercase; margin-left: 6px; font-family: var(--mono); font-weight: 400; }
.agent-pop .gauge { height: 3px; background: var(--line-2); border-radius: 2px; overflow: hidden; margin: 6px 0 10px; }
.agent-pop .gauge i { display: block; height: 100%; width: 0; background: var(--agent); }
.agent-pop .gauge.hot i { background: var(--crit); }
.agent-pop dl { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; }
.agent-pop dt { color: var(--text-3); text-transform: uppercase; letter-spacing: .12em; font-size: 9.5px; }
.agent-pop dd { margin: 0; color: var(--text-2); text-align: right; }
.agent-pop dd.on { color: var(--phosphor); } .agent-pop dd.off { color: var(--danger); }
.agent-pop .foot { margin-top: 10px; font-size: 9.5px; color: var(--text-3); letter-spacing: .1em; text-transform: uppercase; }

/* model chip & menu in the composer */
.picker .model-chip { margin-left: 4px; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); font: inherit; font-family: var(--mono); font-size: 10px; letter-spacing: .08em; text-transform: none; padding: 2px 8px; border-radius: 999px; cursor: pointer; }
.picker .model-chip:hover { color: var(--agent, var(--text)); border-color: var(--agent, var(--line-2)); }
/* Effort chip: a signal meter in the agent's colour, beside the model. Unset, it is a ghost of
   the CLI's own level; set, it fills. No glow at any level: the meter already says how high, and
   light that bleeds says nothing the bars do not. */
.picker .pick-label > .effort-chip { flex: 0 0 auto; }
.picker .effort-chip { --tone: var(--agent, var(--phosphor)); display: inline-flex; align-items: center; gap: 8px; height: 22px; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); font: inherit; font-family: var(--mono); font-size: 10px; letter-spacing: .08em; text-transform: none; padding: 0 10px 0 9px; border-radius: 999px; cursor: pointer; transition: color calc(200ms * var(--motion-scale)), border-color calc(200ms * var(--motion-scale)), background calc(200ms * var(--motion-scale)); }
.picker .effort-chip:hover { color: var(--text); border-color: color-mix(in srgb, var(--tone) 45%, var(--line-2)); }
.picker .effort-chip.set { color: var(--text); border-color: color-mix(in srgb, var(--tone) 38%, var(--line-2)); background: color-mix(in srgb, var(--tone) 7%, transparent); }
.picker .effort-chip .caret { color: var(--text-3); font-size: 9px; }
.effort-meter { --tone: var(--agent, var(--phosphor)); display: inline-flex; align-items: flex-end; gap: 2px; height: 10px; }
.effort-meter i { width: 3px; border-radius: 1px; background: color-mix(in srgb, var(--text-3) 45%, transparent); transition: background calc(200ms * var(--motion-scale)); }
.effort-meter i:nth-child(1) { height: 30%; } .effort-meter i:nth-child(2) { height: 47%; } .effort-meter i:nth-child(3) { height: 64%; } .effort-meter i:nth-child(4) { height: 82%; } .effort-meter i:nth-child(5) { height: 100%; }
.effort-meter i.on { background: var(--tone); }
.effort-meter.ghost i.on { background: color-mix(in srgb, var(--tone) 45%, var(--text-3)); }

.model-menu.effort-menu { --tone: var(--agent, var(--phosphor)); width: min(400px, calc(100vw - 24px)); padding: 12px 14px 10px; }
.effort-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 2px 2px 12px; }
/* The title on the left and AUTO in the right corner, on the same line (2026-10-14): the title
   keeps its room and is cut before it is covered; a long AUTO reading is cut instead of the title. */
.effort-head .model-menu-title { flex: 1 1 auto; min-width: 0; margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; line-height: 1.4; }
.effort-head .effort-auto { margin-left: auto; max-width: 52%; }
.effort-head .effort-auto .hint { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* Letting the CLI decide: a small switch beside the title, lit while it is the choice. */
.effort-auto { display: inline-flex; align-items: center; gap: 7px; flex: none; height: 26px; padding: 0 10px 0 9px; border: 1px solid var(--line-2); border-radius: 999px; background: transparent; color: var(--text-2); font: inherit; cursor: pointer; transition: color var(--motion) var(--ease-out), border-color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out); }
.effort-auto .auto-dot { width: 7px; height: 7px; border-radius: 50%; border: 1.5px solid currentColor; transition: background-color var(--motion) var(--ease-out); }
.effort-auto .name { font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .14em; }
.effort-auto .hint { font-family: var(--read); font-size: 11.5px; color: var(--text-3); }
.effort-auto:hover, .effort-auto:focus-visible { color: var(--text); border-color: color-mix(in srgb, var(--tone) 45%, var(--line-2)); outline: 0; }
.effort-auto.current { color: var(--tone); border-color: color-mix(in srgb, var(--tone) 55%, transparent); background: color-mix(in srgb, var(--tone) 9%, transparent); }
.effort-auto.current .auto-dot { background: currentColor; }

/* What the level means, above the track, in the reading face; it turns a page when it changes. */
.effort-readout { display: grid; grid-template-columns: minmax(0, 1fr) 112px; grid-template-rows: auto auto; gap: 2px 18px; align-items: start; padding: 12px 14px; border-radius: 12px; background: var(--panel-2, color-mix(in srgb, var(--text) 4%, transparent)); }
.effort-readout .name { grid-column: 1; font-family: var(--sans); font-size: 15px; font-weight: 600; letter-spacing: .01em; color: var(--tone); }
.effort-readout .hint { grid-column: 1; font-family: var(--read); font-size: 12.5px; line-height: 1.45; color: var(--text-2); min-height: 2.9em; }
.effort-readout .meters { grid-column: 2; grid-row: 1 / 3; align-self: center; display: grid; gap: 10px; }
.effort-readout .effort-gauge { display: grid; gap: 4px; }
.effort-readout .effort-gauge .what { font-family: var(--mono); font-size: 8.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-3); }
.effort-readout .effort-gauge-track { position: relative; display: block; height: 5px; border-radius: 5px; background: var(--line-2); overflow: hidden; }
.effort-readout .effort-gauge-track i { position: absolute; inset: 0 auto 0 0; width: 0; border-radius: inherit; background: var(--tone); transition: width calc(320ms * var(--motion-scale)) var(--ease-glide); }
.effort-readout .effort-gauge:last-child .effort-gauge-track i { background: color-mix(in srgb, var(--warn) 75%, var(--tone)); }

/* The slider: a rail, its fill up to the thumb, a tick per level, the words under them. */
.effort-slider { --pos: 0; position: relative; margin: 18px 4px 2px; padding: 0 10px; outline: 0; touch-action: none; }
.effort-slider .rail { position: relative; height: 26px; cursor: pointer; }
.effort-slider .rail::before { content: ''; position: absolute; left: 0; right: 0; top: 50%; height: 6px; margin-top: -3px; border-radius: 6px; background: var(--line-2); }
.effort-slider .fill { position: absolute; left: 0; top: 50%; height: 6px; margin-top: -3px; width: calc(var(--pos) * 100%); border-radius: 6px; background: linear-gradient(90deg, color-mix(in srgb, var(--tone) 35%, transparent), var(--tone)); transition: width calc(260ms * var(--motion-scale)) var(--ease-glide); }
.effort-slider .tick { position: absolute; top: 50%; left: calc(var(--at) * 100%); width: 6px; height: 6px; margin: -3px 0 0 -3px; border-radius: 50%; background: var(--panel); box-shadow: 0 0 0 1.5px var(--line-2); pointer-events: none; }
.effort-slider .tick.cli::after { content: 'CLI'; position: absolute; left: 50%; bottom: 12px; transform: translateX(-50%); font-family: var(--mono); font-size: 7.5px; letter-spacing: .12em; color: var(--text-3); }
.effort-slider .thumb { position: absolute; top: 50%; left: calc(var(--pos) * 100%); width: 20px; height: 20px; margin: -10px 0 0 -10px; border-radius: 50%; background: var(--tone); box-shadow: 0 0 0 4px color-mix(in srgb, var(--tone) 20%, transparent), 0 4px 12px -4px rgba(0, 0, 0, .45); transition: left calc(260ms * var(--motion-scale)) var(--ease-glide), transform calc(160ms * var(--motion-scale)) var(--ease-out), box-shadow calc(160ms * var(--motion-scale)) var(--ease-out); pointer-events: none; }
.effort-slider.live .thumb, .effort-slider.live .fill { transition: none; }
.effort-slider.live .thumb, .effort-slider .rail:hover .thumb { transform: scale(1.12); }
.effort-slider:focus-visible .thumb { box-shadow: 0 0 0 4px color-mix(in srgb, var(--tone) 35%, transparent), 0 4px 12px -4px rgba(0, 0, 0, .45); }
/* Auto: the CLI's level, held hollow. */
.effort-slider.auto .thumb { background: var(--panel); box-shadow: 0 0 0 2px var(--tone), 0 4px 12px -4px rgba(0, 0, 0, .35); }
.effort-slider.auto .fill { background: color-mix(in srgb, var(--tone) 30%, transparent); }
.effort-slider .labels { position: relative; height: 18px; margin-top: 4px; }
.effort-slider .stop { position: absolute; left: calc(var(--at) * 100%); transform: translateX(-50%); padding: 2px 4px; border: 0; background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 9.5px; letter-spacing: .04em; white-space: nowrap; cursor: pointer; transition: color var(--motion-fast) var(--ease-out); }
.effort-slider .stop:first-child { transform: translateX(-20%); } .effort-slider .stop:last-child { transform: translateX(-80%); }
.effort-slider .stop:hover, .effort-slider .stop.on { color: var(--text); }
.effort-slider .stop.on { color: var(--tone); font-weight: 600; }
.effort-slider .effort-ends { display: flex; justify-content: space-between; margin: 8px -10px 0; font-family: var(--mono); font-size: 8.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-3); }
.effort-slider .effort-ends span:first-child::before { content: '‹ '; } .effort-slider .effort-ends span:last-child::after { content: ' ›'; }
.effort-menu .model-note { margin: 12px 4px 2px; font-family: var(--read); font-size: 11.5px; letter-spacing: 0; line-height: 1.5; color: var(--text-3); }
.who .badge.effort { text-transform: none; }
/* Permission mode chip: TO @agent  #1 EXCHANGE ▾  model ▾ */
.picker .mode-chip { margin-left: 4px; border: 1px solid var(--mode); background: transparent; color: var(--mode); font: inherit; font-family: var(--mono); font-size: 10px; letter-spacing: .1em; padding: 2px 9px; border-radius: 999px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; transition: background calc(200ms * var(--motion-scale)), color calc(200ms * var(--motion-scale)), border-color calc(200ms * var(--motion-scale)); }
.picker .mode-chip b { font-weight: 700; color: inherit; }
.picker .mode-chip:hover { background: color-mix(in srgb, var(--mode) 12%, transparent); }
.picker .mode-chip.m0 { --mode: var(--mode-0); }
.picker .mode-chip.m1 { --mode: var(--mode-1); }
.picker .mode-chip.m2 { --mode: var(--mode-2); }
.picker .mode-chip.m3 { --mode: var(--mode-3); }
.picker .mode-chip.m4 { --mode: var(--mode-4); }
/* Typed in the message, not armed yet: the dashed line the room uses for what is still to happen. */
.picker .mode-chip.pending { border-style: dashed; }
.mode-menu { width: min(380px, calc(100vw - 24px)); padding: 12px; }
/* One line. The header carries two facts — whose mode, and how far it may go — and both have to
   be readable at once; the sentence about this message living only in this message is on the chip
   that opens this menu. Short enough that the ellipsis below should never have anything to do. */
.mode-menu .model-menu-title { margin: 4px 10px 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mode-menu .mode-ladder { display: grid; gap: 2px; }
.mode-menu .mode-option { --mode: var(--text-2); display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 14px; align-items: baseline; width: 100%; text-align: left; border: 0; background: transparent; color: var(--text); font: inherit; font-family: var(--mono); padding: 12px 10px; border-radius: 8px; cursor: pointer; transition: background calc(150ms * var(--motion-scale)), opacity calc(150ms * var(--motion-scale)); }
.mode-menu .mode-option + .mode-option { border-top: 1px solid var(--line); border-radius: 0 0 8px 8px; }
.mode-menu .mode-option:hover { background: var(--line); }
.mode-menu .mode-option.o0.current { --mode: var(--mode-0); }
.mode-menu .mode-option.o1.current { --mode: var(--mode-1); }
.mode-menu .mode-option.o2.current { --mode: var(--mode-2); }
.mode-menu .mode-option.o3 { --mode: var(--mode-3); }
.mode-menu .mode-option.o4 { --mode: var(--mode-4); }
.mode-menu .mode-option.locked { opacity: .45; }
.mode-menu .mode-option.locked:hover { opacity: 1; }
.mode-menu .mode-option:disabled { opacity: .3; cursor: default; }
.mode-menu .mode-option:disabled:hover { background: transparent; }
.mode-menu .mode-option .n { font-weight: 700; color: var(--mode); font-size: 12px; }
.mode-menu .mode-option .body { display: grid; gap: 3px; min-width: 0; }
.mode-menu .mode-option .name { font-size: 11px; font-weight: 700; letter-spacing: .14em; color: var(--mode); }
.mode-menu .mode-option.current .name, .mode-menu .mode-option:hover .name { color: var(--mode); }
.mode-menu .mode-option:not(.current):not(.o3):not(.o4) .name { color: var(--text); }
.mode-menu .mode-option .body { gap: 5px; }
.mode-menu .mode-option .hint { display: block; font-size: 10.5px; line-height: 1.5; letter-spacing: 0; color: var(--text-2); text-transform: none; font-family: var(--sans, inherit); }
.mode-menu .mode-option .tag { display: inline-flex; align-items: center; gap: 7px; font-size: 8.5px; font-weight: 700; letter-spacing: .16em; color: var(--mode); white-space: nowrap; align-self: center; margin-left: 4px; }
.mode-menu .mode-option .tag.raise { border: 1px solid var(--mode); border-radius: 999px; padding: 3px 9px; }
.mode-menu .mode-option .tag .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--mode); box-shadow: 0 0 0 2px color-mix(in srgb, var(--mode) var(--glow-a), transparent); animation: mode-dot 2.2s ease-in-out infinite; }
@keyframes mode-dot { 0%, 100% { opacity: 1; } 50% { opacity: .45; } }
@media (prefers-reduced-motion: reduce) { .mode-menu .mode-option .tag .dot { animation: none; } }
/* Composer wears the mode */
.composer.ghost .field { border-style: dashed; border-color: var(--mode-0); box-shadow: none; opacity: .92; }
.composer.ghost .crew-label { color: var(--mode-0); }
.composer.ghost .editor textarea { color: transparent; }
.composer.ghost .editor .highlight { color: var(--text-2); font-style: italic; }
.composer.control .field { border-color: var(--terror); box-shadow: 0 0 0 3px color-mix(in srgb, var(--terror) 16%, transparent); }
.composer.control .crew-label { color: var(--terror); text-shadow: none; }
/* AIRLOCK: the same width as CONTROL, a cold ring instead of the red one. */
.composer.airlock .field { border-color: var(--mode-4); box-shadow: 0 0 0 3px color-mix(in srgb, var(--mode-4) 16%, transparent); }
.composer.airlock .crew-label { color: var(--mode-4); text-shadow: none; }
.composer.intruder .crew-label { color: var(--terror); text-shadow: none; animation: blink 1.6s steps(1) infinite; }
/* Mode badges on bubbles and plan steps */
.who .badge.mode { font-weight: 700; letter-spacing: .1em; }
.who .badge.mode.m0 { color: var(--mode-0); border-color: color-mix(in srgb, var(--mode-0) 50%, transparent); } .who .badge.mode.m1 { color: var(--mode-1); border-color: color-mix(in srgb, var(--mode-1) 45%, transparent); } .who .badge.mode.m2 { color: var(--mode-2); border-color: color-mix(in srgb, var(--mode-2) 50%, transparent); } .who .badge.mode.m3 { color: var(--mode-3); border-color: var(--mode-3); } .who .badge.mode.m4 { color: var(--mode-4); border-color: var(--mode-4); }
.row.ghost .bubble { border: 1px dashed var(--line-2); background: transparent; opacity: .85; }
.row.ghost.user .bubble { background: transparent; color: var(--text); border-color: var(--text-3); }
/* An order BISHOP brought (via 'bishop'): not the human's words, so not the human's bubble. */
.row.user.relayed .bubble { background: color-mix(in srgb, var(--panel) 90%, var(--user) 10%); color: var(--text); border: 1px solid color-mix(in srgb, var(--user) 40%, var(--line-2)); }
.row.user.relayed .bubble th, .row.user.relayed .bubble td { border-color: var(--line-2); }
.row.ghost .stamp::after { content: ' · not recorded'; color: var(--text-3); }
.system.plan .step-mode { margin-left: 3px; font-weight: 700; }
.system.plan .step-mode.m1 { color: var(--mode-1); } .system.plan .step-mode.m2 { color: var(--mode-2); }
/* Emergency command override: a small MOTHER terminal */
/* Only an open override is laid out; a closed <dialog> must stay display:none. */
dialog.override[open] { display: grid; place-items: center; }
.override-frame { width: min(680px, 92vw); height: auto; min-height: 0; padding: 26px 30px 22px; border: 1px solid var(--ph-dim); box-shadow: 0 0 0 1px var(--ph-faint), 0 24px 60px rgba(0, 0, 0, .5); animation: mother-on .4s ease; }
/* The override is narrower than MU/TH/UR's own screen, and the title takes most of a row: beside it
   the subtitle was squeezed into a column a word wide. It reads as one line under the title. */
.override .mother-head { grid-template-columns: 1fr auto; row-gap: 8px; }
.override .mother-head .mother-title { grid-column: 1; grid-row: 1; }
.override .mother-head .mother-close { grid-column: 2; grid-row: 1; align-self: center; }
.override .mother-head .mother-sub { grid-column: 1 / -1; grid-row: 2; line-height: 1.5; }
/* On a phone the label, the field and ARM did not fit one row and ARM left the screen. */
.override-reply { min-height: 22px; letter-spacing: .14em; }
.override-reply.denied { color: #ff7b72; text-shadow: 0 0 3px rgba(255, 123, 114, .25); animation: terror-in .8s steps(3, end) 1; }
.override-reply.granted { color: var(--ph); text-shadow: 0 0 3px rgba(155, 255, 102, .25); }
/* MOTHER answering a name that is not this project's: her lines, and the count. */
.override-reply .line { display: block; line-height: 1.6; }
.override-reply .strike { display: block; margin-top: 6px; font-size: 9px; letter-spacing: .18em; color: var(--warn); text-shadow: none; }
.override-frame.shake { animation: override-shake .35s ease; }
@keyframes override-shake { 0%, 100% { transform: none; } 25% { transform: translateX(-6px); } 50% { transform: translateX(6px); } 75% { transform: translateX(-3px); } }
.model-menu { position: fixed; z-index: 40; width: min(320px, calc(100vw - 24px)); padding: 10px; border: 1px solid var(--line-2); border-radius: 14px; background: var(--panel); box-shadow: var(--shadow); font-family: var(--mono); font-size: 11px; letter-spacing: .04em; color: var(--text); }
.model-menu-title { font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-3); margin: 2px 4px 8px; }
.model-menu-title b { color: var(--agent); }
.model-list { display: grid; gap: 2px; max-height: 260px; overflow-y: auto; }
.model-option { text-align: left; border: 0; border-radius: 8px; background: transparent; color: var(--text); font: inherit; font-family: var(--mono); font-size: 12px; padding: 7px 10px; cursor: pointer; }
.model-option:hover { background: color-mix(in srgb, var(--agent) 12%, transparent); }
.model-option.current { background: color-mix(in srgb, var(--agent) 20%, transparent); color: var(--agent); }
.model-custom { margin-top: 8px; }
.model-custom input { width: 100%; border: 1px solid var(--line-2); border-radius: 8px; background: var(--bg); color: var(--text); font: inherit; font-family: var(--mono); font-size: 11px; padding: 6px 9px; outline: 0; }
.model-custom input:focus { border-color: var(--agent, var(--phosphor)); }
.model-note { margin: 8px 4px 0; font-size: 9.5px; color: var(--text-3); line-height: 1.5; }
.who .badge.model { color: var(--agent); border-color: color-mix(in srgb, var(--agent) 50%, transparent); text-transform: none; letter-spacing: .04em; }

/* ================= attachments, inline files & viewer ================= */
.field { grid-template-columns: auto minmax(0, 1fr) auto auto auto auto; }
.attach { width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--text-3); cursor: pointer; display: grid; place-items: center; }
.attach:hover { color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); }
.attach svg { width: var(--ico-md); height: var(--ico-md); }
.composer.dropping .field { border-color: var(--phosphor); box-shadow: 0 0 0 3px color-mix(in srgb, var(--phosphor) 16%, transparent); }
.attachments { display: flex; gap: 8px; flex-wrap: wrap; padding: 0 6px; }
.attachment-chip { display: inline-flex; align-items: center; gap: 8px; padding: 4px 6px 4px 4px; border: 1px solid var(--line-2); border-radius: 10px; background: var(--panel); font-family: var(--mono); font-size: 10.5px; color: var(--text-2); max-width: 260px; }
.attachment-chip img { width: 28px; height: 28px; object-fit: cover; border-radius: 6px; }
.attachment-chip .kind { width: 28px; height: 28px; border-radius: 6px; display: grid; place-items: center; background: color-mix(in srgb, var(--phosphor) 12%, transparent); color: var(--phosphor); font-size: 9px; letter-spacing: .08em; }
.attachment-chip .name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.attachment-chip .remove { border: 0; background: transparent; color: var(--text-3); cursor: pointer; font-size: 13px; padding: 0 2px; }
.attachment-chip .remove:hover { color: var(--danger); }
.attachment-chip.uploading { opacity: .6; }
.bubble .files { display: flex; gap: 8px; flex-wrap: wrap; margin: 8px 0 0; }
.bubble .file-tile { display: inline-flex; align-items: center; gap: 8px; padding: 6px 10px 6px 6px; border-radius: 10px; border: 1px solid rgba(0,0,0,.15); background: rgba(0,0,0,.08); font-family: var(--mono); font-size: 10.5px; cursor: pointer; color: inherit; max-width: 100%; }
.assistant .bubble .file-tile { border-color: var(--line-2); background: var(--panel); color: var(--text-2); }
.bubble .file-tile img { width: 120px; height: 90px; object-fit: cover; border-radius: 6px; display: block; }
.bubble .file-tile.image { padding: 0; border: 0; background: transparent; }
.bubble img.inline { max-width: 100%; max-height: 420px; border-radius: 12px; display: block; margin: 6px 0; cursor: zoom-in; }
.bubble a.file-link { color: var(--agent, var(--phosphor)); text-decoration: none; border-bottom: 1px dashed currentColor; font-family: var(--mono); font-size: .92em; cursor: pointer; }
/* A picture from elsewhere waits as a link: it is fetched only when someone opens it. */
.bubble a.image-away { display: inline-flex; align-items: center; gap: 6px; padding: 2px 9px; border-radius: 999px; font-size: .88em; text-decoration: none; background: color-mix(in srgb, currentColor 10%, transparent); }
dialog.viewer { border: 0; padding: 0; width: min(1100px, 96vw); max-width: 96vw; height: min(88vh, 900px); background: var(--panel); color: var(--text); border-radius: 16px; box-shadow: var(--shadow); }
/* With the browser docked the conversation lives in half a screen, and a bar built for a wide one
   piles its pieces on top of each other.

   The breakpoints are the BAR'S OWN WIDTH, not the window's. That distinction is the whole fix:
   the window stays 2000px wide while the column shrinks to 500, so every @media rule written
   against the viewport sat there never firing while the pieces overlapped. A container query asks
   the element how much room IT has, which is the only question that was ever relevant.

   And a flex child with min-width:auto refuses to shrink below its content and pushes its
   neighbour out of the row instead. That is what put MADRE on top of the agent dots. */
.bar { container-type: inline-size; container-name: bar; }
/* Only what can truncate is allowed to shrink. A button given min-width:0 shrinks below its own
   label and lets it spill past the border onto the next button — which looks exactly like two
   controls overlapping, because they are. Buttons hold their size and lose their words instead,
   at the widths below. */
.bar > * { flex: none; }
/* Everything but the names holds its size. The names are the only thing in the bar that can lose
   characters without losing meaning, so they are the only thing allowed to give — and the group
   that holds them has to be allowed to give too, or its children never get the chance. */
.bar > .bar-left { flex: 0 1 auto; min-width: 0; overflow: hidden; }
/* The project's name holds; the room's title is the one that gives. A project is where you are
   and there is one of them; a room title is a sentence somebody typed and there are seven. */
.bar .project { flex: none; white-space: nowrap; }
.bar .chat-here { min-width: 0; flex: 0 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* No overflow:hidden here. The quota ring is drawn 3px outside each avatar's own box, so hiding
   the overflow of the row that holds them is exactly what shaved a flat edge off every sphere. */
.bar .agents { flex-wrap: nowrap; }

/* The order of loss. Nothing disappears: everything that had a word keeps its glyph, so the bar
   stops being a row of labels and becomes a row of buttons. What a glyph cannot carry — the name
   of the project, the name of the room — is what falls last.

   The crew is the exception that needs markup: five spheres cannot be compacted by CSS into one
   button, so there are two elements and the container query picks which one is on screen. */
.bar-icon { display: inline-flex; align-items: center; justify-content: center; gap: 5px; width: auto; padding: 0 8px 0 6px; height: 28px; padding: 0; border-radius: 8px; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); cursor: pointer; }
.bar-icon svg { width: var(--ico-sm); height: var(--ico-sm); }
.bar-icon:hover { color: var(--phosphor); border-color: var(--phosphor); }
.bar-count { min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; display: inline-grid; place-items: center; background: var(--phosphor); color: var(--phosphor-ink); font-family: var(--mono); font-size: 9px; letter-spacing: 0; }
.bar-glyph { display: none; }
.agents-compact { display: none; }

@container bar (max-width: 1040px) {
  .bar { gap: 9px; }
  /* The dot already says live in colour; the word only repeats it. */
  .connection-label { display: none; }
  /* A narrow bar keeps the pulse alone, the kit's own «solo pulso» version, not half a logo. */
  .brand-logo { display: none; }
  .brand-icon { display: block; }
}
/* The crew collapses before the names do. Five spheres are 178px; at the width where the bar is
   tight, giving those back is what buys the project its name — and a name is information a glyph
   cannot carry, while five spheres say the same thing one button says with a number. */
@container bar (max-width: 980px) {
  /* The crew becomes one button: how many are ready, and the whole list in its title. */
  .agents { display: none; }
  .agents-compact { display: inline-flex; }
  /* A label on a button whose glyph already names it is a label spending room it does not own. */
  /* The word goes and a real glyph takes its place: a puzzle piece for the modules, a pulse for
     MU/TH/UR. The decorative mark each button already carried is not an icon — it is a bullet —
     so leaving only that left two empty outlines on screen. */
  /* Icon and number side by side, inside the button. Pulling the badge out with position:absolute
     made it escape 16-23px past the right edge into an 18px gap, which is exactly the collision
     that was on screen. A count belongs inside the thing it counts. */
  .mother-button { width: auto; height: 28px; padding: 0 9px 0 7px; gap: 5px; font-size: 0; justify-content: center; }
  .mother-button .mother-glyph { display: none; }
  .mother-button .bar-glyph { display: block; width: var(--ico-md); height: var(--ico-md); }
  .mother-button .modules-count, .mother-button .mother-count { font-size: 9px; }
  .stop-all { width: 30px; height: 28px; padding: 0; gap: 0; font-size: 0; justify-content: center; }
  /* Squircles with their count on the corner, the way a phone shows it. The count used to be
     pulled out with position:absolute and escape 16-23px past the edge into an 18px gap; it now
     overhangs by 7px and the bar keeps 14px between buttons, so it sits on its own icon's corner
     and touches nothing else. A ring in the background colour cuts it out of the outline. */
  .bar { gap: 14px; }
  .bar-icon, .mother-button, .stop-all { position: relative; width: 34px; height: 34px; padding: 0; gap: 0; border-radius: 11px; justify-content: center; }
  .bar-icon svg, .mother-button .bar-glyph { width: var(--ico-md); height: var(--ico-md); }
  .bar-icon .bar-count, .mother-button .modules-count, .mother-button .mother-count {
    position: absolute; top: -6px; right: -7px; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px;
    font-family: var(--mono); font-size: 9.5px; font-weight: 700; line-height: 18px; box-shadow: 0 0 0 2px var(--bg);
  }
}
@container bar (max-width: 640px) {
  /* The room's name is the first thing that cannot be drawn, so it becomes the mark that says
     there is one: three dots, with the whole title still in the tooltip. */
  .chat-here { font-size: 0; }
  .chat-here::after { content: '…'; font-size: 11px; letter-spacing: .1em; }
}
@container bar (max-width: 460px) {
  .project:not(.chat-here) { font-size: 0; }
  .project:not(.chat-here)::after { content: '/'; font-size: 11px; }
}

/* The composer has the same disease: its parts have to be allowed to give. */
.composer .field { min-width: 0; }
.composer .editor { min-width: 0; }
/* The field grows with the text to a workable page and then scrolls on its own, so a long brief
   is written in one piece instead of through a three-line window — and the thread above it never
   disappears, because what is being written is usually written against it. */
.composer .editor textarea { scrollbar-width: thin; }
.composer .crew-label { flex: none; }

/* The browser docks beside the conversation; it does not take the screen from it. The point of
   looking at a server while a room full of agents works on it is seeing both, so the thread keeps
   its column and simply narrows. One rule does it: the shell grows a second column, and every
   existing child is already pinned to the first. */
.shell.with-browser { grid-template-columns: minmax(0, 1fr) var(--dock, 46vw); }
.shell.with-browser > .browser-dock { grid-column: 2; grid-row: 1 / -1; }
/* No height of its own: it already spans every row of the shell, and asking for 100dvh on top of
   that made the grid satisfy it by starving the rows in the other column — which is how the
   conversations panel ended up two pixels tall and the thread lost its end. */
.browser-dock { position: relative; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-width: 0; min-height: 0; background: var(--panel); border-left: 1px solid var(--line); }
/* The dock is a fixed grid track, so anything inside it that refuses to shrink pushes the whole
   page wider and hands the human a horizontal scrollbar for a layout that was supposed to fit.
   Its own container query decides what the header can afford. */
.browser-dock { container-type: inline-size; container-name: dock; overflow: hidden; }
.browser-dock .viewer-head { padding: 10px 12px; min-width: 0; }
.browser-dock .viewer-head > * { flex: none; }
.browser-dock .browser-where { flex: 1 1 auto; min-width: 40px; }
.browser-dock .viewer-body { height: auto; min-height: 0; }
.browser-tabs { min-width: 0; }
@container dock (max-width: 620px) {
  /* The widths are a convenience; the address is not. */
  .browser-dock .viewer-sizes { display: none; }
}
@container dock (max-width: 460px) {
  .browser-dock #browser-servers { padding: 0 7px; }
  .browser-dock #browser-servers > span { display: none; }
}
/* The edge between the two: wide enough to grab, invisible until wanted. */
.dock-grip { position: absolute; left: -3px; top: 0; bottom: 0; width: 8px; cursor: ew-resize; z-index: 5; }
.dock-grip::after { content: ''; position: absolute; left: 3px; top: 50%; transform: translateY(-50%); width: 2px; height: 48px; border-radius: 999px; background: var(--line-2); opacity: 0; transition: opacity calc(150ms * var(--motion-scale)); }
.dock-grip:hover::after, .shell.dragging-dock .dock-grip::after { opacity: 1; background: var(--phosphor); }
.shell.dragging-dock .browser-dock iframe { pointer-events: none; }
@media (max-width: 900px) { .shell.with-browser { grid-template-columns: minmax(0, 1fr); } .shell.with-browser > .browser-dock { grid-column: 1; grid-row: 3 / 4; height: auto; border-left: 0; border-top: 1px solid var(--line); } }

/* The browser is its own window on the rail, beside the conversations. */

.browser-head { flex-wrap: nowrap; }
.browser-tabs { display: flex; align-items: stretch; gap: 4px; padding: 10px 12px; border-top: 1px solid var(--line); overflow-x: auto; scrollbar-width: thin; }
.browser-tab { display: inline-flex; align-items: center; gap: 8px; max-width: 220px; padding: 6px 10px; border: 1px solid var(--line-2); border-radius: 8px; background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 11px; cursor: pointer; }
.browser-tab .tab-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.browser-tab .tab-close { opacity: .45; font-size: 13px; line-height: 1; }
.browser-tab .tab-close:hover { opacity: 1; color: var(--danger); }
.browser-tab.on { color: var(--phosphor); border-color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); }
.browser-newtab { flex: none; width: 28px; border: 1px dashed var(--line-2); border-radius: 8px; background: transparent; color: var(--text-3); font-size: 14px; cursor: pointer; }
.browser-newtab:hover { color: var(--phosphor); border-color: var(--phosphor); }

/* Browsing a live server is not reading a file: the page under the glass was built for a window,
   so it gets one. Full bleed, no rounded corners pretending this is a card, and a stage the frame
   can be made narrower inside — because checking a layout at phone width is most of what a human
   opens their own app to do. */
dialog.viewer.browsing { width: 100vw; max-width: 100vw; height: 100vh; max-height: 100vh; border-radius: 0; }
.viewer-body.browsing { padding: 0; display: grid; grid-template-rows: minmax(0, 1fr); place-items: stretch; background: var(--bg); overflow: hidden; }
/* One column as wide as the stage, and the page centred inside it. With `justify-content: center`
   and no columns the track was sized by the iframe itself, whose own width is 300 px, so AUTO
   showed every page 300 px wide in a dock twice that. */
.viewer-stage { position: relative; display: grid; grid-template-rows: minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); justify-items: center; width: 100%; min-height: 0; overflow: hidden; }
.viewer-stage iframe.ripley { width: var(--stage, 100%); max-width: 100%; height: 100%; min-height: 0; border-radius: 0; box-shadow: none; }
.viewer-stage[data-sized="true"] iframe.ripley { box-shadow: 0 0 0 1px var(--line-2); }
/* The edge you pull. Wide enough to grab, invisible until it matters. */
.stage-grip { position: absolute; top: 0; bottom: 0; width: 14px; cursor: ew-resize; display: grid; place-items: center; }
.stage-grip::after { content: ''; width: 3px; height: 46px; border-radius: 999px; background: var(--line-2); opacity: 0; transition: opacity calc(150ms * var(--motion-scale)); }
.stage-grip:hover::after, .viewer-stage.dragging .stage-grip::after { opacity: 1; background: var(--phosphor); }
.viewer-stage.dragging iframe.ripley { pointer-events: none; }
.viewer-sizes { display: inline-flex; gap: 2px; border: 1px solid var(--line-2); border-radius: 999px; padding: 2px; }
.viewer-sizes button { border: 0; background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 9.5px; letter-spacing: .08em; padding: 4px 9px; border-radius: 999px; cursor: pointer; }
.viewer-sizes button[aria-pressed="true"] { background: color-mix(in srgb, var(--phosphor) 18%, transparent); color: var(--phosphor); }
dialog.viewer::backdrop { background: rgba(0,0,0,.7); backdrop-filter: blur(4px); }
.viewer-head { display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-bottom: 1px solid var(--line); font-family: var(--mono); font-size: 11px; }
.viewer-path { color: var(--text-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }
.viewer-open { color: var(--phosphor); text-decoration: none; letter-spacing: .12em; font-size: 10px; }
.viewer-body { height: calc(100% - 46px); overflow: auto; overscroll-behavior: contain; display: grid; place-items: start center; padding: 16px; }
.viewer-nav { display: inline-flex; gap: 4px; }
.viewer-nav .nav { width: 26px; height: 26px; display: grid; place-items: center; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); border-radius: 7px; cursor: pointer; font: inherit; font-size: 14px; line-height: 1; }
.viewer-nav .nav:hover { color: var(--text); border-color: var(--text-3); }
/* The browser's reload is the bar's reload mark (2026-10-14), the same drawing, still. */
.viewer-nav .nav.reload svg { width: var(--ico-sm); height: var(--ico-sm); }
.viewer-nav .nav:disabled { opacity: .35; cursor: default; }
.viewer-errors { display: grid; gap: 6px; padding: 8px 16px; border-bottom: 1px solid color-mix(in srgb, var(--danger) 40%, transparent); background: color-mix(in srgb, var(--danger) 7%, transparent); font-family: var(--mono); font-size: 11px; }
.viewer-errors:not([hidden]) + .viewer-body { height: auto; max-height: calc(100% - 46px); }
.viewer-errors .err-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.viewer-errors .msg { color: var(--danger); overflow-wrap: anywhere; }
.viewer-errors .where { color: var(--text-3); font-size: 10px; }
.viewer-errors button { margin-left: auto; border: 1px solid color-mix(in srgb, var(--danger) 55%, transparent); background: transparent; color: var(--danger); font: inherit; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; padding: 3px 8px; border-radius: 6px; cursor: pointer; }
.viewer-errors button:hover { background: color-mix(in srgb, var(--danger) 14%, transparent); }
/* Not an error: the sealed frame keeps no data, said in the room's own voice, not in red. Alone, the
   band around it is not red either. */
.viewer-errors:not(:has(.err-row:not(.storage))) { border-bottom-color: var(--line); background: color-mix(in srgb, var(--phosphor) 5%, transparent); }
.viewer-errors .err-row.storage .msg { color: var(--text-2); }
.viewer-errors .err-row.storage button { border-color: color-mix(in srgb, var(--phosphor) 55%, transparent); color: var(--phosphor); }
.viewer-errors .err-row.storage button:hover { background: color-mix(in srgb, var(--phosphor) 14%, transparent); }
.viewer-body img { max-width: 100%; max-height: 100%; border-radius: 8px; }
.viewer-body pre { margin: 0; width: 100%; font-family: var(--mono); font-size: 12.5px; line-height: 1.55; white-space: pre-wrap; overflow-wrap: anywhere; color: var(--text); }
.viewer-body iframe { width: 100%; height: 100%; border: 0; background: #fff; border-radius: 8px; }
.viewer-body .err { color: var(--danger); font-family: var(--mono); }
.viewer-body iframe.ripley { background: #fff; box-shadow: 0 0 0 1px var(--line-2); }
.viewer-body .viewer-markdown { width: min(820px, 100%); justify-self: center; padding: 8px 4px 24px; font-size: 15px; line-height: 1.6; background: transparent; }
.viewer-body .viewer-hint { width: 100%; margin-bottom: 10px; padding: 8px 12px; border: 1px dashed var(--line-2); border-radius: 8px; font-family: var(--mono); font-size: 10px; letter-spacing: .1em; color: var(--text-3); }
.viewer-body .viewer-hint b { color: var(--phosphor); font-weight: 600; }
.viewer-mode { border-color: var(--text-3); color: var(--text-2); background: transparent; }
.viewer-mode:hover { color: var(--text); border-color: var(--text-2); background: var(--line); }
.viewer-body pre.code { display: grid; grid-template-columns: max-content 1fr; padding: 4px 0 24px; white-space: pre; overflow: visible; font-size: 12.5px; line-height: 1.6; counter-reset: none; }
.viewer-body pre.code .ln { position: sticky; left: 0; user-select: none; text-align: right; padding: 0 14px 0 10px; color: var(--text-3); cursor: pointer; border-right: 1px solid var(--line); background: var(--panel); }
.viewer-body pre.code .ln:hover { color: var(--phosphor); }
.viewer-body pre.code .tx { padding: 0 16px; white-space: pre-wrap; overflow-wrap: anywhere; min-width: 0; }
.viewer-body pre.code .ln.sel, .viewer-body pre.code .tx.sel { background: color-mix(in srgb, var(--phosphor) 14%, transparent); }
.viewer-body pre.code .ln.sel { color: var(--phosphor); border-right-color: var(--phosphor); }
.viewer-body pre.code .tx.sel { box-shadow: inset 0 -1px 0 color-mix(in srgb, var(--phosphor) 55%, transparent); }
.viewer-body pre.code .ln.hl, .viewer-body pre.code .tx.hl { background: color-mix(in srgb, var(--warn) 16%, transparent); }
.viewer-body pre.code .tx:hover { background: color-mix(in srgb, var(--text) 4%, transparent); }
.viewer-body:has(pre.code) { display: block; padding: 0; }
.viewer-selection { font-family: var(--mono); font-size: 10px; letter-spacing: .12em; color: var(--phosphor); white-space: nowrap; }
.viewer-review { border: 1px solid var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); color: var(--phosphor); font: inherit; font-family: var(--mono); font-size: 10px; letter-spacing: .14em; padding: 5px 10px; border-radius: 6px; cursor: pointer; white-space: nowrap; }
.viewer-review:hover { background: color-mix(in srgb, var(--phosphor) 20%, transparent); }
.viewer-menu { position: fixed; z-index: 50; min-width: 220px; border: 1px solid var(--line-2); background: var(--panel); border-radius: 12px; box-shadow: 0 14px 40px rgba(0, 0, 0, .35); padding: 6px; display: grid; gap: 2px; }
/* Two lines: the range being sent, then the question. The reference is a path and can be long,
   so it wraps instead of pushing the menu wider or being clipped mid-word. */
.viewer-menu .hint { display: grid; gap: 2px; padding: 6px 10px 8px; font-family: var(--mono); font-size: 10px; letter-spacing: .12em; color: var(--text-3); }
.viewer-menu .hint b { color: var(--text-2); font-weight: 500; overflow-wrap: anywhere; }
.viewer-menu .item span { color: var(--text-3); font-size: 11px; }
.viewer-menu .item { display: flex; gap: 10px; align-items: center; padding: 7px 10px; border-radius: 8px; border: 0; background: transparent; color: var(--text); font: inherit; font-size: 13px; cursor: pointer; text-align: left; }
.viewer-menu .item:hover { background: color-mix(in srgb, var(--agent, var(--phosphor)) 14%, transparent); }
.viewer-menu .item b { color: var(--agent, var(--phosphor)); font-family: var(--mono); font-size: 11.5px; letter-spacing: .06em; }
.viewer-menu .item.off { opacity: .5; }
.bubble .file-ref { font-family: var(--mono); font-size: 12.5px; color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); border: 1px solid color-mix(in srgb, var(--phosphor) 35%, transparent); border-radius: 6px; padding: 0 6px; cursor: pointer; }
.bubble .file-ref:hover { background: color-mix(in srgb, var(--phosphor) 18%, transparent); }
.caps { display: flex; gap: 6px; flex-wrap: wrap; }
.cap { font-family: var(--mono); font-size: 9px; letter-spacing: .12em; text-transform: uppercase; padding: 2px 6px; border-radius: 4px; border: 1px solid var(--line-2); color: var(--text-3); }
.cap.on { color: var(--agent, var(--phosphor)); border-color: color-mix(in srgb, var(--agent, var(--phosphor)) 50%, transparent); }
.conn-card .caps .cap.on { color: var(--ph); border-color: var(--ph-dim); }
.conn-card .caps .cap { color: var(--ph-dim); border-color: var(--ph-faint); }

/* ================= creation lease ================= */
.create-toggle { height: 30px; padding: 0 10px 0 8px; border-radius: 999px; border: 1px solid var(--line-2); background: transparent; color: var(--text-3); display: inline-flex; align-items: center; gap: 6px; cursor: pointer; font-family: var(--mono); font-size: 9.5px; letter-spacing: .16em; align-self: center; transition: color calc(200ms * var(--motion-scale)), border-color calc(200ms * var(--motion-scale)), background calc(200ms * var(--motion-scale)); }
.create-toggle svg { width: var(--ico-sm); height: var(--ico-sm); }
.create-toggle:hover { color: var(--text); border-color: var(--text-3); }
.create-toggle[aria-pressed="true"] { color: var(--warn); border-color: var(--warn); background: color-mix(in srgb, var(--warn) 12%, transparent); text-shadow: none; }
.create-toggle .lock.open { display: none; }
.create-toggle.standing { color: var(--warn); border-style: dashed; border-color: color-mix(in srgb, var(--warn) 60%, transparent); }
.create-toggle.standing .lock.closed { display: none; }
.create-toggle.standing .lock.open { display: block; }
.system.lease.missing { color: var(--warn); display: flex; flex-wrap: wrap; gap: 8px 12px; align-items: center; justify-content: center; }
.system.lease.missing .actions { display: inline-flex; gap: 8px; flex-wrap: wrap; }
.system.lease.missing button { border: 1px solid color-mix(in srgb, var(--warn) 60%, transparent); background: color-mix(in srgb, var(--warn) 10%, transparent); color: var(--warn); font: inherit; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; padding: 4px 9px; border-radius: 6px; cursor: pointer; }
.system.lease.missing button:hover { background: color-mix(in srgb, var(--warn) 20%, transparent); }
.system.lease.missing button:disabled { opacity: .6; cursor: default; }
.conn-card .scope.sub { margin-left: 22px; font-size: 9px; margin-top: -2px; }
/* One column for the label, the same width on every row and in every card, so MAX MODE and
   DEFAULT MODE start at the same place instead of each beginning where its own words end. */
.conn-card .ceiling { display: grid; grid-template-columns: 104px 1fr; gap: 8px 12px; align-items: center; margin-top: 6px; padding-top: 12px; border-top: 1px solid var(--ph-faint); }
.conn-card .ceiling .seg { justify-self: start; }
.conn-card .ceiling .k { font-size: 9.5px; letter-spacing: .16em; color: var(--ph-dim); }
.conn-card .ceiling .why { grid-column: 1 / -1; font-size: 9px; letter-spacing: .08em; color: var(--ph-dim); text-transform: none; line-height: 1.5; }
.conn-card .seg { display: inline-flex; border: 1px solid var(--ph-dim); }
.conn-card .seg-option { border: 0; border-right: 1px solid var(--ph-faint); background: transparent; color: var(--ph-dim); font: inherit; font-size: 10px; letter-spacing: .1em; padding: 4px 9px; cursor: pointer; }
.conn-card .seg-option:last-child { border-right: 0; }
.conn-card .seg-option:hover { background: var(--ph-faint); color: var(--ph); }
/* A chosen mode wears its own colour, the same one the composer uses for it. It used to be
   phosphor for every mode but #3, which made one card look like a warning and the rest like
   settings, when all five are the same kind of choice. */
.conn-card .seg-option.current { background: var(--mode, var(--ph)); color: var(--mode-ink, #041004); font-weight: 700; }
.conn-card .seg-option.o0 { --mode: var(--mode-0); --mode-ink: var(--mode-0-ink); }
.conn-card .seg-option.o1 { --mode: var(--mode-1); --mode-ink: var(--mode-1-ink); }
.conn-card .seg-option.o2 { --mode: var(--mode-2); --mode-ink: var(--mode-2-ink); }
.conn-card .seg-option.o3 { --mode: var(--mode-3); --mode-ink: var(--mode-3-ink); }
.conn-card .seg-option.o4 { --mode: var(--mode-4); --mode-ink: var(--mode-4-ink); }
.conn-card .seg-option:disabled { opacity: .35; cursor: default; }
.create-toggle[aria-pressed="true"] .lock.closed { display: none; }
.create-toggle[aria-pressed="true"] .lock.open { display: block; }
/* Ash: a bash prompt on a black terminal, Homebrew green. */
/* Off: a dormant prompt, grey like the other idle controls. On: the terminal lights up. */
.ash-toggle { height: 30px; padding: 0 10px 0 9px; border-radius: 7px; border: 1px dashed var(--line-2); background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 10px; font-weight: 500; letter-spacing: .06em; text-transform: none; cursor: pointer; align-self: center; display: inline-flex; align-items: center; gap: 6px; opacity: .8; transition: color calc(200ms * var(--motion-scale)), border-color calc(200ms * var(--motion-scale)), box-shadow calc(200ms * var(--motion-scale)), background calc(200ms * var(--motion-scale)), opacity calc(200ms * var(--motion-scale)); }
.ash-toggle::before { content: '$'; color: var(--text-3); font-weight: 700; }
.ash-toggle::after { content: ''; width: 7px; height: 12px; background: currentColor; opacity: .25; margin-left: 1px; }
.ash-toggle:hover { opacity: 1; color: var(--text-2); border-color: var(--text-3); }
.ash-toggle[aria-pressed="true"] { opacity: 1; border-style: solid; background: #070907; color: var(--brew); border-color: var(--brew); font-weight: 700; box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--brew) 22%, transparent); text-shadow: none; }
.ash-toggle[aria-pressed="true"]::before { color: color-mix(in srgb, var(--brew) 75%, transparent); }
.ash-toggle[aria-pressed="true"]::after { animation: cursor-blink 1s steps(1) infinite; opacity: 1; }
.ash-toggle[aria-pressed="true"]:hover { color: var(--brew); border-color: var(--brew); }
/* On a light ground the black terminal turned a dark accent into ink on ink (Dijon's olive, even
   Homebrew's light green). There it is a light terminal: a tint of the tone, its border, and the
   tone deepened enough to read. */
:root[data-scheme="light"] .ash-toggle[aria-pressed="true"] { background: color-mix(in srgb, var(--brew) 10%, #ffffff); color: color-mix(in srgb, var(--brew) 78%, #000000); border-color: color-mix(in srgb, var(--brew) 70%, transparent); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .8), 0 1px 2px rgba(20, 30, 20, .08); }
:root[data-scheme="light"] .ash-toggle[aria-pressed="true"]::before { color: color-mix(in srgb, var(--brew) 60%, #000000); }
:root[data-scheme="light"] .ash-toggle[aria-pressed="true"]:hover { color: color-mix(in srgb, var(--brew) 78%, #000000); border-color: var(--brew); }

/* With Ash lit, the field widens like CREATE and glows Homebrew green. */
/* ASH winks at the box when it is switched on and leaves its colour alone: the box always wears
   the colour of its mode. ASH's own green lives on the ASH button. */
.composer.ash-on .field { position: relative; }
/* EXCHANGE (#1) has a colour of its own on the box too, quieter than the modes that open the
   project: the edge and the label in a part of the mode's tone — which is the accent, when one is
   chosen. The other modes draw their own edges (ghost, creating, control, airlock). */
.composer:not(.m0, .m2, .m3, .m4, .ghost, .creating, .control, .airlock) .field { border-color: color-mix(in srgb, var(--mode) 42%, var(--line-2)); }
.composer:not(.m0, .m2, .m3, .m4, .ghost, .creating, .control, .airlock) .field:focus-within { border-color: color-mix(in srgb, var(--mode) 65%, var(--line-2)); box-shadow: 0 0 0 3px color-mix(in srgb, var(--mode) 10%, transparent); }
.composer:not(.m0, .m2, .m3, .m4, .ghost, .creating, .control, .airlock) .crew-label { color: color-mix(in srgb, var(--mode) 80%, var(--text-2)); }
:root[data-scheme="light"] .composer:not(.m0, .m2, .m3, .m4, .ghost, .creating, .control, .airlock) .field:focus-within { box-shadow: 0 0 0 2px color-mix(in srgb, var(--mode) 12%, transparent); }
.composer.creating.ordering .field { border-color: var(--mode-2); box-shadow: 0 0 0 3px color-mix(in srgb, var(--mode-2) 18%, transparent), inset 0 0 0 1px color-mix(in srgb, var(--brew) 45%, transparent); }

/* The wink to MOTHER when the order is given: a CRT sweep and scanlines that fade. */
.composer .field::before { content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; opacity: 0; z-index: 2;
  background:
    linear-gradient(90deg, transparent 0%, color-mix(in srgb, var(--mode, var(--phosphor)) 0%, transparent) 40%, color-mix(in srgb, var(--mode, var(--phosphor)) 38%, transparent) 50%, transparent 60%) no-repeat,
    repeating-linear-gradient(0deg, color-mix(in srgb, var(--mode, var(--phosphor)) 10%, transparent) 0 1px, transparent 1px 3px);
  background-size: 60% 100%, 100% 100%; background-position: -60% 0, 0 0; }
.composer.ash-wink .field::before { animation: ash-sweep 1.5s cubic-bezier(.2, .7, .2, 1) 1; }
.composer.ash-wink .crew-label { animation: phosphor-flicker .8s steps(1) 2; }
.composer.ash-wink .editor textarea { animation: ash-type .9s steps(1) 1; }
@keyframes ash-sweep { 0% { opacity: 0; background-position: -60% 0, 0 0; } 12% { opacity: 1; } 70% { opacity: .9; background-position: 160% 0, 0 0; } 100% { opacity: 0; background-position: 160% 0, 0 0; } }
@keyframes ash-type { 0%, 30% { caret-color: var(--brew); } 40% { caret-color: transparent; } 55% { caret-color: var(--brew); } 100% { caret-color: var(--text); } }
.field .rain { position: absolute; inset: 0; width: 100%; height: 100%; border-radius: inherit; pointer-events: none; z-index: 3; }
.rain.global { position: fixed; inset: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: 60; animation: rain-in .25s ease-out 1; }
@keyframes rain-in { from { opacity: 0; } to { opacity: 1; } }
/* GHOST: the field disintegrates into a grid of dots that shrink to nothing, then reintegrates dashed, in mode #0. */
@property --ghost-dot { syntax: '<length>'; inherits: false; initial-value: 7px; }
.composer.ghost-wink .field { animation: ghost-dissolve 1.3s cubic-bezier(.45, 0, .2, 1) 1;
  -webkit-mask-image: radial-gradient(circle, #000 var(--ghost-dot), transparent calc(var(--ghost-dot) + .6px)); -webkit-mask-size: 8px 8px; -webkit-mask-position: 0 0;
  mask-image: radial-gradient(circle, #000 var(--ghost-dot), transparent calc(var(--ghost-dot) + .6px)); mask-size: 8px 8px; mask-position: 0 0; }
@keyframes ghost-dissolve {
  0% { --ghost-dot: 7px; opacity: 1; border-style: solid; border-color: var(--line-2); filter: blur(0); }
  40% { --ghost-dot: 0px; opacity: .6; border-style: solid; border-color: var(--line-2); filter: blur(1.5px); }
  58% { --ghost-dot: 0px; opacity: .6; border-style: dashed; border-color: var(--mode-0); filter: blur(1.5px); }
  100% { --ghost-dot: 7px; opacity: .92; border-style: dashed; border-color: var(--mode-0); filter: blur(0); } }
.composer.control-wink .field::before { animation: control-sweep 2.2s cubic-bezier(.2, .7, .2, 1) 1;
  background:
    linear-gradient(90deg, transparent 0%, transparent 40%, color-mix(in srgb, var(--terror) 45%, transparent) 50%, transparent 60%) no-repeat,
    repeating-linear-gradient(0deg, color-mix(in srgb, var(--terror) 14%, transparent) 0 1px, transparent 1px 3px);
  background-size: 60% 100%, 100% 100%; }
.composer.control-wink .crew-label { animation: terror-flicker 1.1s steps(1) 2; }
.composer.control-wink .editor textarea { animation: control-type 1.4s steps(1) 1; }
@keyframes control-sweep { 0% { opacity: 0; background-position: -60% 0, 0 0; } 8% { opacity: 1; } 18% { opacity: .3; } 26% { opacity: 1; } 72% { opacity: .9; background-position: 160% 0, 0 0; } 100% { opacity: 0; background-position: 160% 0, 0 0; } }
@keyframes terror-flicker { 0%, 100% { filter: none; } 15% { filter: brightness(2) saturate(1.6); } 30% { filter: brightness(.5); } 45% { filter: brightness(1.8); } 60% { filter: brightness(.8); } }
@keyframes control-type { 0%, 30% { caret-color: var(--terror); } 40% { caret-color: transparent; } 55% { caret-color: var(--terror); } 100% { caret-color: var(--text); } }
