.mode-ask { display: grid; gap: 6px; margin: 10px 12px 2px; padding: 12px 14px; border: 1px solid color-mix(in srgb, var(--warn, #e2a022) 45%, transparent); border-radius: 14px; background: color-mix(in srgb, var(--warn, #e2a022) 6%, transparent); }
.mode-what { min-width: 0; font-size: 13px; line-height: 1.45; color: var(--text); }
.mode-what .who { display: inline; margin: 0; padding: 0; font: inherit; font-weight: 700; letter-spacing: 0; text-transform: none; color: var(--agent, var(--text)); }
.mode-why { font-size: 11.5px; line-height: 1.45; color: var(--text-2); }
.mode-what .mode-time { font-family: var(--mono); font-size: 11px; letter-spacing: .04em; color: var(--text-2); }
/* How long the permission holds: the time the agent asked for, preselected; the human may change it. */
.mode-windows { display: inline-flex; flex-wrap: wrap; gap: 4px; padding: 3px; border-radius: 999px; background: color-mix(in srgb, var(--text) 5%, transparent); justify-self: start; }
.mode-window { border: 0; border-radius: 999px; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 10px; letter-spacing: .08em; padding: 5px 10px; cursor: pointer; transition: background .18s ease, color .18s ease; }
.mode-window:hover { color: var(--text); }
.mode-window[aria-checked="true"] { background: var(--panel, #fff); color: var(--text); box-shadow: 0 1px 2px rgb(0 0 0 / .12); }
.mode-window:focus-visible { outline: 2px solid color-mix(in srgb, var(--warn, #e2a022) 60%, transparent); outline-offset: 1px; }
.mode-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 4px; }
.mode-alt { border: 1px solid var(--line-2); border-radius: 7px; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 10px; letter-spacing: .1em; padding: 6px 11px; cursor: pointer; }
.mode-alt:hover { color: var(--text); border-color: var(--text-3); }
.mode-ask.settled { padding: 8px 14px; border-style: dashed; background: none; }
.mode-ask.settled .mode-what { font-family: var(--mono); font-size: 10.5px; letter-spacing: .06em; color: var(--text-3); }
.mode-go {
  flex: none; border: 0; border-radius: 7px; cursor: pointer;
  background: var(--warn, #e2a022); color: var(--warn-ink, #1a1403);
  font-family: var(--mono); font-size: 10px; font-weight: 700; letter-spacing: .12em; padding: 6px 13px;
  box-shadow: 0 1px 0 color-mix(in srgb, #000 22%, transparent);
}
.mode-go:hover { background: color-mix(in srgb, var(--warn, #e2a022) 86%, #fff); }
.mode-go:active { transform: translateY(1px); box-shadow: none; }

/* A decision handed back, in the agent's colour: read at a glance, answered with one press.
   Options stack as rows, not pills: an option is a sentence, and a sentence wrapped inside a pill
   reads as a broken button. The agent's pick leads, with its tag on the right. The colour is in
   the edges and the numbers, never in a glow. */
.choice { margin: 14px 12px 4px; padding: 18px 18px 14px; border: 1px solid color-mix(in srgb, var(--agent, var(--text-3)) 22%, var(--line-2)); border-radius: 18px; background: color-mix(in srgb, var(--agent, var(--text-3)) 3%, var(--bg-2)); box-shadow: 0 1px 0 rgba(255,255,255,.03) inset; max-width: 760px; }
.choice-head { display: flex; align-items: center; gap: 8px; margin: 0 2px 8px; }
.choice-kicker { font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .18em; text-transform: uppercase; color: var(--agent, var(--text-3)); }
.choice-q { margin: 0 2px 16px; font-size: 14px; line-height: 1.5; font-weight: 500; color: var(--text); text-wrap: pretty; }
.choice-list { display: grid; gap: 8px; }
.choice-option { display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; align-items: start; gap: 14px; width: 100%; border: 1px solid var(--line-2); background: var(--panel); color: var(--text); font: inherit; font-size: 13px; line-height: 1.55; text-align: left; padding: 12px 14px; border-radius: 12px; cursor: pointer; transition: background calc(150ms * var(--motion-scale)), border-color calc(150ms * var(--motion-scale)), transform calc(80ms * var(--motion-scale)); }
.choice-option:hover { background: var(--panel-2, var(--panel)); border-color: color-mix(in srgb, var(--agent, var(--text-3)) 40%, var(--line-2)); }
.choice-option:active { transform: translateY(1px); }
.choice-option:focus-visible { outline: 2px solid color-mix(in srgb, var(--agent, var(--phosphor)) 70%, transparent); outline-offset: 2px; }
.choice-key { display: grid; place-items: center; width: 24px; height: 24px; margin-top: -1px; border: 1px solid var(--line-2); border-radius: 7px; font-family: var(--mono); font-size: 10.5px; font-weight: 600; color: var(--text-3); transition: color calc(150ms * var(--motion-scale)), border-color calc(150ms * var(--motion-scale)), background calc(150ms * var(--motion-scale)); }
.choice-option:hover .choice-key { color: var(--text); }
.choice-text { min-width: 0; overflow-wrap: anywhere; text-wrap: pretty; }
.choice-tag { align-self: center; padding: 4px 9px; border: 1px solid color-mix(in srgb, var(--agent, var(--phosphor)) 45%, transparent); border-radius: 999px; color: var(--agent, var(--phosphor)); font-family: var(--mono); font-size: 8.5px; font-weight: 600; letter-spacing: .16em; white-space: nowrap; }
.choice-option.recommended { border-color: color-mix(in srgb, var(--agent, var(--phosphor)) 40%, var(--line-2)); background: color-mix(in srgb, var(--agent, var(--phosphor)) 6%, var(--panel)); }
.choice-option.recommended .choice-key { border-color: color-mix(in srgb, var(--agent, var(--phosphor)) 50%, transparent); color: var(--agent, var(--phosphor)); }
.choice-tags { align-self: center; display: inline-flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.choice-mode { display: inline-flex; align-items: center; padding: 4px 9px; border-radius: 999px; border: 1px solid currentColor; font-family: var(--mono); font-size: 8.5px; font-weight: 600; letter-spacing: .16em; white-space: nowrap; color: var(--text-2); }
.choice-mode.m2 { color: var(--phosphor); } .choice-mode.m3 { color: var(--terror); } .choice-mode.m4 { color: var(--mode-4); }
.choice-option.picked { border-color: color-mix(in srgb, var(--agent, var(--phosphor)) 70%, transparent); background: color-mix(in srgb, var(--agent, var(--phosphor)) 10%, var(--panel)); }
.choice-option.picked .choice-key { background: var(--agent, var(--phosphor)); border-color: transparent; color: var(--bg); }
.choice-foot { margin: 14px 2px 0; font-family: var(--mono); font-size: 9.5px; letter-spacing: .08em; color: var(--text-3); }
@media (max-width: 560px) {
  .choice { margin: 12px 0 4px; padding: 14px 12px 12px; }
  .choice-option { grid-template-columns: 24px minmax(0, 1fr); gap: 12px; }
  .choice-tag { grid-column: 2; justify-self: start; }
  .choice-tags { grid-column: 2; justify-self: start; }
}

/* A command an agent asks the human to run: a .choice whose options are command lines. The line
   is code, read before it is pressed; the tag says what pressing does, then what happened. */
.run-request .choice-text { font-family: var(--mono); font-size: 12px; }
.run-request .choice-key { font-family: var(--mono); }
.run-request .choice-tag { background: transparent; border: 1px solid var(--agent, var(--phosphor)); color: var(--agent, var(--phosphor)); }
.run-request .run-line.running { cursor: progress; border-color: var(--agent, var(--phosphor)); }
.run-request .run-line.running .choice-tag { animation: klaxon 1.2s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .run-request .run-line.running .choice-tag { animation: none; } }
.run-request .run-line.ran .choice-tag { border-color: var(--ok, var(--phosphor)); color: var(--ok, var(--phosphor)); }
.run-request .run-line.failed .choice-tag { border-color: var(--crit); color: var(--crit); }
.run-request .run-summary { margin: 10px 2px 0; font-family: var(--mono); font-size: 10.5px; color: var(--text-2); }
/* RUN ALL and the hand-back: quiet buttons in the agent's colour, under the summary. */
.run-request .run-actions { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 2px 0; }
.run-request .run-actions:empty { display: none; }
.run-request :is(.run-all, .run-back) { border: 1px solid color-mix(in srgb, var(--agent, var(--phosphor)) 55%, transparent); border-radius: 999px; background: transparent; color: var(--agent, var(--text)); font-family: var(--mono); font-size: 10px; letter-spacing: .1em; padding: 6px 12px; cursor: pointer; transition: background .18s ease; }
.run-request :is(.run-all, .run-back):hover:not(:disabled) { background: color-mix(in srgb, var(--agent, var(--phosphor)) 10%, transparent); }
.run-request :is(.run-all, .run-back):disabled { opacity: .5; cursor: progress; }
.run-request.returned .run-summary { color: var(--ok, var(--phosphor)); }
.run-request.returned .run-all { display: none; }
/* A message MADRE wrote for the human: the results of commands going back. Same bubble, quieter. */
#messages .row.user.auto .bubble { opacity: .82; }
.run-request .run-progress-track { position: relative; flex: 1 1 100%; height: 3px; overflow: hidden; border-radius: 3px; background: color-mix(in srgb, var(--agent, var(--phosphor)) 18%, transparent); }
.run-request .run-progress-track::after { content: ''; position: absolute; inset: 0 auto 0 0; width: 32%; border-radius: inherit; background: var(--agent, var(--phosphor)); animation: run-travel 1.6s ease-in-out infinite alternate; }
@keyframes run-travel { from { transform: translateX(0); } to { transform: translateX(220%); } }
@media (prefers-reduced-motion: reduce) { .run-request .run-progress-track::after { animation: none; width: 100%; } }
.run-request .run-line.refused { cursor: not-allowed; opacity: .6; }
.run-request .run-line.refused .choice-tag { border-color: var(--text-3); color: var(--text-3); }
/* A command still alive: where it serves, and the two things to do with it. The tag holds still
   once it serves; serving is the steady state, not an alarm. */
.run-request .run-line.serving { cursor: default; border-color: var(--agent, var(--phosphor)); }
.run-request .run-line.serving .choice-tag { background: color-mix(in srgb, var(--agent, var(--phosphor)) 18%, transparent); }
.run-request .run-live { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 6px 10px; padding: 0 4px 2px; font-family: var(--mono); font-size: 10.5px; color: var(--text-2); }
.run-request .run-live .where { margin-right: auto; overflow-wrap: anywhere; }
.run-request .run-live button { border: 1px solid var(--line-2); background: transparent; color: var(--text-2); font: inherit; font-size: 9.5px; letter-spacing: .14em; padding: 4px 9px; border-radius: 7px; cursor: pointer; transition: color var(--motion-fast) var(--ease-out), border-color var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out); }
.run-request .run-live .run-open { border-color: color-mix(in srgb, var(--phosphor) 55%, transparent); color: var(--phosphor); }
.run-request .run-live .run-open:hover { background: color-mix(in srgb, var(--phosphor) 12%, transparent); }
.run-request .run-live .run-stop:hover { color: var(--danger); border-color: color-mix(in srgb, var(--danger) 60%, transparent); background: color-mix(in srgb, var(--danger) 10%, transparent); }
.run-request .run-live button:disabled { opacity: .5; cursor: default; }
.run-request .run-live button:focus-visible { outline: 0; box-shadow: var(--ring-soft); }
.run-request .run-why { margin: -2px 2px 4px 34px; font-size: 11.5px; line-height: 1.45; color: var(--text-3); }
.bishop-plan .bishop-order { cursor: default; }
.bishop-plan .bishop-order:active { transform: none; }
.bishop-plan .bishop-where { font-family: var(--mono); font-size: 10.5px; letter-spacing: .04em; color: var(--text-2); }
.bishop-plan .bishop-where b { color: var(--text); font-weight: 600; }
.bishop-plan .bishop-task { margin-top: 3px; overflow-wrap: anywhere; }
.bishop-plan .bishop-order .run-why { margin: 4px 0 0; }
.bishop-plan .bishop-order[data-status="blocked"], .bishop-plan .bishop-order[data-status="skipped"] { opacity: .62; }
.bishop-plan .bishop-act { border: 1px solid var(--line-2); background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; text-transform: uppercase; padding: 5px 10px; border-radius: 7px; cursor: pointer; transition: color var(--motion-fast) var(--ease-out), border-color var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out); }
.bishop-plan .bishop-act.primary { border-color: color-mix(in srgb, var(--agent, var(--phosphor)) 55%, transparent); color: var(--agent, var(--phosphor)); }
.bishop-plan .bishop-act.primary:hover { background: color-mix(in srgb, var(--agent, var(--phosphor)) 12%, transparent); }
.bishop-plan .bishop-act:disabled { opacity: .5; cursor: default; }
.bishop-plan .bishop-act:focus-visible { outline: 0; box-shadow: var(--ring-soft); }
.bishop-plan .choice-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 12px; }
.bishop-plan .bishop-mode { margin-left: auto; color: var(--text-3); }
.bishop-plan .choice-tags { gap: 6px; }
.bishop-plan .bishop-designation { width: 200px; max-width: 100%; border: 1px solid var(--line-2); background: transparent; color: var(--text); font-family: var(--mono); font-size: 11px; padding: 5px 8px; border-radius: 7px; }
.bishop-plan .bishop-designation:focus-visible { outline: 0; box-shadow: var(--ring-soft); }
.bishop-plan .bishop-order[data-status="done"] .choice-tag, .bishop-plan .bishop-link[data-status="signed"] .choice-tag { color: var(--phosphor); border-color: color-mix(in srgb, var(--phosphor) 45%, transparent); }
.bishop-plan .bishop-order[data-status="failed"] .choice-tag { color: var(--danger); border-color: color-mix(in srgb, var(--danger) 45%, transparent); }
.bishop-proposal > .bishop-act { margin-top: 10px; }
.link-reads { display: inline-flex; align-items: center; gap: 6px; font-family: var(--mono); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--text-2); }
.bubble-foot .link-reads { font-size: .68em; }
/* Its own line in the foot: the bubble breaks words anywhere, and squeezed into the row beside the
   stamp the mark shrank to one letter a line. */
.bubble-foot .link-reads { flex: 1 1 100%; order: -1; min-width: 0; flex-wrap: wrap; overflow-wrap: normal; word-break: normal; }
.link-reads .lead { color: var(--text-3); }
.bishop-plan.closed .choice-list { opacity: .72; }
.bishop-plan .bishop-state { color: var(--text-3); }
.bishop-plan .bishop-halt { margin: 0 2px 10px; color: var(--warn); }

/* What the room still has no answer to. Quieter than the free-turn offer above it: that one is
   about to save money, this one is only wondering. */
/* The label on its own line over a single row of pills. Wrapping put the third question on a
   second line and walked the composer down the page; a sideways rail keeps the height fixed
   however many the room is carrying. */
.openq { display: grid; justify-items: center; gap: 5px; margin: 0 0 8px; min-width: 0; }
.openq-lead { font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--text-2); }
.openq-rail { display: flex; gap: 6px; max-width: 100%; overflow-x: auto; scrollbar-width: none; padding: 1px 2px; }
.openq-rail::-webkit-scrollbar { display: none; }
.openq-rail > * { flex: 0 0 auto; }
/* An open question reads as something to press: a card with its own background, the question in
   full-strength text, and a phosphor «?» that says what kind of thing it is. */
.openq-ask { position: relative; max-width: min(360px, 100%); padding: 6px 13px 6px 32px; border: 1px solid color-mix(in srgb, var(--text-3) 40%, transparent); background: var(--panel); color: var(--text); font: inherit; font-size: 12px; line-height: 1.45; border-radius: 999px; cursor: pointer; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; box-shadow: 0 4px 14px -10px rgba(0, 0, 0, .5); }
.openq-ask::before { content: '?'; position: absolute; left: 7px; top: 50%; transform: translateY(-50%); width: 18px; height: 18px; display: grid; place-items: center; border-radius: 50%; background: color-mix(in srgb, var(--phosphor) 16%, transparent); color: var(--phosphor); font-family: var(--mono); font-size: 10px; font-weight: 700; }
.openq-ask:hover { background: color-mix(in srgb, var(--phosphor) 8%, var(--panel)); border-color: color-mix(in srgb, var(--phosphor) 55%, transparent); }

/* The free-turn offer: one line above the field, never in the way of typing. */
.free-offer { display: flex; align-items: center; gap: 12px; margin: 0 0 8px; padding: 8px 12px; border: 1px dashed var(--brew); border-radius: 10px; background: color-mix(in srgb, var(--brew) 7%, transparent); }
.free-offer .free-what { flex: 1; min-width: 0; font-family: var(--mono); font-size: 11px; line-height: 1.5; letter-spacing: .04em; color: var(--text-2); }
.free-offer .free-go { flex: none; border: 1px solid var(--brew); background: transparent; color: var(--brew); font-family: var(--mono); font-size: 10px; font-weight: 600; letter-spacing: .12em; padding: 6px 12px; border-radius: 7px; cursor: pointer; }
.free-offer .free-go:hover { background: color-mix(in srgb, var(--brew) 16%, transparent); }
@media (max-width: 720px) { .free-offer { flex-wrap: wrap; } }
:where(:root.room-720) .free-offer { flex-wrap: wrap; }
/* Intenciones: the same shelf as the @madre offer, in the room's accent when a cheaper rung was
   measured to be enough or is worth measuring, and in the warning ink when the rung chosen looks
   too light. The shelf itself is drawn with the box, below. */
.intent-offer { --tone: var(--phosphor); }
.intent-offer.up { --tone: var(--warn); }
.intent-offer .intent-basis { flex: none; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; padding: 2px 7px; border-radius: 5px; border: 1px solid color-mix(in srgb, var(--tone) 50%, transparent); color: var(--tone); }
.picker .effort-chip .intent-mark { color: var(--phosphor); font-size: 11px; line-height: 1; }
.picker .effort-chip .intent-mark.up { color: var(--warn); }
/* An invitation asks before it advises: a quieter "not now" beside the button that measures. */
.intent-offer .free-later { flex: none; border: 0; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 10px; letter-spacing: .12em; padding: 6px 8px; cursor: pointer; }
.intent-offer .free-later:hover { color: var(--text); }
/* The quick test's window: the room's own ink and reading type, so two answers read like answers. */
dialog.intents-window { width: 760px; height: 640px; }
.intents-body { overflow: auto; }
.intents-page { display: grid; gap: 14px; padding: 18px 22px 22px; align-content: start; }
.intents-page .intents-lead, .intents-page .intents-verdict { margin: 0; font-family: var(--read); font-weight: var(--read-weight); font-size: 14px; line-height: 1.55; color: var(--text); }
.intents-page .intents-verdict { font-size: 16px; }
.intents-page .note, .intents-page .intents-note { margin: 0; font-family: var(--mono); font-size: 10px; letter-spacing: .12em; color: var(--text-2); }
.intents-page .intents-pair { display: grid; gap: 12px; }
.intents-page .intents-question { margin: 0; font-family: var(--read); font-size: 16px; line-height: 1.5; color: var(--text); }
.intents-page .intents-answers { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; }
.intents-page .intents-answer { display: grid; gap: 6px; align-content: start; min-width: 0; }
.intents-page .intents-answer b { font-family: var(--mono); font-weight: 400; font-size: 10px; letter-spacing: .18em; color: var(--text-2); }
.intents-page .intents-answer .text { max-height: 300px; overflow: auto; padding: 12px 14px; border-radius: 12px; background: var(--bubble); color: var(--bubble-ink); font-family: var(--read); font-weight: var(--read-weight); font-size: 14px; line-height: 1.55; white-space: pre-wrap; overflow-wrap: anywhere; }
.intents-page .actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
.intents-page .actions button:not(.custom-accept) { height: 32px; padding: 0 16px; border: 1px solid var(--line-2); border-radius: 10px; background: transparent; color: var(--text); font-family: var(--mono); font-size: 10px; letter-spacing: .14em; cursor: pointer; }
.intents-page .actions button.primary { border-color: var(--phosphor); color: var(--phosphor); }
.intents-page .actions button:hover:not(:disabled) { background: color-mix(in srgb, var(--text) 6%, transparent); }
.intents-page .actions button:disabled { opacity: .45; cursor: default; }
.slash-menu { position: absolute; left: -12px; bottom: calc(100% + 14px); z-index: 30; min-width: 320px; max-width: min(580px, 92vw); border: 1px solid var(--line-2); background: var(--panel); border-radius: 14px; box-shadow: 0 14px 40px rgba(0, 0, 0, .35); padding: 6px; display: grid; gap: 2px; }
.slash-menu .item { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 10px; align-items: baseline; padding: 8px 10px; border-radius: 9px; cursor: pointer; border: 0; background: transparent; color: var(--text); text-align: left; font: inherit; }
.slash-menu .item .key { font-family: var(--mono); font-size: 12.5px; color: var(--agent, var(--phosphor)); font-weight: 600; white-space: nowrap; }
.slash-menu .item .what { font-size: 12.5px; line-height: 1.45; color: var(--text-2); display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; overflow: hidden; }
/* The argument syntax on its own line, under both, free to wrap. */
.slash-menu .item .args { grid-column: 1 / -1; font-family: var(--mono); font-size: 11px; line-height: 1.5; color: var(--text-3); overflow-wrap: anywhere; }
.slash-menu .item.off .key { color: var(--text-3); text-decoration: line-through; }
.slash-menu .item[aria-selected="true"], .slash-menu .item:hover { background: color-mix(in srgb, var(--agent, var(--phosphor)) 14%, transparent); }
.slash-menu .hint { padding: 4px 10px 6px; font-family: var(--mono); font-size: 10px; letter-spacing: .12em; color: var(--text-3); }
/* ---------- project files panel: lives in the free space right of the thread ---------- */
.tree-button { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 26px; border-radius: 6px; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); cursor: pointer; padding: 0; }
.tree-button svg { width: var(--ico-sm); height: var(--ico-sm); }
.tree-button:hover { color: var(--phosphor); border-color: var(--phosphor); box-shadow: var(--ring-soft); }
/* The conversations of this project, on the other side of the canvas from the files: the same
   panel, so there is one shape to learn, and never both edges at once on a narrow screen. */
.tree.chats { justify-self: start; margin: 18px 0 10px 20px; grid-template-rows: auto minmax(0, 1fr) auto auto; }
.chats-new { padding: 10px 12px; border-top: 1px solid var(--line); }
.chats-new-button { display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; border: 1px dashed var(--line-2); border-radius: 10px; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 10px; letter-spacing: .16em; padding: 9px 10px; cursor: pointer; }
.chats-new-button svg { width: var(--ico-sm); height: var(--ico-sm); }
.chats-new-button:hover { color: var(--phosphor); border-color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 8%, transparent); }
.chats-body { padding: 10px 8px; display: grid; gap: 6px; align-content: start; }
.chats-body .chat { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; align-items: baseline; width: 100%; border: 0; background: transparent; color: var(--text-2); font: inherit; text-align: left; padding: 11px 12px; border-radius: 10px; cursor: pointer; }
.chats-body .chat:hover { background: color-mix(in srgb, var(--phosphor) 10%, transparent); color: var(--text); }
.chats-body .chat .name { font-family: var(--sans, inherit); font-size: 12.5px; line-height: 1.4; color: var(--text); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chats-body .chat .when { font-family: var(--mono); font-size: 9px; letter-spacing: .08em; color: var(--text-3); white-space: nowrap; }
.chats-body .chat-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 4px; }
.chats-body .chat-drop { border: 0; background: transparent; color: var(--text-3); font: inherit; font-size: 13px; line-height: 1; padding: 4px 7px; border-radius: 7px; cursor: pointer; opacity: 0; }
.chats-body .chat-row:hover .chat-drop, .chats-body .chat-drop:focus-visible { opacity: 1; }
.chats-body .chat-drop:hover { color: var(--danger); background: color-mix(in srgb, var(--danger) 12%, transparent); }
.chats-body .chat-drop.sure { opacity: 1; color: #fff; background: var(--danger); }
/* A conversation at work spins before its name; one that finished while you were elsewhere keeps
   a dot until you open it. The toggle carries the same two signs while the panel is closed. */
.chats-body .chat-spin { display: inline-block; width: 9px; height: 9px; margin-right: 8px; border: 1.5px solid color-mix(in srgb, var(--phosphor) 30%, transparent); border-top-color: var(--phosphor); border-radius: 50%; vertical-align: -1px; animation: chat-spin .8s linear infinite; }
.chats-body .chat-dot { display: inline-block; width: 7px; height: 7px; margin-right: 8px; border-radius: 50%; background: var(--phosphor); box-shadow: 0 0 6px var(--phosphor); vertical-align: 1px; }
.chats-body .chat.unread .name { font-weight: 600; }
@keyframes chat-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .chats-body .chat-spin { animation: none; border-color: var(--phosphor); } }
.chats-button { position: relative; }
.chats-button.working::after, .chats-button.unread::after { content: ''; position: absolute; top: 4px; right: 4px; width: 7px; height: 7px; border-radius: 50%; background: var(--phosphor); box-shadow: 0 0 6px var(--phosphor); }
.chats-button.working::after { animation: klaxon 1.2s ease-in-out infinite; }
.project.chat-here { flex: 0 1 auto; max-width: 340px; color: var(--text-2); }
.chats-foot { padding: 10px 14px; border-top: 1px solid var(--line); font-family: var(--mono); font-size: 8.5px; letter-spacing: .12em; color: var(--text-3); }
/* Its handle sits in the canvas, under the bar, where the conversation it opens begins. */
.chats-button { grid-row: 3; justify-self: start; align-self: start; z-index: 6; margin: 18px 0 0 20px; display: inline-flex; align-items: center; justify-content: center; width: 40px; height: 36px; border-radius: 11px; border: 1px solid var(--line-2); background: var(--panel); color: var(--text-2); cursor: pointer; padding: 0; }
.chats-button svg { width: var(--ico-lg); height: var(--ico-lg); }
.chats-button:hover { color: var(--phosphor); border-color: var(--phosphor); box-shadow: var(--ring-soft); }
.chats-button:active { transform: translateY(1px); }

.tree { position: relative; grid-row: 3; justify-self: end; align-self: stretch; z-index: 5; width: var(--chats-w, clamp(320px, calc(50vw - 468px), 460px)); margin: 18px 20px 10px 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border: 1px solid var(--line-2); border-radius: 18px; background: var(--panel); box-shadow: 0 10px 30px rgba(0, 0, 0, .06); overflow: hidden; transition: box-shadow var(--glide) var(--ease-glide), border-color var(--glide) var(--ease-glide); }
/* The finder's own row of tools: a search, and what is waiting to be pasted. */
.tree { grid-template-rows: auto auto auto minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); }
/* The files panel reads paths and asks for names; at its old 240px floor neither fit. */
#tree.tree { width: var(--tree-w, clamp(300px, calc(50vw - 476px), 460px)); }
.tree-search { padding: 8px 12px 6px; }
.tree-search input { width: 100%; border: 1px solid var(--line-2); border-radius: 8px; background: color-mix(in srgb, var(--text-3) 6%, transparent); color: var(--text); font-family: var(--mono); font-size: 11px; padding: 6px 10px; outline: 0; }
.tree-search input:focus { border-color: var(--phosphor); }
.tree-clip { display: flex; flex-wrap: wrap; min-width: 0; align-items: center; gap: 6px 8px; margin: 0 12px 6px; padding: 8px 10px; border: 1px dashed var(--phosphor); border-radius: 8px; font-family: var(--mono); font-size: 11px; color: var(--text-2); }
.tree-clip .what { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tree-clip .how { flex: 1 1 100%; font-size: 10px; line-height: 1.45; color: var(--text-3); }
.tree-clip button { border: 0; border-radius: 6px; background: transparent; color: var(--phosphor); font: inherit; font-size: 11px; letter-spacing: .08em; padding: 4px 8px; cursor: pointer; }
.tree-clip button:hover { background: color-mix(in srgb, var(--phosphor) 12%, transparent); }
/* What is being asked is its own line, and the box has the full width under it: a placeholder in
   a strip three words wide was cut off before anyone could read it. */
.tree-ask { display: grid; gap: 6px; flex: 1 1 100%; min-width: 0; }
.tree-ask .ask-label { font-size: 11px; letter-spacing: .1em; color: var(--text); }
.tree-ask .ask-label .where { margin-left: 6px; letter-spacing: 0; color: var(--text-3); overflow-wrap: anywhere; }
.tree-ask .ask-hint { font-size: 10.5px; line-height: 1.45; color: var(--text-2); overflow-wrap: anywhere; }
.tree-ask input { width: 100%; min-width: 0; border: 1px solid var(--line-2); border-radius: 6px; background: color-mix(in srgb, var(--text-3) 6%, transparent); color: var(--text); font: inherit; font-size: 13px; padding: 6px 8px; outline: none; }
.tree-ask input:focus { border-color: var(--phosphor); }
.tree-ask .ask-actions { display: flex; justify-content: flex-end; gap: 4px; }
.tree-ask .go { color: var(--bg); background: var(--phosphor); }
.tree-ask .go:hover { background: var(--phosphor); filter: brightness(1.08); }
.tree .node.fresh { animation: tree-fresh 2.4s ease-out; }
@keyframes tree-fresh { 0%, 35% { background: color-mix(in srgb, var(--phosphor) 22%, transparent); } 100% { background: transparent; } }
@media (prefers-reduced-motion: reduce) { .tree .node.fresh { animation: none; background: color-mix(in srgb, var(--phosphor) 14%, transparent); } }
.tree-menu { position: absolute; z-index: 20; min-width: 170px; border: 1px solid var(--line-2); border-radius: 10px; background: var(--panel); box-shadow: 0 12px 30px rgba(0,0,0,.35); padding: 5px; display: grid; gap: 1px; }
.tree-menu button { border: 0; background: transparent; color: var(--text); font: inherit; font-size: 12px; text-align: left; padding: 7px 10px; border-radius: 7px; cursor: pointer; }
.tree-menu button:hover { background: color-mix(in srgb, var(--phosphor) 12%, transparent); }
.tree-menu .guarded { color: var(--warn); }
/* A zone is a state, not a category: the one that still travels wears the room's own green, the
   one that does not is dimmed to the colour of everything the archive keeps and never serves. */
.nostromo-card .zone { font-family: var(--mono); font-size: 10px; letter-spacing: .12em; }
.nostromo-card .zone.underway { color: var(--phosphor); }
.nostromo-card .zone.archived { color: var(--text-3); opacity: .75; }
.nostromo-card .zone.archived::after { content: ' ·'; }

/* The brake for one answer, in the row of the answer it stops. Quiet until the turn is worth
   stopping — which is when the human is already looking at it. */
.stop-turn {
  margin-left: 10px; padding: 2px 9px; border: 1px solid var(--line-2); border-radius: 999px;
  background: transparent; color: var(--text-3);
  font-family: var(--mono); font-size: 9px; letter-spacing: .14em; cursor: pointer;
  opacity: .5; transition: opacity calc(150ms * var(--motion-scale)), color calc(150ms * var(--motion-scale)), border-color calc(150ms * var(--motion-scale));
}
.row.thinking:hover .stop-turn, .stop-turn:focus-visible { opacity: 1; }
.stop-turn:hover { color: var(--terror); border-color: var(--terror); }
.stop-turn:disabled { opacity: .7; cursor: default; color: var(--text-3); border-color: var(--line-2); }

.tree-menu .note { padding: 5px 10px 6px; font-family: var(--mono); font-size: 8.5px; letter-spacing: .1em; color: var(--text-3); }

@keyframes panel-in-right { from { opacity: 0; transform: translateX(22px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes panel-in-left { from { opacity: 0; transform: translateX(-22px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes panel-out-right { to { opacity: 0; transform: translateX(18px) scale(.985); } }
@keyframes panel-out-left { to { opacity: 0; transform: translateX(-18px) scale(.985); } }
/* Conversations open where their handle is. The files panel is anchored right because its button
   lives in the bar's right end; this one's handle sits at the left of the thread, so a panel that
   appeared on the far side — behind the browser, once there is one — read as not opening at all. */
.chats { justify-self: start; margin-left: 20px; margin-right: 0; z-index: 7; transform-origin: left center; }
#tree.tree { transform-origin: right center; }
.tree-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 12px 10px 16px; border-bottom: 1px solid var(--line); font-family: var(--mono); font-size: 10px; letter-spacing: .18em; color: var(--text-2); }
.tree-title { display: flex; gap: 8px; align-items: baseline; min-width: 0; }
.tree-root { color: var(--text-3); letter-spacing: .06em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tree-close { border: 0; background: transparent; color: var(--text-3); font: inherit; font-size: 16px; line-height: 1; cursor: pointer; padding: 2px 6px; border-radius: 6px; }
.tree-close:hover { color: var(--text); background: var(--line); }
.tree-body { overflow: auto; padding: 8px 8px 14px; font-family: var(--mono); font-size: 12px; letter-spacing: .01em; }
.tree-body ul { list-style: none; margin: 0; padding: 0; }
.tree-body ul ul { padding-left: 14px; border-left: 1px solid var(--line); margin-left: 9px; }
.tree-body li { margin: 0; }
.tree-body .node { display: flex; align-items: center; gap: 6px; width: 100%; border: 0; background: transparent; color: var(--text-2); font: inherit; text-align: left; padding: 4px 8px; border-radius: 7px; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tree-body .node:hover { background: color-mix(in srgb, var(--phosphor) 10%, transparent); color: var(--text); }
.tree-body .node .caret { width: 10px; color: var(--text-3); flex: none; font-size: 10px; }
.tree-body .node .name { overflow: hidden; text-overflow: ellipsis; }
.tree-body .node.dir .name { color: var(--text); }
.tree-body .node.file .name::before { content: ''; display: inline-block; width: 6px; height: 6px; border-radius: 2px; margin-right: 7px; background: var(--line-2); vertical-align: 1px; }
.tree-body .node.file.image .name::before { background: var(--phosphor); }
.tree-body .node.file.code .name::before { background: color-mix(in srgb, var(--warn) 70%, transparent); }
.tree-body .node .size { margin-left: auto; color: var(--text-3); font-size: 10px; padding-left: 8px; }
.tree-body .node.shallow .name::after { content: ' · not walked'; color: var(--text-3); font-size: 10px; }
.tree-body .empty-dir, .tree-body .error { padding: 4px 24px; color: var(--text-3); font-size: 11px; }
/* On a narrow window only the browser steps out (it needs a side of its own); the files, like the
   conversations, open over the thread, and PERSONALIZE and reload stay in the bar. */
@media (max-width: 1180px) { #browser-button { display: none !important; } }

.command-card { margin: 10px 0 6px; max-width: min(860px, 100%); border: 1px solid var(--line-2); border-radius: 12px; background: color-mix(in srgb, var(--panel) 80%, transparent); overflow: hidden; }
.command-card.failed { border-color: color-mix(in srgb, var(--crit) 60%, transparent); }

/* EYECAT: a question the room is asking the human, so it reads as one thing until it is answered. */
.command-card.eyecat { border-color: color-mix(in srgb, var(--mem-aberration) 55%, transparent); }
.command-card.eyecat .head b { color: var(--mem-aberration); }
.command-card.eyecat > div:not(.head):not(.eyecat-actions):not(.eyecat-settled) { padding: 10px 12px; border-bottom: 1px solid var(--line-2); }
.command-card.eyecat b { display: block; font-family: var(--mono); font-size: 9px; letter-spacing: .18em; color: var(--text-2); margin-bottom: 4px; }
.command-card.eyecat p { margin: 0; font-size: 13.5px; line-height: 1.5; }
.command-card.eyecat .eyecat-claim p { color: var(--mem-aberration); }
.command-card.eyecat .eyecat-correction p { color: var(--ok, #9bff66); }
.eyecat-actions { display: flex; gap: 8px; padding: 10px 12px; }
.eyecat-actions button { font-family: var(--mono); font-size: 10px; letter-spacing: .16em; padding: 6px 12px; border-radius: 999px; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); cursor: pointer; }
.eyecat-actions button.primary { border-color: color-mix(in srgb, var(--mem-aberration) 70%, transparent); color: var(--mem-aberration); }
.eyecat-actions button:hover:not(:disabled) { background: var(--ph-faint); }
.eyecat-actions button:disabled { opacity: .45; cursor: default; }
.eyecat-settled { padding: 9px 12px; font-family: var(--mono); font-size: 9.5px; letter-spacing: .16em; color: var(--text-2); }
.command-card.eyecat.filed { border-color: color-mix(in srgb, var(--mem-aberration) 75%, transparent); }
.command-card.eyecat.stands { border-color: var(--line-2); opacity: .7; }
.command-card .head { display: flex; gap: 10px; align-items: baseline; padding: 8px 12px; font-family: var(--mono); font-size: 10.5px; letter-spacing: .14em; color: var(--text-2); border-bottom: 1px solid var(--line-2); }
.command-card .head b { color: var(--phosphor); font-weight: 600; }
.command-card .head .args { color: var(--text-3); letter-spacing: .04em; }
.command-card .head > span { min-width: 0; overflow-wrap: anywhere; }
.command-card pre { margin: 0; padding: 10px 12px; max-height: 320px; overflow: auto; font-family: var(--mono); font-size: 12px; line-height: 1.55; color: var(--text); white-space: pre-wrap; overflow-wrap: anywhere; }
.command-card pre .h { color: var(--phosphor); font-weight: 600; }
.command-card .undo { margin: 0 12px 10px; border: 1px solid var(--terror); background: color-mix(in srgb, var(--terror) 12%, transparent); color: var(--terror); font: inherit; font-family: var(--mono); font-size: 10px; letter-spacing: .16em; padding: 7px 12px; border-radius: 8px; cursor: pointer; }
.command-card .undo:hover { background: color-mix(in srgb, var(--terror) 22%, transparent); }
.command-card .undo:disabled { opacity: .5; cursor: default; }
/* What a terminal said, folded (2026-10-14): one line — the command, how it ended, how long, who
   asked — and its last line beneath; the output opens on a click, without a jump. */
.command-card.terminal .term-head { all: unset; box-sizing: border-box; display: flex; align-items: center; gap: 10px; width: 100%; padding: 9px 12px; cursor: pointer; font-family: var(--mono); font-size: 11.5px; color: var(--text-2); }
.command-card.terminal .term-head:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 55%, transparent); outline-offset: -2px; border-radius: 12px; }
.command-card.terminal .term-tag { flex: none; font-size: 9.5px; letter-spacing: .14em; font-weight: 600; color: var(--text-3); }
.command-card.terminal code.term-line { padding: 0; border: 0; background: none; }
.command-card.terminal .term-line { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mono); font-size: 12px; color: var(--text); }
.command-card.terminal .term-status { flex: none; padding: 2px 9px; border-radius: 999px; font-size: 10px; letter-spacing: .03em; white-space: nowrap; color: var(--text-2); background: color-mix(in srgb, var(--text) 6%, transparent); }
.command-card.terminal .term-status.ok { color: var(--ok, #2f9e44); background: color-mix(in srgb, var(--ok, #2f9e44) 12%, transparent); }
.command-card.terminal .term-status.failed { color: var(--crit); background: color-mix(in srgb, var(--crit) 12%, transparent); }
.command-card.terminal .term-who { flex: none; font-size: 10.5px; color: var(--agent, var(--text-3)); }
.command-card.terminal .term-count { flex: none; font-size: 10px; color: var(--text-3); white-space: nowrap; }
.command-card.terminal .term-head .chev-icon { flex: none; display: inline-flex; color: var(--text-3); transition: transform .22s ease; }
.command-card.terminal.open .term-head .chev-icon { transform: rotate(180deg); }
.command-card.terminal .term-peek { margin-top: -4px; padding: 0 12px 9px; font-family: var(--mono); font-size: 11px; color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.command-card.terminal.open .term-peek { display: none; }
/* A module's own page for this result (a report to print): a key under the card's line. */
.command-card.terminal .term-link { display: inline-flex; align-items: center; margin: -2px 12px 10px; padding: 6px 12px; border-radius: 999px; background: var(--madre-green); color: #fff; font-size: 12.5px; font-weight: 650; text-decoration: none; }
.command-card.terminal .term-link:hover { filter: brightness(1.08); }
.command-card.terminal .term-out { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .24s ease; }
.command-card.terminal.open .term-out { grid-template-rows: 1fr; }
.command-card.terminal .term-clip { min-height: 0; overflow: hidden; }
.command-card.terminal pre { max-height: 420px; border-top: 1px solid var(--line-2); background: color-mix(in srgb, var(--text) 3%, transparent); }
.command-card.terminal pre .l-bad { color: var(--crit); }
.command-card.terminal pre .l-good { color: var(--ok, #2f9e44); }
.command-card.terminal .undo { margin-top: 10px; }
@media (max-width: 560px) { .command-card.terminal .term-count, .command-card.terminal .term-tag { display: none; } }
@media (prefers-reduced-motion: reduce) { .command-card.terminal .term-out, .command-card.terminal .term-head .chev-icon { transition: none; } }
.command-card .outcome { display: inline-block; margin: 0 12px 10px; font-family: var(--mono); font-size: 10px; letter-spacing: .16em; color: var(--phosphor); }

.module-card select { border: 1px solid var(--ph-dim); background: #000; color: var(--ph); font: inherit; font-size: 10.5px; letter-spacing: .06em; padding: 6px 8px; }

/* Copy and reply at the end of every reply: faint until the pointer is over the bubble. */
.bubble-actions { display: flex; justify-content: flex-end; gap: 2px; margin: 6px -8px -6px 0; opacity: 0; transition: opacity calc(180ms * var(--motion-scale)) ease; }
.bubble:hover .bubble-actions, .bubble:focus-within .bubble-actions { opacity: 1; }
@media (hover: none) { .bubble-actions { opacity: .55; } }
.bubble-actions .act { width: 26px; height: 26px; display: grid; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--text-3); cursor: pointer; padding: 0; transition: color calc(150ms * var(--motion-scale)), background calc(150ms * var(--motion-scale)); }
.bubble-actions .act svg { width: var(--ico-sm); height: var(--ico-sm); }
.bubble-actions .act:hover { color: var(--text); background: color-mix(in srgb, var(--text) 8%, transparent); }
.bubble-actions .act.good.on { color: var(--phosphor); }
.bubble-actions .act.bad.on { color: var(--terror); }
.bubble-actions .act.prefer.on { color: var(--phosphor); }
.bubble-actions .act.never.on { color: var(--terror); }
/* Shown only once the verdict they escalate is in: at rest the bubble carries no extra chrome. */
.bubble-actions .act.prefer[hidden], .bubble-actions .act.never[hidden] { display: none; }
.bubble-actions .act.done { color: var(--phosphor); }
.reply-menu { width: min(280px, calc(100vw - 24px)); padding: 8px; }
.reply-menu .model-menu-title { margin: 4px 8px 6px; }
.reply-menu .item { display: flex; gap: 10px; align-items: center; width: 100%; padding: 8px 10px; border-radius: 8px; border: 0; background: transparent; color: var(--text); font: inherit; font-size: 13px; cursor: pointer; text-align: left; }
.reply-menu .item b { color: var(--agent, var(--text)); font-family: var(--mono); font-size: 11px; letter-spacing: .06em; }
.reply-menu .item span { color: var(--text-3); font-size: 12px; }
.reply-menu .item:hover { background: color-mix(in srgb, var(--agent, var(--phosphor)) 12%, transparent); }
.reply-menu .item:disabled { opacity: .4; cursor: default; }

/* Light scheme: the CRT glow is a dark-room effect. In daylight, the room keeps its colours and loses the shine;
   MU/TH/UR's and NOSTROMO's own screens stay as they are. */
:root[data-scheme="light"] :not(.mother-frame, .mother-frame *, .nostromo-frame, .nostromo-frame *, .override-frame, .override-frame *) { text-shadow: none; }
:root[data-scheme="light"] { --brand-pulse: #2f8a1c; --brand-word: #121512; }
:root[data-scheme="light"] .field button[type="submit"] { box-shadow: 0 1px 2px rgba(0, 0, 0, .12), 0 2px 6px rgba(0, 0, 0, .08); }
:root[data-scheme="light"] .user .bubble { box-shadow: var(--lift-1); }
:root[data-scheme="light"] .composer.control .field { box-shadow: 0 0 0 2px color-mix(in srgb, var(--terror) 30%, transparent); }
:root[data-scheme="light"] .composer.airlock .field { box-shadow: 0 0 0 2px color-mix(in srgb, var(--mode-4) 35%, transparent); }
:root[data-scheme="light"] .composer.creating .field, :root[data-scheme="light"] .composer.creating.ordering .field { box-shadow: 0 0 0 2px color-mix(in srgb, var(--mode-2) 30%, transparent); }
:root[data-scheme="light"] .composer.dropping .field { box-shadow: 0 0 0 2px color-mix(in srgb, var(--phosphor) 35%, transparent); }
:root[data-scheme="light"] .composer.module-command .field { box-shadow: 0 0 0 2px color-mix(in srgb, var(--module-electric) 34%, transparent); }
:root[data-scheme="light"] .memory-hint .pill { animation: none; box-shadow: none; }
:root[data-scheme="light"] .mode-menu .mode-option .tag .dot { box-shadow: none; }
:root[data-scheme="light"] .picker .mode-chip, :root[data-scheme="light"] .who .badge { text-shadow: none; box-shadow: none; }
:root[data-scheme="light"] .stop-all.armed { box-shadow: none; }
:root[data-scheme="light"] .system.alert, :root[data-scheme="light"] .system.control, :root[data-scheme="light"] .system.mother, :root[data-scheme="light"] .system.mother-alert { text-shadow: none; }
:root[data-scheme="light"] .system.mother-alert { background: color-mix(in srgb, var(--terror) 4%, transparent); }
:root[data-scheme="light"] .crew-label { text-shadow: none; animation: none; }

/* MU/TH/UR: the sentinel section. */
.mother-section.sentinel .toggle, .mother-section.update .toggle { display: flex; align-items: center; gap: 8px; font-size: 10px; letter-spacing: .16em; color: var(--ph-dim); cursor: pointer; }
.mother-section.sentinel .toggle input, .mother-section.update .toggle input { accent-color: var(--brew); margin: 0; flex: none; }
.mother-section.sentinel .toggle input:disabled + * , .mother-section.sentinel .toggle:has(input:disabled) { opacity: .6; cursor: default; }
.mother-section.sentinel button, .mother-section.update button { border: 1px solid var(--ph-dim); background: transparent; color: var(--ph); font: inherit; font-size: 9.5px; letter-spacing: .16em; padding: 6px 10px; cursor: pointer; }
.mother-section.sentinel button:hover, .mother-section.update button:hover { background: var(--ph-faint); }
.module-card .ollama-status { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; font-size: 10px; letter-spacing: .1em; }
.module-card .ollama-status dt { color: var(--ph-dim); } .module-card .ollama-status dd { margin: 0; color: rgba(210, 255, 190, .85); overflow-wrap: anywhere; }
.module-card .actions .toggle { display: inline-flex; align-items: center; gap: 6px; font-size: 9.5px; letter-spacing: .14em; color: var(--ph-dim); cursor: pointer; }
.module-card .actions .toggle input { accent-color: var(--brew); }
.mother-section.sentinel .note, .mother-section.update .note { margin: 0 0 10px; font-size: 10px; letter-spacing: .12em; line-height: 1.7; color: var(--ph-dim); }

/* Motion of controls: every colour change eases over 220 ms. Nothing snaps. */
.mother-button, .tree-button, .chats-button, .stop-all, .mother-close, .mother-section button, .seg-option, .mode-chip, .model-chip, .bubble-actions .act, .codeblock .copy { transition: background-color calc(220ms * var(--motion-scale)) ease, color calc(220ms * var(--motion-scale)) ease, border-color calc(220ms * var(--motion-scale)) ease, box-shadow calc(220ms * var(--motion-scale)) ease, opacity calc(220ms * var(--motion-scale)) ease, transform calc(160ms * var(--motion-scale)) ease; }
.mother-button:active, .tree-button:active, .mother-close:active, .mother-section button:active { transform: scale(.98); }
@media (prefers-reduced-motion: reduce) { .mother-button, .tree-button, .chats-button, .stop-all, .mother-close, .mother-section button, .seg-option, .mode-chip, .model-chip, .bubble-actions .act, .update-pill { transition: none; } }

/* ================= icons: one hand for the bar and the conversations =================
   Every control in the bar carries a drawing in the same idiom — 20×20, round ends, one stroke —
   and its word, where it has one, beside it. What is open is drawn heavier and its word is set
   bolder; the pointer gets half of that on the way. Colour, weight and ground carry the state. */
.bar .bar-glyph { display: block; flex: none; width: var(--ico-sm); height: var(--ico-sm); }
.bar > .mother-button .mother-glyph { display: none; }
.bar > .mother-button, .bar > .stop-all { gap: 7px; }
.update-glyph { display: inline-flex; }
@container bar (max-width: 980px) {
  .bar > :is(.mother-button, .stop-all) .bar-glyph { width: var(--ico-md); height: var(--ico-md); }
  .bar > .mother-button, .bar > .stop-all { gap: 0; }
}
/* The live line: the dot keeps saying the state, the waves around it say what the dot is. */
.connection-icon { display: inline-grid; place-items: center; flex: none; }
.connection-icon > * { grid-area: 1 / 1; }
.bar .connection .bar-glyph { width: 16px; height: 16px; color: var(--text-3); transition: color var(--motion) var(--ease-out), opacity var(--motion) var(--ease-out); opacity: .7; }
.connection[data-state="live"] .connection-icon .bar-glyph { color: var(--phosphor); opacity: .55; }
.connection[data-state="reconnecting"] .connection-icon .bar-glyph { color: var(--warn); }

/* One stroke, read from the control that holds the drawing, so a state changes it in one place. */
.bar > :is(.tree-button, .mother-button, .stop-all, .bar-icon), .connection-icon, .chats-button, .chats .tree-close, .chats-new-button, .chats-body .chat-glyph { --icon-w: var(--icon-stroke); }
:is(.bar > :is(.tree-button, .mother-button, .stop-all, .bar-icon), .connection-icon, .chats-button, .chats .tree-close, .chats-new-button, .chats-body .chat-glyph) svg :is(path, circle, rect) {
  stroke-width: var(--icon-w);
  transition: stroke-width var(--motion) var(--ease-out);
}
:is(.bar > :is(.tree-button, .mother-button, .stop-all, .bar-icon), .chats-button, .chats .tree-close, .chats-new-button) svg {
  transition: transform var(--motion) var(--ease-out);
}
.bar > :is(.tree-button, .mother-button, .bar-icon, .update-pill, .stop-all.armed):hover,
.chats-button:hover, .chats .tree-close:hover, .chats-new-button:hover { --icon-w: var(--icon-stroke-hover); }
.bar > :is(.tree-button, .mother-button, .bar-icon, .update-pill):hover svg,
.chats-button:hover svg, .chats-new-button:hover svg { transform: translateY(-.5px) scale(1.07); }

/* Pressed: the panel or the screen it opens is open. Heavier line, bolder word, a tint of ground. */
.bar > :is(.tree-button, .mother-button):not(.arming), .chats-button {
  font-weight: 400;
  transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out), border-color var(--motion) var(--ease-out), box-shadow var(--motion) var(--ease-out), font-weight var(--motion) var(--ease-out), opacity var(--motion) var(--ease-out), transform var(--motion-fast) var(--ease-out);
}
.bar > :is(.tree-button, .mother-button)[aria-pressed="true"], .chats-button[aria-pressed="true"] {
  /* Open: the drawing fills and the word goes bold. The button around it stays as it was. */
  font-weight: 650; color: var(--text);
}
.bar > :is(.tree-button, .mother-button)[aria-pressed="true"] svg, .chats-button[aria-pressed="true"] svg { color: var(--phosphor); }
.bar > :is(.tree-button, .mother-button), .chats-button { --knock: var(--bg); }
/* PERSONALIZE's drawing is mostly line: filling its two knobs alone read as half on. Open, its
   line takes the heavy weight too, so the whole drawing goes bold like the others. */
.bar > .custom-button[aria-pressed="true"] { --icon-w: var(--icon-stroke-on); }
.chats-button { --knock: var(--panel); }

/* The filled drawing. ic-f is the shape that fills, ic-k the detail cut out of it in the colour of
   the ground behind, ic-disc a disc for a drawing with no shape of its own (a line), and ic-ring
   repaints an outline the cut would otherwise notch. Fill comes in with a short ease; the shape
   settles from a hair smaller so the change is felt, not just seen. */
.ic-f { transition: fill var(--motion) var(--ease-out), stroke var(--motion) var(--ease-out); }
.ic-k { transition: stroke var(--motion) var(--ease-out); }
.ic-disc { fill: currentColor; opacity: 0; transform: scale(.55); transform-origin: center; transform-box: fill-box; transition: opacity var(--motion) var(--ease-out), transform var(--motion-slow) var(--ease-out); }
:is(.bar > :is(.tree-button, .mother-button)[aria-pressed="true"], .chats-button[aria-pressed="true"]) svg {
  animation: icon-fill var(--motion-slow) var(--ease-out);
}
:is(.bar > :is(.tree-button, .mother-button)[aria-pressed="true"], .chats-button[aria-pressed="true"], .chats-body .chat.on) .ic-f { fill: currentColor; }
:is(.bar > :is(.tree-button, .mother-button)[aria-pressed="true"], .chats-button[aria-pressed="true"], .chats-body .chat.on) .ic-k { stroke: var(--knock, var(--bg)); opacity: 1; }
:is(.bar > :is(.tree-button, .mother-button)[aria-pressed="true"], .chats-button[aria-pressed="true"]) .ic-disc { opacity: 1; transform: none; }
@keyframes icon-fill { from { transform: scale(.86); } 60% { transform: scale(1.06); } to { transform: none; } }
.bar > :is(.tree-button, .mother-button, .bar-icon):active { transform: scale(.96); }

/* The conversations and the files are read, not glanced at: 240px cut every name to its first
   two words. They take at least 320px, and up to 460px when the side of the room has it. */
@media (max-width: 720px) { .tree { width: min(320px, calc(100vw - 32px)); } }
/* ---------- conversations ---------- */
/* Its arrival is .entering's alone (the panels section below). An animation of its own here
   replayed the moment .entering was taken off — the panel arrived twice. */
.tree.chats { transform-origin: left top; }
.chats .tree-close { display: inline-grid; place-items: center; padding: 4px; transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out); }
.chats .tree-close svg { display: block; width: var(--ico-sm); height: var(--ico-sm); }
.chats .tree-close:hover svg { transform: rotate(90deg); }
.chats-new-button { transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out), border-color var(--motion) var(--ease-out); }
.chats-new-button:hover { border-style: solid; }
.chats-new-button svg { width: var(--ico-sm); height: var(--ico-sm); }
.chats-body .chat { grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; transition: background-color var(--motion) var(--ease-out), color var(--motion) var(--ease-out), transform var(--motion-fast) var(--ease-out); }
.chats-body .chat:active { transform: scale(.985); }
.chats-body .chat-glyph { display: grid; place-items: center; width: 16px; height: 16px; color: var(--text-3); transition: color var(--motion) var(--ease-out), transform var(--motion) var(--ease-out); }
.chats-body .chat-glyph svg { display: block; width: var(--ico-sm); height: var(--ico-sm); }
.chats-body .chat-glyph :is(.chat-spin, .chat-dot) { margin: 0; vertical-align: 0; }
.chats-body .chat:hover .chat-glyph { color: var(--text-2); transform: translateX(1px); }
.chats-body .chat.on .chat-glyph { color: var(--phosphor); transform: none; }
.chats-body .chat { --knock: var(--panel); }
.chats-body .chat .name { font-weight: 400; transition: font-weight var(--motion) var(--ease-out), color var(--motion) var(--ease-out); }
.chats-body .chat.on .name, .chats-body .chat.unread .name { font-weight: 600; }
.chats-body .chat.on .name { color: var(--text); }

@media (prefers-reduced-motion: reduce) {
  :root { --motion-fast: 0s; --motion: 0s; --motion-slow: 0s; }
  .tree.chats { animation: none; }
  :is(.bar > *, .chats-button, .chats .tree-close, .chats-new-button, .chats-body .chat) svg,
  .chats-body .chat-glyph, .bar > *:active, .chats-body .chat:active { transform: none !important; }
}
.tour-button { min-width: 30px; padding: 6px 0; text-align: center; font-weight: 700; }

/* DEV modules and proposals */
.module-card .dev-tag { font-family: var(--mono); font-size: 8.5px; letter-spacing: .18em; color: var(--warn); border: 1px solid color-mix(in srgb, var(--warn) 55%, transparent); padding: 2px 7px; margin-left: 8px; align-self: center; }
.module-card .note { font-size: 9.5px; letter-spacing: .1em; color: var(--ph-dim); text-transform: none; }
.system.module-proposed { color: var(--text-3); } .system.module-proposed .who { color: var(--agent, var(--text-2)); }

/* The local model saying whether it has been measured against this project, and the one button
   that measures it. Same system line as the rest, with room for an answer and an action. */
.system.local-model { color: var(--text-3); display: grid; gap: 8px; justify-items: center; }
.system.local-model .who { color: var(--agent, var(--text-2)); }
.system.local-model .says { margin: 0; max-width: 52ch; font-size: 11px; letter-spacing: .04em; text-transform: none; line-height: 1.65; color: var(--text-2); }
.system.local-model .acts { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 8px; }
.system.local-model button { border: 1px solid var(--line-2); border-radius: 999px; background: transparent; color: var(--text-2); font: inherit; font-size: 9.5px; letter-spacing: .16em; text-transform: uppercase; padding: 5px 12px; cursor: pointer; }
.system.local-model button:hover:not(:disabled) { border-color: var(--phosphor); color: var(--phosphor); }
.system.local-model button:disabled { opacity: .5; cursor: default; }
.system.local-model button.primary { border-color: var(--phosphor); color: var(--phosphor); }
.system.local-model .note { font-size: 8.5px; letter-spacing: .14em; color: var(--text-3); }
.system.local-model .says.small { color: var(--text-3); }

/* THE BRIDGE: first contact, one card per agent with the one action it needs now. */
.bridge { max-width: 640px; }
.bridge h2 { margin: 0 0 8px; }
.bridge-crew { display: grid; gap: 10px; width: 100%; margin: 18px 0 6px; text-align: left; }
.bridge-card { border: 1px solid var(--line-2); border-radius: 14px; padding: 14px 16px; background: var(--panel); display: grid; gap: 10px; }
.bridge-card .head { display: flex; align-items: center; gap: 10px; }
.bridge-card .title { display: grid; gap: 2px; min-width: 0; flex: 1; }
.bridge-card .title b { font-size: 13px; letter-spacing: .02em; color: var(--text); }
.bridge-card .vendor { font-family: var(--mono); font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--text-3); }
.bridge-card .state { font-family: var(--mono); font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--text-3); border: 1px solid var(--line-2); border-radius: 999px; padding: 3px 9px; white-space: nowrap; }
.bridge-card .state.ready { color: var(--phosphor); border-color: color-mix(in srgb, var(--phosphor) 55%, transparent); }
.bridge-card .state.signed-out { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 50%, transparent); }
.bridge-card .detail { font-size: 11.5px; line-height: 1.5; color: var(--text-2); }
.bridge-card .actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.bridge-card .actions button { font-family: var(--mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); border-radius: 8px; padding: 7px 12px; cursor: pointer; transition: background-color calc(220ms * var(--motion-scale)) ease, color calc(220ms * var(--motion-scale)) ease, border-color calc(220ms * var(--motion-scale)) ease; }
.bridge-card .actions button:hover { color: var(--text); border-color: var(--text-3); }
.bridge-card .actions button.primary { border-color: var(--phosphor); color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); }
.bridge-card .actions button.primary:hover { background: color-mix(in srgb, var(--phosphor) 20%, transparent); }
.bridge-card .actions button:disabled { opacity: .5; cursor: default; }
.bridge-card .actions .note { font-family: var(--mono); font-size: 9.5px; letter-spacing: .12em; text-transform: uppercase; color: var(--text-3); }
.bridge-log { margin: 0; max-height: 140px; overflow-y: auto; font-family: var(--mono); font-size: 10.5px; line-height: 1.55; color: var(--text-2); background: var(--bg); border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px; white-space: pre-wrap; }
.bridge-log a { color: var(--phosphor); }
/* The other way in, folded under the buttons: the same install or sign-in typed in a terminal.
   A quiet line until someone asks for it; the room's own buttons stay the way forward. */
.terminal-way > summary { width: max-content; font-size: 11.5px; color: var(--text-3); cursor: pointer; list-style: none; }
.terminal-way > summary::-webkit-details-marker { display: none; }
.terminal-way > summary::after { content: ' ›'; }
.terminal-way[open] > summary::after { content: ' ⌄'; }
.terminal-way > summary:hover { color: var(--text-2); }
.terminal-way .mother-cmd { margin: 8px 0 0; }

.bridge-card .account { font-size: 11px; line-height: 1.5; color: var(--text-3); }
.bridge-card .account .free { font-family: var(--mono); font-size: 8.5px; letter-spacing: .16em; color: var(--phosphor); border: 1px solid color-mix(in srgb, var(--phosphor) 45%, transparent); border-radius: 999px; padding: 2px 7px; margin-right: 8px; }
.conn-card .meta .account { margin-top: 4px; color: var(--ph-dim); }
#bridge-close { margin-top: 4px; }
.empty-starts { display: grid; gap: 6px; width: 100%; margin-top: 4px; }
.empty-start { font: inherit; font-size: 12.5px; line-height: 1.45; text-align: left; color: var(--text-2); background: transparent; border: 1px solid var(--line-2); border-radius: 12px; padding: 9px 12px; cursor: pointer; transition: background-color calc(220ms * var(--motion-scale)) ease, color calc(220ms * var(--motion-scale)) ease, border-color calc(220ms * var(--motion-scale)) ease; }
.empty-start:hover { color: var(--text); border-color: var(--text-3); background: color-mix(in srgb, var(--text) 4%, transparent); }
.bridge-close { font-family: var(--mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; border: 1px solid var(--line-2); background: transparent; color: var(--text-2); border-radius: 8px; padding: 7px 12px; cursor: pointer; }
.bridge-close:hover { color: var(--text); border-color: var(--text-3); }

/* Pasting a provider key: a plain form, the value never comes back. */
.key-slot { display: grid; gap: 8px; }
.key-form { display: grid; gap: 8px; }
.key-form label { display: grid; gap: 4px; }
.key-form .k { font-family: var(--mono); font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--text-3); }
.key-form input, .key-form select { font: inherit; font-size: 12.5px; color: var(--text); background: var(--bg); border: 1px solid var(--line-2); border-radius: 10px; padding: 8px 10px; width: 100%; }
.key-form input:focus, .key-form select:focus { outline: none; border-color: var(--phosphor); }
.key-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.key-row button { font-family: var(--mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; border: 1px solid var(--phosphor); color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); border-radius: 8px; padding: 7px 12px; cursor: pointer; }
.key-row button:disabled { opacity: .5; cursor: default; }
.key-link { font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; color: var(--text-3); text-decoration: none; }
.key-link:hover { color: var(--phosphor); }
.key-note { margin: 0; font-size: 10.5px; line-height: 1.5; color: var(--text-3); }
.key-said { margin: 0; min-height: 1em; font-family: var(--mono); font-size: 10px; letter-spacing: .1em; color: var(--text-3); }
.key-said.bad { color: var(--danger); text-transform: none; letter-spacing: 0; font-family: inherit; font-size: 11.5px; line-height: 1.5; }
/* The key form is shared: it is the bridge's own, on the page's light ground, and it is also
   inside a connection card, where the ground is black and everything is phosphor. It carried the
   page's palette into both, so a key field sat there white and rounded among terminal fields.
   Inside the panel it wears the panel's clothes. */
.conn-card .key-form { margin-bottom: 10px; }
.conn-card .key-form .k, .conn-card .key-link, .conn-card .key-note, .conn-card .key-said { color: var(--ph-dim); }
.conn-card .key-form input, .conn-card .key-form select { color: var(--ph); background: #000; border: 1px solid var(--ph-dim); border-radius: 0; font-size: 12px; padding: 6px 8px; }
.conn-card .key-form input::placeholder { color: var(--ph-dim); opacity: .7; }
.conn-card .key-form input:focus, .conn-card .key-form select:focus { outline: 1px solid var(--ph); border-color: var(--ph); }
.conn-card .key-row button { border: 1px solid var(--ph); color: #041004; background: var(--ph); border-radius: 0; }
.conn-card .key-row button:hover:not(:disabled) { background: var(--ph-dim); color: #041004; }
.conn-card .key-link:hover { color: var(--ph); }
.conn-card .key-said.bad { color: var(--terror); }

/* The second half of a browser sign-in. The CLI opens a page and then waits to be told the code
   that page gives back; this is where the address stays put and where the code is typed. It used
   to be nowhere, so the only thing on screen was a heartbeat and the sign-in died of its clock. */
.login-ask { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.login-ask[hidden] { display: none; }
.login-device { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.login-device code { font-family: var(--mono); font-size: 15px; letter-spacing: .12em; color: var(--text); user-select: all; }
.login-code { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; flex: 1 1 260px; }
.login-code input { flex: 1 1 180px; min-width: 150px; font: inherit; font-size: 12.5px; color: var(--text); background: var(--bg); border: 1px solid var(--line-2); border-radius: 10px; padding: 8px 10px; }
.login-code input:focus { outline: none; border-color: var(--phosphor); }
.login-code button { font-family: var(--mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; border: 1px solid var(--phosphor); color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); border-radius: 8px; padding: 7px 12px; cursor: pointer; }
.login-code button:disabled { opacity: .5; cursor: default; }
.login-code .key-said { flex: 1 0 100%; }
/* Inside a connection card the ground is black and everything is phosphor, as the key form is. */
.conn-card .login-code input { color: var(--ph); background: #000; border: 1px solid var(--ph-dim); border-radius: 0; font-size: 12px; padding: 6px 8px; }
.conn-card .login-code input::placeholder { color: var(--ph-dim); opacity: .7; }
.conn-card .login-code input:focus { outline: 1px solid var(--ph); border-color: var(--ph); }
.conn-card .login-code button { border: 1px solid var(--ph); color: #041004; background: var(--ph); border-radius: 0; }

/* A module card, floor by floor: what it is, what it does, what it touches, how it is doing, and
   then the switch. Everything inside a card wears the panel's phosphor, never the page's palette,
   and every number is given room so it can never land on its own label. */
/* The version line: who made it, what version is running, the button that goes and looks for a
   newer one, and what the last look found. */
.module-card .vendor { font-size: 9.5px; letter-spacing: .2em; color: var(--ph-dim); line-height: 1.4; }
/* The version, the button that goes and looks, and what the last look found. */
.module-card .version { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.module-card .version b { font-family: var(--mono); font-size: 12px; font-weight: 600; letter-spacing: .04em; color: var(--ph); text-shadow: none; }
.module-card .version .check { border: 1px solid var(--ph-faint); background: transparent; color: var(--ph-dim); font: inherit; font-size: 11px; line-height: 1; letter-spacing: 0; padding: 3px 7px; cursor: pointer; }
.module-card .version .check:hover { border-color: var(--ph); color: var(--ph); }
.module-card .version .check:disabled { opacity: .4; cursor: default; }
.mother-head .mother-close.add { color: var(--ph); border-color: var(--ph-dim); }
.mother-head .mother-close.add:hover { background: color-mix(in srgb, var(--ph) 14%, transparent); }
.module-card .version .get { border: 1px solid var(--warn); background: color-mix(in srgb, var(--warn) 12%, transparent); color: var(--warn); font: inherit; font-size: 8.5px; letter-spacing: .16em; padding: 3px 8px; cursor: pointer; }
.module-card .version .get:hover { background: color-mix(in srgb, var(--warn) 22%, transparent); }
.module-card .version .get:disabled { opacity: .45; cursor: default; }
.module-card .version .update { font-family: var(--mono); font-size: 8.5px; letter-spacing: .14em; color: var(--ph-dim); text-shadow: none; }
.module-card .version .update:empty { display: none; }
.module-card .version .update.new { color: var(--warn); }
.module-card .card-panel { display: grid; gap: 14px; }
.module-card .card-panel:empty, .module-card .actions:empty { display: none; }
.module-card .card-block { display: grid; gap: 8px; }
.module-card .card-block h5 { margin: 0; font-size: 9px; font-weight: 400; letter-spacing: .22em; color: var(--ph-dim); border: 0; padding: 0; }
/* INTENCIONES: one table per agent, and the blind pair while the quick test waits for the human. */
.module-card .intents-agent { display: grid; gap: 8px; padding-top: 10px; border-top: 1px solid var(--ph-faint); }
.module-card .intents-head { font-size: 10px; letter-spacing: .14em; color: var(--ph); }
.module-card .intents-table { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, .9fr) 3ch minmax(0, 2fr); gap: 5px 10px; font-size: 9.5px; letter-spacing: .1em; color: var(--ph-dim); }
.module-card .intents-table .settled { color: var(--ph); }
/* The card keeps its lines on one line; this table's last column is a sentence and has to wrap. */
.module-card .intents-agent, .module-card .intents-live { white-space: normal; }
.module-card .intents-table > span { min-width: 0; overflow-wrap: anywhere; }
.module-card .intents-table .intent-n { text-align: right; }
.module-card .intents-live { display: grid; gap: 10px; }
.module-card .intents-pair { display: grid; gap: 10px; }
.module-card .intents-question { margin: 0; font-family: var(--read); font-weight: var(--read-weight); font-size: 14px; line-height: 1.5; color: var(--ph); text-transform: none; letter-spacing: 0; }
.module-card .intents-answers { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; }
.module-card .intents-answer { display: grid; gap: 6px; align-content: start; }
.module-card .intents-answer b { font-weight: 400; font-size: 9px; letter-spacing: .22em; color: var(--ph-dim); }
.module-card .intents-answer .text { max-height: 260px; overflow: auto; padding: 10px 12px; border: 1px solid var(--ph-faint); font-family: var(--read); font-weight: var(--read-weight); font-size: 13px; line-height: 1.55; color: var(--ph); white-space: pre-wrap; text-transform: none; letter-spacing: 0; }
.module-card .card-toggles { display: flex; flex-wrap: wrap; gap: 10px 18px; align-items: center; }
.module-card .card-toggles .control { display: inline-flex; align-items: center; gap: 8px; font-size: 9.5px; letter-spacing: .14em; color: var(--ph-dim); }
.module-card .card-toggles .control input[type="text"] { border: 1px solid var(--ph-dim); background: #000; color: var(--ph); font: inherit; font-size: 10.5px; letter-spacing: .04em; padding: 5px 8px; }
.module-card .card-toggles .toggle { display: inline-flex; align-items: center; gap: 6px; font-size: 9.5px; letter-spacing: .14em; color: var(--ph-dim); cursor: pointer; }
.module-card .card-toggles .toggle input { accent-color: var(--brew); }

/* A fold inside a card: the section name, how many lines are behind it, and its own button. */
.card-fold > summary { display: flex; align-items: center; gap: 10px; cursor: pointer; list-style: none; }
.card-fold > summary::-webkit-details-marker { display: none; }
.card-fold > summary b { font-size: 9px; font-weight: 400; letter-spacing: .22em; color: var(--ph-dim); }
.card-fold > summary:hover b { color: var(--ph); }
.card-fold > summary .caret { margin-left: auto; font-family: var(--mono); font-size: 8.5px; letter-spacing: .16em; color: var(--ph); white-space: nowrap; }
.card-fold > summary .count { font-family: var(--mono); font-size: 9px; letter-spacing: .1em; color: var(--ph-dim); }
.card-fold-body { padding-top: 10px; }
.module-card .card-fold ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.module-card .card-fold li { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 10px; align-items: baseline; font-size: 11.5px; line-height: 1.55; color: rgba(210, 255, 190, .82); text-shadow: none; }
.module-card .card-fold li i { font-style: normal; font-family: var(--mono); font-size: 8.5px; letter-spacing: .16em; color: var(--ph-dim); }
.module-card .card-fold ul.card-commands { gap: 4px; }
.module-card .card-fold ul.card-commands li { grid-template-columns: 1fr; font-family: var(--mono); font-size: 11px; letter-spacing: .04em; color: var(--ph); }

/* Numbers read at a glance: the figure, then its name under it, each in its own cell. */
.module-card .metrics { display: grid; grid-template-columns: repeat(auto-fit, minmax(92px, 1fr)); gap: 12px 14px; }
.module-card .metric { display: grid; gap: 3px; align-content: start; min-width: 0; }
.module-card .metric b { font-family: var(--mono); font-size: 15px; font-weight: 600; line-height: 1.15; letter-spacing: .01em; color: var(--ph); text-shadow: none; overflow-wrap: anywhere; }
.module-card .metric span { font-family: var(--mono); font-size: 8.5px; line-height: 1.4; letter-spacing: .14em; color: var(--ph-dim); text-shadow: none; }

/* ASH · what each block of the briefing weighs against the heaviest one. */
.ash-blocks { display: grid; gap: 5px; }
.ash-block { display: grid; grid-template-columns: 96px minmax(50px, 1fr) auto; gap: 10px; align-items: center; }
.ash-block b { font-family: var(--mono); font-size: 8.5px; letter-spacing: .14em; color: var(--ph-dim); font-weight: 600; text-shadow: none; overflow: hidden; text-overflow: ellipsis; }
.ash-block i { height: 5px; background: var(--ph-faint); position: relative; }
.ash-block i::after { content: ''; position: absolute; inset: 0 auto 0 0; width: var(--fill, 0%); background: color-mix(in srgb, var(--ph) 65%, transparent); }
.ash-block span { font-family: var(--mono); font-size: 8.5px; letter-spacing: .1em; color: var(--ph-dim); white-space: nowrap; text-shadow: none; }
@container console (max-width: 650px) { .ash-block { grid-template-columns: 1fr; } .ash-block i { display: none; } }

/* How grown the archive is. Six readings, the weakest marked, and what would raise it. */
/* The three tests. A verdict that can say NOT YET is worth more than a bar that only fills. */
.exams { display: grid; gap: 10px; margin: 18px 0 4px; }
.exams h4 { margin: 0; font-size: 10px; font-weight: 400; letter-spacing: .22em; color: var(--ph); }
.exams .exam { display: grid; gap: 6px; padding: 12px 14px; border: 1px solid var(--ph-faint); border-left: 2px solid var(--ph-dim); }
.exams .exam.passed { border-left-color: var(--ph); }
.exams .exam.failed { border-left-color: var(--warn); }
.exams .exam-head { display: flex; align-items: baseline; gap: 12px; }
.exams .exam-head b { font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .14em; color: rgba(210, 255, 190, .9); }
.exams .verdict { margin-left: auto; font-family: var(--mono); font-size: 9px; letter-spacing: .18em; color: var(--ph-dim); white-space: nowrap; }
.exams .exam.passed .verdict { color: var(--ph); }
.exams .exam.failed .verdict { color: var(--warn); }
.exams .about { text-transform: none; letter-spacing: .02em; line-height: 1.6; }
.exams .said { margin: 0; font-size: 12px; line-height: 1.55; color: #eaffdf; text-shadow: none; }
.exams .actions { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-top: 2px; }
.exams button { border: 1px solid var(--ph); background: transparent; color: var(--ph); font: inherit; font-size: 10px; letter-spacing: .18em; padding: 7px 12px; cursor: pointer; }
.exams button.primary { background: var(--ph); color: #041004; text-shadow: none; }
.exams button:disabled { opacity: .4; cursor: default; }

.maturity-next { color: var(--ph); }

/* A record you have dealt with: the way out sits at the end of its own row. */
.mother-record .drop { justify-self: end; background: none; border: 0; color: var(--ph-faint); cursor: pointer; font: inherit; font-size: 14px; padding: 0; line-height: 1; }
.mother-record .drop:hover { color: var(--warn); }
.mother-card .tags .code { color: var(--ph); border: 1px solid var(--ph-faint); border-radius: 3px; padding: 0 4px; letter-spacing: .1em; }
.mother-clear { display: inline-block; margin: 8px 10px 10px 0; background: none; border: 1px solid var(--ph-faint); border-radius: 4px; color: var(--ph-dim); cursor: pointer; font: inherit; font-size: 9px; letter-spacing: .16em; padding: 4px 10px; }
.mother-clear:hover { color: var(--ph); border-color: var(--ph-dim); }

/* A remedy this room can carry out itself: the button goes above the commands it replaces. */
.mother-goto { display: block; margin: 6px 0 0; border: 1px solid var(--ph-dim); border-radius: 4px; background: transparent; color: var(--ph); cursor: pointer; font: inherit; font-size: 10px; letter-spacing: .14em; padding: 6px 12px; text-transform: uppercase; }
.mother-goto:hover { background: color-mix(in srgb, var(--ph) 12%, transparent); }

/* A file an agent wrote in this room, in that agent's own colour. */
.tree .node .touched { width: 6px; height: 6px; border-radius: 50%; background: var(--agent, var(--ph)); box-shadow: none; flex: 0 0 auto; margin-left: 2px; }
/* The way down to what changed: a folder carries the dot of the last touch beneath it, hollow, so
   the filled one is always the file itself. */
.tree .node .touched.trail { background: transparent; box-shadow: inset 0 0 0 1.5px var(--agent, var(--ph)); }
.tree-head .tree-refresh.spin svg { animation: tree-spin .6s ease; }
@keyframes tree-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .tree-head .tree-refresh.spin svg { animation: none; } }

/* Read by what the file is. Six roles, the room's own phosphor: enough to find a string or a
   comment at a glance, and never so many colours that the code stops being the thing you see. */
.viewer .code .t-keyword { color: var(--syn-keyword); }
.viewer .code .t-string  { color: var(--syn-string); }
.viewer .code .t-comment { color: var(--syn-comment); font-style: italic; }
.viewer .code .t-number  { color: var(--syn-number); }
.viewer .code .t-literal { color: var(--syn-literal); }
.viewer .code .t-regex   { color: var(--syn-regex); }
.viewer-lang { color: var(--ph-dim); font-size: 9.5px; letter-spacing: .16em; text-transform: uppercase; }

/* A connector's key: a password field that is never filled back in, what MADRE knows about it
   (its length, never its value), and the way to take it out again. */
.module-card .card-secret { display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center; }
.module-card .card-secret .control { display: inline-flex; align-items: center; gap: 8px; font-size: 9.5px; letter-spacing: .14em; color: var(--ph-dim); }
.module-card .card-secret .control input { border: 1px solid var(--ph-dim); background: #000; color: var(--ph); font: inherit; font-size: 10.5px; letter-spacing: .18em; padding: 5px 8px; min-width: 190px; }
.module-card .card-secret button.ghost { background: none; border: 1px solid var(--ph-dim); color: var(--ph-dim); font: inherit; font-size: 8.5px; letter-spacing: .18em; padding: 5px 9px; cursor: pointer; }
.module-card .card-secret button.ghost:hover { color: var(--ph); border-color: var(--ph); }
.module-card .card-block > .note { margin: 0; font-size: 10px; line-height: 1.7; letter-spacing: .08em; color: var(--ph-dim); }
.module-card .card-block > a.note { justify-self: start; color: var(--brew); text-decoration: none; letter-spacing: .18em; font-size: 8.5px; }
.module-card .card-block > a.note:hover { text-decoration: underline; }

/* A starter under /module: an instruction to edit, not a command to run. Dimmer key, so the
   command above it still reads as the command. */
.slash-menu .item.starter .key { color: var(--text-3); font-size: 11px; }
.slash-menu .item.starter .what { color: var(--text-2); }

/* EXPAND ALL, taken out of the bar. The bar is a row of destinations — CONNECTIONS, MEMORY,
   NOSTROMO — and this is not one: it acts on the canvas underneath it. A frame made it a rival
   of those buttons, so it has none: it speaks like the ▸ OPEN of each fold, dim, at the same right
   edge, over the column of carets it moves all at once. */
.fold-all-row { display: flex; justify-content: flex-end; margin: 14px 0 6px; }

/* ---------- MEMORY · the dashboard ----------
   The same phosphor as the rest of MU/TH/UR: hairline frames, one green, the brighter ink only
   for the figures. A chart here is boxes with heights, so it stays crisp at any width. */
.mem-dash { display: grid; gap: 14px; margin-bottom: 8px; transition: opacity calc(200ms * var(--motion-scale)); }
.mem-dash.loading { opacity: .45; }
.mem-dash-head { display: flex; align-items: baseline; justify-content: flex-end; gap: 14px; flex-wrap: wrap; margin-top: -4px; }
.mem-dash-head .when { font-size: 9px; letter-spacing: .16em; color: var(--ph-dim); }
.mem-dash button { border: 1px solid var(--ph-dim); background: transparent; color: var(--ph); font: inherit; font-size: 9.5px; letter-spacing: .16em; padding: 6px 10px; cursor: pointer; }
.mem-dash button:hover { background: var(--ph-faint); }
.mem-dash button.primary { background: var(--ph); color: #041004; text-shadow: none; border-color: var(--ph); }
.mem-dash button:disabled { opacity: .4; cursor: default; }
.mem-dash .note { margin: 0; font-size: 9.5px; letter-spacing: .12em; line-height: 1.7; color: var(--ph-dim); }

.mem-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; }
.mem-tile { display: grid; align-content: start; gap: 6px; padding: 14px 16px 12px; border: 1px solid var(--ph-faint); background: rgba(40, 254, 20, .025); min-width: 0; }
.mem-tile .label { font-size: 9px; letter-spacing: .2em; color: var(--ph-dim); }
.mem-tile .value { font-size: clamp(26px, 3vw, 34px); font-weight: 700; letter-spacing: .04em; line-height: 1.05; color: #eaffdf; text-shadow: none; }
.mem-tile .sub { font-size: 9px; letter-spacing: .14em; line-height: 1.6; color: var(--ph); text-transform: uppercase; }
.mem-tile .mem-cols.spark { height: 22px; margin-top: 4px; }
.mem-tile .mem-meter { margin-top: 8px; }

.mem-verdict { display: grid; gap: 8px; }
.mem-verdict .says { margin: 0; font-size: 10.5px; letter-spacing: .1em; line-height: 1.7; text-transform: uppercase; color: rgba(210, 255, 190, .9); }
.mem-verdict .says b { font-size: 10px; letter-spacing: .24em; color: var(--ph); margin-right: 8px; }
.mem-verdict .maturity-next { margin: 0; font-family: var(--mono); font-size: 10.5px; line-height: 1.8; letter-spacing: .1em; text-transform: uppercase; color: #eaffdf; text-shadow: none; padding: 11px 13px; border: 1px solid var(--ph); background: var(--ph-faint); }
.mem-verdict .maturity-next b { font-size: 9px; letter-spacing: .22em; color: var(--ph); margin-right: 10px; }
.mem-verdict .maturity-next .where { font-size: 9px; letter-spacing: .16em; color: var(--ph); white-space: nowrap; }

.mem-grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 14px; }
.mem-card { grid-column: span 6; display: grid; align-content: start; gap: 12px; padding: 14px 16px 16px; border: 1px solid var(--ph-faint); min-width: 0; }
.mem-card.span-3 { grid-column: span 3; }
.mem-card.span-5 { grid-column: span 5; }
.mem-card.span-7 { grid-column: span 7; }
.mem-card.span-12 { grid-column: 1 / -1; }
.mem-card > h4 { margin: 0; font-size: 9.5px; font-weight: 400; letter-spacing: .24em; color: var(--ph); }
.mem-card .detail { font-size: 8.5px; letter-spacing: .1em; line-height: 1.6; color: var(--ph-dim); text-transform: uppercase; }
@container console (max-width: 1060px) { .mem-card.span-3 { grid-column: span 6; } .mem-card.span-5, .mem-card.span-7 { grid-column: 1 / -1; } }
@container console (max-width: 576px) { .mem-card.span-3 { grid-column: 1 / -1; } }

/* Columns from one baseline: 4px rounded ends, square at the floor, 2px of black between them. */
.mem-cols { display: flex; align-items: flex-end; gap: 2px; height: 46px; border-bottom: 1px solid var(--ph-faint); }
.mem-cols i { flex: 1; min-width: 0; max-width: 24px; height: var(--h, 0); background: var(--ph-dim); border-radius: 2px 2px 0 0; }
.mem-cols i.zero { height: 1px; background: var(--ph-faint); border-radius: 0; }
.mem-cols i.now { background: var(--ph); }
.mem-cols i.on { background: #eaffdf; box-shadow: none; }
.mem-cols.big i { max-width: none; border-radius: 4px 4px 0 0; }
.mem-cols.spark { border-bottom: 0; }
.mem-cols.spark i { border-radius: 1px 1px 0 0; }

.mem-activity { position: relative; display: grid; gap: 12px; outline: none; cursor: crosshair; }
.mem-activity:focus-visible { outline: 1px solid var(--ph-dim); outline-offset: 6px; }
.mem-strip { display: grid; gap: 6px; }
.mem-strip-head { display: flex; align-items: baseline; gap: 10px; }
.mem-strip-head b { font-size: 9px; font-weight: 400; letter-spacing: .18em; color: rgba(210, 255, 190, .9); }
.mem-strip-head span { margin-left: auto; font-size: 8.5px; letter-spacing: .14em; color: var(--ph-dim); }
.mem-axis { display: flex; justify-content: space-between; font-size: 8.5px; letter-spacing: .14em; color: var(--ph-dim); margin-top: -4px; }
.mem-cross { position: absolute; top: 0; bottom: 14px; width: 1px; background: var(--ph-dim); pointer-events: none; }
.mem-tip { position: absolute; top: 18px; z-index: 2; display: grid; gap: 4px; min-width: 150px; padding: 9px 11px; background: #020402; border: 1px solid var(--ph); pointer-events: none; box-shadow: 0 6px 24px rgba(0, 0, 0, .6); }
.mem-tip .when { font-size: 9px; font-weight: 400; letter-spacing: .2em; color: var(--ph-dim); }
.mem-tip div { display: flex; align-items: baseline; gap: 8px; }
.mem-tip strong { min-width: 28px; font-size: 13px; color: #eaffdf; font-variant-numeric: tabular-nums; }
.mem-tip span { font-size: 8.5px; letter-spacing: .14em; color: var(--ph); }

.mem-table { width: 100%; border-collapse: collapse; font-size: 9.5px; letter-spacing: .1em; }
.mem-table th { text-align: right; font-weight: 400; font-size: 8.5px; letter-spacing: .16em; color: var(--ph-dim); padding: 4px 6px; border-bottom: 1px solid var(--ph-faint); }
.mem-table td { text-align: right; padding: 4px 6px; color: var(--ph); font-variant-numeric: tabular-nums; border-bottom: 1px solid rgba(40, 254, 20, .06); }
.mem-table th:first-child, .mem-table td:first-child { text-align: left; }

/* A meter: the fill against its own track, with an optional mark where it has to reach. */
.mem-meter { position: relative; display: block; height: 6px; background: var(--ph-faint); }
.mem-meter > i { position: absolute; inset: 0 auto 0 0; background: var(--ph-dim); border-radius: 0 3px 3px 0; }
.mem-meter > .mark { position: absolute; top: -4px; bottom: -4px; width: 2px; margin-left: -1px; background: #eaffdf; }
.mem-tile .mem-meter > i, .mem-signal.weakest .mem-meter > i { background: var(--ph); }
.mem-signal { display: grid; gap: 5px; }
.mem-signal .top { display: flex; align-items: baseline; gap: 10px; }
.mem-signal .top b { font-size: 9px; font-weight: 400; letter-spacing: .14em; color: rgba(210, 255, 190, .9); }
.mem-signal .top span { margin-left: auto; font-size: 10px; letter-spacing: .08em; color: #eaffdf; font-variant-numeric: tabular-nums; }
.mem-signal.weakest .top b { color: var(--ph); }
.mem-signal.weakest .top b::after { content: " ◂"; }

.mem-bars { display: grid; gap: 9px; }
.mem-bar { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 10px; align-items: center; }
.mem-bar .name { display: flex; align-items: center; gap: 7px; font-size: 9px; letter-spacing: .14em; color: rgba(210, 255, 190, .9); min-width: 0; overflow-wrap: anywhere; }
.mem-bar .swatch { flex: none; width: 8px; height: 8px; box-shadow: none; }
.mem-bar .value { font-size: 9px; letter-spacing: .08em; color: var(--ph-dim); font-variant-numeric: tabular-nums; white-space: nowrap; }
.mem-bar .track { grid-column: 1 / -1; display: block; height: 8px; }
.mem-bar .track i { display: block; height: 100%; min-width: 2px; background: var(--ph-dim); border-radius: 0 4px 4px 0; }
.mem-bar:first-child .track i { background: var(--ph); }

.mem-split { display: flex; gap: 2px; height: 12px; }
.mem-split i { flex-basis: 0; min-width: 2px; }
.mem-split i.search { background: var(--ph); border-radius: 0; }
.mem-split i.cascade { background: var(--ph-dim); border-radius: 0 4px 4px 0; }
.mem-legend { display: flex; flex-wrap: wrap; gap: 6px 16px; }
.mem-legend .k { display: inline-flex; align-items: center; gap: 6px; font-size: 9px; letter-spacing: .14em; color: rgba(210, 255, 190, .9); }
.mem-legend .k i { width: 10px; height: 10px; }
.mem-legend .k.search i { background: var(--ph); }
.mem-legend .k.cascade i { background: var(--ph-dim); }
.mem-legend .k b { font-weight: 400; color: var(--ph-dim); font-variant-numeric: tabular-nums; }

/* The three tests, side by side on a wide screen, each with its rate against the line it has to reach. */
.mem-dash .exams { margin: 0; grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: start; }
@container console (max-width: 810px) { .mem-dash .exams { grid-template-columns: minmax(0, 1fr); } }
.mem-dash .exams > .note, .mem-dash .exams > button { grid-column: 1 / -1; justify-self: start; }
/* One hairline all round: the verdict and the bar already say passed or not, so no coloured edge. */
.mem-dash .exams .exam, .mem-dash .exams .exam.passed, .mem-dash .exams .exam.failed { align-content: start; height: 100%; box-sizing: border-box; border: 1px solid var(--ph-faint); }
.mem-dash .exams .said { font-family: var(--mono); font-size: 11px; letter-spacing: .04em; line-height: 1.65; }
.exam-bullet { display: grid; gap: 6px; margin: 2px 0; }
.exam-bullet .mem-meter { height: 8px; }
.exam-bullet .mem-meter > i { background: var(--ph); }
.exams .exam.failed .exam-bullet .mem-meter > i { background: var(--warn); }
.exam-bullet span { font-size: 9px; letter-spacing: .14em; color: var(--ph-dim); }
.exams .exam .actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

/* ---------- What's new ----------
   A board after an update: a window in the room's own material with the version you now have, a
   grid of cards (picture, title, one line) in AJUSTES' soft relief, and behind each card the whole
   of it with a key that takes you there. The window holds still; its middle scrolls. */
dialog.whats-new { position: fixed; inset: 0; width: 100vw; height: 100dvh; max-width: none; max-height: none; margin: 0; border: 0; padding: 24px 16px; box-sizing: border-box; background: transparent; color: var(--text); overflow: hidden; }
dialog.whats-new[open] { display: flex; align-items: center; justify-content: center; }
dialog.whats-new::backdrop { background: rgba(0, 0, 0, .45); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); }
.wn-sheet {
  display: flex; flex-direction: column; width: min(980px, 100%); height: min(720px, 100%); box-sizing: border-box; overflow: hidden;
  border-radius: 16px; font-family: var(--read); color: var(--text);
  background: color-mix(in srgb, var(--bg-2) 96%, transparent); -webkit-backdrop-filter: blur(22px) saturate(1.2); backdrop-filter: blur(22px) saturate(1.2);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--text) 9%, transparent), inset 0 1px 0 rgba(255, 255, 255, .1), 0 16px 34px -12px rgba(0, 0, 0, .55), 0 48px 110px -36px rgba(0, 0, 0, .75);
  animation: wn-in calc(420ms * var(--motion-scale)) cubic-bezier(.2, .8, .2, 1);
}
:root[data-scheme="light"] .wn-sheet { box-shadow: 0 0 0 1px rgba(20, 30, 20, .1), inset 0 1px 0 rgba(255, 255, 255, .95), 0 16px 34px -14px rgba(20, 30, 20, .26), 0 48px 110px -40px rgba(20, 30, 20, .38); }
@keyframes wn-in { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .wn-sheet { animation: none; } }

.wn-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 16px; align-items: start; padding: 22px 24px 16px; }
.wn-headline { display: grid; justify-items: start; gap: 6px; min-width: 0; }
.wn-head .wn-logo { display: block !important; height: 17px; width: auto; margin-bottom: 8px; }
.wn-eyebrow { font-size: 12.5px; font-weight: 500; color: var(--text-2); }
.wn-head h2 { margin: 0; font-size: clamp(24px, 3.4vw, 32px); font-weight: 650; letter-spacing: -.015em; line-height: 1.12; }
.wn-intro { margin: 2px 0 0; max-width: 64ch; font-size: 14.5px; line-height: 1.55; color: var(--text-2); }
.wn-keys { align-self: start; }

.wn-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 6px 24px 22px; }
.wn-board { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; align-content: start; }
.wn-card {
  display: grid; align-content: start; gap: 6px; min-width: 0; padding: 10px 10px 14px; border: 0; border-radius: 14px; text-align: left;
  background: var(--surface, var(--panel)); color: var(--text); font-family: var(--read); cursor: pointer; outline: none;
  box-shadow: var(--raise, var(--float-sm)); transition: box-shadow var(--motion-fast, 160ms) var(--ease-out, ease);
}
.wn-card:hover { box-shadow: var(--raise-over, var(--float)); }
.wn-card:active { box-shadow: var(--key-down); }
.wn-card:focus-visible { box-shadow: var(--raise, var(--float-sm)), 0 0 0 2px color-mix(in srgb, var(--phosphor) 55%, transparent); }
.wn-card-shot { margin-bottom: 4px; }
.wn-card-title { padding: 0 4px; font-size: 14px; font-weight: 600; line-height: 1.3; }
.wn-card-line { padding: 0 4px; font-size: 13px; line-height: 1.45; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

/* A picture's place: the colour of the card a shade apart while it loads, and the 8-bit mark of
   the note when there is no picture. */
.wn-shot { position: relative; display: grid; place-items: center; width: 100%; aspect-ratio: 16 / 10; overflow: hidden; border-radius: 10px; background: color-mix(in srgb, var(--text) 7%, var(--surface, var(--panel))); }
.wn-shot img { display: block; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity calc(240ms * var(--motion-scale)) var(--ease-out, ease); }
.wn-shot.loaded img { opacity: 1; }
.wn-shot .wn-shot-icon { display: block; width: 34px; height: 34px; color: var(--phosphor); }
.wn-shot .wn-shot-icon svg { display: block; width: 100%; height: 100%; }

.wn-more { display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 14px; align-items: start; margin-top: 18px; padding: 16px 18px; border-radius: 14px; border: 1px dashed var(--line-2); }
.wn-more-icon { display: block; width: 26px; height: 26px; color: var(--module-electric, var(--phosphor)); }
.wn-more-icon svg { display: block; width: 100%; height: 100%; }
.wn-more b { font-size: 14px; font-weight: 600; font-style: italic; }
.wn-more p { margin: 4px 0 0; font-size: 13.5px; line-height: 1.5; color: var(--text-2); }
.wn-detail { display: grid; gap: 18px; max-width: 900px; margin: 0 auto; }
/* Wide, the picture and its words side by side, so the key that goes there is in view at once;
   while a note is open the intro steps out of the head to give it the room. */
@media (min-width: 761px) {
  .wn-detail { grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr); align-items: start; column-gap: 24px; }
  .wn-detail-bar { grid-column: 1 / -1; }
}
.wn-sheet.reading .wn-intro { display: none; }
.wn-detail-bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.wn-steps { display: inline-flex; align-items: center; gap: 10px; }
.wn-count { font-size: 12.5px; color: var(--text-2); font-variant-numeric: tabular-nums; }
.wn-step.next .settings-back-icon { transform: rotate(-90deg); }
.wn-step:disabled { opacity: .35; box-shadow: none !important; cursor: default; }
.wn-detail-shot { border-radius: 12px; }
.wn-detail-shot .wn-shot-icon { width: 56px; height: 56px; }
.wn-detail-text { display: grid; justify-items: start; gap: 10px; }
.wn-detail-text h3 { margin: 0; font-size: 22px; font-weight: 650; letter-spacing: -.01em; line-height: 1.2; }
.wn-detail-body { margin: 0; max-width: 64ch; font-size: 15px; line-height: 1.6; color: var(--text); }
.wn-where { display: flex; flex-wrap: wrap; gap: 4px 8px; margin: 0; font-size: 13px; line-height: 1.5; color: var(--text-2); }
.wn-where .k { font-weight: 600; color: var(--text); }

/* The accent key: «Take me there» and «Start». */
.wn-go, .wn-start {
  height: 36px; padding: 0 18px; border: 0; border-radius: 10px; background: var(--phosphor); color: var(--phosphor-ink);
  font-family: var(--read); font-size: 14px; font-weight: 600; letter-spacing: 0; cursor: pointer;
  box-shadow: var(--key-rest); transition: box-shadow calc(160ms * var(--motion-scale)) var(--ease-out, ease);
}
.wn-go { margin-top: 6px; }
.wn-go:hover, .wn-start:hover { box-shadow: var(--key-over); }
.wn-go:active, .wn-start:active { box-shadow: var(--key-down); }
.wn-go:focus-visible, .wn-start:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 70%, transparent); outline-offset: 2px; }

.wn-foot { display: flex; align-items: center; gap: 16px; padding: 14px 24px 18px; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); }
.wn-start { margin-left: auto; min-width: 140px; }
.wn-changes { font-size: 13px; color: var(--text-2); text-decoration: none; }
.wn-changes:hover { color: var(--text); text-decoration: underline; }

@media (max-width: 860px) { .wn-board { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) {
  dialog.whats-new { padding: 0; }
  /* A phone scrolls the whole sheet, head included; the foot stays at hand. */
  .wn-sheet { width: 100%; height: 100dvh; border-radius: 0; overflow-y: auto; overscroll-behavior: contain; }
  .wn-head { padding: 18px 16px 12px; }
  .wn-body { flex: 1 0 auto; min-height: auto; overflow: visible; padding: 4px 16px 18px; }
  .wn-foot { position: sticky; bottom: 0; z-index: 1; background: color-mix(in srgb, var(--bg-2) 92%, transparent); -webkit-backdrop-filter: blur(16px); backdrop-filter: blur(16px); }
  .wn-board { grid-template-columns: minmax(0, 1fr); gap: 14px; }
  .wn-foot { padding: 12px 16px calc(14px + env(safe-area-inset-bottom, 0px)); }
  .wn-start { min-width: 0; }
}

/* The modes, in order and in their own colours: the same chip the composer wears. */
.tour-keys { list-style: none; margin: 14px 0 0; padding: 0; display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 9px 12px; align-items: baseline; }
.tour-keys[hidden] { display: none; }
.tour-keys li { display: contents; }

/* First touch: a card under a button that has never been pressed, saying what it opens. */
.hint-card {
  position: fixed; z-index: 2147483000; width: min(320px, calc(100vw - 24px)); box-sizing: border-box; padding: 16px 18px 14px;
  border-radius: 16px; background: var(--panel); color: var(--text); border: 1px solid var(--line-2);
  box-shadow: 0 18px 50px rgba(0, 0, 0, .4); animation: wn-in calc(300ms * var(--motion-scale)) cubic-bezier(.2, .8, .2, 1);
}
@media (prefers-reduced-motion: reduce) { .hint-card { animation: none; } }
.hint-card h3 { margin: 0 0 6px; font-size: 15px; font-weight: 700; }
.hint-card p { margin: 0; font-size: 13.5px; line-height: 1.5; color: var(--text-2); }
.hint-ok { margin-top: 12px; border: 0; border-radius: 10px; padding: 7px 14px; background: var(--accent); color: var(--accent-ink); font: inherit; font-size: 13px; font-weight: 650; cursor: pointer; }
.hint-ok:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* A link inside a fold's header: text in the header's own voice, a step dimmer, that does
   something without opening or closing the fold. */
.mother-section .fold > summary .fold-link { border: 0; background: transparent; padding: 2px 0 2px 10px; margin-left: 2px; border-left: 1px solid var(--ph-faint); font-family: var(--mono); font-size: 10px; letter-spacing: .2em; color: var(--ph-dim); cursor: pointer; }
.mother-section .fold > summary .fold-link:hover, .mother-section .fold > summary .fold-link:focus-visible { color: var(--ph); }

/* /module's ideas: a grid of small cards under the command, each with its mark and the shape of
   module it would be, in that shape's colour. The command row and the hint keep the full width. */
.slash-menu.with-starters { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; min-width: min(560px, 92vw); }
.slash-menu.with-starters > .item:not(.starter), .slash-menu.with-starters > .hint { grid-column: 1 / -1; }
.slash-menu .item.starter {
  display: grid; grid-template-columns: 22px minmax(0, 1fr); grid-template-rows: auto auto; gap: 6px 10px; align-items: start;
  padding: 10px 12px; border-radius: 12px; border: 1px solid var(--line); background: color-mix(in srgb, var(--bg) 35%, transparent);
  --shape: var(--phosphor);
}
.slash-menu .item.starter[aria-selected="true"], .slash-menu .item.starter:hover { border-color: color-mix(in srgb, var(--shape) 55%, transparent); background: color-mix(in srgb, var(--shape) 10%, transparent); }
.slash-menu .item.starter .starter-icon { grid-row: 1 / 3; width: 18px; height: 18px; margin-top: 2px; color: var(--shape); }
.slash-menu .item.starter .idea { font-size: 12.5px; line-height: 1.4; color: var(--text); text-align: left; }
.slash-menu .item.starter .shape { justify-self: start; font-family: var(--mono); font-size: 9.5px; letter-spacing: .12em; text-transform: uppercase; padding: 2px 7px; border-radius: 999px; color: var(--shape); border: 1px solid color-mix(in srgb, var(--shape) 45%, transparent); }
.slash-menu .item.starter:has(.shape.connector) { --shape: var(--module-electric); }
.slash-menu .item.starter:has(.shape.sends) { --shape: var(--mode-4); }
.slash-menu .item.starter:has(.shape.card) { --shape: var(--mode-2); }
:root[data-scheme="light"] .slash-menu .item.starter:has(.shape.command) { --shape: #178f0c; }
:root[data-scheme="light"] .slash-menu .item.starter:has(.shape.sends) { --shape: #1f6f9e; }
:root[data-scheme="light"] .slash-menu .item.starter:has(.shape.card) { --shape: #9a6400; }
@media (max-width: 560px) { .slash-menu.with-starters { grid-template-columns: minmax(0, 1fr); } }
.system.module-proposed .replaces { display: block; margin-top: 4px; color: var(--warn, var(--text-2)); }

/* Reading surfaces in Geist (--read). Last in the file on purpose: several of these chips reset
   `font: inherit` where they are drawn, and the reading face has to win over that. */
.bubble, .editor, .memory-hint .pill, .settled-note, .openq-ask, .choice-option { font-family: var(--read); font-weight: var(--read-weight); }
/* At 300 the emphasis has to be asked for: "bolder" from 300 is only 400. */
.bubble strong, .bubble b { font-weight: 600; }

/* ================= split: a second conversation in the right half =================
   The right half is the same page loaded with ?pane=split&chat=<id> inside a frame. Here: the
   dock that holds it on the left page, the button beside × in the list, and what the page inside
   the frame drops (the bar and every panel). Thin lines, no glow. Below 900px there is no room
   for two and the page is one again. */
.shell.with-split { grid-template-columns: minmax(0, 1fr) var(--split, 50%); }
.shell.with-split > .split-dock { grid-column: 2; grid-row: 1 / -1; }
/* Split and browser at once: three panes, and none of them may starve another. The two
   conversations share what the browser leaves, half and half until the human drags an edge; every
   pane keeps a floor, and the fixed widths grow into the free space before the open conversation
   takes the rest, so a wide browser remembered from before can no longer squeeze it to a sliver. */
.shell.with-split.with-browser { grid-template-columns: minmax(360px, 1fr) minmax(360px, var(--split-3, 1fr)) minmax(320px, var(--dock, 34vw)); }
.shell.with-split.with-browser > .browser-dock { grid-column: 3; }
/* Too narrow for three: the browser takes the right half while it is open and the second
   conversation waits behind it, still live, until the browser closes. */
@media (max-width: 1100px) {
  .shell.with-split.with-browser { grid-template-columns: minmax(0, 1fr) var(--dock, 46vw); }
  .shell.with-split.with-browser > .browser-dock { grid-column: 2; }
  .shell.with-split.with-browser > .split-dock { display: none; }
}
.split-dock { position: relative; display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; background: var(--bg); border-left: 1px solid var(--line-2); }
.split-head { display: flex; align-items: center; gap: 6px; min-width: 0; padding: 7px 10px 7px 14px; border-bottom: 1px solid var(--line); }
.split-title { flex: 1 1 auto; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; color: var(--text-2); font-family: var(--mono); font-size: 11px; letter-spacing: .06em; text-transform: uppercase; }
.split-spin { display: none; width: 9px; height: 9px; flex: none; border: 1.5px solid color-mix(in srgb, var(--phosphor) 30%, transparent); border-top-color: var(--phosphor); border-radius: 50%; animation: chat-spin .8s linear infinite; }
.split-dock.working .split-spin { display: inline-block; }
@media (prefers-reduced-motion: reduce) { .split-spin { animation: none; border-color: var(--phosphor); } }
.split-action { flex: none; display: inline-grid; place-items: center; width: 26px; height: 26px; padding: 0; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--text-3); font: inherit; font-size: 16px; line-height: 1; cursor: pointer; }
.split-action svg { width: var(--ico-sm); height: var(--ico-sm); }
.split-action:hover, .split-action:focus-visible { color: var(--text); border-color: var(--line-2); }
.split-frame { display: block; width: 100%; height: 100%; min-height: 0; border: 0; background: transparent; }
.shell.dragging-split .split-frame, .shell.dragging-split .browser-dock iframe { pointer-events: none; }
.shell.dragging-split .split-grip::after { opacity: 1; background: var(--phosphor); }

.chats-body .chat-row:has(.chat-beside) { grid-template-columns: minmax(0, 1fr) auto auto; }
/* The two ways to have a conversation beside the open one, side by side: the other half of the
   window, or a window of its own. One lit is how it is shown now; the other moves it. */
.chats-body .chat-beside { display: inline-flex; align-items: center; gap: 2px; }
.chats-body :is(.chat-split, .chat-window) { display: inline-grid; place-items: center; border: 1px solid transparent; background: transparent; color: var(--text-3); padding: 3px 5px; border-radius: 7px; cursor: pointer; opacity: 0; }
.chats-body :is(.chat-split, .chat-window) svg { width: var(--ico-sm); height: var(--ico-sm); }
.chats-body :is(.chat-split, .chat-window) { transition: opacity var(--motion) var(--ease-out), color var(--motion) var(--ease-out), border-color var(--motion) var(--ease-out); }
.chats-body .chat-row:hover :is(.chat-split, .chat-window), .chats-body :is(.chat-split, .chat-window):focus-visible, .chats-body :is(.chat-split, .chat-window).on, .chats-body .chat-beside:has(.on) :is(.chat-split, .chat-window) { opacity: 1; }
.chats-body :is(.chat-split, .chat-window):hover { color: var(--text); border-color: var(--line-2); }
.chats-body :is(.chat-split, .chat-window).on { color: var(--phosphor); border-color: color-mix(in srgb, var(--phosphor) 35%, transparent); }
/* No room for another: still pressable, so the room can say why, but plainly at rest. */
.chats-body .chat-row:hover :is(.chat-split, .chat-window).full { opacity: .32; }
.chats-body :is(.chat-split, .chat-window).full:hover { color: var(--text-3); border-color: transparent; opacity: .5; }

/* The page inside the frame: the conversation and its composer, nothing of the bar. */
.split-pane .shell > .bar, .split-pane .chats-button, .split-pane #chats, .split-pane #tree, .split-pane .browser-dock, .split-pane .split-dock, .split-pane .colophon, .split-pane .notices { display: none !important; }
.split-pane .shell { --column: min(880px, 100% - 32px); grid-template-columns: minmax(0, 1fr); }

@media (max-width: 900px) {
  .shell.with-split, .shell.with-split.with-browser { grid-template-columns: minmax(0, 1fr); }
  .shell.with-split.with-browser > .browser-dock { grid-column: 1; grid-row: 3 / 4; }
  .shell.with-split > .split-dock, .chats-body .chat-beside, .conv-window { display: none; }
  .chats-body .chat-row:has(.chat-beside) { grid-template-columns: minmax(0, 1fr) auto; }
}
/* The panes beside the conversation are cards, not strips: a gutter of ground on every side, one
   hairline, soft corners. The edge you drag is the card's own left side, and it says so with a
   small pill that is always faintly there and wakes under the pointer. */
@media (min-width: 901px) {
  .shell.with-split > .split-dock, .shell.with-browser > .browser-dock {
    margin: 10px 10px 10px 2px; min-height: 0;
    border: 1px solid var(--line); border-radius: 14px; overflow: hidden;
    box-shadow: var(--lift-1);
  }
  .shell.with-split > .split-dock { background: var(--bg); }
  /* The cards stand on the window's floor, like the open conversation does: measured from the same
     bottom, the box and the line under it in either half meet without nudging one of them. */
  .shell.with-split > .split-dock, .shell.with-browser > .browser-dock { margin-bottom: 0; border-bottom: 0; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
  .shell.with-split.with-browser > .split-dock { margin-right: 0; }
  .split-head { padding: 9px 10px 9px 16px; background: var(--panel); }
  .split-dock > .dock-grip, .browser-dock > .dock-grip { left: 0; width: 10px; }
  .split-dock > .dock-grip::after, .browser-dock > .dock-grip::after { left: 3px; width: 3px; height: 36px; opacity: .55; background: var(--line-2); transition: opacity var(--motion) var(--ease-out), height var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out); }
  .split-dock > .dock-grip:hover::after, .browser-dock > .dock-grip:hover::after,
  .shell.dragging-split .split-grip::after, .shell.dragging-dock .browser-dock > .dock-grip::after { opacity: 1; height: 56px; background: var(--phosphor); }
}
/* The browser and the second conversation in either order. Only where three panes fit: below that
   the browser stands alone on the right and the order has nothing to say. */
.pane-swap { display: none; }
@media (min-width: 1101px) {
  .shell.with-split.with-browser .pane-swap { display: inline-grid; }
  .shell.with-split.with-browser.browser-first { grid-template-columns: minmax(360px, 1fr) minmax(320px, var(--dock, 34vw)) minmax(360px, var(--split-3, 1fr)); }
  .shell.with-split.with-browser.browser-first > .browser-dock { grid-column: 2; margin-right: 0; }
  .shell.with-split.with-browser.browser-first > .split-dock { grid-column: 3; margin-right: 10px; }
}
.browser-dock { view-transition-name: madre-browser; }
.split-dock { view-transition-name: madre-split; }
::view-transition-group(madre-browser), ::view-transition-group(madre-split) { animation-duration: var(--glide); animation-timing-function: var(--ease-glide); }

/* The canvas of a page narrowed to a width: its edges are where it is pulled, and the ground on
   either side pulls it too. The handles stand on the canvas's own edges, not the panel's. */
