.browser-down { position: absolute; inset: 0; z-index: 5; display: grid; place-items: center; padding: 24px; background: color-mix(in srgb, var(--bg) 62%, transparent); -webkit-backdrop-filter: blur(6px) saturate(.8); backdrop-filter: blur(6px) saturate(.8); animation: down-in calc(320ms * var(--motion-scale)) var(--ease-glide); }
.browser-down.leaving { animation: down-out calc(240ms * var(--motion-scale)) var(--ease-leave) forwards; }
