  position: fixed; z-index: 35; margin: 0; grid-column: auto; grid-row: auto; min-width: 0; min-height: 0;
  border: 1px solid color-mix(in srgb, var(--text) 12%, var(--line-2)); border-radius: 16px; overflow: hidden;
  box-shadow: 0 1px 0 rgba(255, 255, 255, .04) inset, 0 18px 50px -24px rgba(0, 0, 0, .5);
