.mother-head .surface-mode { color: var(--ph-dim); border-radius: 0; }
.mother-head .surface-mode:hover, .mother-head .surface-mode:focus-visible { color: var(--ph); background: var(--ph-faint); }
.mother-head .surface-mode[aria-pressed="true"] { color: var(--ph); background: var(--ph-faint); }

/* A panel split wider, or floating, gives its grip up: the room or the window decides its width. */
.tree:is(.split, .window) > .panel-grip { display: none; }

/* A dialog split beside the conversation, or floating: a card in the room, not a sheet over it. */
dialog.surface:is(.split, .window) {
  position: fixed; inset: auto; margin: 0; max-width: none; max-height: none; z-index: 6;
  border: 1px solid var(--line-2); border-radius: 16px; overflow: hidden;
  box-shadow: 0 1px 0 rgba(255, 255, 255, .04) inset, 0 18px 50px -24px rgba(0, 0, 0, .5);
}
dialog.surface.window { z-index: 35; transition: box-shadow calc(260ms * var(--motion-scale)) var(--ease-glide), transform calc(260ms * var(--motion-scale)) var(--ease-glide); }
dialog.surface.window.front { z-index: 36; box-shadow: 0 1px 0 rgba(255, 255, 255, .05) inset, 0 34px 90px -30px rgba(0, 0, 0, .66), 0 8px 24px -8px rgba(0, 0, 0, .3); }
