.ed-bar::-webkit-scrollbar { display: none; }
.ed-btn { display: inline-flex; align-items: center; gap: 7px; flex: none; height: 28px; padding: 0 10px; border: 1px solid transparent; border-radius: 8px; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 10px; letter-spacing: .1em; cursor: pointer; transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out), border-color var(--motion) var(--ease-out); }
.ed-btn:hover, .ed-btn:focus-visible { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); outline: 0; }
.ed-btn:disabled { opacity: .35; cursor: default; }
.ed-btn kbd { font-family: var(--mono); font-size: 9.5px; letter-spacing: 0; color: var(--text-3); padding: 1px 5px; border: 1px solid var(--line-2); border-radius: 5px; }
.ed-btn[aria-pressed="true"] { color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 12%, transparent); }
.ed-save { border-color: var(--line-2); color: var(--text); }
.ed-save .ed-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--text-3); transition: background-color var(--motion) var(--ease-out), box-shadow var(--motion) var(--ease-out); }
.code-editor.dirty .ed-save { border-color: color-mix(in srgb, var(--warn) 55%, var(--line-2)); }
.code-editor.dirty .ed-save .ed-dot { background: var(--warn); box-shadow: 0 0 0 3px color-mix(in srgb, var(--warn) 18%, transparent); }
.code-editor.just-saved .ed-save .ed-dot { background: var(--phosphor); box-shadow: 0 0 0 3px color-mix(in srgb, var(--phosphor) 22%, transparent); }
.code-editor.saving .ed-save { opacity: .6; }
.ed-sep { width: 1px; height: 18px; margin: 0 4px; background: var(--line-2); flex: none; }
.ed-grow { flex: 1 1 auto; }

/* Find, replace, go to line: a strip under the bar, not a window over the text. */
.ed-find, .ed-goto { display: grid; gap: 6px; padding: 8px 10px; border-bottom: 1px solid var(--line); background: var(--panel); }
.ed-find[hidden], .ed-goto[hidden], .ed-replace-row[hidden] { display: none; }
.ed-row { display: flex; align-items: center; gap: 4px; }
