.ed-find input, .ed-goto input { flex: 1 1 auto; min-width: 0; height: 28px; padding: 0 10px; border: 1px solid var(--line-2); border-radius: 8px; background: var(--bg); color: var(--text); font-family: var(--mono); font-size: 12px; outline: 0; }
.ed-goto input { flex: 0 0 120px; }
.ed-find input:focus, .ed-goto input:focus { border-color: color-mix(in srgb, var(--phosphor) 55%, var(--line-2)); }
.ed-find.none .ed-q { border-color: color-mix(in srgb, var(--danger) 60%, var(--line-2)); }
.ed-opt, .ed-nav, .ed-x { flex: none; height: 28px; min-width: 28px; padding: 0 7px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 11px; cursor: pointer; }
.ed-opt:hover, .ed-nav:hover, .ed-x:hover { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
.ed-opt[aria-pressed="true"] { color: var(--phosphor); border-color: color-mix(in srgb, var(--phosphor) 40%, transparent); }
.ed-count { min-width: 64px; text-align: right; font-family: var(--mono); font-size: 10px; color: var(--text-3); white-space: nowrap; }

/* The page: numbers, the line you are on, the drawing, and the textarea on top of it. */
