.ed-gutter { position: relative; overflow: hidden; border-right: 1px solid var(--line); background: var(--bg-2); }
.ed-gutter-inner { padding: var(--ed-pad) 10px var(--ed-pad) 0; font-family: var(--ed-font); font-size: 11.5px; line-height: var(--ed-lh); color: var(--text-3); text-align: right; opacity: .7; will-change: transform; }
.ed-gutter-inner > div { height: var(--ed-lh); }
