.ed-active { position: absolute; left: 0; right: 0; top: 0; height: var(--ed-lh); background: color-mix(in srgb, var(--text) 4%, transparent); border-top: 1px solid color-mix(in srgb, var(--text) 5%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--text) 5%, transparent); pointer-events: none; will-change: transform; }
.ed-hl, .ed-input {
  font-family: var(--ed-font); font-size: var(--ed-size); line-height: var(--ed-lh); letter-spacing: 0; tab-size: 4;
  font-variant-ligatures: none; white-space: pre; padding: var(--ed-pad) 18px var(--ed-pad) 14px; margin: 0; border: 0;
}
.ed-hl { position: absolute; left: 0; top: 0; min-width: 100%; color: var(--text); pointer-events: none; will-change: transform; }
.ed-hl .l { min-height: var(--ed-lh); }
.ed-hl mark { background: color-mix(in srgb, var(--warn) 30%, transparent); color: inherit; border-radius: 3px; box-shadow: 0 0 0 1px color-mix(in srgb, var(--warn) 45%, transparent); }
.ed-hl mark.cur { background: color-mix(in srgb, var(--warn) 60%, transparent); }
.ed-hl .t-keyword { color: var(--syn-keyword); }
.ed-hl .t-string { color: var(--syn-string); }
.ed-hl .t-comment { color: var(--syn-comment); font-style: italic; }
.ed-hl .t-number { color: var(--syn-number); }
.ed-hl .t-literal { color: var(--syn-literal); }
