.ed-status { display: flex; align-items: center; gap: 16px; padding: 6px 12px; border-top: 1px solid var(--line); background: var(--panel); font-family: var(--mono); font-size: 10px; letter-spacing: .06em; color: var(--text-3); white-space: nowrap; overflow: hidden; }
.ed-status .ed-pos { color: var(--text-2); }
.ed-status .ed-state { color: var(--phosphor); }
.code-editor.dirty .ed-status .ed-state { color: var(--warn); }
.viewer-edit.on { color: var(--phosphor); border-color: color-mix(in srgb, var(--phosphor) 45%, transparent); }
@media (max-width: 720px) {
  .code-editor { --ed-gutter: 44px; --ed-size: 12.5px; }
  .ed-btn kbd, .ed-status .ed-indent, .ed-status .ed-eol { display: none; }
}

/* ================= the menu after / , @ and # =================
   Rows that read at a glance: a tile that says what kind of thing it is, the name with how it is
   written beside it as a quiet chip, what it does under them. Commands come grouped — the room's
   own, then the modules', then what cannot run here — and the keys are drawn as keys. */
.slash-menu { width: min(560px, 92vw); max-height: min(62vh, 560px); overflow-y: auto; padding: 6px; gap: 1px; border-radius: 16px; scrollbar-width: thin; box-shadow: 0 1px 0 rgba(255, 255, 255, .04) inset, 0 24px 60px -18px rgba(0, 0, 0, .5), 0 2px 8px rgba(0, 0, 0, .14); }
