.model-menu.mode-menu { width: min(430px, calc(100vw - 24px)); padding: 8px; }
.mode-menu .model-menu-title { margin: 8px 10px 10px; }
.mode-menu .mode-ladder { gap: 3px; }
.mode-menu .mode-option { grid-template-columns: 30px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 10px 12px; border: 1px solid transparent; border-radius: 12px; transition: background-color var(--motion-fast) var(--ease-out), border-color var(--motion-fast) var(--ease-out); }
.mode-menu .mode-option + .mode-option { border-top: 1px solid transparent; border-radius: 12px; }
.mode-menu .mode-option:hover { background: color-mix(in srgb, var(--text) 5%, transparent); }
.mode-menu .mode-option.o0 { --mode: var(--mode-0); }
.mode-menu .mode-option.o1 { --mode: var(--mode-1); }
.mode-menu .mode-option.o2 { --mode: var(--mode-2); }
.mode-menu .mode-option .n { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; border: 1px solid color-mix(in srgb, var(--mode) 35%, transparent); background: color-mix(in srgb, var(--mode) 7%, transparent); font-size: 11px; color: var(--mode); }
.mode-menu .mode-option .body { gap: 3px; }
.mode-menu .mode-option .name { font-size: 10.5px; letter-spacing: .14em; }
.mode-menu .mode-option:not(.current):not(.o3):not(.o4) .name { color: var(--text); }
.mode-menu .mode-option .hint { font-family: var(--read); font-size: 12px; line-height: 1.4; color: var(--text-2); display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; overflow: hidden; }
.mode-menu .mode-option.current { background: color-mix(in srgb, var(--mode) 9%, transparent); border-color: color-mix(in srgb, var(--mode) 28%, transparent); }
.mode-menu .mode-option.current .n { background: var(--mode); color: var(--mode-ink, var(--bg)); border-color: transparent; }
