dialog.viewer .viewer-path .dir { color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; flex: 0 1 auto; direction: rtl; text-align: left; }
dialog.viewer .viewer-path .file { color: var(--text); font-weight: 600; white-space: nowrap; flex: none; }
dialog.viewer .viewer-lang { flex: none; padding: 2px 8px; border: 1px solid var(--line-2); border-radius: 999px; color: var(--text-3); font-size: 9px; letter-spacing: .14em; }
dialog.viewer .viewer-open { flex: none; padding: 6px 8px; border-radius: 8px; color: var(--text-2); font-size: 9.5px; letter-spacing: .12em; transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out); }
dialog.viewer .viewer-open:hover { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
dialog.viewer .viewer-mode { flex: none; }
.viewer-seg { display: inline-flex; flex: none; padding: 2px; border: 1px solid var(--line-2); border-radius: 9px; background: color-mix(in srgb, var(--text) 3%, transparent); }
.viewer-seg[hidden] { display: none; }
.viewer-seg-btn { height: 24px; padding: 0 11px; border: 0; border-radius: 6px; background: transparent; color: var(--text-3); font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .14em; cursor: pointer; transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out); }
.viewer-seg-btn:hover { color: var(--text); }
.viewer-seg-btn[aria-pressed="true"] { color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 14%, transparent); }
dialog.viewer .viewer-status { flex: none; display: flex; align-items: center; gap: 12px; min-height: 34px; padding: 6px 14px; border-top: 1px solid var(--line); background: var(--panel); font-family: var(--mono); font-size: 10px; letter-spacing: .04em; color: var(--text-3); }
dialog.viewer .viewer-status:not(:has(> :not([hidden]))) { display: none; }
