.room-ask-title { margin: 0; font-family: var(--mono); font-size: 11px; font-weight: 600; letter-spacing: .16em; text-transform: uppercase; color: var(--text); overflow-wrap: anywhere; }
.room-ask-body { margin: 0; font-family: var(--read); font-weight: var(--read-weight); font-size: 14px; line-height: 1.55; color: var(--text-2); white-space: pre-line; overflow-wrap: anywhere; }
.room-ask-field { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 10px; padding: 8px 0; border-bottom: 1px solid var(--line-2); }
.room-ask-field .k { font-family: var(--mono); font-size: 9.5px; letter-spacing: .18em; color: var(--text-3); }
.room-ask-field input { min-width: 0; border: 0; outline: 0; background: transparent; color: var(--text); font-family: var(--mono); font-size: 13px; letter-spacing: .06em; caret-color: var(--phosphor); }
.room-ask-field:focus-within { border-bottom-color: var(--phosphor); }
.room-ask-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 4px; }
.room-ask-choice { height: 34px; padding: 0 14px; border: 1px solid var(--line-2); border-radius: 10px; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 10.5px; letter-spacing: .14em; text-transform: uppercase; cursor: pointer; transition: color var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out), border-color var(--motion-fast) var(--ease-out); }
.room-ask-choice:hover { color: var(--text); border-color: var(--text-3); }
.room-ask-choice:focus-visible { outline: 0; box-shadow: var(--ring-soft); }
.room-ask-choice.primary { border-color: var(--phosphor); background: var(--phosphor); color: var(--phosphor-ink); }
.room-ask-choice.primary:hover { filter: brightness(1.06); }
.room-ask-choice.danger { border-color: color-mix(in srgb, var(--danger) 55%, transparent); background: color-mix(in srgb, var(--danger) 12%, transparent); color: var(--danger); }
.room-ask-choice.danger:hover { background: var(--danger); border-color: var(--danger); color: #fff; }
/* From the console: its black, its scanlines, its phosphor. */
dialog.room-ask.console { --ph: #28fe14; --ph-dim: rgba(40, 254, 20, .52); --ph-faint: rgba(40, 254, 20, .13); color: var(--ph); }
dialog.room-ask.console::backdrop { background: rgba(0, 0, 0, .7); }
dialog.room-ask.console .room-ask-card {
  border: 1px solid var(--ph-dim); border-radius: 0;
  background: linear-gradient(rgba(155, 255, 102, .05) 1px, transparent 1px) 0 0 / 100% 3px, radial-gradient(ellipse at 50% 0%, #0a1506, #020402 70%);
  box-shadow: 0 24px 60px rgba(0, 0, 0, .6);
  font-family: var(--mono); text-shadow: 0 0 3px rgba(155, 255, 102, .18);
}
dialog.room-ask.console .room-ask-title { color: var(--ph); font-size: 12px; letter-spacing: .22em; }
dialog.room-ask.console .room-ask-body { font-family: var(--mono); font-size: 11px; letter-spacing: .06em; line-height: 1.75; color: rgba(210, 255, 190, .88); text-transform: uppercase; }
dialog.room-ask.console .room-ask-field { border-bottom-color: var(--ph-faint); }
dialog.room-ask.console .room-ask-field .k { color: var(--ph-dim); }
dialog.room-ask.console .room-ask-field input { color: var(--ph); caret-color: var(--ph); text-transform: uppercase; }
dialog.room-ask.console .room-ask-field:focus-within { border-bottom-color: var(--ph); }
dialog.room-ask.console .room-ask-choice { border-radius: 0; border-color: var(--ph-dim); color: var(--ph); }
dialog.room-ask.console .room-ask-choice:hover { background: var(--ph-faint); }
dialog.room-ask.console .room-ask-choice.primary { background: var(--ph); border-color: var(--ph); color: #041004; text-shadow: none; }
dialog.room-ask.console .room-ask-choice.danger { border-color: color-mix(in srgb, var(--danger) 70%, transparent); background: transparent; color: var(--danger); }
dialog.room-ask.console .room-ask-choice.danger:hover { background: color-mix(in srgb, var(--danger) 18%, transparent); color: var(--danger); }
@media (prefers-reduced-motion: reduce) { dialog.room-ask[open] .room-ask-card { animation: none; } }

/* ================= effort: a colour with the strength of the level =================
   One tone, mixed toward the quiet grey at the lowest level and pure at the highest; the fill, the
   thumb, its halo and the level's name all take it, so how much the agent will think is seen before
   it is read. The CLI's own level is a small tag riding above the track, clear of the thumb's halo. */
.model-menu.effort-menu { --level-tone: color-mix(in srgb, var(--tone) calc(25% + var(--strength, 1) * 75%), var(--text-3)); }
.effort-slider .fill { background: linear-gradient(90deg, color-mix(in srgb, var(--level-tone) 30%, transparent), var(--level-tone)); }
.effort-slider .thumb { background: var(--level-tone); box-shadow: 0 0 0 calc(3px + var(--strength, 1) * 3px) color-mix(in srgb, var(--level-tone) calc(12% + var(--strength, 1) * 16%), transparent), 0 4px 12px -4px rgba(0, 0, 0, .45); transition: left calc(260ms * var(--motion-scale)) var(--ease-glide), transform calc(160ms * var(--motion-scale)) var(--ease-out), box-shadow calc(220ms * var(--motion-scale)) var(--ease-out), background-color calc(220ms * var(--motion-scale)) var(--ease-out); }
.effort-slider.auto .thumb { background: var(--panel); box-shadow: 0 0 0 2px var(--level-tone), 0 4px 12px -4px rgba(0, 0, 0, .35); }
.effort-readout .name, .effort-slider .stop.on { color: var(--level-tone); transition: color calc(220ms * var(--motion-scale)) var(--ease-out); }
.effort-readout .effort-gauge:first-child .effort-gauge-track i { background: var(--level-tone); }
.effort-slider .tick.cli::after { bottom: 17px; padding: 1px 5px; border-radius: 5px; background: var(--panel); box-shadow: 0 0 0 1px var(--line-2); font-size: 7.5px; line-height: 1.5; color: var(--text-2); transition: color calc(160ms * var(--motion-scale)) var(--ease-out), box-shadow calc(160ms * var(--motion-scale)) var(--ease-out); }
.effort-slider .tick.cli.under::after { color: var(--level-tone); box-shadow: 0 0 0 1px color-mix(in srgb, var(--level-tone) 55%, transparent); }
.effort-slider { margin-top: 24px; }

/* ================= a connection's card: who, and a light for how =================
   The agent's mark and name from the left, like every card's title; the state of its session is a
   light in the card's top corner instead of a word in a box. */
.conn-card { position: relative; }
.conn-card > .head { align-self: stretch; justify-content: flex-start; padding-right: 22px; }
.conn-dot { position: absolute; top: 14px; right: 14px; width: 9px; height: 9px; border-radius: 50%; background: var(--ph-dim); box-shadow: 0 0 0 3px rgba(40, 254, 20, .08); }
.conn-dot.on { background: var(--ph); box-shadow: 0 0 0 3px color-mix(in srgb, var(--ph) 18%, transparent), 0 0 10px color-mix(in srgb, var(--ph) 55%, transparent); }
.conn-dot.off { background: var(--danger); box-shadow: 0 0 0 3px color-mix(in srgb, var(--danger) 18%, transparent), 0 0 8px color-mix(in srgb, var(--danger) 45%, transparent); }
.conn-dot.busy { background: var(--warn); box-shadow: 0 0 0 3px color-mix(in srgb, var(--warn) 18%, transparent); animation: conn-dot-breathe 1.4s ease-in-out infinite; }
.conn-dot.absent { background: transparent; box-shadow: inset 0 0 0 1.5px var(--ph-dim); }
.conn-dot.unknown { background: var(--ph-faint); box-shadow: inset 0 0 0 1px var(--ph-dim); }
@keyframes conn-dot-breathe { 50% { opacity: .45; transform: scale(.85); } }
@media (prefers-reduced-motion: reduce) { .conn-dot.busy { animation: none; } }

/* ================= the composer's row of chips =================
   The chips wrap whenever they do not fit, at any width, instead of running past the box's edge —
   a conversation in a window is narrow without the screen being so. */
.picker { flex-wrap: wrap; row-gap: 10px; }
.picker .pick-label { flex-wrap: wrap; row-gap: 8px; }
/* A conversation in a window or in the other half has nothing under its box: it keeps its air. */
.split-pane .shell > .composer { margin-bottom: 16px; }

/* The browser's header is a layer of its own as a window (its frosted ground makes it one); it is
   raised above the tabs and the page, or the servers' menu it opens is drawn under them. */
.browser-dock .browser-head { position: relative; z-index: 6; }

/* ================= point and ask =================
   Over the page, a layer that takes the pointer: the toolbox at the top in the room's look, a point
   that pulses where it was pressed or an area drawn with a dashed edge, and beside the mark a card
   with who should look and what to ask. */
.browser-head .nav.point { display: inline-flex; align-items: center; gap: 6px; width: auto; padding: 0 10px 0 8px; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; }
.browser-head .nav.point svg { width: var(--ico-sm); height: var(--ico-sm); }
.browser-head .nav.point[aria-pressed="true"] { color: var(--phosphor); border-color: color-mix(in srgb, var(--phosphor) 45%, transparent); background: color-mix(in srgb, var(--phosphor) 12%, transparent); }
@container dock (max-width: 620px) { .browser-head .nav.point > span { display: none; } .browser-head .nav.point { padding: 0 7px; } }
.point-layer { position: absolute; z-index: 3; cursor: crosshair; background: color-mix(in srgb, var(--phosphor) 3%, transparent); box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 45%, transparent); }
.point-tools { position: absolute; top: 12px; left: 50%; transform: translateX(-50%); z-index: 2; display: inline-flex; align-items: center; gap: 2px; padding: 3px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); box-shadow: 0 14px 34px -14px rgba(0, 0, 0, .5); cursor: default; animation: point-in calc(220ms * var(--motion-scale)) var(--ease-glide); }
.point-tool { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px 0 9px; border: 0; border-radius: 9px; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; cursor: pointer; transition: color var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out); }
.point-tool svg { width: var(--ico-sm); height: var(--ico-sm); }
.point-tool:hover { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
.point-tool[aria-pressed="true"] { color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 14%, transparent); }
.point-sep { width: 1px; height: 16px; margin: 0 3px; background: var(--line-2); }
.point-tools .point-close { width: 28px; height: 28px; }
.point-hint { position: absolute; top: 56px; left: 50%; transform: translateX(-50%); z-index: 2; padding: 4px 10px; border-radius: 999px; background: color-mix(in srgb, var(--panel) 88%, transparent); color: var(--text-2); font-family: var(--mono); font-size: 9.5px; letter-spacing: .1em; white-space: nowrap; pointer-events: none; }
.point-dot { position: absolute; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; background: var(--phosphor); box-shadow: 0 0 0 3px color-mix(in srgb, var(--panel) 85%, transparent), 0 4px 12px -2px rgba(0, 0, 0, .45); pointer-events: none; }
.point-dot::after { content: ''; position: absolute; inset: -8px; border-radius: 50%; border: 2px solid var(--phosphor); opacity: 0; animation: point-pulse 1.8s var(--ease-out) infinite; }
.point-area { position: absolute; border: 1.5px dashed var(--phosphor); border-radius: 6px; background: color-mix(in srgb, var(--phosphor) 10%, transparent); pointer-events: none; }
@keyframes point-in { from { opacity: 0; transform: translate(var(--point-x, 0), 4px); } to { opacity: 1; } }
.point-tools { --point-x: -50%; }
@keyframes point-pulse { 0% { opacity: .7; transform: scale(.6); } 100% { opacity: 0; transform: scale(1.4); } }
@media (prefers-reduced-motion: reduce) { .point-tools { animation: none; } .point-dot::after { animation: none; } }
.point-tools .point-close { border: 0; background: transparent; color: var(--text-3); }
.point-hint { max-width: calc(100% - 24px); white-space: normal; text-align: center; }

/* ================= asking about something on the screen =================
   One card wherever something is asked about — lines in the editor, a spot or an area on a page:
   the agents in a row, the questions the thing raises, what the memory adds, and writing one's own
   as the card's first action, with a pen: the same key as a new conversation. */
.ask-card { position: fixed; z-index: 75; display: grid; gap: 10px; width: min(300px, calc(100vw - 24px)); padding: 10px; border: 1px solid var(--line-2); border-radius: 14px; background: var(--panel); box-shadow: 0 1px 0 rgba(255, 255, 255, .04) inset, 0 22px 54px -20px rgba(0, 0, 0, .55); animation: ask-card-in calc(200ms * var(--motion-scale)) var(--ease-glide); }
.ask-card[hidden] { display: none; }
@keyframes ask-card-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.ask-card-head { padding: 2px 4px 0; font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-3); }
.ask-crew { display: flex; flex-wrap: wrap; gap: 8px; padding: 0 4px; }
.ask-agent { --size: 26px; cursor: pointer; border: 1px solid transparent; background: color-mix(in srgb, var(--agent) 10%, transparent); transition: transform calc(120ms * var(--motion-scale)) ease, box-shadow calc(120ms * var(--motion-scale)) ease; }
.ask-agent:hover { transform: translateY(-1px); }
.ask-agent[aria-checked="true"] { box-shadow: 0 0 0 2px var(--panel), 0 0 0 3.5px var(--agent); background: color-mix(in srgb, var(--agent) 22%, transparent); }
.ask-agent:focus-visible { outline: 0; box-shadow: 0 0 0 2px var(--panel), 0 0 0 3.5px var(--agent), var(--ring-soft); }
.ask-group { display: grid; gap: 1px; }
.ask-group-title { padding: 4px 10px 3px; font-family: var(--mono); font-size: 8.5px; letter-spacing: .18em; color: var(--text-3); }
.ask-item { padding: 8px 10px; border: 0; border-radius: 8px; background: transparent; color: var(--text); font-family: var(--read); font-size: 13px; line-height: 1.4; text-align: left; cursor: pointer; transition: background-color var(--motion-fast) var(--ease-out); }
.ask-item:hover, .ask-item:focus-visible { background: color-mix(in srgb, var(--phosphor) 10%, transparent); outline: 0; }
.ask-remembered:empty { display: none; }
.ask-own { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 4px; border-radius: 10px; font-family: var(--mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; cursor: pointer; }
.ask-own svg { width: var(--ico-sm); height: var(--ico-sm); }
@media (prefers-reduced-motion: reduce) { .ask-card { animation: none; } }

/* Taking the picture: only the page, without the toolbox, the layer's tint or the area's frame —
   the picture is the area. A spot keeps its dot, still: it says where, inside what surrounds it. */
.point-layer.capturing { background: transparent; box-shadow: none; }
.point-layer.capturing :is(.point-tools, .point-hint, .point-area) { visibility: hidden; }
.point-layer.capturing .point-dot::after { animation: none; opacity: 0; }

/* The place pointed at, in the composer: the same characters as a chip, the server clear, the rest quiet. */
.editor .highlight .chip.point { --agent: var(--text); padding: 2px 0; border-radius: 5px; background: color-mix(in srgb, var(--phosphor) 10%, transparent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--phosphor) 10%, transparent); }
.editor .highlight .chip.point .sig { color: var(--phosphor); }
.editor .highlight .chip.point .base { color: var(--text); }
.editor .highlight .chip.point .dir { color: var(--text-2); -webkit-text-stroke: 0; }
/* As a popover it starts from the browser's own popover box; it keeps the card's. */
.ask-card[popover] { inset: auto; margin: 0; overflow: visible; color: var(--text); }

/* A turn cut short: what it left before it stopped, with its way back, and one press to try again
   with more time. The same tiles, list and UNDO as a turn that finished, in the failure's own line. */
.system.fail .partial { display: grid; gap: 8px; justify-items: center; margin-top: 10px; padding: 10px 14px; border: 1px dashed color-mix(in srgb, var(--danger) 45%, transparent); border-radius: 12px; color: var(--text-2); }
.system.fail .partial > .label { color: var(--text-2); opacity: 1; }
.system.fail .partial .artifacts { justify-items: center; }
.system.fail .partial .files { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-family: var(--mono); font-size: 11px; text-align: center; }
.system.fail .partial .note { font-family: var(--mono); font-size: 10.5px; color: var(--warn); }
.system.fail .partial .undo { border: 1px solid var(--terror); background: color-mix(in srgb, var(--terror) 12%, transparent); color: var(--terror); font: inherit; font-family: var(--mono); font-size: 10px; letter-spacing: .16em; padding: 7px 12px; border-radius: 8px; cursor: pointer; }
.system.fail .partial .undo:hover { background: color-mix(in srgb, var(--terror) 22%, transparent); }
.system.fail .partial .undo:disabled { opacity: .5; cursor: default; }
.system.fail .retry-longer { display: block; margin: 10px auto 0; border: 1px solid var(--phosphor); background: color-mix(in srgb, var(--phosphor) 10%, transparent); color: var(--phosphor); font-family: var(--mono); font-size: 10px; letter-spacing: .16em; padding: 7px 14px; border-radius: 8px; cursor: pointer; transition: background-color var(--motion-fast) var(--ease-out); }
.system.fail .retry-longer:hover { background: color-mix(in srgb, var(--phosphor) 20%, transparent); }
.system.fail .retry-longer:focus-visible { outline: 0; box-shadow: var(--ring-soft); }
.system.fail .retry-longer:disabled { opacity: .6; cursor: default; }

/* ---------- PERSONALIZE: a window of its own ----------
   Always a window (carried by its header, sized from its edges, window button and × like every
   other). A preview of the conversation beside the choices; below 600 px of its own width, one
   above the other. Language is for the whole room; accent, bubbles and text are read under
   #messages and the preview, and the accent also by every button. */
dialog.custom-window { width: 720px; height: 560px; padding: 0; color: var(--text); background: color-mix(in srgb, var(--panel) 92%, transparent); -webkit-backdrop-filter: blur(22px) saturate(1.2); backdrop-filter: blur(22px) saturate(1.2); container: custom / inline-size; }
dialog.custom-window[open] { display: flex; flex-direction: column; }
dialog.custom-window.entering { animation: window-in calc(440ms * var(--motion-scale)) var(--ease-glide); transform-origin: 85% 0%; }
dialog.custom-window::backdrop { display: none; }
.custom-head { display: flex; align-items: center; gap: 12px; padding: 12px 12px 12px 18px; border-bottom: 1px solid var(--line); cursor: grab; user-select: none; touch-action: none; }
.custom-head .surface-modes { margin-left: auto; }
.custom-title { font-family: var(--mono); font-size: 11px; font-weight: 600; letter-spacing: .22em; color: var(--text); }
.custom-sub { font-family: var(--mono); font-size: 9.5px; letter-spacing: .16em; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.custom-body { flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.custom-grid { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.15fr); overflow: hidden; }
.custom-look { display: grid; grid-template-rows: auto 1fr; gap: 10px; padding: 16px 18px; border-right: 1px solid var(--line); background: color-mix(in srgb, var(--bg) 55%, transparent); min-height: 0; overflow: hidden; }
.custom-kicker { font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .18em; color: var(--text-3); }
.custom-choices { display: grid; align-content: start; gap: 18px; padding: 16px 18px 18px; overflow-y: auto; min-height: 0; font-family: var(--mono); font-size: 11px; letter-spacing: .04em; }
@container custom (max-width: 600px) {
  .custom-grid { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); overflow-y: auto; }
  .custom-look { border-right: 0; border-bottom: 1px solid var(--line); }
  .custom-choices { overflow: visible; }
  .custom-sub { display: none; }
}
/* The preview is the conversation in small: the same rows and bubbles, its own column. */
.look-preview { display: flex; flex-direction: column; gap: 4px; align-content: start; min-height: 0; overflow: hidden; padding: 4px 2px; }
.look-preview .row { max-width: 100%; margin-top: 10px; }
.look-preview .row.user { align-self: flex-end; }
.look-preview .avatar { width: 22px; height: 22px; border-radius: 50%; background: color-mix(in srgb, var(--text) 10%, transparent); }
.custom-section { display: grid; gap: 8px; }
.custom-label { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; padding: 0 2px; }
.custom-label b { font-size: 9.5px; font-weight: 600; letter-spacing: .18em; color: var(--text-3); }
.custom-current { font-family: var(--read); font-size: 12px; letter-spacing: 0; color: var(--text-2); }
.custom-note { margin: 0; padding: 0 2px; font-family: var(--read); font-size: 11.5px; letter-spacing: 0; line-height: 1.45; color: var(--text-3); }
.custom-seg { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 3px; padding: 3px; border: 1px solid var(--line-2); border-radius: 12px; background: var(--bg-2); }
.custom-seg.two { grid-template-columns: 1fr 1fr; }
.seg-option { min-height: 30px; padding: 0 4px; border: 0; border-radius: 9px; background: transparent; color: var(--text-2); font-family: var(--read); font-size: 11.5px; letter-spacing: 0; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: background var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out); }
.seg-option:hover { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
.seg-option[aria-checked="true"] { background: var(--panel-2); color: var(--text); font-weight: 600; box-shadow: var(--lift-1); }
.seg-option:focus-visible, .swatch:focus-visible, .custom-reset:focus-visible, .arrange-option:focus-visible { outline: 2px solid var(--phosphor); outline-offset: 2px; }
/* «Visual» shows what it does: the word in the weight it sets. */
.seg-option.look-text-visual { font-weight: 650; }
.seg-option.look-text-larger { font-size: 12.5px; } .seg-option.look-text-smaller { font-size: 10.5px; }
.custom-swatches { display: flex; flex-wrap: wrap; gap: 12px; padding: 3px 2px; }
.swatch { --sw: #9bff66; position: relative; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 50%; background: var(--sw); cursor: pointer; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .18), inset 0 2px 3px rgba(255, 255, 255, .25), 0 2px 6px -2px rgba(0, 0, 0, .4); transition: transform var(--motion-fast) var(--ease-out); }
.swatch:hover { transform: translateY(-1px) scale(1.06); }
.swatch[aria-checked="true"] { box-shadow: 0 0 0 2px var(--panel), 0 0 0 4px var(--sw), 0 4px 10px -3px rgba(0, 0, 0, .45); }
.swatch[aria-checked="true"]::after { content: ''; position: absolute; left: 50%; top: 50%; width: 9px; height: 5px; border-left: 2px solid var(--sw-ink, #0a1405); border-bottom: 2px solid var(--sw-ink, #0a1405); transform: translate(-50%, -65%) rotate(-45deg); }
/* Each sphere shows its colour's identity, in either theme: Madre green is MADRE's own phosphor,
   and the others the hex they were named for. The homologue for a ground is what the room wears,
   not what the sphere is. */
.swatch[data-swatch="madre"] { --sw: #9bff66; --sw-ink: #0a1405; }
.swatch[data-swatch="mountain"] { --sw: #28f7ca; --sw-ink: #04201a; }
.swatch[data-swatch="caribbean"] { --sw: #2ddff7; --sw-ink: #031a1f; }
.swatch[data-swatch="phantom"] { --sw: #9063f2; --sw-ink: #ffffff; }
.swatch[data-swatch="malbec"] { --sw: #9e094c; --sw-ink: #ffffff; }
.swatch[data-swatch="dijon"] { --sw: #f5cc05; --sw-ink: #1a1400; }
.swatch[data-swatch="pacific"] { --sw: #54e3ed; --sw-ink: #00282b; }
.swatch[data-swatch="love"] { --sw: #fb46dd; --sw-ink: #ffffff; }
.swatch[data-swatch="sierra"] { --sw: #bcd8f9; --sw-ink: #0d2340; }
.swatch[data-swatch="pitahaya"] { --sw: #ff4278; --sw-ink: #ffffff; }
.swatch[data-swatch="papaya"] { --sw: #ffa266; --sw-ink: #2e1300; }
.swatch[data-swatch="agave"] { --sw: #496a4d; --sw-ink: #ffffff; }
.swatch[data-swatch="dinamo"] { --sw: #696969; --sw-ink: #ffffff; }
.swatch[data-swatch="marina"] { --sw: #7fffd4; --sw-ink: #00332a; }
.swatch[data-swatch="pulso"] { --sw: #99a17d; --sw-ink: #ffffff; }
.swatch[data-swatch="leal"] { --sw: #ff6a1f; --sw-ink: #ffffff; }
.swatch[data-swatch="dulce"] { --sw: #ffd061; --sw-ink: #2b2000; }
:root[data-scheme="light"] .swatch { box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .14), inset 0 2px 3px rgba(255, 255, 255, .35), 0 2px 6px -2px rgba(20, 30, 20, .3); }
:root[data-scheme="light"] .swatch[aria-checked="true"] { box-shadow: 0 0 0 2px var(--panel), 0 0 0 4px color-mix(in srgb, var(--sw) 80%, #000000), 0 4px 10px -3px rgba(20, 30, 20, .3); }
.custom-current { transition: color var(--motion-fast) var(--ease-out); }
.custom-current.peek { color: var(--text-3); font-style: italic; }
/* A button in the preview, in the draft's tone, as the room's buttons will wear it. */
.look-preview .look-button { align-self: flex-start; margin: 16px 0 0 30px; padding: 7px 14px; border: 1px solid color-mix(in srgb, var(--phosphor) 45%, var(--line-2)); border-radius: 999px; background: color-mix(in srgb, var(--phosphor) 10%, transparent); color: var(--phosphor); font-family: var(--mono); font-size: 9.5px; font-weight: 600; letter-spacing: .14em; }
.custom-acts { display: inline-flex; align-items: center; gap: 16px; }
.custom-accept { height: 32px; padding: 0 18px; border: 0; border-radius: 10px; background: var(--phosphor); color: var(--phosphor-ink); font-family: var(--mono); font-size: 10px; font-weight: 700; letter-spacing: .16em; cursor: pointer; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .25), 0 2px 6px -2px rgba(0, 0, 0, .4); transition: filter var(--motion-fast) var(--ease-out), opacity var(--motion-fast) var(--ease-out); }
.custom-accept:hover:not(:disabled) { filter: brightness(1.06); }
.custom-accept:disabled { opacity: .4; cursor: default; box-shadow: none; }
.custom-accept:focus-visible { outline: 2px solid var(--phosphor); outline-offset: 2px; }
.custom-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 18px; border-top: 1px solid var(--line); }
.custom-scope { font-family: var(--read); font-size: 11.5px; letter-spacing: 0; color: var(--text-3); }
.custom-reset { border: 0; padding: 0; background: transparent; color: var(--text-2); font-family: var(--mono); font-size: 9.5px; letter-spacing: .14em; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }
.custom-reset:hover { color: var(--text); }
@media (prefers-reduced-motion: reduce) { dialog.custom-window.entering { animation: none; } .swatch { transition: none; } }

/* The accents. Each is three inks: a tone for what the conversation and the buttons mark, the ink
   written on that tone, and the human's own bubble with its ink. Every pair passes AA (4.5:1):
   where the bright tone fails on one ground it has a homologue there — darker on light, lighter
   on dark. The tokens follow a data-accent wherever it is written: on the root once accepted, on
   the preview while it is only a draft. Madre green is the room as it was and writes nothing on
   the root. The permission modes are colours with a meaning (--mode-n, fixed at the root) and do
   not follow the accent. */
[data-accent="madre"] { --acc: #9bff66; --acc-ink: #0a1405; --acc-bubble: #9bff66; --acc-bubble-ink: #0a1405; }
[data-accent="mountain"] { --acc: #28f7ca; --acc-ink: #04201a; --acc-bubble: #28f7ca; --acc-bubble-ink: #04201a; }
[data-accent="caribbean"] { --acc: #2ddff7; --acc-ink: #031a1f; --acc-bubble: #2ddff7; --acc-bubble-ink: #031a1f; }
[data-accent="phantom"] { --acc: #a585f7; --acc-ink: #12062b; --acc-bubble: #8255ee; --acc-bubble-ink: #ffffff; }
[data-accent="malbec"] { --acc: #f0679b; --acc-ink: #2a0614; --acc-bubble: #9e094c; --acc-bubble-ink: #ffffff; }
[data-accent="dijon"] { --acc: #f5cc05; --acc-ink: #1a1400; --acc-bubble: #f5cc05; --acc-bubble-ink: #1a1400; }
[data-accent="pacific"] { --acc: #54e3ed; --acc-ink: #00282b; --acc-bubble: #54e3ed; --acc-bubble-ink: #00282b; }
[data-accent="love"] { --acc: #fb46dd; --acc-ink: #ffffff; --acc-bubble: #fb46dd; --acc-bubble-ink: #ffffff; }
[data-accent="sierra"] { --acc: #bcd8f9; --acc-ink: #0d2340; --acc-bubble: #bcd8f9; --acc-bubble-ink: #0d2340; }
[data-accent="pitahaya"] { --acc: #ff4278; --acc-ink: #ffffff; --acc-bubble: #ff4278; --acc-bubble-ink: #ffffff; }
[data-accent="papaya"] { --acc: #ffa266; --acc-ink: #2e1300; --acc-bubble: #ffa266; --acc-bubble-ink: #2e1300; }
[data-accent="agave"] { --acc: #8db691; --acc-ink: #0c1a0e; --acc-bubble: #496a4d; --acc-bubble-ink: #ffffff; }
[data-accent="dinamo"] { --acc: #b0b0b0; --acc-ink: #141414; --acc-bubble: #696969; --acc-bubble-ink: #ffffff; }
[data-accent="marina"] { --acc: #7fffd4; --acc-ink: #00332a; --acc-bubble: #7fffd4; --acc-bubble-ink: #00332a; }
[data-accent="pulso"] { --acc: #b7bf98; --acc-ink: #ffffff; --acc-bubble: #99a17d; --acc-bubble-ink: #ffffff; }
[data-accent="leal"] { --acc: #ff6a1f; --acc-ink: #ffffff; --acc-bubble: #ff6a1f; --acc-bubble-ink: #ffffff; }
[data-accent="dulce"] { --acc: #ffd061; --acc-ink: #2b2000; --acc-bubble: #ffd061; --acc-bubble-ink: #2b2000; }
:root[data-scheme="light"][data-accent="madre"], :root[data-scheme="light"] [data-accent="madre"] { --acc: #2f8a1c; --acc-ink: #ffffff; --acc-bubble: #2f8a1c; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="mountain"], :root[data-scheme="light"] [data-accent="mountain"] { --acc: #0b7d66; --acc-ink: #ffffff; --acc-bubble: #0b7d66; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="caribbean"], :root[data-scheme="light"] [data-accent="caribbean"] { --acc: #0a7189; --acc-ink: #ffffff; --acc-bubble: #0a7189; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="phantom"], :root[data-scheme="light"] [data-accent="phantom"] { --acc: #6a3fd6; --acc-ink: #ffffff; --acc-bubble: #6a3fd6; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="malbec"], :root[data-scheme="light"] [data-accent="malbec"] { --acc: #9e094c; --acc-ink: #ffffff; --acc-bubble: #9e094c; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="dijon"], :root[data-scheme="light"] [data-accent="dijon"] { --acc: #7d6300; --acc-ink: #ffffff; --acc-bubble: #f5cc05; --acc-bubble-ink: #1a1400; }
:root[data-scheme="light"][data-accent="pacific"], :root[data-scheme="light"] [data-accent="pacific"] { --acc: #00727a; --acc-ink: #ffffff; --acc-bubble: #54e3ed; --acc-bubble-ink: #00282b; }
:root[data-scheme="light"][data-accent="love"], :root[data-scheme="light"] [data-accent="love"] { --acc: #a8128f; --acc-ink: #ffffff; --acc-bubble: #fb46dd; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="sierra"], :root[data-scheme="light"] [data-accent="sierra"] { --acc: #2f5d96; --acc-ink: #ffffff; --acc-bubble: #bcd8f9; --acc-bubble-ink: #0d2340; }
:root[data-scheme="light"][data-accent="pitahaya"], :root[data-scheme="light"] [data-accent="pitahaya"] { --acc: #c0124a; --acc-ink: #ffffff; --acc-bubble: #ff4278; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="papaya"], :root[data-scheme="light"] [data-accent="papaya"] { --acc: #a84d0c; --acc-ink: #ffffff; --acc-bubble: #ffa266; --acc-bubble-ink: #2e1300; }
:root[data-scheme="light"][data-accent="agave"], :root[data-scheme="light"] [data-accent="agave"] { --acc: #496a4d; --acc-ink: #ffffff; --acc-bubble: #496a4d; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="dinamo"], :root[data-scheme="light"] [data-accent="dinamo"] { --acc: #4f4f4f; --acc-ink: #ffffff; --acc-bubble: #696969; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="marina"], :root[data-scheme="light"] [data-accent="marina"] { --acc: #00806a; --acc-ink: #ffffff; --acc-bubble: #7fffd4; --acc-bubble-ink: #00332a; }
:root[data-scheme="light"][data-accent="pulso"], :root[data-scheme="light"] [data-accent="pulso"] { --acc: #5f6744; --acc-ink: #ffffff; --acc-bubble: #99a17d; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="leal"], :root[data-scheme="light"] [data-accent="leal"] { --acc: #c2470a; --acc-ink: #ffffff; --acc-bubble: #ff6a1f; --acc-bubble-ink: #ffffff; }
:root[data-scheme="light"][data-accent="dulce"], :root[data-scheme="light"] [data-accent="dulce"] { --acc: #8a6400; --acc-ink: #ffffff; --acc-bubble: #ffd061; --acc-bubble-ink: #2b2000; }
/* Where the accepted accent is read: the conversation and every button in the room. A button's
   phosphor is set on the button itself, so its border, its fill and its ink follow. */
:root[data-accent] :is(#messages, button, [role="button"]) { --phosphor: var(--acc); --phosphor-ink: var(--acc-ink); --accent: var(--acc); --accent-ink: var(--acc-ink); }
/* ASH keeps Homebrew's green whatever the accent: it is a terminal, and that is its colour. */
:root[data-accent] .ash-toggle { --brew: #28fe14; --phosphor: #28fe14; }
:root[data-scheme="light"][data-accent] .ash-toggle { --brew: #178f0c; --phosphor: #178f0c; }
/* The box you write in takes the accent while it is in EXCHANGE (#1), the mode the room is in by
   default; every other mode keeps the colour that says what it lets an agent do. The mode menu
   and the chip say the same. */
:root[data-accent] :is(.composer, .mode-menu, .picker) { --mode-1: var(--acc); --mode-1-ink: var(--acc-ink); }
:root[data-accent] #messages { --user: var(--acc-bubble); --user-ink: var(--acc-bubble-ink); }
/* The preview always carries the draft, Madre green included, so it never borrows the room's. */
.look-preview[data-accent] { --phosphor: var(--acc); --phosphor-ink: var(--acc-ink); --accent: var(--acc); --accent-ink: var(--acc-ink); --user: var(--acc-bubble); --user-ink: var(--acc-bubble-ink); }

/* The bubbles. Comfortable is the room as it was: 88% of the column up to 860 px, 12 × 16 inside.
   The thinking row keeps its own small bubble whatever is chosen. */
:is(:root[data-bubbles="large"] #messages, .look-preview[data-bubbles="large"]) .row { max-width: min(96%, 940px); margin-top: 18px; }
:is(:root[data-bubbles="large"] #messages, .look-preview[data-bubbles="large"]) .row.compact { margin-top: 2px; }
:is(:root[data-bubbles="large"] #messages, .look-preview[data-bubbles="large"]) .row:not(.thinking) .bubble { padding: 16px 20px; border-radius: 22px; line-height: 1.6; }
:is(:root[data-bubbles="compact"] #messages, .look-preview[data-bubbles="compact"]) .row { max-width: min(74%, 640px); margin-top: 10px; }
:is(:root[data-bubbles="compact"] #messages, .look-preview[data-bubbles="compact"]) .row.compact { margin-top: 0; }
:is(:root[data-bubbles="compact"] #messages, .look-preview[data-bubbles="compact"]) .row:not(.thinking) .bubble { padding: 8px 12px; border-radius: 16px; line-height: 1.42; }
/* Fitted: wider than comfortable and roomier between lines, with less padding above and below,
   so a long answer reads in fewer, fuller lines. */
:is(:root[data-bubbles="fitted"] #messages, .look-preview[data-bubbles="fitted"]) .row { max-width: min(92%, 900px); margin-top: 12px; }
:is(:root[data-bubbles="fitted"] #messages, .look-preview[data-bubbles="fitted"]) .row.compact { margin-top: 0; }
:is(:root[data-bubbles="fitted"] #messages, .look-preview[data-bubbles="fitted"]) .row:not(.thinking) .bubble { padding: 10px 18px; border-radius: 18px; line-height: 1.58; }
:is(:root:is([data-bubbles="large"], [data-bubbles="compact"], [data-bubbles="fitted"]) #messages, .look-preview:is([data-bubbles="large"], [data-bubbles="compact"], [data-bubbles="fitted"])) .assistant .bubble { border-bottom-left-radius: 6px; }
:is(:root:is([data-bubbles="large"], [data-bubbles="compact"], [data-bubbles="fitted"]) #messages, .look-preview:is([data-bubbles="large"], [data-bubbles="compact"], [data-bubbles="fitted"])) .user .bubble { border-bottom-right-radius: 6px; }

/* The text read in the bubbles, the human's and the crew's. Comfortable is 15 px at 300. */
:is(:root[data-text="larger"] #messages, .look-preview[data-text="larger"]) .bubble { font-size: 17px; line-height: 1.55; }
:root[data-text="larger"] #messages .codeblock pre { font-size: 13.5px; }
:is(:root[data-text="smaller"] #messages, .look-preview[data-text="smaller"]) .bubble { font-size: 13.5px; line-height: 1.48; }
:root[data-text="smaller"] #messages .codeblock pre { font-size: 11.5px; }
:is(:root[data-text="visual"] #messages, .look-preview[data-text="visual"]) { --read-weight: 450; }
:is(:root[data-text="visual"] #messages, .look-preview[data-text="visual"]) .bubble :is(b, strong) { font-weight: 700; }
:is(:root[data-text="visual"] #messages, .look-preview[data-text="visual"]) .bubble :is(h1, h2, h3, h4) { font-weight: 750; }

/* ---------- ARRANGE: the card under a window button ----------
   Four ways to set what floats: the window asked from in the solid tile, the others in the light
   ones. A way that has more places than there are windows is offered all the same, a little
   quieter: the places left are simply left free. */
