  background-image: linear-gradient(180deg, rgba(255, 255, 255, .55), transparent 120px);
  box-shadow: 0 0 0 1px rgba(20, 30, 20, .08), inset 0 1px 0 rgba(255, 255, 255, .95), inset 0 -1px 0 rgba(20, 30, 20, .06), 0 1px 2px rgba(20, 30, 20, .08), 0 10px 24px -12px rgba(20, 30, 20, .2), 0 30px 70px -32px rgba(20, 30, 20, .3);
}
:root[data-scheme="light"] :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).front {
  box-shadow: 0 0 0 1px rgba(20, 30, 20, .1), inset 0 1px 0 rgba(255, 255, 255, .95), inset 0 -1px 0 rgba(20, 30, 20, .07), 0 2px 3px rgba(20, 30, 20, .1), 0 16px 34px -14px rgba(20, 30, 20, .26), 0 48px 110px -40px rgba(20, 30, 20, .38);
