  scale: calc(1 - var(--depth, 1) * .004);
  transition: filter calc(340ms * var(--motion-scale)) var(--ease-glide), scale calc(340ms * var(--motion-scale)) var(--ease-glide), box-shadow calc(260ms * var(--motion-scale)) var(--ease-glide), transform calc(260ms * var(--motion-scale)) var(--ease-glide), border-color calc(260ms * var(--motion-scale)) var(--ease-glide), opacity calc(200ms * var(--motion-scale)) var(--ease-out);
}
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).behind:hover {
  filter: blur(calc(var(--depth, 1) * .18px)) saturate(calc(1 - var(--depth, 1) * .03));
}
