:root.desk-behind .shell > :is(.bar, .chats-button, #messages, .onboarding, .composer, .safety, .colophon, .tree:not(.window), .browser-dock:not(.window), .split-dock, dialog.surface.split) {
  filter: blur(calc(var(--desk-depth, 1) * .4px)) saturate(calc(1 - var(--desk-depth, 1) * .06)) brightness(calc(1 - var(--desk-depth, 1) * .03));
  transition: filter calc(380ms * var(--motion-scale)) var(--ease-glide);
}
@media (prefers-reduced-motion: reduce) {
