}
:root[data-scheme="light"] {
  --wp-jarrito: linear-gradient(rgb(252 250 246 / min(.96, calc(.62 * var(--veil-k, 1)))), rgb(252 250 246 / min(.97, calc(.72 * var(--veil-k, 1))))), url("/assets/wallpapers/jarrito.webp?v=3") 50% 50% / cover no-repeat, #f6f2ea;
  --wp-canela: linear-gradient(rgb(252 248 244 / min(.96, calc(.52 * var(--veil-k, 1)))), rgb(252 248 244 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/canela.webp?v=3") 50% 50% / cover no-repeat, #f6f0ea;
  --wp-paradise: linear-gradient(rgb(246 250 255 / min(.96, calc(.5 * var(--veil-k, 1)))), rgb(246 250 255 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/paraiso.webp?v=3") 50% 55% / cover no-repeat, #eef4fa;
  --wp-ventura: linear-gradient(rgb(245 246 247 / min(.96, calc(.52 * var(--veil-k, 1)))), rgb(245 246 247 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/ventura.webp?v=4") 50% 50% / cover no-repeat, #eef0f1;
