}
:root[data-wallpaper] .shell::before { content: ''; position: fixed; inset: 0; z-index: -1; pointer-events: none; transition: filter calc(380ms * var(--motion-scale)) var(--ease-glide); }
:root[data-wallpaper="jarrito"] .shell::before { background: var(--wp-jarrito); }
:root[data-wallpaper="canela"] .shell::before { background: var(--wp-canela); }
:root[data-wallpaper="paradise"] .shell::before { background: var(--wp-paradise); }
