/* ---------- Glass: the bevel of a drop of water ----------
   Windows, the bar and the plates the room's lines stand on are glass now. Their edge is not a
   line drawn around them but the glass itself turning: light caught along the top, a shadow
   settling along the bottom, the sides lit faintly, and the faintest split of colour at the rim
   (rose on one side, cyan on the other) the way a curved edge bends light. Over the face, a
   diffraction sheen at a slant, a breath of white and of blue. Every part is a few percent:
   felt as material, never read as decoration, and never in the way of the words. */
:root {
  --bevel:
    inset 0 1px 0 rgba(255, 255, 255, .13),
    inset 0 -1px 0 rgba(0, 0, 0, .42),
    inset 1px 0 0 rgba(255, 255, 255, .05),
    inset -1px 0 0 rgba(255, 255, 255, .03),
    inset 0 14px 22px -16px rgba(255, 255, 255, .09),
    inset 0 -16px 24px -18px rgba(0, 0, 0, .4),
    inset .8px 0 0 rgba(255, 92, 170, .07),
    inset -.8px 0 0 rgba(90, 210, 255, .07);
  --sheen: linear-gradient(118deg, rgba(255, 255, 255, .06) 0%, transparent 26%, transparent 70%, rgba(140, 210, 255, .035) 100%);
  --glass-rim: color-mix(in srgb, #ffffff 7%, transparent);
  --plate: color-mix(in srgb, var(--bg) 64%, transparent);
}
:root[data-scheme="light"] {
  --bevel:
    inset 0 1px 0 rgba(255, 255, 255, .95),
    inset 0 -1px 0 rgba(20, 30, 20, .08),
    inset 1px 0 0 rgba(255, 255, 255, .6),
    inset -1px 0 0 rgba(255, 255, 255, .4),
    inset 0 14px 22px -16px rgba(255, 255, 255, .7),
    inset 0 -16px 24px -18px rgba(20, 30, 20, .07),
    inset .8px 0 0 rgba(255, 92, 170, .08),
    inset -.8px 0 0 rgba(60, 170, 230, .08);
  --sheen: linear-gradient(118deg, rgba(255, 255, 255, .55) 0%, transparent 28%, transparent 70%, rgba(150, 200, 255, .12) 100%);
  --glass-rim: rgba(255, 255, 255, .7);
  --plate: color-mix(in srgb, #ffffff 70%, transparent);
}

/* Windows: the rim is the glass, not a stroke around it. */
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window) {
  border-color: var(--glass-rim); border-radius: 18px;
  background-image: var(--sheen);
  box-shadow: var(--bevel), 0 1px 2px rgba(0, 0, 0, .3), 0 10px 24px -10px rgba(0, 0, 0, .45), 0 30px 70px -30px rgba(0, 0, 0, .6);
}
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).front {
  box-shadow: var(--bevel), 0 2px 3px rgba(0, 0, 0, .32), 0 16px 34px -12px rgba(0, 0, 0, .55), 0 48px 110px -36px rgba(0, 0, 0, .75);
}
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).lifted {
  box-shadow: var(--bevel), 0 0 0 1px color-mix(in srgb, var(--phosphor) 20%, transparent), 0 4px 6px rgba(0, 0, 0, .3), 0 24px 48px -14px rgba(0, 0, 0, .6), 0 70px 140px -40px rgba(0, 0, 0, .8);
}
:root[data-scheme="light"] :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window) {
  box-shadow: var(--bevel), 0 1px 2px rgba(20, 30, 20, .08), 0 10px 24px -12px rgba(20, 30, 20, .2), 0 30px 70px -32px rgba(20, 30, 20, .3);
}
:root[data-scheme="light"] :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).front {
  box-shadow: var(--bevel), 0 2px 3px rgba(20, 30, 20, .1), 0 16px 34px -14px rgba(20, 30, 20, .26), 0 48px 110px -40px rgba(20, 30, 20, .38);
}
:root[data-scheme="light"] :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).lifted {
  box-shadow: var(--bevel), 0 0 0 1px color-mix(in srgb, var(--phosphor) 26%, transparent), 0 4px 6px rgba(20, 30, 20, .12), 0 24px 48px -16px rgba(20, 30, 20, .3), 0 70px 140px -44px rgba(20, 30, 20, .42);
}

/* The bar: the same glass, rounder, with the same turned edge. */
.shell > .bar {
  border-color: var(--glass-rim); border-radius: 20px;
  background-image: var(--sheen);
  box-shadow: var(--bevel), 0 1px 2px rgba(0, 0, 0, .2), 0 12px 32px -18px rgba(0, 0, 0, .6);
}
:root[data-scheme="light"] .shell > .bar { box-shadow: var(--bevel), 0 1px 2px rgba(20, 30, 20, .06), 0 12px 32px -18px rgba(20, 30, 20, .28); }

/* ---------- Reading over a wallpaper ----------
   With a wallpaper behind it, everything the room writes straight on the ground stands on a
   plate of frosted glass: the lines of the room, who answered and what it cost, the memory a
   reply used, the card where an agent asks for a mode, and the chips of the box you write in.
   The plates are the room's own ground, mostly opaque and blurred behind, with the glass edge;
   the small grey labels are lifted one step so they read on any photograph. */
:root[data-wallpaper] #messages .system:not(.mother-alert) {
  width: fit-content; max-width: min(92%, 64ch); padding: 10px 18px; border-radius: 16px;
  background: var(--plate);
  -webkit-backdrop-filter: blur(16px) saturate(1.35); backdrop-filter: blur(16px) saturate(1.35);
  box-shadow: var(--bevel), 0 6px 18px -12px rgba(0, 0, 0, .45);
}
/* The plates lift the grey one step through variables, so a line with a colour of its own (an
   alert's red, a warning's amber) keeps it. */
:root[data-wallpaper] #messages { --sys-ink: var(--text-2); --sys-head: var(--text-2); }
:root[data-wallpaper] #messages :is(.who, .stamp, .memory-hint .lead) {
  width: fit-content; max-width: 100%; padding: 3px 10px; border-radius: 999px;
  background: var(--plate);
  -webkit-backdrop-filter: blur(12px) saturate(1.3); backdrop-filter: blur(12px) saturate(1.3);
  box-shadow: var(--bevel);
}
:root[data-wallpaper] #messages :is(.stamp, .who .reply, .who .spent, .memory-hint .lead, .memory-hint .more) { color: var(--text-2); }
:root[data-wallpaper] #messages .memory-hint .pill {
  background: color-mix(in srgb, var(--bg) 72%, transparent);
  -webkit-backdrop-filter: blur(12px) saturate(1.3); backdrop-filter: blur(12px) saturate(1.3);
  box-shadow: var(--bevel); color: var(--text);
}
:root[data-wallpaper] #messages :is(.mode-ask, .command-card) {
  background: color-mix(in srgb, var(--panel) 80%, transparent);
  -webkit-backdrop-filter: blur(18px) saturate(1.35); backdrop-filter: blur(18px) saturate(1.35);
  box-shadow: var(--bevel), 0 10px 26px -16px rgba(0, 0, 0, .5);
}
:root[data-wallpaper] .picker :is(.mode-chip, .model-chip, .effort-chip) {
  background: var(--plate);
  -webkit-backdrop-filter: blur(12px) saturate(1.3); backdrop-filter: blur(12px) saturate(1.3);
  box-shadow: var(--bevel);
}
:root[data-wallpaper] .picker :is(.model-chip, .effort-chip) { color: var(--text); }
:root[data-wallpaper] .picker .pick-label { text-shadow: 0 1px 2px color-mix(in srgb, var(--bg) 80%, transparent); }

/* ---------- Chips you can read ----------
   The small pills the room writes in — who answered and in which mode, ASH, the model, what a reply
   cost, the label after the crew's spheres, the brake in an alert — were 9 to 10 px of grey on a
   hairline. Each is a chip now: a step larger, a step darker in light and lighter in dark, a fill
   of its own colour behind the word so the border is not the only thing carrying it, and on a
   light ground a mode's bright colour deepened until it reads. */
.who { font-size: 10.5px; }
.who .badge { color: var(--text-2); border-color: color-mix(in srgb, var(--text) 20%, transparent); background: color-mix(in srgb, var(--text) 5%, transparent); padding: 2px 8px; font-weight: 500; }
.who .badge:is(.mode, .ash, .model, .lease) { background: color-mix(in srgb, currentColor 11%, transparent); border-color: color-mix(in srgb, currentColor 48%, transparent); }
.who :is(.reply, .spent) { color: var(--text-2); }
:root[data-scheme="light"] .who .badge.mode.m2, :root[data-scheme="light"] .picker .mode-chip { color: color-mix(in srgb, var(--mode) 68%, #000000); }
:root[data-scheme="light"] .who .badge.mode.m2 { color: color-mix(in srgb, var(--mode-2) 62%, #000000); }
:root[data-scheme="light"] .who .badge.mode.m0 { color: color-mix(in srgb, var(--mode-0) 60%, #000000); }
:root[data-scheme="light"] .who .badge.mode.m4 { color: color-mix(in srgb, var(--mode-4) 55%, #000000); }
/* Over a wallpaper the chips inside the row's plate take more ground of their own. */
:root[data-wallpaper] #messages .who .badge { background: color-mix(in srgb, var(--bg) 55%, color-mix(in srgb, currentColor 14%, transparent)); }

/* The label after the crew's spheres: PARA @AGENTE and what that agent can do. */
.picker .pick-label { font-size: 11.5px; }
.pick-label .pick-note { font-size: 10.5px; letter-spacing: .1em; color: var(--text-2); }
:root[data-wallpaper] .picker .pick-label { text-shadow: 0 0 2px var(--bg), 0 0 6px var(--bg), 0 0 12px color-mix(in srgb, var(--bg) 70%, transparent); }
:root[data-wallpaper] .picker .pick-label :is(.mode-chip, .model-chip, .effort-chip) { text-shadow: none; }

/* PARAR TODO, inside an alert: a button, red on a red-tinted fill, deepened on a light ground. */
.system.alert .cmd { font: inherit; font-weight: 700; color: var(--terror); background: color-mix(in srgb, var(--terror) 12%, transparent); border: 1px solid color-mix(in srgb, var(--terror) 70%, transparent); border-radius: 8px; padding: 3px 12px; cursor: pointer; text-transform: uppercase; transition: background var(--motion-fast) var(--ease-out); }
.system.alert .cmd:hover:not(:disabled) { background: color-mix(in srgb, var(--terror) 22%, transparent); }
.system.alert .cmd:focus-visible { outline: 2px solid var(--terror); outline-offset: 2px; }
.system.alert .cmd:disabled { opacity: .5; cursor: default; }
:root[data-scheme="light"] .system.alert, :root[data-scheme="light"] .system.alert b, :root[data-scheme="light"] .system.alert .cmd { color: #c01a12; }

/* The bar's edge, thinner: no drawn border, a half-pixel hairline and a half-pixel of light. */
.shell > .bar {
  border-width: 0;
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 12%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .14), inset 0 -.5px 0 rgba(0, 0, 0, .3), inset .5px 0 0 rgba(255, 92, 170, .06), inset -.5px 0 0 rgba(90, 210, 255, .06), 0 1px 2px rgba(0, 0, 0, .18), 0 12px 32px -18px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] .shell > .bar {
  box-shadow: 0 0 0 .5px rgba(20, 30, 20, .1), inset 0 1px 0 rgba(255, 255, 255, .85), inset .5px 0 0 rgba(255, 92, 170, .06), inset -.5px 0 0 rgba(60, 170, 230, .06), 0 1px 2px rgba(20, 30, 20, .05), 0 12px 32px -20px rgba(20, 30, 20, .22);
}

/* ---------- The reply's foot ----------
   What a reply recalled and what it cost travel inside it: the memory as dots and a count on the
   left, the bill on the right, under a hairline of the bubble's own ink. The notes open below the
   foot when the count is pressed. */
.bubble-foot { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 16px; margin-top: 10px; padding-top: 8px; border-top: 1px solid color-mix(in srgb, currentColor 12%, transparent); }
.bubble-foot .stamp { margin: 0 0 0 auto; gap: 0; flex-wrap: wrap; font-size: 10px; color: var(--text-2); letter-spacing: .05em; text-transform: uppercase; }
.bubble-foot .stamp > span + span::before { content: '·'; margin: 0 7px; opacity: .55; }
.bubble-foot .stamp .uncharged { color: var(--brew); }
.mem-used { display: inline-flex; align-items: center; gap: 7px; padding: 0; border: 0; background: none; cursor: pointer; font-family: var(--mono); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--text-2); transition: color var(--motion-fast, .12s) ease; }
.mem-used:hover, .mem-used[aria-expanded="true"] { color: var(--text); }
.mem-used:focus-visible { outline: 2px solid var(--agent, var(--phosphor)); outline-offset: 3px; border-radius: 4px; }
.mem-used .dots { display: inline-flex; gap: 3px; }
.mem-used .dots i { width: 7px; height: 7px; border-radius: 50%; background: var(--kind); box-shadow: 0 0 0 1px color-mix(in srgb, var(--text-3) 40%, transparent); }
.mem-used .dots i.carried { background: transparent; box-shadow: inset 0 0 0 1.6px var(--kind), 0 0 0 1px color-mix(in srgb, var(--text-3) 40%, transparent); }
.mem-used .chev { font-size: 9px; transition: transform calc(180ms * var(--motion-scale)) ease; }
.mem-used[aria-expanded="true"] .chev { transform: rotate(180deg); }
.bubble .memory-hint.used { margin: 8px 0 0; }
.bubble .memory-hint.used[hidden] { display: none; }
.bubble-actions { margin-bottom: -4px; }

/* ---------- The wallpaper's tint ----------
   Each wallpaper lends the reply a veil of its own colour, and lends the words written straight
   on it an atmosphere of the same colour: a wide, soft cloud instead of a plate. */
:is(:root, .look-preview)[data-wallpaper="jarrito"] { --tint: #16132a; }
:is(:root, .look-preview)[data-wallpaper="canela"] { --tint: #1f1712; }
:is(:root, .look-preview)[data-wallpaper="paradise"] { --tint: #13283d; }
:is(:root, .look-preview)[data-wallpaper="ventura"] { --tint: #14191c; }
:is(:root, .look-preview)[data-wallpaper="magna"] { --tint: #221614; }
:is(:root, .look-preview)[data-scheme="light"][data-wallpaper="jarrito"] { --tint: #f6f2fb; }
:is(:root, .look-preview)[data-scheme="light"][data-wallpaper="canela"] { --tint: #f8f0e8; }
:is(:root, .look-preview)[data-scheme="light"][data-wallpaper="paradise"] { --tint: #e6f0fb; }
:is(:root, .look-preview)[data-scheme="light"][data-wallpaper="ventura"] { --tint: #f3f4f5; }
:is(:root, .look-preview)[data-scheme="light"][data-wallpaper="magna"] { --tint: #f7f4f3; }

:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble {
  background: color-mix(in srgb, var(--tint) 90%, transparent);
  -webkit-backdrop-filter: blur(16px) saturate(1.3); backdrop-filter: blur(16px) saturate(1.3);
  box-shadow: var(--bevel), var(--lift-1);
}
:root[data-wallpaper] #messages {
  --atmos: 0 0 3px color-mix(in srgb, var(--tint) 85%, transparent), 0 0 18px color-mix(in srgb, var(--tint) 75%, transparent), 0 0 36px color-mix(in srgb, var(--tint) 50%, transparent), 0 0 60px color-mix(in srgb, var(--tint) 40%, transparent);
}
/* The plates come off: the room's lines, who answered, a user's delivery line and the lead of a
   saved memory stand on the atmosphere. Anything with a fill of its own keeps it, without a glow. */
:root[data-wallpaper] #messages .system:not(.mother-alert),
:root[data-wallpaper] #messages :is(.who, .col > .stamp, .col > .memory-hint .lead) {
  background: none; -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: none;
  text-shadow: var(--atmos);
}
:root[data-wallpaper] #messages :is(.system, .who) :is(button, .badge, .chip, code) { text-shadow: none; }
/* Inside the reply the bill needs no plate: the bubble is its ground. */
:root[data-wallpaper] #messages .bubble-foot .stamp { width: auto; padding: 0; border-radius: 0; background: none; -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: none; }

/* ---------- Who answered, on one line ----------
   The chips never break inside themselves: the agent, the model, the mode and ASH keep their
   width, and what gives way is the quoted question, which ends in an ellipsis. Over a wallpaper
   each chip is a small piece of the same glass. */
.who { align-items: center; }
.who > :not(.reply) { flex: none; white-space: nowrap; }
.who .reply { flex: 0 1 auto; min-width: 0; max-width: none; }
:root[data-wallpaper] #messages .who .badge {
  border: 0;
  background: color-mix(in srgb, currentColor 9%, transparent);
  -webkit-backdrop-filter: blur(14px) saturate(1.8); backdrop-filter: blur(14px) saturate(1.8);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 45%, transparent), inset 1px 0 1px -.5px rgba(255, 70, 160, .35), inset -1px 0 1px -.5px rgba(60, 200, 255, .35);
}
:root[data-scheme="light"][data-wallpaper] #messages .who .badge:not(.mode):not(.ash) { color: var(--text); }

/* ---------- Buttons in the room's lines, as clear glass ----------
   INSTALL, PARAR TODO, the lease and escalation answers, the local model's choices: no shine and no
   milk. A clear pane of the button's own colour, the room behind it blurred and saturated, a rim
   of the same colour, and at the edges the faint split of light a lens makes: pink on the left,
   cyan on the right. It rises a hair under the pointer and gives under the press. */
#messages .system :is(.claim-act, .cmd), #messages .system:is(.lease, .escalation, .local-model) button {
  --glass-fill: 7%; --glass-rim: 42%;
  border: 0; border-radius: 999px;
  background: color-mix(in srgb, currentColor var(--glass-fill), transparent);
  -webkit-backdrop-filter: blur(18px) saturate(1.8); backdrop-filter: blur(18px) saturate(1.8);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, currentColor var(--glass-rim), transparent),
    inset 1.5px 0 1px -.5px rgba(255, 70, 160, .42),
    inset -1.5px 0 1px -.5px rgba(60, 200, 255, .42),
    0 6px 18px -10px rgba(0, 0, 0, .4);
  text-shadow: none; filter: none;
  transition: background-color var(--motion-fast) var(--ease-out), box-shadow var(--motion-fast) var(--ease-out), transform var(--motion-fast) var(--ease-out);
}
#messages .system :is(.claim-act, .cmd):hover:not(:disabled), #messages .system:is(.lease, .escalation, .local-model) button:hover:not(:disabled) {
  --glass-fill: 13%; --glass-rim: 64%;
  transform: translateY(-1px); filter: none;
}
#messages .system :is(.claim-act, .cmd):active:not(:disabled), #messages .system:is(.lease, .escalation, .local-model) button:active:not(:disabled) { transform: scale(.97); }
:root[data-scheme="light"] #messages .system :is(.claim-act, .cmd), :root[data-scheme="light"] #messages .system:is(.lease, .escalation, .local-model) button {
  --glass-fill: 9%; --glass-rim: 55%;
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, currentColor var(--glass-rim), transparent),
    inset 1.5px 0 1px -.5px rgba(255, 50, 150, .38),
    inset -1.5px 0 1px -.5px rgba(30, 170, 240, .38),
    0 6px 18px -12px rgba(20, 30, 20, .3);
}
:root[data-scheme="light"] #messages .system :is(.claim-act, .cmd):hover:not(:disabled), :root[data-scheme="light"] #messages .system:is(.lease, .escalation, .local-model) button:hover:not(:disabled) { --glass-fill: 15%; --glass-rim: 75%; }
/* On a light ground the buttons' colours are taken down until the word reads on the glass. */
:root[data-scheme="light"] #messages .system:is(.claim, .local-model) button { color: color-mix(in srgb, var(--phosphor) 60%, #000000); }

/* ---------- Decided here, in order ----------
   The heading on its own line, the decisions under it in even columns that fill the width, each
   one a card of the same height, so three never land as two and a stray. */
.settled { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 280px), 1fr)); gap: 8px; align-items: stretch; }
.settled-lead { grid-column: 1 / -1; margin-bottom: 2px; }
.settled-note { width: 100%; max-width: none; min-width: 0; padding: 7px 12px 7px 10px; border-radius: 12px; }
:root[data-wallpaper] #messages .settled { border-bottom-color: color-mix(in srgb, var(--text) 14%, transparent); }
:root[data-wallpaper] #messages .settled-lead { color: var(--text-2); text-shadow: var(--atmos); }
:root[data-wallpaper] #messages .settled-note {
  border: 0; color: var(--text);
  background: color-mix(in srgb, var(--tint) 82%, transparent);
  -webkit-backdrop-filter: blur(14px) saturate(1.3); backdrop-filter: blur(14px) saturate(1.3);
  box-shadow: var(--bevel), 0 6px 16px -12px rgba(0, 0, 0, .5);
}
:root[data-wallpaper] #messages .settled-note:hover { background: color-mix(in srgb, var(--tint) 94%, transparent); }

/* ---------- The conversations' handle, as the bar ----------
   The same glass as the bar, with its half-pixel edge, and it can be carried: held a moment it
   lifts (larger, a deeper shadow), and then it follows the pointer. */
:root .shell > .chats-button {
  width: 42px; height: 40px; border: 0; border-radius: 14px;
  color: var(--text-2);
  background-color: color-mix(in srgb, var(--bg) 58%, transparent);
  background-image: var(--sheen);
  -webkit-backdrop-filter: blur(22px) saturate(1.7); backdrop-filter: blur(22px) saturate(1.7);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 12%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .14), inset 0 -.5px 0 rgba(0, 0, 0, .3), inset .5px 0 0 rgba(255, 92, 170, .06), inset -.5px 0 0 rgba(90, 210, 255, .06), 0 1px 2px rgba(0, 0, 0, .18), 0 12px 32px -18px rgba(0, 0, 0, .55);
  touch-action: none; user-select: none; -webkit-user-select: none;
  transition: color var(--motion) var(--ease-out), background-color var(--motion) var(--ease-out), box-shadow var(--motion) var(--ease-out), scale var(--motion-fast) var(--ease-out);
}
:root[data-wallpaper] .shell > .chats-button { background-color: color-mix(in srgb, var(--bg) 70%, transparent); }
:root[data-scheme="light"] .shell > .chats-button {
  background-color: color-mix(in srgb, #ffffff 62%, transparent);
  box-shadow: 0 0 0 .5px rgba(20, 30, 20, .1), inset 0 1px 0 rgba(255, 255, 255, .85), inset .5px 0 0 rgba(255, 92, 170, .06), inset -.5px 0 0 rgba(60, 170, 230, .06), 0 1px 2px rgba(20, 30, 20, .05), 0 12px 32px -20px rgba(20, 30, 20, .22);
}
:root[data-scheme="light"][data-wallpaper] .shell > .chats-button { background-color: color-mix(in srgb, #ffffff 72%, transparent); }
:root .shell > .chats-button:hover { color: var(--text); border-color: transparent; box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 22%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .2), inset 0 -.5px 0 rgba(0, 0, 0, .3), 0 2px 4px rgba(0, 0, 0, .2), 0 14px 34px -18px rgba(0, 0, 0, .6); }
:root[data-scheme="light"] .shell > .chats-button:hover { box-shadow: 0 0 0 .5px rgba(20, 30, 20, .18), inset 0 1px 0 rgba(255, 255, 255, .9), 0 2px 4px rgba(20, 30, 20, .07), 0 14px 34px -20px rgba(20, 30, 20, .3); }
:root .shell > .chats-button.carrying { scale: 1.08; cursor: grabbing; box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 22%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .2), 0 4px 8px rgba(0, 0, 0, .25), 0 24px 48px -16px rgba(0, 0, 0, .6); }
:root[data-scheme="light"] .shell > .chats-button.carrying { box-shadow: 0 0 0 .5px rgba(20, 30, 20, .18), inset 0 1px 0 rgba(255, 255, 255, .9), 0 4px 8px rgba(20, 30, 20, .1), 0 24px 48px -16px rgba(20, 30, 20, .32); }
:root .shell > .chats-button { --knock: var(--bg); }
:root[data-scheme="light"] .shell > .chats-button { --knock: #ffffff; }
@media (prefers-reduced-motion: reduce) { :root .shell > .chats-button.carrying { scale: 1; } }

/* ---------- Contrast over a wallpaper, light theme ----------
   On a light wallpaper the photograph sits in the middle greys, where the room's grey ink had
   nowhere to stand. The lines written straight on it take the room's dark ink instead, the quoted
   question and the bill under a message too; the atmosphere stays the same. */
:root[data-scheme="light"][data-wallpaper] #messages { --sys-ink: color-mix(in srgb, var(--text) 84%, transparent); --sys-head: var(--text); }
:root[data-scheme="light"][data-wallpaper] #messages :is(.who .reply, .who .spent, .col > .stamp, .settled-lead) { color: color-mix(in srgb, var(--text) 80%, transparent); }
:root[data-scheme="dark"][data-wallpaper] #messages { --sys-ink: color-mix(in srgb, var(--text) 78%, transparent); --sys-head: color-mix(in srgb, var(--text) 88%, transparent); }
/* A step's mode in a plan (#2) was the mode's bright colour on grey: taken down on light. */
:root[data-scheme="light"] .system.plan .step-mode.m1 { color: color-mix(in srgb, var(--mode-1) 62%, #000000); }
:root[data-scheme="light"] .system.plan .step-mode.m2 { color: color-mix(in srgb, var(--mode-2) 62%, #000000); }

/* ---------- The crew's spheres over a wallpaper ----------
   A tint of the agent over a photograph is the photograph. Each sphere stands on a disc of glass
   first, the room's ground blurred behind it, and the agent's colour goes on top. */
:root[data-wallpaper] :is(#messages, .picker) .avatar:not(.gradient):not(.offline):not(.detected) {
  background: color-mix(in srgb, var(--agent) 20%, color-mix(in srgb, var(--bg) 78%, transparent));
  -webkit-backdrop-filter: blur(12px) saturate(1.5); backdrop-filter: blur(12px) saturate(1.5);
}
:root[data-wallpaper] :is(#messages, .picker) .avatar:not(.gradient):not(.offline):not(.detected):not(.pick[aria-checked="true"]) { box-shadow: inset 0 0 0 1.5px var(--agent-ink, color-mix(in srgb, var(--agent) 70%, transparent)), 0 4px 12px -8px rgba(0, 0, 0, .5); }
:root[data-scheme="light"][data-wallpaper] :is(#messages, .picker) .avatar:not(.gradient):not(.offline):not(.detected) {
  background: color-mix(in srgb, var(--agent) 18%, rgba(255, 255, 255, .82));
}
:root[data-wallpaper] .picker .pick[aria-checked="true"] { background: color-mix(in srgb, var(--agent) 30%, color-mix(in srgb, var(--bg) 78%, transparent)); }
:root[data-scheme="light"][data-wallpaper] .picker .pick[aria-checked="true"] { background: color-mix(in srgb, var(--agent) 28%, rgba(255, 255, 255, .82)); }

/* ---------- An open question's mark ----------
   The «?» is one of the room's own drawings now, in the accent. */
.openq-ask::before { content: none; }
.openq-ask .q-mark { position: absolute; left: 9px; top: 50%; transform: translateY(-50%); width: var(--ico-sm); height: var(--ico-sm); display: block; color: var(--phosphor); }
.openq-ask .q-mark svg { width: 100%; height: 100%; display: block; }
:root[data-scheme="light"] .openq-ask .q-mark { color: color-mix(in srgb, var(--phosphor) 62%, #000000); }

/* ---------- The conversations' handle takes the accent ----------
   Like the bar's buttons: under the pointer, and while it is carried, the drawing and the edge go
   to the accent. */
:root .shell > .chats-button:is(:hover, .carrying) { color: var(--phosphor); }
:root .shell > .chats-button:hover { box-shadow: 0 0 0 1px color-mix(in srgb, var(--phosphor) 55%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .14), 0 2px 4px rgba(0, 0, 0, .2), 0 14px 34px -18px rgba(0, 0, 0, .6); }
:root .shell > .chats-button.carrying { box-shadow: 0 0 0 1px color-mix(in srgb, var(--phosphor) 70%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .14), 0 4px 8px rgba(0, 0, 0, .25), 0 24px 48px -16px rgba(0, 0, 0, .6); }
:root[data-scheme="light"] .shell > .chats-button:hover { box-shadow: 0 0 0 1px color-mix(in srgb, var(--phosphor) 45%, transparent), inset 0 1px 0 rgba(255, 255, 255, .9), 0 2px 4px rgba(20, 30, 20, .07), 0 14px 34px -20px rgba(20, 30, 20, .3); }
:root[data-scheme="light"] .shell > .chats-button.carrying { box-shadow: 0 0 0 1px color-mix(in srgb, var(--phosphor) 60%, transparent), inset 0 1px 0 rgba(255, 255, 255, .9), 0 4px 8px rgba(20, 30, 20, .1), 0 24px 48px -16px rgba(20, 30, 20, .32); }

/* ---------- The bar on a narrow window ----------
   MADRE keeps its whole name; what gives way is the conversation's title, which ends in an
   ellipsis and keeps the rest in its tooltip. The conversations keep their floating handle at
   every width: it is carried and opened on the canvas the same way. */
.bar .brand { flex: none; }
.bar > .bar-left { flex: 1 1 auto; }
.bar .project:not(.chat-here) { flex: none; }
.bar .project.chat-here { flex: 1 1 auto; min-width: 0; }
@container bar (max-width: 1040px) {
  .brand-logo { display: block; }
  .brand-icon { display: none; }
}
@container bar (max-width: 640px) {
  .chat-here { font-size: inherit; }
  .chat-here::after { content: none; }
}
@container bar (max-width: 520px) {
  .brand-logo { display: none; }
  .brand-icon { display: block; }
}
/* Very narrow: the project's folder steps out first, and the conversation's title stays and
   truncates. The bar keeps one line. */
@media (max-width: 680px) {
  .bar { flex-wrap: nowrap; }
  .bar .project.chat-here { display: block; }
}

/* ---------- The reply over a wallpaper: white, not tinted ----------
   The wallpaper's veil made the reply the colour of the ground it stood on, and on Autumn or Magna
   it sank into it. The reply is the room's own sheet now: near-white glass on light, the bubble's
   own dark on dark. The wallpaper's colour stays in the atmosphere around the words outside it. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble {
  background: color-mix(in srgb, var(--bubble) 92%, transparent);
}
:is(:root[data-scheme="light"][data-wallpaper] #messages, .look-preview[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble {
  background: rgba(255, 255, 255, .9);
  box-shadow: var(--bevel), 0 1px 2px rgba(20, 30, 20, .06), 0 10px 28px -14px rgba(20, 30, 20, .28);
}

/* The preview wears its own theme's glass, not the room's: a dark preview inside a light room took
   the light theme's bright inner edge and drew a hard white outline round the sample. */
.look-preview[data-scheme="dark"] {
  --bevel: inset 0 1px 0 rgba(255, 255, 255, .13), inset 0 -1px 0 rgba(0, 0, 0, .42), inset 1px 0 0 rgba(255, 255, 255, .05), inset -1px 0 0 rgba(255, 255, 255, .03), inset .8px 0 0 rgba(255, 92, 170, .07), inset -.8px 0 0 rgba(90, 210, 255, .07);
  --sheen: linear-gradient(118deg, rgba(255, 255, 255, .06) 0%, transparent 26%, transparent 70%, rgba(140, 210, 255, .035) 100%);
}
.look-preview[data-scheme="light"] {
  --bevel: inset 0 1px 0 rgba(255, 255, 255, .95), inset 0 -1px 0 rgba(20, 30, 20, .08), inset 1px 0 0 rgba(255, 255, 255, .6), inset -1px 0 0 rgba(255, 255, 255, .4), inset .8px 0 0 rgba(255, 92, 170, .08), inset -.8px 0 0 rgba(60, 170, 230, .08);
  --sheen: linear-gradient(118deg, rgba(255, 255, 255, .55) 0%, transparent 28%, transparent 70%, rgba(150, 200, 255, .12) 100%);
}
.look-preview .bubble { box-shadow: var(--bevel), 0 6px 18px -12px rgba(0, 0, 0, .45); }
.look-preview .assistant .bubble code { white-space: nowrap; }

/* ---------- The memories a reply used, in order ----------
   Under the foot, in even columns that fill the bubble's width (one on a narrow window), each note
   a full-width row. Everything inside the bubble is measured in its own type, so the sizes and the
   weight chosen in PERSONALIZE carry into the foot and the notes. */
.bubble .bubble-foot { font-size: 1em; }
.bubble-foot .stamp, .bubble-foot .mem-used { font-size: .68em; }
.bubble .memory-hint.used:not([hidden]) {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 15em), 1fr)); gap: .4em; align-items: center;
  margin: .6em 0 0; font-size: 1em;
}
.bubble .memory-hint.used .last { display: flex; align-items: center; gap: .4em; min-width: 0; }
.bubble .memory-hint.used .last .pill { flex: 1 1 auto; }
.bubble .memory-hint.used .pill { width: 100%; max-width: none; min-width: 0; font-size: .76em; padding: .45em .85em .45em .7em; border-radius: .9em; gap: .55em; }
.bubble .memory-hint.used .pill .dot { width: .6em; height: .6em; }
.bubble .memory-hint.used .more { flex: none; font-family: var(--mono); font-size: .66em; color: var(--text-2); padding: 0 .4em; }

/* ---------- The photographs, tuned ----------
   Paraíso, Ventura and Magna can wear the room's ground as a LAYER (a flat veil, the way they
   always did) or as a MESH of the photograph's own colours, pooled in three corners. --veil-k sets
   how strong either is (1 is the original), and --wp-blur how far the photograph softens. The
   blurred layer is drawn larger than the window so its edges never show. */
:is(:root:not([data-scheme="light"]), .look-preview[data-scheme="dark"])[data-wp-style="mesh"] {
  --wp-paradise: radial-gradient(75% 65% at 12% 8%, rgb(19 40 61 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(24 52 44 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(10 18 34 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(6 10 18 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(6 10 18 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/paraiso.webp?v=3") 50% 55% / cover no-repeat, #0a1220;
  --wp-ventura: radial-gradient(75% 65% at 12% 8%, rgb(23 33 41 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(27 41 56 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(26 25 22 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(9 11 13 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(9 11 13 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/ventura.webp?v=4") 50% 50% / cover no-repeat, #090b0d;
  --wp-magna: radial-gradient(75% 65% at 12% 8%, rgb(61 41 35 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(49 35 32 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(30 17 16 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(16 10 9 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(16 10 9 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/magna.webp?v=4") 50% 50% / cover no-repeat, #100a09;
}
:is(:root[data-scheme="light"], .look-preview[data-scheme="light"])[data-wp-style="mesh"] {
  --wp-paradise: radial-gradient(75% 65% at 12% 8%, rgb(230 240 251 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(226 242 232 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(244 248 253 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(246 250 255 / min(.9, calc(.42 * var(--veil-k, 1)))), rgb(246 250 255 / min(.9, calc(.42 * var(--veil-k, 1))))), url("/assets/wallpapers/paraiso.webp?v=3") 50% 55% / cover no-repeat, #eef4fa;
  --wp-ventura: radial-gradient(75% 65% at 12% 8%, rgb(237 240 243 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(238 243 248 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(238 238 237 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(245 246 247 / min(.9, calc(.42 * var(--veil-k, 1)))), rgb(245 246 247 / min(.9, calc(.42 * var(--veil-k, 1))))), url("/assets/wallpapers/ventura.webp?v=4") 50% 50% / cover no-repeat, #eef0f1;
  --wp-magna: radial-gradient(75% 65% at 12% 8%, rgb(250 243 241 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(246 241 240 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(240 235 235 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(248 245 245 / min(.9, calc(.42 * var(--veil-k, 1)))), rgb(248 245 245 / min(.9, calc(.42 * var(--veil-k, 1))))), url("/assets/wallpapers/magna.webp?v=4") 50% 50% / cover no-repeat, #f4efee;
}
:is(:root[data-wallpaper="paradise"], :root[data-wallpaper="ventura"], :root[data-wallpaper="magna"], .look-preview[data-wallpaper="paradise"], .look-preview[data-wallpaper="ventura"], .look-preview[data-wallpaper="magna"]) { --wp-blur-on: var(--wp-blur, 0px); }
:is(:root[data-wallpaper="paradise"], :root[data-wallpaper="ventura"], :root[data-wallpaper="magna"]) .shell::before { inset: calc(-2 * var(--wp-blur-on, 0px)); filter: blur(var(--wp-blur-on, 0px)); }
:root[data-wallpaper].desk-behind .shell::before { filter: blur(calc(var(--wp-blur-on, 0px) + var(--desk-depth, 1) * .4px)) saturate(calc(1 - var(--desk-depth, 1) * .06)) brightness(calc(1 - var(--desk-depth, 1) * .03)); }
:is(.look-preview[data-wallpaper="paradise"], .look-preview[data-wallpaper="ventura"], .look-preview[data-wallpaper="magna"]) { background: none !important; position: relative; isolation: isolate; overflow: hidden; }
:is(.look-preview[data-wallpaper="paradise"], .look-preview[data-wallpaper="ventura"], .look-preview[data-wallpaper="magna"])::before { content: ""; position: absolute; inset: calc(-2 * var(--wp-blur-on, 0px)); z-index: -1; filter: blur(var(--wp-blur-on, 0px)); pointer-events: none; }
.look-preview[data-wallpaper="paradise"]::before { background: var(--wp-paradise); }
.look-preview[data-wallpaper="ventura"]::before { background: var(--wp-ventura); }
.look-preview[data-wallpaper="magna"]::before { background: var(--wp-magna); }

/* The photograph's dials under the wallpapers: layer or mesh, then two sliders with their value. */
.paper-box { display: grid; gap: 12px; }
.paper-tune { display: grid; gap: 10px; padding: 12px; border: 1px solid var(--line-2); border-radius: 14px; background: color-mix(in srgb, var(--text) 3%, transparent); }
.tune-row { display: grid; grid-template-columns: minmax(84px, auto) minmax(0, 1fr) 48px; align-items: center; gap: 12px; font-family: var(--mono); font-size: 10px; letter-spacing: .14em; text-transform: uppercase; color: var(--text-2); }
.tune-value { text-align: right; color: var(--text); letter-spacing: .04em; }
.tune-range { -webkit-appearance: none; appearance: none; width: 100%; height: 18px; margin: 0; background: transparent; cursor: pointer; }
.tune-range::-webkit-slider-runnable-track { height: 4px; border-radius: 999px; background: linear-gradient(90deg, var(--phosphor) var(--fill, 50%), color-mix(in srgb, var(--text) 16%, transparent) var(--fill, 50%)); }
.tune-range::-moz-range-track { height: 4px; border-radius: 999px; background: color-mix(in srgb, var(--text) 16%, transparent); }
.tune-range::-moz-range-progress { height: 4px; border-radius: 999px; background: var(--phosphor); }
.tune-range::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; margin-top: -6px; border-radius: 50%; background: #ffffff; border: 0; box-shadow: 0 0 0 1px color-mix(in srgb, var(--text) 18%, transparent), 0 2px 6px rgba(0, 0, 0, .3); transition: transform var(--motion-fast) var(--ease-out); }
.tune-range::-moz-range-thumb { width: 16px; height: 16px; border-radius: 50%; background: #ffffff; border: 0; box-shadow: 0 0 0 1px color-mix(in srgb, var(--text) 18%, transparent), 0 2px 6px rgba(0, 0, 0, .3); }
.tune-range:active::-webkit-slider-thumb { transform: scale(1.12); }
.tune-range:focus-visible { outline: none; }
.tune-range:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 3px color-mix(in srgb, var(--phosphor) 45%, transparent), 0 2px 6px rgba(0, 0, 0, .3); }

/* ---------- Reading between the messages ----------
   Nothing written between the bubbles may be hard to read. Four things were working against it:
   the grey ink (text-3, about 3:1 on the plain ground and less on a photograph), the atmosphere's
   wide clouds (18 to 60px of the wallpaper's tint around each letter, which on a light photograph
   read as the text itself being blurred), chips whose colour was the glass's colour, and sizes that
   ignored what PERSONALIZE says about the text. */
#messages { --sys-ink: var(--text-2); --sys-head: var(--text-2); }
#messages :is(.user .who, .stamp, .who .reply, .who .spent, .memory-hint .lead, .settled-lead) { color: var(--text-2); }
/* Over a wallpaper the ink goes all the way, and the halo is a tight one: a hairline of the tint
   that keeps each letter off the photograph without spreading into a fog. */
:root[data-wallpaper] #messages {
  --sys-ink: color-mix(in srgb, var(--text) 88%, transparent); --sys-head: var(--text);
  --atmos: 0 0 1px var(--tint), 0 0 2px var(--tint), 0 0 5px color-mix(in srgb, var(--tint) 85%, transparent), 0 0 10px color-mix(in srgb, var(--tint) 45%, transparent);
}
:root[data-wallpaper] #messages :is(.system:not(.alert):not(.lease), .who, .col > .stamp, .who .reply, .who .spent, .col > .memory-hint .lead, .settled-lead) { font-weight: 500; }
:root[data-wallpaper] #messages :is(.user .who, .col > .stamp, .who .reply, .who .spent, .col > .memory-hint .lead, .settled-lead) { color: color-mix(in srgb, var(--text) 86%, transparent); }
/* The chips over a wallpaper: a ground of their own, nearly opaque, so the word is read against
   the chip and never against the photograph; the colours deepen on light. */
:root[data-wallpaper] #messages .who .badge { background: color-mix(in srgb, var(--bg) 78%, transparent); text-shadow: none; }
:root[data-scheme="light"][data-wallpaper] #messages .who .badge { background: rgba(255, 255, 255, .82); }
:root[data-scheme="light"] #messages .who .badge.ash:not(.skipped) { color: color-mix(in srgb, var(--phosphor) 62%, #000000); }
:root[data-scheme="light"] #messages .who .badge.model { color: color-mix(in srgb, var(--agent) 58%, #000000); }
:root[data-scheme="light"] #messages .who > span:first-child { color: color-mix(in srgb, var(--agent, var(--text-2)) 62%, #000000); }
/* The permission line (CREATE) is the warning's yellow, which on a light ground is not read. */
:root[data-scheme="light"] #messages .system.lease:not(.refused):not(.missing) { color: color-mix(in srgb, var(--warn) 55%, #000000); }
:root[data-scheme="light"] #messages .system.lease.missing { color: color-mix(in srgb, var(--warn) 55%, #000000); }
/* The names of agents inside the room's lines are their colour, taken down on light. */
:root[data-scheme="light"] #messages .system .who { color: color-mix(in srgb, var(--agent, var(--text-2)) 60%, #000000); }

/* What PERSONALIZE says about the text reaches the room's lines too: larger and smaller scale them
   with the bubbles, Visual gives them a heavier stroke. */
:root[data-text="larger"] #messages :is(.system, .who, .col > .stamp, .col > .memory-hint, .settled, .mode-ask) { zoom: 1.12; }
:root[data-text="smaller"] #messages :is(.system, .who, .col > .stamp, .col > .memory-hint, .settled, .mode-ask) { zoom: .92; }
:root[data-text="visual"] #messages :is(.system, .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead) { font-weight: 600; }
:root[data-text="visual"] #messages .system > b:first-child { font-weight: 700; }

/* PARAR TODO: the fill deepens under the pointer, nothing moves; once nothing is running it is
   history, and history cannot be pulled again. */
#messages .system.alert .cmd { transition: background-color var(--motion-fast) var(--ease-out), box-shadow var(--motion-fast) var(--ease-out); }
#messages .system.alert .cmd:hover:not(:disabled) { transform: none; background: color-mix(in srgb, currentColor 18%, transparent); }
#messages .system.alert .cmd:active:not(:disabled) { transform: none; background: color-mix(in srgb, currentColor 26%, transparent); }
#messages .system.alert .cmd:disabled { opacity: .45; cursor: default; box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 30%, transparent); background: transparent; }
/* The kinds of line that painted themselves in the faint grey take the room's line ink too, and so
   do their small notes. */
#messages .system:is(.memory, .recovered, .escalation.denied, .module-proposed, .local-model) { color: var(--sys-ink); }
#messages .system :is(.claim-note, .files .st, .stat, .clock, .note) { color: var(--sys-ink); }
#messages .system.local-model .note { font-size: 9.5px; }

/* ==========================================================================================
   LEGIBILITY OVER A WALLPAPER: the material, the way Apple does it
   ------------------------------------------------------------------------------------------
   Apple never writes text straight onto a photograph. Every label stands on a material — the
   content behind blurred and saturated under a tint of the system's own ground — and the label's
   colour is chosen for the material, not for whatever happens to be behind it (HIG, Materials:
   "use only vibrant colors on top of materials"; Liquid Glass: a clear surface "needs a dimming
   layer" to keep labels legible). A halo around each letter was the opposite: its contrast
   depended on the photograph, so every wallpaper, intensity and blur gave a different (and often
   unreadable) result.

   So: one REGULAR material for everything the room writes between the bubbles — the room's
   lines, who answered, the delivery line, a saved memory's lead, DECIDED HERE, the label beside
   the crew and the colophon. Thick enough that the text's contrast is the theme's own contrast
   whatever the wallpaper, its intensity or its blur; flat (no shadow, no shine) so it stays below
   the reply in the hierarchy. Labels follow the theme's hierarchy: primary ink for headings,
   secondary for the rest; never the faint tertiary on a material. Coloured words (an agent, an
   alert, a permission) are taken down on light so they hold 4.5:1 against the material.
   ========================================================================================== */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) {
  --atmos: none;
  --sys-ink: var(--text-2); --sys-head: var(--text);
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(
  .system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead
), :root[data-wallpaper] :is(.picker .pick-label, .openq-lead) {
  background: color-mix(in srgb, var(--bg) 62%, transparent);
  -webkit-backdrop-filter: blur(18px) saturate(1.6); backdrop-filter: blur(18px) saturate(1.6);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 9%, transparent);
  text-shadow: none; font-weight: 500;
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .system:not(.mother-alert) {
  width: fit-content; max-width: min(92%, 64ch); padding: 7px 14px; border-radius: 13px;
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.who, .col > .stamp, .col > .memory-hint .lead, .settled-lead),
:root[data-wallpaper] :is(.picker .pick-label, .openq-lead) {
  width: fit-content; max-width: 100%; padding: 2px 9px; border-radius: 999px;
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .user :is(.who, .col > .stamp) { margin-left: auto; }
/* Secondary labels on the material: the theme's second ink, whole. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.user .who, .col > .stamp, .who .reply, .who .spent, .col > .memory-hint .lead, .settled-lead, .system .note, .system .claim-note) { color: var(--text-2); }
:root[data-wallpaper] :is(.picker .pick-label, .openq-lead) { color: var(--text-2); text-shadow: none; }
/* No glass on glass: a chip on the material is a tint and a rim, not another pane. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .who .badge {
  background: color-mix(in srgb, currentColor 10%, transparent); border: 1px solid color-mix(in srgb, currentColor 42%, transparent);
  -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: none; text-shadow: none;
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .system :is(button, .badge, .chip, code) { text-shadow: none; }
/* DECIDED HERE: the cards are the same material, one step thicker. */
:root[data-wallpaper] #messages .settled-note {
  background: color-mix(in srgb, var(--bg) 68%, transparent); color: var(--text);
  -webkit-backdrop-filter: blur(18px) saturate(1.6); backdrop-filter: blur(18px) saturate(1.6);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 11%, transparent);
}
:root[data-wallpaper] #messages .settled-note:hover { background: color-mix(in srgb, var(--bg) 82%, transparent); }
/* Coloured lines on light hold their contrast against the material. */
:is(:root[data-scheme="light"] #messages, .look-preview[data-scheme="light"]) .system:is(.warn, .escalation, .lease, .lease.missing):not(.refused) { color: color-mix(in srgb, var(--warn) 55%, #000000); }
:is(:root[data-scheme="light"] #messages, .look-preview[data-scheme="light"]) .system.crit { color: color-mix(in srgb, var(--crit) 70%, #000000); }
:is(:root[data-scheme="light"] #messages, .look-preview[data-scheme="light"]) .system:is(.fail, .lease.refused) { color: color-mix(in srgb, var(--danger) 75%, #000000); }
:is(:root[data-scheme="light"] #messages, .look-preview[data-scheme="light"]) .system:is(.mother, .halted, .control, .alert) { color: #b3140d; }

/* The preview's small print, in the same order the room draws it. */
.look-preview .system { align-self: center; margin: 4px auto 2px; font-size: 9.5px; }
.look-preview .who { margin: 0 0 4px 0; font-size: 9.5px; gap: 6px; }
.look-preview .who .badge { padding: 1px 7px; }
.look-preview .user .stamp { justify-content: flex-end; margin: 4px 0 0; font-size: 9.5px; }
.look-preview .assistant .col { min-width: 0; }
.look-preview .who { flex-wrap: wrap; max-width: 100%; }
.look-preview[data-wallpaper]:not([data-wallpaper="default"]) .look-button {
  background: color-mix(in srgb, var(--phosphor) 12%, color-mix(in srgb, var(--bg) 62%, transparent));
  -webkit-backdrop-filter: blur(18px) saturate(1.6); backdrop-filter: blur(18px) saturate(1.6);
}
.look-preview[data-scheme="light"] .look-button { color: color-mix(in srgb, var(--phosphor) 60%, #000000); }

/* ---------- The choosers beside the crew, in one line ----------
   Mode, model and effort are words you press, not three capsules: each is its word in its colour
   and a drawn chevron that says it opens. Under the pointer, or while its menu is open, a soft
   ground of its own colour comes up behind it. */
.chev-icon { display: inline-block; flex: none; width: 15px; height: 15px; vertical-align: -3px; }
.chev-icon svg { display: block; width: 100%; height: 100%; }
:root[data-scheme] .picker :is(.mode-chip, .model-chip, .effort-chip) {
  display: inline-flex; align-items: center; gap: 5px; height: auto;
  margin-left: 6px; padding: 3px 6px 3px 7px; border: 0; border-radius: 8px;
  background: transparent; box-shadow: none; -webkit-backdrop-filter: none; backdrop-filter: none;
  font-size: 10.5px; line-height: 1.3; cursor: pointer;
  transition: background-color var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out);
}
:root[data-scheme] .picker :is(.mode-chip, .model-chip, .effort-chip):is(:hover, :focus-visible, [aria-expanded="true"]) { background: color-mix(in srgb, currentColor 11%, transparent); }
:root[data-scheme] .picker :is(.mode-chip, .model-chip, .effort-chip) .chev-icon { opacity: .9; transition: transform var(--motion-fast) var(--ease-out); }
:root[data-scheme] .picker :is(.mode-chip, .model-chip, .effort-chip):hover .chev-icon { transform: translateY(1px); }
:root[data-scheme] .picker .mode-chip { font-weight: 600; }
:root[data-scheme] .picker .mode-chip.pending { text-decoration: underline dashed; text-underline-offset: 3px; border: 0; }
:root[data-scheme] .picker .model-chip { color: var(--text); }
:root[data-scheme] .picker .effort-chip { color: var(--text-2); }
/* The memory a reply used opens with the same chevron. */
.mem-used .chev-icon { width: 14px; height: 14px; vertical-align: -3px; }

/* The colophon stands on its own line, no plate: the version and APOYAR in the brand green, with a
   hairline of the room's ground around the letters so the photograph never runs into them. */
:root[data-wallpaper] .colophon { opacity: 1; text-shadow: 0 0 1px var(--bg), 0 0 3px color-mix(in srgb, var(--bg) 85%, transparent), 0 1px 6px color-mix(in srgb, var(--bg) 60%, transparent); }

/* ---------- Nothing in the scrolling thread samples what is behind it ----------
   Every backdrop-filter is a layer of its own that the browser has to re-render from what lies
   behind it. A conversation holds hundreds of bubbles, chips and lines: scrolled fast, above all
   inside a window, the browser fell behind and drew them as empty grey blocks. Inside the thread
   the material is a flat tint instead, a little thicker to make up for the blur it gives up; the
   bar, the composer and the windows, which do not scroll, keep their glass. */
:is(#messages, .look-preview) :is(.bubble, .system, .who, .who .badge, .stamp, .memory-hint, .memory-hint .pill, .memory-hint .lead, .settled-note, .settled-lead, .avatar, button, .cmd, .claim-act, .mode-ask, .command-card) {
  -webkit-backdrop-filter: none !important; backdrop-filter: none !important;
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead) {
  background: color-mix(in srgb, var(--bg) 76%, transparent);
}
:root[data-wallpaper] #messages .settled-note { background: color-mix(in srgb, var(--bg) 84%, transparent); }
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble { background: color-mix(in srgb, var(--bubble) 96%, transparent); }
:is(:root[data-scheme="light"][data-wallpaper] #messages, .look-preview[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble { background: rgba(255, 255, 255, .95); }
:root[data-wallpaper] :is(#messages, .picker) .avatar:not(.gradient):not(.offline):not(.detected) { background: color-mix(in srgb, var(--agent) 20%, color-mix(in srgb, var(--bg) 88%, transparent)); }
:root[data-scheme="light"][data-wallpaper] :is(#messages, .picker) .avatar:not(.gradient):not(.offline):not(.detected) { background: color-mix(in srgb, var(--agent) 18%, rgba(255, 255, 255, .92)); }
:root[data-wallpaper] .picker .avatar { -webkit-backdrop-filter: none; backdrop-filter: none; }
#messages .system :is(.claim-act, .cmd), #messages .system:is(.lease, .escalation, .local-model) button { background: color-mix(in srgb, currentColor var(--glass-fill), color-mix(in srgb, var(--bg) 40%, transparent)); }

/* ---------- Carrying a window ----------
   While it is held, the window is one flat layer moved by the compositor: no glass re-sampling
   the room under it on every frame, and the browser is told in advance that it will move. */
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).lifted {
  will-change: translate; -webkit-backdrop-filter: none !important; backdrop-filter: none !important;
  background-color: color-mix(in srgb, var(--panel) 97%, transparent);
}
:root.carrying-window :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window):not(.lifted) { transition: none; }

/* Jarrito and Canela, the two pictures that took the drawn tiles' places, tuned like the others. */
:is(:root:not([data-scheme="light"]), .look-preview[data-scheme="dark"])[data-wp-style="mesh"] {
  --wp-jarrito: radial-gradient(75% 65% at 12% 8%, rgb(28 24 64 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(64 22 46 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(20 30 60 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(10 8 18 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(10 8 18 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/jarrito.webp?v=3") 50% 50% / cover no-repeat, #120e1c;
  --wp-canela: radial-gradient(75% 65% at 12% 8%, rgb(58 34 20 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(30 34 40 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(20 24 22 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(12 10 9 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(12 10 9 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/canela.webp?v=3") 50% 50% / cover no-repeat, #14100d;
}
:is(:root[data-scheme="light"], .look-preview[data-scheme="light"])[data-wp-style="mesh"] {
  --wp-jarrito: radial-gradient(75% 65% at 12% 8%, rgb(236 236 252 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(252 236 242 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(252 246 230 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(252 250 246 / min(.9, calc(.42 * var(--veil-k, 1)))), rgb(252 250 246 / min(.9, calc(.42 * var(--veil-k, 1))))), url("/assets/wallpapers/jarrito.webp?v=3") 50% 50% / cover no-repeat, #f6f2ea;
  --wp-canela: radial-gradient(75% 65% at 12% 8%, rgb(250 236 222 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(236 238 242 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(242 240 232 / min(.95, calc(.78 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(252 248 244 / min(.9, calc(.42 * var(--veil-k, 1)))), rgb(252 248 244 / min(.9, calc(.42 * var(--veil-k, 1))))), url("/assets/wallpapers/canela.webp?v=3") 50% 50% / cover no-repeat, #f6f0ea;
}
:is(:root[data-wallpaper="jarrito"], :root[data-wallpaper="canela"], .look-preview[data-wallpaper="jarrito"], .look-preview[data-wallpaper="canela"]) { --wp-blur-on: var(--wp-blur, 0px); }
:is(:root[data-wallpaper="jarrito"], :root[data-wallpaper="canela"]) .shell::before { inset: calc(-2 * var(--wp-blur-on, 0px)); filter: blur(var(--wp-blur-on, 0px)); }
:is(.look-preview[data-wallpaper="jarrito"], .look-preview[data-wallpaper="canela"]) { background: none !important; position: relative; isolation: isolate; overflow: hidden; }
:is(.look-preview[data-wallpaper="jarrito"], .look-preview[data-wallpaper="canela"])::before { content: ""; position: absolute; inset: calc(-2 * var(--wp-blur-on, 0px)); z-index: -1; filter: blur(var(--wp-blur-on, 0px)); pointer-events: none; }
.look-preview[data-wallpaper="jarrito"]::before { background: var(--wp-jarrito); }
.look-preview[data-wallpaper="canela"]::before { background: var(--wp-canela); }
:root[data-wallpaper].desk-behind .shell::before { filter: blur(calc(var(--wp-blur-on, 0px) + var(--desk-depth, 1) * .4px)) saturate(calc(1 - var(--desk-depth, 1) * .06)) brightness(calc(1 - var(--desk-depth, 1) * .03)); }

/* ---------- RELOAD, with grace ----------
   Going: the room eases back and softens, a curtain of its own ground rises over it, and the
   logo draws itself in the middle as it does at start — the pulse, the dot, then the name.
   Arriving: the same curtain is there before the first frame, the logo complete; when the room is
   ready the logo glides and shrinks into its place in the bar while the curtain clears. */
.reload-curtain {
  position: fixed; inset: 0; z-index: 2147483000; display: grid; place-items: center; pointer-events: all;
  /* Shown as a popover (2026-10-10), so it stands in the top layer over any open window and its
     blurred backdrop: the loader is never under a blur. What a popover brings by default is undone. */
  width: 100%; height: 100%; max-width: none; max-height: none; margin: 0; padding: 0; border: 0; overflow: hidden; color: var(--text);
  background-color: color-mix(in srgb, var(--bg) 90%, transparent);
  -webkit-backdrop-filter: blur(26px) saturate(1.3); backdrop-filter: blur(26px) saturate(1.3);
  animation: curtain-in calc(560ms * var(--motion-scale)) var(--ease-glide) both;
}
.reload-curtain.arrived { animation: none; }
@keyframes curtain-in { from { background-color: transparent; -webkit-backdrop-filter: blur(0) saturate(1); backdrop-filter: blur(0) saturate(1); } }
@keyframes curtain-logo-in { from { opacity: 0; filter: blur(4px); } }
@keyframes dot-run { from { transform: translateX(-59px); } to { transform: none; } }
/* Arriving: the pulse already traced, the dot at its end; the name appears once the room is ready. */
.reload-curtain.arrived .brand-logo { animation: none; }
.reload-curtain.arrived .brand-logo :is(.beat, .beat-dot) { animation: none !important; stroke-dashoffset: 0; opacity: 1; }
.reload-curtain.leaving { animation: curtain-out 760ms var(--ease-glide) forwards; pointer-events: none; }
@keyframes curtain-out { to { background-color: transparent; -webkit-backdrop-filter: blur(0) saturate(1); backdrop-filter: blur(0) saturate(1); } }
.reload-curtain.leaving .brand-logo { animation: curtain-logo-out 520ms ease forwards; }
@keyframes curtain-logo-out { to { opacity: 0; } }
:root.reloading .shell { transform: scale(.985); filter: saturate(.85); transition: transform 600ms var(--ease-glide), filter 600ms var(--ease-glide); }

/* ---------- The bar's icon buttons, one size ----------
   PERSONALIZE, reload, the browser and the files kept their own 28×26 box and 16px drawing while
   the crew, the modules and MU/TH/UR became 34px squircles on a narrower bar. They follow the same
   steps now: 26px tall with a 15px drawing on a wide bar, the same 34px squircle and 18px drawing
   on a narrow one. */
.bar > .tree-button { width: 28px; height: 26px; }
.bar > .tree-button svg { width: var(--ico-sm); height: var(--ico-sm); }
@container bar (max-width: 980px) {
  .bar > .tree-button { width: 34px; height: 34px; border-radius: 11px; display: inline-grid; place-items: center; padding: 0; }
  .bar > .tree-button svg { width: var(--ico-md); height: var(--ico-md); }
}

/* ==========================================================================================
   THE COMPOSER: the crew in one sphere, the options under the box
   ------------------------------------------------------------------------------------------
   The agent you write to is a round button at the left of the box. Under the pointer, focused or
   pressed, the rest of the crew rises above it in a column of glass; choosing one closes it. The
   line in the box says the whole address — HUMAN › ASH › @CODEX › — and mode, model and effort
   sit in a row under the box, where they read as what this message will be sent with.
   ========================================================================================== */
.field { grid-template-columns: auto auto minmax(0, 1fr) auto auto auto auto; padding-left: 6px; }
.field > .reply-quote { grid-column: 1 / -1; }
.picker.crew { position: relative; display: grid; place-items: center; padding: 0; gap: 0; flex-wrap: nowrap; align-self: center; }
.crew-orb {
  position: relative; display: grid; place-items: center; width: 40px; height: 40px; padding: 0; border: 0; border-radius: 50%;
  background: transparent; cursor: pointer;
  transition: transform var(--motion-fast) var(--ease-out), box-shadow var(--motion-fast) var(--ease-out);
}
.crew-orb .avatar { pointer-events: none; }
.crew-orb:hover, .picker.crew:is(.open, :focus-within) .crew-orb { transform: scale(1.06); }
.crew-orb:focus-visible { outline: 2px solid var(--phosphor); outline-offset: 2px; }
.crew-stack {
  position: absolute; left: 50%; bottom: calc(100% + 12px); z-index: 30;
  display: flex; flex-direction: column-reverse; align-items: center; gap: 8px; padding: 8px;
  border-radius: 999px;
  background-color: color-mix(in srgb, var(--bg) 70%, transparent);
  background-image: var(--sheen);
  -webkit-backdrop-filter: blur(22px) saturate(1.7); backdrop-filter: blur(22px) saturate(1.7);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 14%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .16), inset .5px 0 0 rgba(255, 92, 170, .07), inset -.5px 0 0 rgba(90, 210, 255, .07), 0 12px 30px -12px rgba(0, 0, 0, .55);
  opacity: 0; pointer-events: none; transform: translate(-50%, 8px) scale(.94); transform-origin: 50% 100%;
  transition: opacity calc(180ms * var(--motion-scale)) var(--ease-out), transform calc(260ms * var(--motion-scale)) var(--ease-glide);
}
/* A bridge over the gap, so the pointer can travel from the sphere up into the column. */
.crew-stack::after { content: ''; position: absolute; left: -6px; right: -6px; top: 100%; height: 14px; }
.picker.crew:is(:hover, :focus-within, .open) .crew-stack { opacity: 1; pointer-events: auto; transform: translate(-50%, 0) scale(1); }
.crew-stack .pick { transition: transform var(--motion-fast) var(--ease-out); }
.crew-stack .pick:hover { transform: scale(1.1); }
:root[data-scheme="light"] .crew-stack { background-color: color-mix(in srgb, #ffffff 72%, transparent); box-shadow: 0 0 0 .5px rgba(20, 30, 20, .12), inset 0 1px 0 rgba(255, 255, 255, .9), 0 12px 30px -14px rgba(20, 30, 20, .3); }
@media (prefers-reduced-motion: reduce) { .crew-stack { transition: opacity 0s; transform: translate(-50%, 0); } }
/* The address in the box closes with the agent, in its colour. */
.crew-label .crew-to { color: var(--agent); letter-spacing: .14em; }
:root[data-scheme="light"] .crew-label .crew-to { color: color-mix(in srgb, var(--agent) 60%, #000000); }
/* The options under the box: one quiet line, aligned with the text above it. */
.composer > .pick-options { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 0 0 0 58px; margin-top: -4px; min-height: 26px; }
.composer > .pick-options:empty { display: none; }
.composer > .pick-options .pick-label { gap: 4px; margin-left: 0; }
:root[data-scheme] .composer > .pick-options :is(.mode-chip, .model-chip, .effort-chip) { margin-left: 0; }

/* In a narrow column the text takes the first row; the sphere, the address and the buttons sit
   under it, and the options under those. */
@container composer (max-width: 560px) {
  .field { row-gap: 0; padding: 8px 8px 6px 8px; border-radius: 20px; align-items: center; }
  .field > .reply-quote { grid-row: 1; grid-column: 1 / -1; }
  .field > .editor { grid-row: 2; grid-column: 1 / -1; margin: 0 0 4px 8px; }
  .field > .picker.crew { grid-row: 3; grid-column: 1; }
  .field > .crew-label { grid-row: 3; grid-column: 2 / 4; overflow: hidden; text-overflow: ellipsis; }
  .field > .create-toggle { grid-row: 3; grid-column: 4; }
  .field > .ash-toggle { grid-row: 3; grid-column: 5; }
  .field > .attach { grid-row: 3; grid-column: 6; }
  .field > button[type="submit"] { grid-row: 3; grid-column: 7; }
  .composer > .pick-options { padding-left: 12px; }
}

/* The version and APOYAR: the bottom-right corner of the room, in their own row. */
.shell > .colophon { justify-self: end; width: auto; margin: 0 22px 10px 0; text-align: right; }

/* ---------- The conversations' handle, with body ----------
   It was lost among the rest of the room. Now it has the bar's glass plus volume: a light that
   falls from above (a brighter top, a lit upper edge, a shaded lower one) and a shadow in three
   steps, so it reads as a thing you can pick up. */
:root .shell > .chats-button {
  width: 44px; height: 42px; border-radius: 15px;
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .1), rgba(255, 255, 255, 0) 55%), var(--sheen);
  box-shadow:
    0 0 0 .5px color-mix(in srgb, var(--text) 16%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, .22), inset 0 -1.5px 0 rgba(0, 0, 0, .35),
    inset 1px 0 0 rgba(255, 92, 170, .08), inset -1px 0 0 rgba(90, 210, 255, .08),
    0 1px 1px rgba(0, 0, 0, .3), 0 6px 14px -6px rgba(0, 0, 0, .55), 0 18px 34px -16px rgba(0, 0, 0, .6);
}
:root .shell > .chats-button svg { width: var(--ico-lg); height: var(--ico-lg); filter: drop-shadow(0 1px 0 rgba(0, 0, 0, .35)); }
:root[data-scheme="light"] .shell > .chats-button {
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .9), rgba(255, 255, 255, .35) 60%), var(--sheen);
  box-shadow:
    0 0 0 .5px rgba(20, 30, 20, .14),
    inset 0 1px 0 #ffffff, inset 0 -1.5px 0 rgba(20, 30, 20, .1),
    inset 1px 0 0 rgba(255, 92, 170, .08), inset -1px 0 0 rgba(60, 170, 230, .08),
    0 1px 1px rgba(20, 30, 20, .08), 0 6px 14px -6px rgba(20, 30, 20, .22), 0 18px 34px -16px rgba(20, 30, 20, .28);
}
:root[data-scheme="light"] .shell > .chats-button svg { filter: drop-shadow(0 1px 0 rgba(255, 255, 255, .8)); }

/* ---------- Bubbles and the small print, as discreet liquid glass ----------
   Without sampling what is behind them (that is what broke the scroll), they still read as glass:
   a light that falls on the top edge and fades down the surface, a shaded lower edge, the faint
   pink and cyan split of a lens on the sides, and a soft shadow that lifts them off the wallpaper.
   The fill stays dense enough that the words keep the theme's contrast. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble {
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, 0) 42%);
  box-shadow:
    0 0 0 .5px color-mix(in srgb, var(--text) 12%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, .16), inset 0 -1px 0 rgba(0, 0, 0, .3),
    inset 1px 0 0 rgba(255, 92, 170, .09), inset -1px 0 0 rgba(90, 210, 255, .09),
    0 2px 4px rgba(0, 0, 0, .18), 0 14px 32px -16px rgba(0, 0, 0, .55);
}
:is(:root[data-scheme="light"][data-wallpaper] #messages, .look-preview[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"])) :is(.assistant, .thinking) .bubble {
  background-color: rgba(255, 255, 255, .93);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .7), rgba(255, 255, 255, 0) 40%);
  box-shadow:
    0 0 0 .5px rgba(20, 30, 20, .1),
    inset 0 1px 0 #ffffff, inset 0 -1px 0 rgba(20, 30, 20, .06),
    inset 1px 0 0 rgba(255, 50, 150, .09), inset -1px 0 0 rgba(30, 170, 240, .09),
    0 2px 4px rgba(20, 30, 20, .06), 0 14px 32px -18px rgba(20, 30, 20, .3);
}
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead, .settled-note) {
  background-color: color-mix(in srgb, var(--bg) 82%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, 0) 50%);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 12%, transparent), inset 0 1px 0 rgba(255, 255, 255, .12), inset 1px 0 0 rgba(255, 92, 170, .07), inset -1px 0 0 rgba(90, 210, 255, .07), 0 6px 16px -10px rgba(0, 0, 0, .45);
}
:is(:root[data-scheme="light"][data-wallpaper] #messages, .look-preview[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead, .settled-note) {
  background-color: rgba(255, 255, 255, .84);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .7), rgba(255, 255, 255, 0) 50%);
  box-shadow: 0 0 0 .5px rgba(20, 30, 20, .1), inset 0 1px 0 #ffffff, inset 1px 0 0 rgba(255, 50, 150, .07), inset -1px 0 0 rgba(30, 170, 240, .07), 0 6px 16px -12px rgba(20, 30, 20, .25);
}

/* ---------- A reply's actions live in its foot ----------
   Rate, copy and reply sit in the foot, between the memory and the bill, and show under the
   pointer or focus. The bubble clips what runs past its sides (a long line of code must not push
   it wider), so they cannot float outside it; inside the foot they cost no row of their own. */
.bubble-foot .bubble-actions { display: inline-flex; align-items: center; gap: 0; margin: 0 0 0 auto; opacity: 0; transition: opacity calc(160ms * var(--motion-scale)) ease; }
.bubble-foot .bubble-actions + .stamp { margin-left: 10px; }
.bubble:is(:hover, :focus-within) .bubble-foot .bubble-actions { opacity: 1; }
@media (hover: none) { .bubble-foot .bubble-actions { opacity: .7; } }
.bubble-foot .bubble-actions .act { width: 26px; height: 24px; }

/* ---------- The conversation runs on under the composer ----------
   No cut where the composer begins and no glass: the thread reaches down beneath the composer by a
   negative margin as tall as the strip, and its last line can still scroll up above the box. */
.shell > .thread { margin-bottom: calc(-1 * var(--dock-h, 0px)); }
.thread-inner { padding-bottom: calc(var(--dock-h, 0px) + 28px); }
.shell > :is(.composer, .safety, .colophon) { position: relative; z-index: 4; }

/* ---------- The provider's name, out of the sphere ----------
   In the crew's column, the sphere under the pointer lets its provider's name slide out to its
   right on a small pane of glass. */
.crew-stack .pick { position: relative; overflow: visible; }
.crew-stack .pick-vendor {
  position: absolute; left: calc(100% + 12px); top: 50%; z-index: 1;
  padding: 4px 10px; border-radius: 999px; white-space: nowrap;
  font-family: var(--mono); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--text);
  background-color: color-mix(in srgb, var(--bg) 72%, transparent);
  -webkit-backdrop-filter: blur(18px) saturate(1.6); backdrop-filter: blur(18px) saturate(1.6);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 14%, transparent), inset 0 .5px 0 rgba(255, 255, 255, .16), 0 8px 20px -10px rgba(0, 0, 0, .5);
  opacity: 0; transform: translate(-8px, -50%); pointer-events: none;
  transition: opacity calc(160ms * var(--motion-scale)) var(--ease-out), transform calc(220ms * var(--motion-scale)) var(--ease-out);
}
.crew-stack .pick:is(:hover, :focus-visible) .pick-vendor { opacity: 1; transform: translate(0, -50%); }
:root[data-scheme="light"] .crew-stack .pick-vendor { background-color: color-mix(in srgb, #ffffff 80%, transparent); box-shadow: 0 0 0 .5px rgba(20, 30, 20, .12), inset 0 1px 0 #ffffff, 0 8px 20px -12px rgba(20, 30, 20, .3); }

/* ---------- Suggested questions: centred, as liquid glass ----------
   They are offers, not messages: centred over the box, each on a clear pane of glass with a lit
   top edge and the lens's split on its sides, so they never read as a chat bubble. */
.openq { justify-items: center; }
.openq-rail { width: fit-content; max-width: 100%; margin-inline: auto; }
.openq-ask {
  border: 0;
  background-color: color-mix(in srgb, var(--bg) 46%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .12), rgba(255, 255, 255, 0) 60%);
  -webkit-backdrop-filter: blur(20px) saturate(1.8); backdrop-filter: blur(20px) saturate(1.8);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 18%, transparent), inset 0 1px 0 rgba(255, 255, 255, .22), inset 1px 0 0 rgba(255, 92, 170, .12), inset -1px 0 0 rgba(90, 210, 255, .12), 0 8px 22px -12px rgba(0, 0, 0, .5);
}
.openq-ask:hover { background-color: color-mix(in srgb, var(--bg) 34%, transparent); }
:root[data-scheme="light"] .openq-ask {
  background-color: color-mix(in srgb, #ffffff 46%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .7), rgba(255, 255, 255, 0) 60%);
  box-shadow: 0 0 0 .5px rgba(20, 30, 20, .14), inset 0 1px 0 #ffffff, inset 1px 0 0 rgba(255, 50, 150, .1), inset -1px 0 0 rgba(30, 170, 240, .1), 0 8px 22px -14px rgba(20, 30, 20, .3);
}
:root[data-scheme="light"] .openq-ask:hover { background-color: color-mix(in srgb, #ffffff 62%, transparent); }

/* ---------- The box you write in: liquid glass that gives under the press ---------- */
.composer .field {
  background-color: color-mix(in srgb, var(--panel) 84%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(255, 255, 255, 0) 55%);
  -webkit-backdrop-filter: blur(22px) saturate(1.7); backdrop-filter: blur(22px) saturate(1.7);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .16), inset 0 -1px 0 rgba(0, 0, 0, .3), inset 1px 0 0 rgba(255, 92, 170, .1), inset -1px 0 0 rgba(90, 210, 255, .1), 0 10px 28px -14px rgba(0, 0, 0, .55);
  transition: transform calc(160ms * var(--motion-scale)) var(--ease-out), box-shadow calc(160ms * var(--motion-scale)) var(--ease-out), border-color calc(220ms * var(--motion-scale)) ease, background-color calc(220ms * var(--motion-scale)) ease;
}
:root[data-scheme="light"] .composer .field {
  background-color: color-mix(in srgb, #ffffff 88%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .75), rgba(255, 255, 255, 0) 55%);
  box-shadow: inset 0 1px 0 #ffffff, inset 0 -1px 0 rgba(20, 30, 20, .06), inset 1px 0 0 rgba(255, 50, 150, .09), inset -1px 0 0 rgba(30, 170, 240, .09), 0 10px 28px -16px rgba(20, 30, 20, .3);
}

/* ---------- Mode, model and effort: flush left with the sphere and the box ---------- */
.composer > .pick-options { padding-left: 0; }

/* ---------- The version and APOYAR, crisp ----------
   No haze around the letters. */
:root[data-wallpaper] .colophon, .colophon { text-shadow: none; opacity: 1; font-weight: 600; }

/* ---------- MADRE's live light breathes ----------
   While the room is live, the dot by EN VIVO swells and settles, slowly, and its waves follow. */
.connection[data-state="live"] .connection-dot { animation: live-breath 2.8s ease-in-out infinite; }
.connection[data-state="live"] .connection-icon .bar-glyph { animation: live-waves 2.8s ease-in-out infinite; }
@keyframes live-breath { 0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 color-mix(in srgb, var(--phosphor) 45%, transparent); } 50% { transform: scale(1.18); box-shadow: 0 0 0 4px color-mix(in srgb, var(--phosphor) 0%, transparent); } }
@keyframes live-waves { 0%, 100% { opacity: .5; } 50% { opacity: .8; } }

/* After RELOAD, the bar answers with one pulse: the logo's dot and the live light. */
:root.just-arrived .bar .brand-logo .beat-dot { animation: dot-emit 1.1s cubic-bezier(.2, .7, .2, 1) 1 !important; transform-origin: center; transform-box: fill-box; }
:root.just-arrived .connection .connection-dot { animation: live-emit 1.1s cubic-bezier(.2, .7, .2, 1) 1; }
@keyframes dot-emit { 0% { transform: scale(1); filter: none; } 35% { transform: scale(1.7); filter: drop-shadow(0 0 4px var(--brand-pulse)); } 100% { transform: scale(1); filter: none; } }
@keyframes live-emit { 0% { transform: scale(1); box-shadow: 0 0 0 0 color-mix(in srgb, var(--phosphor) 60%, transparent); } 40% { transform: scale(1.5); } 100% { transform: scale(1); box-shadow: 0 0 0 9px color-mix(in srgb, var(--phosphor) 0%, transparent); } }
@media (prefers-reduced-motion: reduce) { .connection[data-state="live"] :is(.connection-dot, .connection-icon .bar-glyph), :root.just-arrived :is(.bar .brand-logo .beat-dot, .connection .connection-dot) { animation: none !important; } }

/* ==========================================================================================
   POLISH: concentric chips, real liquid glass, a box that sinks
   ========================================================================================== */
/* A chip inside a container keeps the same gap on every side, and the container's radius is the
   chip's plus that gap, so the two curves run parallel. Pills in pills: 3px all round. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .who { padding: 3px 12px; }
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .who:has(> .badge:last-child) { padding-right: 3px; }
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .who:has(> .badge:first-child) { padding-left: 3px; }
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .who .badge { padding: 2px 9px; line-height: 1.35; }
/* The options under the box: the chips sit 3px inside the pill, and their own ground, when they
   show one, is a pill too. */
:root[data-scheme] .composer > .pick-options .pick-label { padding: 3px; gap: 0; border-radius: 999px; }
:root[data-scheme] .composer > .pick-options :is(.mode-chip, .model-chip, .effort-chip, .effort-chip.set, .effort-chip.peak) {
  height: 26px; padding: 0 10px 0 12px; border: 0; border-radius: 999px; background: transparent; box-shadow: none;
}
:root[data-scheme] .composer > .pick-options :is(.mode-chip, .model-chip, .effort-chip):is(:hover, :focus-visible, [aria-expanded="true"]) { background: color-mix(in srgb, currentColor 12%, transparent); }
/* THE COPILOT (2026-10-14): a robot beside mode · model · effort, in the same glass; MADRE's green
   when it is on, with the time it has left. Its menu says what it does, its switch and how long. */
.picker .pick-label > .copilot-chip { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border: 0; border-radius: 999px; background: transparent; color: var(--text-2); font: inherit; letter-spacing: .06em; cursor: pointer; transition: background .18s ease, color .18s ease; }
.picker .pick-label > .copilot-chip:is(:hover, :focus-visible) { background: color-mix(in srgb, currentColor 12%, transparent); outline: none; }
.copilot-icon { display: inline-flex; width: var(--ico-sm); height: var(--ico-sm); }
.copilot-icon svg { width: 100%; height: 100%; }
.picker .pick-label > .copilot-chip.on { color: var(--madre-green); background: color-mix(in srgb, var(--madre-green) 14%, transparent); }
.picker .pick-label > .copilot-chip .left { font-size: 10px; }
.copilot-menu { display: grid; gap: 8px; }
.copilot-menu .copilot-title { display: flex; align-items: center; gap: 8px; margin: 2px 2px 0; color: var(--text); }
.copilot-menu .copilot-title b { flex: 1; color: var(--text); font-size: 11px; }
.copilot-menu .copilot-title .copilot-icon { color: var(--madre-green); }
.copilot-menu .copilot-body { display: grid; gap: 8px; padding: 0 2px 2px; font-family: var(--read, inherit); letter-spacing: 0; }
/* Three weights (2026-10-14): what it does reads first; what it never does is the small print. */
.copilot-menu .copilot-body p { margin: 0; font-size: 12.5px; line-height: 1.45; color: var(--text-2); }
.copilot-menu .copilot-body .copilot-lead { font-size: 14px; line-height: 1.45; color: var(--text); font-weight: 400; }
.copilot-menu .copilot-body .copilot-never { padding-top: 8px; border-top: 1px solid var(--line); font-size: 11.5px; line-height: 1.5; color: color-mix(in srgb, var(--text) 46%, transparent); }
.copilot-menu .copilot-body .copilot-state { color: var(--madre-green); font-weight: 600; }
.copilot-menu .copilot-body .copilot-foot { font-size: 11px; color: var(--text-3); }
.copilot-menu .copilot-how { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 12px; color: var(--text-2); }
/* A message under the copilot: the box wears green, not EDIT's red. */
.composer.copilot .field { border-color: var(--madre-green); --ring: 0 0 0 3px color-mix(in srgb, var(--madre-green) 16%, transparent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--madre-green) 16%, transparent); }
.composer.copilot .crew-label { color: var(--madre-green); }
/* The reply written as the copilot: a green round robot on the agent's own circle, shown on every
   reply of a run of them, so a glance down the thread says which ones the copilot wrote. */
#messages .row.copilot > .avatar { position: relative; overflow: visible; }
#messages .row.copilot.compact > .avatar { visibility: visible; }
#messages .row.copilot.compact > .avatar > :not(.copilot-badge) { visibility: hidden; }
#messages .row.copilot > .avatar .copilot-badge { position: absolute; right: -6px; bottom: -6px; z-index: 1; visibility: visible; display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; padding: 3px; border-radius: 50%; background: var(--madre-green); color: var(--madre-green-ink); box-shadow: 0 0 0 2px var(--bg), 0 2px 6px rgb(0 0 0 / .18); }
#messages .row.copilot > .avatar .copilot-badge svg { width: 100%; height: 100%; }
#messages .who .badge.copilot { color: var(--madre-green); background: color-mix(in srgb, var(--madre-green) 14%, transparent); }
/* The lines of the room that carry a chip: the box's radius follows the chip it holds. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) .system:not(.mother-alert) { border-radius: 18px; padding: 8px 16px 9px; }

/* Nothing inside the conversation samples what lies behind it. Every piece that blurs the
   wallpaper is a layer of its own that the browser has to keep painted while the thread scrolls,
   and with a conversation's worth of them it runs out and draws them as empty blocks, square and
   without their words. Lighting only the rows on screen made it rarer, not gone. So the bubbles
   and the small print are a dense tint over the picture instead, which at these strengths is all
   the blur ever showed; the glass stays on the bar and the box, which do not scroll. */
:root[data-wallpaper] #messages, :root[data-wallpaper] #messages * { -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }
:root[data-wallpaper] #messages .row:is(.assistant, .thinking) .bubble { background-color: color-mix(in srgb, var(--bubble) 90%, transparent); }
:root[data-scheme="light"][data-wallpaper] #messages .row:is(.assistant, .thinking) .bubble { background-color: rgba(255, 255, 255, .9); }
:root[data-wallpaper] #messages .thread-inner > :is(.system:not(.mother-alert)),
:root[data-wallpaper] #messages .thread-inner > * :is(.who, .col > .stamp, .col > .memory-hint .lead),
:root[data-wallpaper] #messages .thread-inner > :is(.settled) :is(.settled-lead, .settled-note) { background-color: color-mix(in srgb, var(--bg) 76%, transparent); }
:root[data-scheme="light"][data-wallpaper] #messages .thread-inner > :is(.system:not(.mother-alert)),
:root[data-scheme="light"][data-wallpaper] #messages .thread-inner > * :is(.who, .col > .stamp, .col > .memory-hint .lead),
:root[data-scheme="light"][data-wallpaper] #messages .thread-inner > :is(.settled) :is(.settled-lead, .settled-note) { background-color: rgba(255, 255, 255, .78); }

/* ==========================================================================================
   SOLID BAR AND BOX; A PRESS THAT NEITHER MOVES NOR RESIZES
   ========================================================================================== */
/* The bar and the box you write in are the room's two fixed pieces: nearly solid now, the
   wallpaper only a breath behind them. */
.shell > .bar, :root[data-wallpaper] .shell > .bar { background-color: color-mix(in srgb, var(--bg) 93%, transparent); }
:root[data-scheme="light"] .shell > .bar, :root[data-scheme="light"][data-wallpaper] .shell > .bar { background-color: color-mix(in srgb, #ffffff 94%, transparent); }
.composer .field { background-color: color-mix(in srgb, var(--panel) 96%, transparent); }
:root[data-scheme="light"] .composer .field { background-color: color-mix(in srgb, #ffffff 97%, transparent); }

/* The box's outline is the sum of two things that never change size: the ring of its mode, when
   the mode has one (CREATE, CONTROL, AIRLOCK, a file being dropped), and its own lift. Clicking into
   it adds only shade inside, from the top edge down, as a key reads pressed: it stays where it is,
   as big as it is. */
.composer .field { --ring: 0 0 #0000; --press: 0 0 #0000; transform: none; }
.composer.creating .field { --ring: 0 0 0 3px color-mix(in srgb, var(--mode-2) 18%, transparent); }
.composer.creating.ordering .field { --ring: 0 0 0 3px color-mix(in srgb, var(--mode-2) 18%, transparent), inset 0 0 0 1px color-mix(in srgb, var(--brew) 45%, transparent); }
.composer.control .field { --ring: 0 0 0 3px color-mix(in srgb, var(--terror) 16%, transparent); }
.composer.airlock .field { --ring: 0 0 0 3px color-mix(in srgb, var(--mode-4) 16%, transparent); }
.composer.dropping .field { --ring: 0 0 0 3px color-mix(in srgb, var(--phosphor) 16%, transparent); }
:root[data-scheme="light"] .composer.creating .field, :root[data-scheme="light"] .composer.creating.ordering .field { --ring: 0 0 0 2px color-mix(in srgb, var(--mode-2) 30%, transparent); }
:root[data-scheme="light"] .composer.control .field { --ring: 0 0 0 2px color-mix(in srgb, var(--terror) 30%, transparent); }
:root[data-scheme="light"] .composer.airlock .field { --ring: 0 0 0 2px color-mix(in srgb, var(--mode-4) 35%, transparent); }
:root[data-scheme="light"] .composer.dropping .field { --ring: 0 0 0 2px color-mix(in srgb, var(--phosphor) 35%, transparent); }
:root[data-scheme="light"] .composer.module-command .field { --ring: 0 0 0 2px color-mix(in srgb, var(--module-electric) 34%, transparent); }
.composer .field:focus-within { --press: inset 0 4px 12px rgba(0, 0, 0, .42), inset 0 1px 3px rgba(0, 0, 0, .3); }
:root[data-scheme="light"] .composer .field:focus-within { --press: inset 0 4px 12px rgba(20, 30, 20, .16), inset 0 1px 3px rgba(20, 30, 20, .14); }
:root[data-scheme] .shell .composer .field, :root[data-scheme] .shell .composer .field:focus-within {
  transform: none;
  box-shadow: var(--ring), var(--press), inset 0 1px 0 rgba(255, 255, 255, .16), inset 0 -1px 0 rgba(0, 0, 0, .3), inset 1px 0 0 rgba(255, 92, 170, .1), inset -1px 0 0 rgba(90, 210, 255, .1), 0 10px 28px -14px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] .shell .composer .field, :root[data-scheme="light"] .shell .composer .field:focus-within {
  box-shadow: var(--ring), var(--press), inset 0 1px 0 #ffffff, inset 0 -1px 0 rgba(20, 30, 20, .06), inset 1px 0 0 rgba(255, 50, 150, .09), inset -1px 0 0 rgba(30, 170, 240, .09), 0 10px 28px -16px rgba(20, 30, 20, .3);
}
:root[data-scheme] .shell .composer.ghost .field { box-shadow: var(--press); }

/* SIGUE ABIERTO AQUÍ can be put away: a small × beside its heading, quiet until the pointer finds it. */
.openq-head { display: inline-flex; align-items: center; gap: 6px; }
.openq-close { display: inline-grid; place-items: center; width: 20px; height: 20px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--text-3); cursor: pointer; opacity: .75; transition: opacity var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out); }
.openq-close svg { width: var(--ico-xs); height: var(--ico-xs); }
/* Centred is the label, not the label and its ×: the × hangs at the label's right, out of the
   count, so «sigue abierto aquí» stands on the same axis as the questions under it and the card above. */
.openq-head { position: relative; }
.openq-head > .openq-close { position: absolute; top: 50%; left: calc(100% + 6px); translate: 0 -50%; }
.openq-close:hover, .openq-close:focus-visible { opacity: 1; color: var(--text); background: color-mix(in srgb, var(--text) 10%, transparent); }
:root[data-wallpaper] .openq-close { color: var(--text-2); background: color-mix(in srgb, var(--bg) 62%, transparent); }

/* The box you write in is solid: one colour, no light falling down its face. */
:root[data-scheme] .shell .composer .field { background-image: none; }

/* ---------- The starters on an empty room, as the small print's glass ---------- */
#messages .empty-starts .empty-start {
  border: 0; color: var(--text);
  background-color: color-mix(in srgb, var(--bg) 62%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, 0) 50%);
  -webkit-backdrop-filter: blur(18px) saturate(1.8) brightness(1.04) !important; backdrop-filter: blur(18px) saturate(1.8) brightness(1.04) !important;
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 12%, transparent), inset 0 1px 0 rgba(255, 255, 255, .12), inset 1px 0 0 rgba(255, 92, 170, .07), inset -1px 0 0 rgba(90, 210, 255, .07), 0 6px 16px -10px rgba(0, 0, 0, .45);
}
#messages .empty-starts .empty-start:hover { background-color: color-mix(in srgb, var(--bg) 74%, transparent); }
:root[data-scheme="light"] #messages .empty-starts .empty-start {
  background-color: rgba(255, 255, 255, .66);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .7), rgba(255, 255, 255, 0) 50%);
  box-shadow: 0 0 0 .5px rgba(20, 30, 20, .1), inset 0 1px 0 #ffffff, inset 1px 0 0 rgba(255, 50, 150, .07), inset -1px 0 0 rgba(30, 170, 240, .07), 0 6px 16px -12px rgba(20, 30, 20, .25);
}
:root[data-scheme="light"] #messages .empty-starts .empty-start:hover { background-color: rgba(255, 255, 255, .8); }

/* ---------- Buttons in the room's lines: one colour, start to finish ----------
   MEDIRLO CONTRA ESTA SALA and its kin showed a pink and cyan rim at rest and the accent under the
   pointer: two looks for one button. They wear their own colour from the start now — the accent
   for the local model's choices — on clear glass with a rim of that colour; the pointer only
   deepens the fill. */
#messages .system.local-model button { color: var(--phosphor); }
:root[data-scheme="light"] #messages .system.local-model button { color: color-mix(in srgb, var(--phosphor) 60%, #000000); }
#messages .system :is(.claim-act, .cmd), #messages .system:is(.lease, .escalation, .local-model) button {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor var(--glass-rim), transparent), inset 0 1px 0 rgba(255, 255, 255, .08), 0 6px 18px -10px rgba(0, 0, 0, .4);
}
:root[data-scheme="light"] #messages .system :is(.claim-act, .cmd), :root[data-scheme="light"] #messages .system:is(.lease, .escalation, .local-model) button {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor var(--glass-rim), transparent), inset 0 1px 0 rgba(255, 255, 255, .7), 0 6px 18px -12px rgba(20, 30, 20, .3);
}

/* ---------- The bar's buttons under the pointer: a shine on the edge, nothing more ----------
   They answered with a halo three pixels wide on top of an accent border — two outlines, and not
   the same on every button. Now every one of them does the same quiet thing: the drawing takes the
   accent and the edge catches a thin line of it, inside the button, with no glow around it. */
:root[data-scheme] .bar > :is(.tree-button, .mother-button, .bar-icon):hover {
  color: var(--phosphor);
  border-color: color-mix(in srgb, var(--phosphor) 42%, var(--line-2));
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--phosphor) 28%, transparent), inset 0 1px 0 rgba(255, 255, 255, .07);
}
:root[data-scheme="light"] .bar > :is(.tree-button, .mother-button, .bar-icon):hover {
  color: color-mix(in srgb, var(--phosphor) 70%, #000000);
  border-color: color-mix(in srgb, var(--phosphor) 45%, var(--line-2));
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--phosphor) 25%, transparent), inset 0 1px 0 rgba(255, 255, 255, .85);
}
:root[data-scheme] .bar > :is(.tree-button, .mother-button, .bar-icon):hover svg { transform: none; }
:root[data-scheme] .shell > .chats-button:hover {
  box-shadow:
    0 0 0 .5px color-mix(in srgb, var(--phosphor) 45%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, .22), inset 0 -1.5px 0 rgba(0, 0, 0, .35),
    0 1px 1px rgba(0, 0, 0, .3), 0 6px 14px -6px rgba(0, 0, 0, .55), 0 18px 34px -16px rgba(0, 0, 0, .6);
}
:root[data-scheme="light"] .shell > .chats-button:hover {
  box-shadow:
    0 0 0 .5px color-mix(in srgb, var(--phosphor) 45%, transparent),
    inset 0 1px 0 #ffffff, inset 0 -1.5px 0 rgba(20, 30, 20, .1),
    0 1px 1px rgba(20, 30, 20, .08), 0 6px 14px -6px rgba(20, 30, 20, .22), 0 18px 34px -16px rgba(20, 30, 20, .28);
}
:root[data-scheme] .shell > .chats-button:hover svg { transform: none; }

/* ==========================================================================================
   BUBBLES, PLAIN AND SOLID
   ------------------------------------------------------------------------------------------
   The simplest bubble reads best on any wallpaper: a solid sheet, a small even radius, a hairline
   of shadow under it and nothing else — no glass, no light running down its face, no coloured rims.
   The reply is white on light and the room's bubble colour on dark; your own keeps its accent.
   ========================================================================================== */
:root[data-scheme] :is(#messages, .look-preview) .row:is(.assistant, .user, .thinking) .bubble {
  border-radius: 8px;
  background-image: none !important;
  -webkit-backdrop-filter: none !important; backdrop-filter: none !important;
  box-shadow: 0 1px .5px rgba(0, 0, 0, .35);
}
:root[data-scheme] :is(#messages, .look-preview) .row:is(.assistant, .thinking) .bubble { background-color: var(--bubble); }
:root[data-scheme="light"] :is(#messages, .look-preview) .row:is(.assistant, .user, .thinking) .bubble { box-shadow: 0 1px .5px rgba(11, 20, 26, .13); }
:root[data-scheme="light"] :is(#messages, .look-preview) .row:is(.assistant, .thinking) .bubble { background-color: #ffffff; }
.look-preview[data-scheme="dark"] .row:is(.assistant, .thinking) .bubble { background-color: var(--bubble) !important; box-shadow: 0 1px .5px rgba(0, 0, 0, .35) !important; }
.look-preview[data-scheme="light"] .row:is(.assistant, .thinking) .bubble { background-color: #ffffff !important; box-shadow: 0 1px .5px rgba(11, 20, 26, .13) !important; }

/* ---------- A new room's welcome, on a card ----------
   On a busy wallpaper the mark, the line and the three openings lost their strength standing
   loose. They sit together on one card of the small print's glass now, and the three openings are
   rows inside it — a tint and a hairline, not a second pane of glass. */
#messages .empty {
  max-width: 540px; width: min(540px, 100%); padding: 26px 24px 20px; border-radius: 22px;
  color: var(--text-2);
  background-color: color-mix(in srgb, var(--bg) 62%, transparent);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, 0) 40%);
  -webkit-backdrop-filter: blur(18px) saturate(1.8) brightness(1.04); backdrop-filter: blur(18px) saturate(1.8) brightness(1.04);
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 12%, transparent), inset 0 1px 0 rgba(255, 255, 255, .12), inset 1px 0 0 rgba(255, 92, 170, .07), inset -1px 0 0 rgba(90, 210, 255, .07), 0 14px 34px -18px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] #messages .empty {
  background-color: rgba(255, 255, 255, .72);
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .7), rgba(255, 255, 255, 0) 40%);
  box-shadow: 0 0 0 .5px rgba(20, 30, 20, .1), inset 0 1px 0 #ffffff, inset 1px 0 0 rgba(255, 50, 150, .07), inset -1px 0 0 rgba(30, 170, 240, .07), 0 14px 34px -20px rgba(20, 30, 20, .3);
}
#messages .empty-starts .empty-start {
  background-color: color-mix(in srgb, var(--text) 5%, transparent); background-image: none;
  -webkit-backdrop-filter: none !important; backdrop-filter: none !important;
  box-shadow: inset 0 0 0 .5px color-mix(in srgb, var(--text) 14%, transparent);
}
#messages .empty-starts .empty-start:hover { background-color: color-mix(in srgb, var(--text) 9%, transparent); }
:root[data-scheme="light"] #messages .empty-starts .empty-start { background-color: rgba(20, 30, 20, .04); background-image: none; box-shadow: inset 0 0 0 .5px rgba(20, 30, 20, .12); }
:root[data-scheme="light"] #messages .empty-starts .empty-start:hover { background-color: rgba(20, 30, 20, .07); }

/* ---------- MEDIRLO and its kin: one rim, and the pointer only deepens the fill ----------
   The rim and a lit top line read as two borders under the pointer. One rim now, the same at rest
   and under the pointer, and the button does not move. */
#messages .system :is(.claim-act, .cmd), #messages .system:is(.lease, .escalation, .local-model) button,
:root[data-scheme="light"] #messages .system :is(.claim-act, .cmd), :root[data-scheme="light"] #messages .system:is(.lease, .escalation, .local-model) button {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 45%, transparent);
}
#messages .system :is(.claim-act, .cmd):is(:hover, :active):not(:disabled), #messages .system:is(.lease, .escalation, .local-model) button:is(:hover, :active):not(:disabled) {
  transform: none;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 45%, transparent);
  background-color: color-mix(in srgb, currentColor 16%, transparent);
}

/* ==========================================================================================
   THE DESKTOP RECEDES BEHIND A VEIL, NOT A FILTER
   ------------------------------------------------------------------------------------------
   While windows float, the desktop softens behind one veil placed between it and them (windows
   live at 30–49, the veil at 20). A filter on the conversation or the bar turned off the glass of
   every bubble and line inside it; the veil blurs what is under it and leaves that glass intact.
   The conversations — their panel and their handle — stand above the veil: they are how you move
   between rooms, and they stay sharp whatever floats.
   ========================================================================================== */
:root.desk-behind .shell > :is(.bar, .chats-button, #messages, .onboarding, .composer, .safety, .colophon, .tree:not(.window), .browser-dock:not(.window), .split-dock, dialog.surface.split) { filter: none; }
:root[data-wallpaper].desk-behind .shell::before { filter: blur(var(--wp-blur-on, 0px)); }
.desk-veil {
  position: fixed; inset: 0; z-index: 20; pointer-events: none; opacity: 0;
  -webkit-backdrop-filter: blur(calc(var(--desk-depth, 1) * .4px)) saturate(calc(1 - var(--desk-depth, 1) * .06)) brightness(calc(1 - var(--desk-depth, 1) * .03));
  backdrop-filter: blur(calc(var(--desk-depth, 1) * .4px)) saturate(calc(1 - var(--desk-depth, 1) * .06)) brightness(calc(1 - var(--desk-depth, 1) * .03));
  transition: opacity calc(380ms * var(--motion-scale)) var(--ease-glide);
}
:root.desk-behind .desk-veil { opacity: 1; }
.shell > .chats-button, .shell > .tree.chats:not(.window) { z-index: 25; }
@media (prefers-reduced-motion: reduce) { .desk-veil { transition: none; } }
.split-pane .desk-veil { display: none; }

/* ---------- Windows cast a soft parallel shadow ----------
   Beside the shadow that falls straight under each window, a second one, very soft, offset down
   and to the right as if the light came from the upper left: the window reads as a plane standing
   off the room, not a sticker on it. */
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window) {
  box-shadow: var(--bevel), 0 1px 2px rgba(0, 0, 0, .3), 0 10px 24px -10px rgba(0, 0, 0, .45), 0 30px 70px -30px rgba(0, 0, 0, .6), 18px 24px 56px -26px rgba(0, 0, 0, .32);
}
:is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).front {
  box-shadow: var(--bevel), 0 2px 3px rgba(0, 0, 0, .32), 0 16px 34px -12px rgba(0, 0, 0, .55), 0 48px 110px -36px rgba(0, 0, 0, .75), 22px 30px 64px -28px rgba(0, 0, 0, .36);
}
:root[data-scheme="light"] :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window) {
  box-shadow: var(--bevel), 0 1px 2px rgba(20, 30, 20, .08), 0 10px 24px -12px rgba(20, 30, 20, .2), 0 30px 70px -32px rgba(20, 30, 20, .3), 18px 24px 56px -28px rgba(20, 30, 20, .16);
}
:root[data-scheme="light"] :is(.tree.window, dialog.surface.window, .conv-window, .browser-dock.window).front {
  box-shadow: var(--bevel), 0 2px 3px rgba(20, 30, 20, .1), 0 16px 34px -14px rgba(20, 30, 20, .26), 0 48px 110px -40px rgba(20, 30, 20, .38), 22px 30px 64px -30px rgba(20, 30, 20, .2);
}

/* ==========================================================================================
   THE OFFERS ABOVE THE BOX
   ========================================================================================== */
/* What is offered about the message being written (@madre answering it for free, Intenciones and
   the effort it needs) belongs to the box, so it is drawn like the box: the same nearly solid
   ground, which reads on any wallpaper, the glass edge, a hairline in its own tone instead of a
   dashed outline, and the theme's main ink. */
.free-offer {
  --tone: var(--brew);
  gap: 10px; padding: 7px 7px 7px 16px;
  border: .5px solid color-mix(in srgb, var(--tone) 60%, var(--line-2));
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 96%, transparent);
  box-shadow: var(--bevel), 0 10px 26px -18px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] .free-offer {
  background: color-mix(in srgb, #ffffff 97%, transparent);
  box-shadow: var(--bevel), 0 10px 26px -18px rgba(20, 30, 20, .28);
}
.free-offer .free-what { color: var(--text); }
.free-offer .free-go { display: inline-flex; align-items: center; height: 30px; padding: 0 14px; border-color: var(--tone); color: var(--tone); border-radius: 12px; }
.free-offer .free-go:hover { background: color-mix(in srgb, var(--tone) 14%, transparent); }

/* ==========================================================================================
   THE ROOM'S LINES AS FLAT LIQUID GLASS
   ========================================================================================== */
/* The plates under the room's lines (PLAN, MEMORIA, a relay), who answered and the time: flatter
   and clearer. No light falling down the face and no shadow under it; the wallpaper shows through
   a thinner tint, and the glass is told by its edge alone: a bright hairline rim, a specular line
   on top and the faint pink and cyan split of a lens at the sides. There is still no blur inside
   the conversation (it is what left blank blocks when scrolling), so the tint stays thick enough
   for the ink to read on any photograph. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead, .settled-note) {
  background-color: color-mix(in srgb, var(--bg) 60%, transparent);
  background-image: none;
  box-shadow:
    0 0 0 .5px rgba(255, 255, 255, .16),
    inset 0 .5px 0 rgba(255, 255, 255, .24),
    inset .8px 0 0 rgba(255, 92, 170, .12), inset -.8px 0 0 rgba(90, 210, 255, .12);
}
:is(:root[data-scheme="light"][data-wallpaper] #messages, .look-preview[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead, .settled-note) {
  background-color: rgba(255, 255, 255, .62);
  background-image: none;
  box-shadow:
    0 0 0 .5px rgba(255, 255, 255, .9), 0 0 0 1px rgba(20, 30, 20, .05),
    inset 0 1px 0 rgba(255, 255, 255, .95),
    inset .8px 0 0 rgba(255, 50, 150, .12), inset -.8px 0 0 rgba(30, 170, 240, .12);
}

/* ==========================================================================================
   THE BAR AND THE BOX STAND OFF THE CANVAS
   ========================================================================================== */
/* The same light as the windows, from the upper left, and softer, because these two are fixed to
   the room rather than floating over it: a contact shadow right under the edge, an ambient one
   that spreads a little, and a third offset down and to the right, so each reads as a plane a
   finger's width above the canvas. The box keeps its mode's ring and its press inside. */
:root[data-scheme] .shell > .bar {
  box-shadow: var(--bevel), 0 1px 1.5px rgba(0, 0, 0, .3), 0 6px 16px -8px rgba(0, 0, 0, .35), 12px 18px 40px -22px rgba(0, 0, 0, .42);
}
:root[data-scheme="light"] .shell > .bar {
  box-shadow: var(--bevel), 0 1px 1.5px rgba(20, 30, 20, .07), 0 6px 16px -10px rgba(20, 30, 20, .14), 12px 18px 40px -24px rgba(20, 30, 20, .2);
}
:root[data-scheme] .shell .composer .field, :root[data-scheme] .shell .composer .field:focus-within {
  box-shadow: var(--ring), var(--press), var(--bevel), 0 1px 1.5px rgba(0, 0, 0, .3), 0 6px 16px -8px rgba(0, 0, 0, .35), 12px 18px 40px -22px rgba(0, 0, 0, .42);
}
:root[data-scheme="light"] .shell .composer .field, :root[data-scheme="light"] .shell .composer .field:focus-within {
  box-shadow: var(--ring), var(--press), var(--bevel), 0 1px 1.5px rgba(20, 30, 20, .07), 0 6px 16px -10px rgba(20, 30, 20, .14), 12px 18px 40px -24px rgba(20, 30, 20, .2);
}

/* ==========================================================================================
   THE SHIP'S TERMINAL KEEPS ITS TYPE
   ========================================================================================== */
/* The room speaks its small print in Geist Mono; MU/TH/UR and NOSTROMO are the ship's own console,
   phosphor on black, and keep the terminal's JetBrains Mono. */
dialog.mother { --mono: "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace; }

/* ==========================================================================================
   WATER-DROP EDGES, WITH NO LINES ROUND THEM
   ========================================================================================== */
/* The edges were drawn as lines: a hairline ring outside, a white line inside, a border on top of
   both, so every chip and plate read as two borders stuck on the canvas. A drop of water has no
   line round it. Its rim is light caught on a curve, soft and fuller at the top, shade gathering
   at the bottom, and it lifts off what it rests on by its own shadow. So that is all an edge is
   now: blurred light inside the top, blurred shade inside the bottom, a breath of the lens split at
   the sides, and a soft float below. No strokes anywhere. One recipe, read by everything glass. */
:root, .look-preview[data-scheme="dark"] {
  --bevel:
    inset 0 1.5px 2.5px -1px rgba(255, 255, 255, .16),
    inset 0 -1.5px 2.5px -1px rgba(0, 0, 0, .45),
    inset 2px 0 3px -2px rgba(255, 92, 170, .12),
    inset -2px 0 3px -2px rgba(90, 210, 255, .12);
  --float: 0 1px 2px rgba(0, 0, 0, .3), 0 8px 20px -10px rgba(0, 0, 0, .5);
  --float-sm: 0 1px 1.5px rgba(0, 0, 0, .28), 0 4px 10px -5px rgba(0, 0, 0, .4);
}
:root[data-scheme="light"], .look-preview[data-scheme="light"] {
  --bevel:
    inset 0 1.5px 2.5px -1px rgba(255, 255, 255, .95),
    inset 0 -1.5px 2.5px -1px rgba(20, 40, 60, .09),
    inset 2px 0 3px -2px rgba(255, 50, 150, .12),
    inset -2px 0 3px -2px rgba(30, 170, 240, .12);
  --float: 0 1px 2px rgba(20, 40, 60, .08), 0 8px 20px -10px rgba(20, 40, 60, .2);
  --float-sm: 0 1px 1.5px rgba(20, 40, 60, .08), 0 4px 10px -5px rgba(20, 40, 60, .16);
}
/* The room's plates, chips and pills: the drop's edge and a small float, and no border of their own.
   A border that only changes colour stays transparent, so nothing shifts by a pixel. */
:is(:root[data-wallpaper] #messages, .look-preview[data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead, .settled-note),
:is(:root[data-scheme="light"][data-wallpaper] #messages, .look-preview[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"])) :is(.system:not(.mother-alert), .who, .col > .stamp, .col > .memory-hint .lead, .settled-lead, .settled-note) {
  box-shadow: var(--bevel), var(--float-sm);
}
:root[data-scheme] #messages .who .badge,
:root[data-scheme] #messages .memory-hint .pill,
:root[data-scheme] .composer .openq-ask {
  border-color: transparent;
  box-shadow: var(--bevel), var(--float-sm);
}

/* The foot of a reply keeps one left edge. When the bill drops under the memory it starts where
   the memory's dots start: the space beside the actions is the row's gap, not a margin it carries
   onto the next line. */
.bubble-foot .bubble-actions + .stamp { margin-left: 0; }

/* ==========================================================================================
   CHIPS IN FLAT TONE
   ========================================================================================== */
/* (`:not(#chip-weight)` only lifts these above the plate rules of the conversation, without !important.)
   Every chip in the room is a tag, not a pebble: a faint fill of its own colour (the mode's, the
   agent's, the kind of memory's; grey for what has none), a small 7px corner instead of a capsule,
   and no edge or shadow at all. The fill sits on a ground of the room's own colour, so a tag still
   reads on a photograph. Hierarchy is colour alone. The room's plates (PLAN, MEMORIA) stay plates. */
:root { --chip-ground: color-mix(in srgb, var(--bg) 80%, transparent); --chip-r: 7px; }
:root[data-scheme="light"] { --chip-ground: rgba(255, 255, 255, .8); }
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) :is(.who .badge, .claim-head > .who, .col > .stamp, .settled-lead, .settled-note, .memory-hint .pill),
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) .composer:not(#chip-weight) .openq-ask {
  border-color: transparent;
  border-radius: var(--chip-r);
  box-shadow: none;
  background: color-mix(in srgb, var(--tone, currentColor) 14%, var(--chip-ground));
}
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) :is(.who .badge, .claim-head > .who, .col > .stamp, .settled-lead) { padding: 2px 8px; }
/* Who answered: a flat strip of the room's ground holding its tags, its corner the tags' plus the gap. */
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) .col > .who {
  border-radius: calc(var(--chip-r) + 3px);
  box-shadow: none;
  background: var(--chip-ground);
}
/* Tags whose text is ink take their colour from what they hold. */
:root[data-scheme] #messages .settled-note { --tone: #e0a800; }
:root[data-scheme] #messages .memory-hint .pill { --tone: var(--kind); }
:root[data-scheme] .composer .openq-ask { --tone: var(--phosphor); }
:root[data-scheme] #messages :is(.who .badge, .col > .stamp, .settled-lead, .settled-note, .memory-hint .pill):hover { background: color-mix(in srgb, var(--tone, currentColor) 22%, var(--chip-ground)); }
.intent-offer .intent-basis { border: 0; border-radius: 6px; background: color-mix(in srgb, var(--tone) 16%, transparent); }

/* ==========================================================================================
   ROUND OF 6 OCT: FOOT ORDER, DARK INK, A QUIETER BOX, ONE SHELF, PRESSABLE BAR
   ========================================================================================== */
/* A reply's foot: the bill first, its actions to the right of it. On one line both sit at the
   right; when the bill drops under the memory it still starts at the memory's left edge. */
.bubble-foot { justify-content: flex-start; }
.bubble-foot > .stamp.stamp { order: 2; margin-left: auto; }
.bubble-foot > .mem-used { margin-right: auto; }
.bubble-foot > .mem-used ~ .stamp.stamp { margin-left: 0; }
.bubble-foot > .bubble-actions, .bubble-foot .bubble-actions + .stamp ~ .bubble-actions { order: 3; margin-left: 0; }

/* Dark theme: the faintest ink was too faint on a dark bubble (PLAN and labels like it). */
:root { --text-3: #868e83; }
.plan-label { color: var(--text-2); font-weight: 600; }

/* Dark theme: the box is its own black, a neutral graphite rather than the room's green-black,
   and the row of mode, model and effort under it steps back so it never competes with it. */
:root:not([data-scheme="light"]) .shell .composer .field { background-color: color-mix(in srgb, #1a1b1d 96%, transparent); }
/* Dark glass reads on a dark ground (2026-10-14): the ground at 45% over the ground was invisible,
   so it takes a breath of the text colour, a half-pixel rim and the same blur as in light. */
:root:not([data-scheme="light"]) .composer > .pick-options .pick-label { background: color-mix(in srgb, var(--text) 13%, color-mix(in srgb, var(--bg) 52%, transparent)); box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 20%, transparent), inset 0 1px 0 rgb(255 255 255 / .09), 0 6px 18px rgb(0 0 0 / .28); -webkit-backdrop-filter: blur(20px) saturate(1.7); backdrop-filter: blur(20px) saturate(1.7); }
:root:not([data-scheme="light"]) .composer > .pick-options :is(.mode-chip, .model-chip, .effort-chip) { opacity: .78; }
:root:not([data-scheme="light"]) .composer > .pick-options :is(.mode-chip, .model-chip, .effort-chip):is(:hover, :focus-visible, [aria-expanded="true"]) { opacity: 1; }

/* The box has no outline that changes with the mode: what changes is the send button and the
   words of the line (who writes, the agent, the model). */
:root[data-scheme] .shell .composer .field,
:root[data-scheme] .shell .composer:is(.ghost, .creating, .ordering, .control, .airlock, .dropping, .module-command) .field {
  border-color: transparent; border-style: solid; --ring: 0 0 #0000;
}

/* The offers above the box: flat glass, no coloured outline. The words carry the ink; the button
   is a tag of its own tone, darkened where it sits on light. */
.free-offer {
  border-color: transparent;
  background: color-mix(in srgb, var(--bg) 70%, transparent);
  -webkit-backdrop-filter: blur(18px) saturate(1.6); backdrop-filter: blur(18px) saturate(1.6);
  box-shadow: var(--bevel), var(--float-sm);
}
:root[data-scheme="light"] .free-offer { background: rgba(255, 255, 255, .72); box-shadow: var(--bevel), var(--float-sm); }
.free-offer .free-go { border: 0; border-radius: 9px; background: color-mix(in srgb, var(--tone) 18%, transparent); color: var(--tone); }
.free-offer .free-go:hover { background: color-mix(in srgb, var(--tone) 28%, transparent); }
:root[data-scheme="light"] .free-offer .free-go { color: color-mix(in srgb, var(--tone) 62%, #000000); }

/* The bar's buttons stand up from it: a faint face, the drop's edge and a small shadow, lifted a
   hair under the pointer and pressed into the bar when clicked. */
.bar > :is(.tree-button, .mother-button), .shell > .chats-button {
  border-color: transparent;
  background-color: color-mix(in srgb, var(--text) 5%, transparent);
  box-shadow: var(--bevel), 0 1px 1.5px rgba(0, 0, 0, .25), 0 3px 6px -3px rgba(0, 0, 0, .35);
}
:root[data-scheme="light"] .bar > :is(.tree-button, .mother-button), :root[data-scheme="light"] .shell > .chats-button {
  background-color: rgba(255, 255, 255, .78);
  box-shadow: var(--bevel), 0 1px 1.5px rgba(20, 40, 60, .1), 0 3px 6px -3px rgba(20, 40, 60, .18);
}
:root .shell .bar > :is(.tree-button, .mother-button):hover, :root .shell > .chats-button:hover { transform: translateY(-1px); }
:root .bar > :is(.tree-button, .mother-button):hover, :root .shell > .chats-button:hover { box-shadow: var(--bevel), 0 2px 3px rgba(0, 0, 0, .22), 0 6px 12px -5px rgba(0, 0, 0, .35); }
:root[data-scheme="light"] .bar > :is(.tree-button, .mother-button):hover, :root[data-scheme="light"] .shell > .chats-button:hover { box-shadow: var(--bevel), 0 2px 3px rgba(20, 40, 60, .1), 0 6px 12px -5px rgba(20, 40, 60, .2); }
:root .shell .bar > :is(.tree-button, .mother-button):active, :root .shell > .chats-button:active { transform: translateY(.5px); box-shadow: inset 0 1px 3px rgba(0, 0, 0, .3) !important; }

/* Each drawing moves in its own way under the pointer — while its key is off. A key that is on
   (its panel open) already says so in its drawing, and moving it again over that reads as a glitch. */
#browser-button svg { transform-style: preserve-3d; }
#browser-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg { animation: icon-globe 480ms var(--ease-out); }
@keyframes icon-globe { from { transform: perspective(60px) rotateY(0); } to { transform: perspective(60px) rotateY(360deg); } }
#reload-button:hover svg { animation: icon-reload 420ms var(--ease-out); }
@keyframes icon-reload { from { transform: rotate(0); } to { transform: rotate(360deg); } }
/* The folder opens: its front drops forward into the open shape and the back stays. */
#tree-button svg .ic-open { opacity: 0; transform-box: fill-box; transform-origin: left bottom; transform: skewX(14deg) scaleY(.6); transition: opacity 140ms var(--ease-out), transform 180ms var(--ease-out); }
#tree-button svg .ic-k { transition: opacity 120ms var(--ease-out); }
#tree-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg .ic-open { opacity: 1; transform: none; }
#tree-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg .ic-k { opacity: 0; }
#custom-button svg circle { transform-box: fill-box; transition: transform 200ms var(--ease-out); }
#custom-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg circle:nth-of-type(1) { transform: translateX(-4.2px); }
#custom-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg circle:nth-of-type(2) { transform: translateX(4.2px); }
#modules-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg { animation: icon-shake 340ms var(--ease-out); }
@keyframes icon-shake { 0%, 100% { transform: rotate(0); } 20% { transform: rotate(-11deg); } 40% { transform: rotate(9deg); } 60% { transform: rotate(-6deg); } 80% { transform: rotate(3deg); } }
.chats-button svg .ic-k { stroke-dasharray: 1 1; stroke-dashoffset: 0; }
.chats-button:not([aria-pressed="true"]):not([aria-expanded="true"]):hover svg .ic-k { animation: icon-type .8s steps(8) infinite; }
@keyframes icon-type { 0% { stroke-dashoffset: 1; } 75%, 100% { stroke-dashoffset: 0; } }
@media (prefers-reduced-motion: reduce) {
  #browser-button:hover svg, #reload-button:hover svg, #modules-button:hover svg, .chats-button:hover svg .ic-k { animation: none; }
  #tree-button svg .ic-open { transition: none; } #custom-button:hover svg circle { transform: none; }
}

/* A new conversation is a plus, a little larger than the icons beside it. */
.chats-new-button svg { width: var(--ico-sm); height: var(--ico-sm); }

/* ==========================================================================================
   SURFACES THAT STAND OUT FROM THE GROUND, AND BUTTONS LIKE PEBBLES
   ========================================================================================== */
/* The ground was the same white or the same black as what stands on it, so the replies, the bar
   and the conversations button sank into it. The ground steps back a tone; the surfaces keep
   theirs: light, a soft grey ground under white sheets; dark, a near-black ground under graphite. */
:root { --bg: #0a0b0a; --bg-2: #101210; --surface: #1c1f1d; --bubble: #1e2220; }
:root[data-scheme="light"] { --bg: #e4e6e1; --bg-2: #eceee9; --surface: #ffffff; }
:root:not([data-scheme="light"]) .shell > .bar { background-color: color-mix(in srgb, var(--surface) 96%, transparent); }
:root:not([data-scheme="light"]) .shell > .chats-button { background-color: var(--surface); }
:root[data-scheme="light"] .shell > .chats-button { background-color: #ffffff; }

/* Buttons: no ring and no coloured edge. A pebble: a face a shade off the bar, light gathered
   softly along the top curve, shade gathered along the bottom one, and a small close shadow. */
:root .shell .bar > :is(.tree-button, .mother-button), :root .shell > .chats-button {
  border-color: transparent;
  background-color: color-mix(in srgb, #ffffff 6%, var(--surface));
  box-shadow: inset 0 1px 1.5px rgba(255, 255, 255, .07), inset 0 -2px 3px rgba(0, 0, 0, .35), 0 1px 2px rgba(0, 0, 0, .45), 0 2px 6px -2px rgba(0, 0, 0, .35);
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button), :root[data-scheme="light"] .shell > .chats-button {
  background-color: #ffffff;
  box-shadow: inset 0 1px 1px #ffffff, inset 0 -2px 3px rgba(20, 40, 60, .07), 0 1px 2px rgba(20, 40, 60, .14), 0 2px 6px -2px rgba(20, 40, 60, .14);
}
:root .shell .bar > :is(.tree-button, .mother-button):hover, :root .shell > .chats-button:hover {
  box-shadow: inset 0 1px 1.5px rgba(255, 255, 255, .09), inset 0 -2px 3px rgba(0, 0, 0, .35), 0 2px 3px rgba(0, 0, 0, .45), 0 5px 10px -3px rgba(0, 0, 0, .4);
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button):hover, :root[data-scheme="light"] .shell > .chats-button:hover {
  box-shadow: inset 0 1px 1px #ffffff, inset 0 -2px 3px rgba(20, 40, 60, .07), 0 2px 3px rgba(20, 40, 60, .14), 0 5px 10px -3px rgba(20, 40, 60, .18);
}
:root .shell .bar > :is(.tree-button, .mother-button):active, :root .shell > .chats-button:active { box-shadow: inset 0 1px 3px rgba(0, 0, 0, .35) !important; }

/* ==========================================================================================
   ROUND OF 6 OCT, LATE: DEPTH, KEYS THAT GIVE, TAGS INSIDE THEIR STRIP, DECISIONS IN STONE
   ========================================================================================== */
/* The box and the bar sit deeper off the ground, in both themes. */
:root[data-scheme] .shell > .bar {
  box-shadow: var(--bevel), 0 1px 2px rgba(0, 0, 0, .45), 0 10px 24px -10px rgba(0, 0, 0, .6), 16px 24px 50px -24px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] .shell > .bar {
  box-shadow: var(--bevel), 0 1px 2px rgba(20, 40, 60, .12), 0 10px 24px -12px rgba(20, 40, 60, .24), 16px 24px 50px -26px rgba(20, 40, 60, .28);
}
:root[data-scheme] .shell .composer .field, :root[data-scheme] .shell .composer .field:focus-within {
  box-shadow: var(--ring), var(--press), var(--bevel), 0 1px 2px rgba(0, 0, 0, .45), 0 10px 24px -10px rgba(0, 0, 0, .6), 16px 24px 50px -24px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] .shell .composer .field, :root[data-scheme="light"] .shell .composer .field:focus-within {
  box-shadow: var(--ring), var(--press), var(--bevel), 0 1px 2px rgba(20, 40, 60, .12), 0 10px 24px -12px rgba(20, 40, 60, .24), 16px 24px 50px -26px rgba(20, 40, 60, .28);
}

/* The bar's buttons are keys: they give a little under the pointer and further under the press.
   Nothing rises; the shadow under them shortens and shade gathers inside as they go down. An open
   panel keeps its drawing filled, as before. */
:root .shell .bar > :is(.tree-button, .mother-button):hover, :root .shell > .chats-button:hover {
  transform: translateY(1px);
  box-shadow: inset 0 1px 1.5px rgba(255, 255, 255, .05), inset 0 1px 3px rgba(0, 0, 0, .3), 0 .5px 1px rgba(0, 0, 0, .45);
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button):hover, :root[data-scheme="light"] .shell > .chats-button:hover {
  box-shadow: inset 0 1px 3px rgba(20, 40, 60, .12), 0 .5px 1px rgba(20, 40, 60, .16);
}
:root .shell .bar > :is(.tree-button, .mother-button):active, :root .shell > .chats-button:active {
  transform: translateY(2px);
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, .45) !important;
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button):active, :root[data-scheme="light"] .shell > .chats-button:active { box-shadow: inset 0 2px 5px rgba(20, 40, 60, .2) !important; }
:root .shell .bar > :is(.tree-button, .mother-button)[aria-pressed="true"], :root .shell > .chats-button[aria-pressed="true"] {
  transform: translateY(1px);
  box-shadow: inset 0 1px 4px rgba(0, 0, 0, .38), 0 .5px 1px rgba(0, 0, 0, .4);
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button)[aria-pressed="true"], :root[data-scheme="light"] .shell > .chats-button[aria-pressed="true"] { box-shadow: inset 0 1px 4px rgba(20, 40, 60, .16), 0 .5px 1px rgba(20, 40, 60, .14); }

/* Who answered: the strip holds its tags with room around them, so a tag reads as smaller than
   what holds it. Three pixels all round, and the strip's corner is the tag's plus those three. */
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) .col > .who { padding: 3px 4px 3px 10px; }
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) .who .badge { padding: 0 6px; font-size: 9.5px; line-height: 17px; }

/* DECIDIDO AQUÍ is a label the width of its words, not a bar across the room. */
#messages .settled-lead { width: fit-content; max-width: max-content; justify-self: start; }

/* Decisions are stone, not amber: #edece4 in light; a warm graphite in dark. */
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) .settled .settled-note { background: #2a2925; color: var(--text); }
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme="light"]) #messages:not(#chip-weight) .settled .settled-note { background: #edece4; color: #3a3933; }
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme]) #messages:not(#chip-weight) .settled .settled-note:hover { background: #34332e; }
:is(:root[data-scheme="light"][data-wallpaper], :root[data-scheme="light"]) #messages:not(#chip-weight) .settled .settled-note:hover { background: #e3e2d8; }

/* ==========================================================================================
   AJUSTES
   ------------------------------------------------------------------------------------------
   One window for every setting. It lays itself out by its own width (the window can float, dock
   or fill the screen): a board of three sections with a sheet over it when there is room, the
   category over the whole window when a sheet would be cramped, and a rail of categories when it
   is narrow. The panels it shows are MU/TH/UR's own, wearing the room's ink.
   ========================================================================================== */
dialog.settings-window { width: 980px; height: 700px; padding: 0; color: var(--text); background: color-mix(in srgb, var(--bg-2) 94%, transparent); -webkit-backdrop-filter: blur(22px) saturate(1.2); backdrop-filter: blur(22px) saturate(1.2); }
dialog.settings-window[open] { display: flex; flex-direction: column; }
dialog.settings-window.entering { animation: window-in calc(440ms * var(--motion-scale)) var(--ease-glide); transform-origin: 85% 0%; }
dialog.settings-window::backdrop { display: none; }
.settings-head { display: flex; align-items: center; gap: 14px; }
.settings-search { flex: 1; min-width: 0; max-width: 420px; display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px; border-radius: 10px; background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text-2); cursor: text; }
.settings-search svg { width: var(--ico-sm); height: var(--ico-sm); flex: none; }
.settings-search input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--text); font: inherit; font-family: var(--read); font-size: 13.5px; }
.settings-search:focus-within { box-shadow: 0 0 0 2px color-mix(in srgb, var(--phosphor) 45%, transparent); }
.settings-body { position: relative; flex: 1; min-height: 0; display: flex; overflow: hidden; }

/* The board. */
.settings-board { flex: 1; min-width: 0; overflow: auto; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; align-content: start; padding: 16px 20px 22px; }
.settings-section { display: grid; gap: 10px; align-content: start; min-width: 0; }
.settings-section > header { display: grid; gap: 1px; padding: 0 2px 2px; }
.settings-section > header b { font-size: 13.5px; font-weight: 600; }
.settings-section > header span { font-size: 12px; color: var(--text-2); }
.settings-card { display: grid; gap: 6px; padding: 13px 14px; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); cursor: pointer; outline: none; transition: box-shadow var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out); }
.settings-card:hover { box-shadow: var(--bevel), var(--float); }
.settings-card:focus-visible { box-shadow: var(--bevel), 0 0 0 2px color-mix(in srgb, var(--phosphor) 55%, transparent); }
.settings-card.open { box-shadow: var(--bevel), 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 50%, transparent); }
.settings-card-head { display: flex; align-items: center; gap: 10px; }
.settings-card-head b { font-size: 14px; font-weight: 600; }
.settings-card-head .settings-go { margin-left: auto; width: 14px; height: 14px; color: var(--text-2); transform: rotate(-90deg); }
.settings-icon { display: grid; place-items: center; width: 28px; height: 28px; flex: none; border-radius: 8px; background: color-mix(in srgb, var(--cat) 16%, transparent); color: var(--cat); }
.settings-icon svg { width: var(--ico-sm); height: var(--ico-sm); }
.settings-line { margin: 0; font-size: 12.5px; line-height: 1.45; color: var(--text-2); }
.settings-warn { justify-self: start; margin: 2px 0 0; padding: 3px 8px; border-radius: 7px; font-size: 12px; background: color-mix(in srgb, #f2c94c 18%, transparent); color: #f2c94c; }
:root[data-scheme="light"] .settings-warn { color: #7a5c00; }
.settings-quick { display: grid; margin: 6px -14px -13px; border-top: .5px solid var(--line); }
.settings-quick-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; min-height: 36px; padding: 0 14px; font-size: 12.5px; }
.settings-quick-row + .settings-quick-row { border-top: .5px solid var(--line); }
.settings-quick-row.agent .who { color: var(--agent, var(--text)); font-weight: 500; }
.settings-quick-row.agent .state { color: var(--text-2); }
.settings-quick-row.agent .state.off { color: #c99a10; }
.settings-quick-row.agent .state.on::before { content: ''; display: inline-block; width: 6px; height: 6px; margin-right: 6px; border-radius: 50%; background: var(--phosphor); vertical-align: 1px; }
.settings-switch { position: relative; display: inline-flex; flex: none; cursor: pointer; }
.settings-switch input { position: absolute; opacity: 0; inset: 0; margin: 0; cursor: pointer; }
.settings-switch i { width: 32px; height: 19px; border-radius: 999px; background: color-mix(in srgb, var(--text) 16%, transparent); position: relative; transition: background-color var(--motion-fast) var(--ease-out); }
.settings-switch i::after { content: ''; position: absolute; top: 2px; left: 2px; width: 15px; height: 15px; border-radius: 50%; background: #ffffff; box-shadow: 0 1px 2px rgba(0, 0, 0, .3); transition: transform var(--motion-fast) var(--ease-out); }
.settings-switch input:checked + i { background: var(--phosphor); }
.settings-switch input:checked + i::after { transform: translateX(13px); }
.settings-switch input:disabled + i { opacity: .4; }
.settings-switch input:focus-visible + i { box-shadow: 0 0 0 2px color-mix(in srgb, var(--phosphor) 50%, transparent); }
.settings-seg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 9px; background: color-mix(in srgb, var(--text) 7%, transparent); }
.settings-seg button { border: 0; background: transparent; color: var(--text-2); font: inherit; font-size: 12px; padding: 3px 9px; border-radius: 7px; cursor: pointer; }
.settings-seg button.on { background: var(--surface, var(--panel)); color: var(--text); box-shadow: 0 1px 2px rgba(0, 0, 0, .2); }

/* The sheet over the board. */
.settings-scrim { position: absolute; inset: 0; background: rgba(0, 0, 0, .3); animation: settings-fade calc(160ms * var(--motion-scale)) var(--ease-out); }
:root[data-scheme="light"] .settings-scrim { background: rgba(20, 30, 20, .12); }
.settings-sheet { position: absolute; top: 0; right: 0; bottom: 0; width: min(580px, 64%); overflow: auto; padding: 16px 20px 26px; background: var(--bg-2); box-shadow: -24px 0 48px -20px rgba(0, 0, 0, .55); animation: settings-in calc(200ms * var(--motion-scale)) var(--ease-out); }
:root[data-scheme="light"] .settings-sheet { background: #f6f7f4; box-shadow: -24px 0 48px -22px rgba(20, 40, 60, .25); }
.settings-sheet.full { position: static; flex: 1; width: auto; box-shadow: none; animation: none; }
@keyframes settings-in { from { transform: translateX(18px); opacity: .6; } to { transform: none; opacity: 1; } }
@keyframes settings-fade { from { opacity: 0; } to { opacity: 1; } }
.settings-detail-head { display: grid; gap: 6px; margin: 0 0 6px; }
.settings-back { justify-self: start; display: inline-flex; align-items: center; gap: 4px; border: 0; background: transparent; color: var(--phosphor); font: inherit; font-size: 12.5px; padding: 2px 0; cursor: pointer; }
.settings-back .settings-back-icon { width: 13px; height: 13px; transform: rotate(90deg); }
.settings-detail-title { display: flex; align-items: center; gap: 10px; }
.settings-detail-title b { font-size: 18px; font-weight: 600; }
.settings-reading { margin: 8px 2px; font-size: 13px; color: var(--text-2); }

/* MU/TH/UR's panels, in the room's ink: the console's variables point at the theme's. */
.settings-detail { --ph: var(--text); --ph-dim: var(--text-2); --ph-faint: var(--line-2); color: var(--text); }
/* A result of the search lands here, and says so. */
.settings-found { animation: settings-found 1.6s var(--ease-out); border-radius: 10px; }
@keyframes settings-found { 0%, 40% { box-shadow: 0 0 0 2px color-mix(in srgb, var(--phosphor) 60%, transparent); background-color: color-mix(in srgb, var(--phosphor) 10%, transparent); } 100% { box-shadow: 0 0 0 2px transparent; } }

/* The search, answering over everything. */
.settings-results { flex: 1; overflow: auto; padding: 10px 14px 20px; display: grid; gap: 2px; align-content: start; }
.settings-result { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 44px; padding: 6px 10px; border: 0; border-radius: 10px; background: transparent; color: var(--text); text-align: left; cursor: pointer; font: inherit; }
.settings-result:hover, .settings-result:focus-visible { background: color-mix(in srgb, var(--text) 6%, transparent); outline: none; }
.settings-result b { font-weight: 500; font-size: 13px; }
.settings-result span:last-child { margin-left: auto; font-size: 12px; color: var(--text-2); }

/* A narrow window: a rail of categories and the category beside it, so moving between them is
   one click and never a step back. */
dialog.settings-window.rail .settings-body { display: grid; grid-template-columns: 58px minmax(0, 1fr); }
.settings-rail { display: grid; gap: 6px; align-content: start; padding: 12px 8px; border-right: .5px solid var(--line); }
.settings-rail-item { position: relative; display: grid; place-items: center; width: 42px; height: 42px; border: 0; border-radius: 12px; background: transparent; cursor: pointer; }
.settings-rail-item:hover { background: color-mix(in srgb, var(--text) 6%, transparent); }
.settings-rail-item.on { background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); }
.settings-pending { position: absolute; top: 6px; right: 6px; width: 7px; height: 7px; border-radius: 50%; background: #f2c94c; }
.settings-page { overflow: auto; padding: 14px 16px 22px; }
.settings-page .settings-detail-title b { font-size: 16px; }
/* The board follows the window's width, not the screen's: three sections side by side, or one
   above the other with their two cards side by side. */
.settings-body { container: settings / inline-size; }
@container settings (max-width: 820px) {
  .settings-board { grid-template-columns: 1fr; }
  .settings-section { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .settings-section > header { grid-column: 1 / -1; }
}

/* Inside AJUSTES the console's bright green-white becomes the room's own text, so the memory
   board, its meters and every highlighted figure read in the light theme as well as the dark one. */
.settings-detail :is(.mem-tile .value, .mem-tip strong, .mem-signal .top span, .mem-verdict .maturity-next, .exams .said, .mother-record .e.more.open) { color: var(--text); }
.settings-detail :is(.mem-cols i.on, .mem-meter > .mark) { background: var(--text); }

/* ==========================================================================================
   AJUSTES · the sheets, in blocks. Every category is built from the same pieces: a block is a
   card with a title and a line about it, then rows; a row says what it is on the left and holds
   its control on the right. The room's type throughout, in sentence case; mono only for what is
   literally typed or printed.
   ========================================================================================== */
.settings-host { display: grid; gap: 14px; }
.settings-host + .settings-host { margin-top: 14px; }
.settings-detail-head { margin-bottom: 12px; }
.sx-intro { margin: 0 2px 2px; font-size: 13px; line-height: 1.55; color: var(--text-2); }
.sx-block { min-width: 0; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); overflow: hidden; }
.sx-head { display: flex; align-items: flex-start; gap: 12px; padding: 14px 16px 12px; }
.sx-head .sx-words { flex: 1; min-width: 0; display: grid; gap: 3px; }
.sx-head h3 { margin: 0; font-family: var(--read); font-size: 14.5px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--text); }
.sx-head p { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--text-2); }
.sx-rows:empty { display: none; }
.sx-row { display: flex; align-items: center; gap: 16px; min-height: 52px; padding: 10px 16px; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); }
.sx-row > .sx-words { flex: 1; min-width: 0; display: grid; gap: 2px; }
.sx-row > .sx-words b { font-size: 13.5px; font-weight: 500; color: var(--text); }
.sx-hint { font-size: 12px; line-height: 1.45; color: var(--text-2); }
.sx-row .sx-control { flex: none; display: flex; align-items: center; justify-content: flex-end; max-width: 62%; }
.sx-row.stack { flex-direction: column; align-items: stretch; gap: 10px; }
.sx-row.stack .sx-control { max-width: none; justify-content: stretch; }
.sx-row.stack .sx-control > * { flex: 1; min-width: 0; }
.sx-row.off > .sx-words { opacity: .5; }
.sx-foot { margin: 0; padding: 11px 16px 13px; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); font-size: 12px; line-height: 1.5; color: var(--text-2); }
.sx-link { justify-self: start; padding: 0; border: 0; background: none; color: var(--phosphor); font: inherit; font-size: 12px; text-decoration: none; cursor: pointer; }
.sx-link:hover { text-decoration: underline; }

/* Controls. A button is a soft key; the primary one wears the accent; a danger one says so. */
.sx-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 30px; padding: 0 13px; border: 0; border-radius: 9px; background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text); font-family: var(--read); font-size: 12.5px; font-weight: 550; letter-spacing: 0; white-space: nowrap; cursor: pointer; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06); transition: background-color var(--motion-fast) var(--ease-out), transform var(--motion-fast) var(--ease-out); }
.sx-btn:hover { background: color-mix(in srgb, var(--text) 13%, transparent); }
.sx-btn:active { transform: translateY(1px); }
.sx-btn.primary { background: var(--phosphor); color: var(--phosphor-ink); }
.sx-btn.primary:hover { background: color-mix(in srgb, var(--phosphor) 88%, var(--text)); }
.sx-btn.danger { background: color-mix(in srgb, var(--danger) 14%, transparent); color: var(--danger); }
.sx-btn.danger:hover { background: color-mix(in srgb, var(--danger) 22%, transparent); }
.sx-btn:disabled { opacity: .42; cursor: default; transform: none; }
.sx-btn:focus-visible, .sx-seg button:focus-visible, .sx-pick:focus-visible, .sx-stepper button:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 70%, transparent); outline-offset: 2px; }
.sx-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px 16px 14px; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); }
.sx-actions.inline { padding: 0; border: 0; justify-content: flex-end; }
.sx-actions.end { justify-content: flex-end; border: 0; padding: 4px 2px 0; }

.sx-seg { display: inline-flex; gap: 2px; padding: 2px; border-radius: 10px; background: color-mix(in srgb, var(--text) 7%, transparent); }
.sx-seg button { min-width: 36px; height: 28px; padding: 0 10px; border: 0; border-radius: 8px; background: transparent; color: var(--text-2); font-family: var(--read); font-size: 12.5px; font-weight: 500; cursor: pointer; }
.sx-seg button:hover:not(:disabled) { color: var(--text); }
.sx-seg button[aria-checked="true"] { background: var(--surface, var(--panel)); color: var(--text); font-weight: 650; box-shadow: 0 1px 2px rgba(0, 0, 0, .22), inset 0 1px 0 rgba(255, 255, 255, .06); }
.sx-seg button:disabled { opacity: .32; cursor: default; }
/* The permission modes keep their own colour, here as everywhere. */
.sx-seg button.o0[aria-checked="true"] { color: var(--mode-0); } .sx-seg button.o1[aria-checked="true"] { color: var(--mode-1); }
.sx-seg button.o2[aria-checked="true"] { color: var(--mode-2); } .sx-seg button.o3[aria-checked="true"] { color: var(--mode-3); }
.sx-seg button.o4[aria-checked="true"] { color: var(--mode-4); }

.sx-input { width: 100%; min-width: 0; height: 32px; padding: 0 10px; border: 0; border-radius: 9px; background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text); font-family: var(--read); font-size: 13px; letter-spacing: 0; box-shadow: inset 0 1px 2px rgba(0, 0, 0, .16); transition: box-shadow var(--motion-fast) var(--ease-out); }
.sx-input.mono { font-family: var(--mono); font-size: 12.5px; }
textarea.sx-input { height: auto; padding: 9px 11px; line-height: 1.55; resize: vertical; }
select.sx-input { width: auto; max-width: 100%; padding-right: 8px; cursor: pointer; }
.sx-row:not(.stack) input.sx-input { width: 180px; }
/* A field sinks when it is being written in, the way the composer does. */
.sx-input:focus, .sx-num:focus-within { outline: none; box-shadow: inset 0 3px 9px rgba(0, 0, 0, .36), inset 0 1px 2px rgba(0, 0, 0, .3), 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 40%, transparent); }
:root[data-scheme="light"] :is(.sx-input:focus, .sx-num:focus-within) { box-shadow: inset 0 3px 9px rgba(20, 30, 20, .14), inset 0 1px 2px rgba(20, 30, 20, .12), 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 45%, transparent); }
.sx-num { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px 0 4px; border-radius: 9px; background: color-mix(in srgb, var(--text) 6%, transparent); box-shadow: inset 0 1px 2px rgba(0, 0, 0, .16); cursor: text; }
.sx-num input { width: 84px; height: 30px; padding: 0 6px; border: 0; outline: 0; background: transparent; color: var(--text); font-family: var(--read); font-size: 13px; font-variant-numeric: tabular-nums; text-align: right; -moz-appearance: textfield; }
.sx-num input::-webkit-inner-spin-button, .sx-num input::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
.sx-num span { font-size: 12px; color: var(--text-2); }
.sx-stepper { display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 10px; background: color-mix(in srgb, var(--text) 7%, transparent); }
.sx-stepper button { width: 28px; height: 28px; border: 0; border-radius: 8px; background: transparent; color: var(--text); font-size: 16px; line-height: 1; cursor: pointer; }
.sx-stepper button:hover:not(:disabled) { background: var(--surface, var(--panel)); box-shadow: 0 1px 2px rgba(0, 0, 0, .2); }
.sx-stepper button:disabled { opacity: .3; cursor: default; }
.sx-stepper output { min-width: 26px; text-align: center; font-size: 13.5px; font-weight: 600; font-variant-numeric: tabular-nums; }
.sx-chip { flex: none; align-self: center; padding: 3px 9px; border-radius: 7px; font-size: 12px; font-weight: 550; white-space: nowrap; background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text-2); }
.sx-chip.on { background: color-mix(in srgb, var(--phosphor) 16%, transparent); color: var(--phosphor); }
.sx-chip.off { background: color-mix(in srgb, var(--danger) 14%, transparent); color: var(--danger); }
.sx-chip.busy, .sx-chip.warn { background: color-mix(in srgb, #f2c94c 18%, transparent); color: #d9a90f; }
:root[data-scheme="light"] :is(.sx-chip.busy, .sx-chip.warn) { color: #7a5c00; }
.sx-pick { height: 28px; padding: 0 11px; border: 0; border-radius: 8px; background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text-2); font-family: var(--read); font-size: 12.5px; cursor: pointer; }
.sx-pick[aria-pressed="true"] { background: color-mix(in srgb, var(--phosphor) 16%, transparent); color: var(--text); font-weight: 550; }
.sx-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.sx-field { display: flex; gap: 8px; }
.sx-field .sx-input { flex: 1; }
/* Settings › Connect MCP (2026-10-14): a row per server — what it is and where, how it stands,
   the one thing to do, and from which mode its tools that act travel. */
.mcp-row { gap: 10px; }
.mcp-row .mcp-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; width: 100%; }
.mcp-row .mcp-top .sx-words { min-width: 0; display: grid; gap: 4px; }
.mcp-row .mcp-where { display: block; font-family: var(--mono); font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 52ch; }
.mcp-row.off .mcp-top .sx-words > b { color: var(--text-2); }
.mcp-problem { margin: 0; font-size: 12px; line-height: 1.45; color: var(--danger); overflow-wrap: anywhere; }
.mcp-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.mcp-block > .mcp-actions { padding: 4px 16px 14px; }
.mcp-from { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.mcp-tools { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; }
.mcp-tools li { display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px; border-radius: 7px; background: color-mix(in srgb, var(--text) 6%, transparent); font-size: 11.5px; }
.mcp-tools li code { font-family: var(--mono); font-size: 11.5px; }
.mcp-tools .mcp-tool-kind { font-size: 10px; letter-spacing: .04em; color: var(--text-3); }
.mcp-tools li.acts .mcp-tool-kind { color: #d9a90f; }
.mcp-vars { display: grid; gap: 6px; width: 100%; }
.mcp-vars .sx-field { align-items: center; }
.mcp-secret { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--text-2); white-space: nowrap; }
.mcp-pick { display: inline-flex; align-items: center; }
.mcp-block .sx-row .sx-hint { overflow-wrap: anywhere; }
.mcp-pick input, .mcp-secret input { width: 16px; height: 16px; accent-color: var(--phosphor); }
.sx-command { display: flex; align-items: center; gap: 8px; padding: 4px 4px 4px 10px; border-radius: 9px; background: color-mix(in srgb, var(--text) 5%, transparent); }
.sx-command code { flex: 1; min-width: 0; overflow-x: auto; white-space: nowrap; font-family: var(--mono); font-size: 11.5px; color: var(--text); scrollbar-width: none; }
.sx-more { border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); }
.sx-more > summary { display: flex; align-items: center; gap: 8px; padding: 12px 16px; font-size: 13px; font-weight: 500; color: var(--text); cursor: pointer; list-style: none; }
.sx-more > summary::-webkit-details-marker { display: none; }
.sx-more > summary::after { content: ''; width: 7px; height: 7px; margin-left: auto; border-right: 1.5px solid var(--text-2); border-bottom: 1.5px solid var(--text-2); transform: rotate(-45deg); transition: transform var(--motion-fast) var(--ease-out); }
.sx-more[open] > summary::after { transform: rotate(45deg); }
.sx-more > :not(summary) { margin: 0 16px 14px; }
.sx-steps { display: grid; gap: 12px; margin: 10px 16px 16px; padding-left: 18px; }
.sx-steps li { display: grid; gap: 6px; font-size: 12.5px; }
.sx-steps li b { font-weight: 600; color: var(--text); }
/* The training recipe, numbered and explained (2026-10-14). */
.sx-steps { counter-reset: step; list-style: none; padding-left: 0; gap: 14px; }
.sx-steps li { position: relative; padding-left: 34px; counter-increment: step; }
.sx-steps li::before { content: counter(step); position: absolute; left: 0; top: -1px; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: color-mix(in srgb, var(--phosphor) 16%, transparent); color: var(--phosphor); font: 600 11.5px/1 var(--read); }
.sx-steps li .sx-hint { font-size: 12px; line-height: 1.45; color: var(--text-2); }
.sx-train-what { margin: 0 16px 10px; font-size: 12.5px; line-height: 1.5; color: var(--text-2); }
.sx-train-platform { margin: 10px 16px 6px; }
.sx-more > .sx-hint { margin: 0 16px; }

/* An agent's card: its colour on the avatar and the name, where it lives in small print. */
.sx-agent .sx-head { align-items: center; }
.sx-agent .sx-head h3 { color: var(--agent, var(--text)); }
.sx-meta { display: grid; gap: 2px; padding: 0 16px 12px 60px; margin-top: -6px; font-size: 12px; color: var(--text-2); }
.sx-meta code { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mono); font-size: 11px; color: var(--text-3, var(--text-2)); }
.sx-slot { display: grid; gap: 10px; padding: 0 16px 14px; }
.sx-slot:empty { display: none; }
.sx-agent .sx-row .sx-words .sx-link { margin-top: 2px; }

/* Memory: four figures and how ripe the archive is, before anything to set. */
.sx-glance .sx-head { align-items: center; }
.sx-aside { display: flex; align-items: center; gap: 10px; }
.sx-glance-body { display: grid; gap: 14px; padding: 2px 16px 16px; transition: opacity var(--motion-fast) var(--ease-out); }
.sx-glance-body.loading { opacity: .55; }
.sx-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.sx-stat { display: grid; gap: 2px; align-content: start; min-width: 0; padding: 11px 12px 10px; border-radius: 11px; background: color-mix(in srgb, var(--text) 4.5%, transparent); }
.sx-stat .k { font-size: 12px; color: var(--text-2); }
.sx-stat strong { font-size: 24px; font-weight: 650; letter-spacing: -.01em; line-height: 1.15; font-variant-numeric: tabular-nums; color: var(--text); }
.sx-stat .sub { font-size: 11.5px; color: var(--text-2); }
.sx-spark { display: flex; align-items: flex-end; gap: 2px; height: 22px; margin-top: 6px; }
.sx-spark i { flex: 1; height: var(--h, 2px); min-height: 2px; border-radius: 2px; background: color-mix(in srgb, #3fb6d9 70%, transparent); }
.sx-spark i.zero { background: color-mix(in srgb, var(--text) 12%, transparent); height: 2px; }
.sx-spark i.now { background: #3fb6d9; }
@container settings (max-width: 620px) { .sx-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.sx-ripe { display: grid; gap: 8px; }
.sx-ripe .top { display: flex; align-items: baseline; gap: 10px; }
.sx-ripe .top b { font-size: 13.5px; font-weight: 500; }
.sx-ripe .top .stage { font-size: 12px; color: var(--text-2); }
.sx-ripe .top strong { margin-left: auto; font-size: 15px; font-weight: 650; font-variant-numeric: tabular-nums; }
.sx-ripe p { margin: 0; font-size: 12.5px; line-height: 1.5; color: var(--text-2); }
.sx-ripe p.next { padding: 9px 11px; border-radius: 9px; background: color-mix(in srgb, #3fb6d9 10%, transparent); color: var(--text); }
.sx-ripe p.next b { font-weight: 600; }
.sx-ripe p.next .where { color: var(--text-2); }
.settings-detail .mem-meter { display: block; position: relative; height: 6px; border: 0; border-radius: 999px; background: color-mix(in srgb, var(--text) 10%, transparent); overflow: visible; }
.settings-detail .mem-meter > i { display: block; height: 100%; border-radius: inherit; background: #3fb6d9; box-shadow: none; }

/* The analysis behind the glance: the console's charts, wearing the room's type and ink. */
.settings-detail .sx-analysis { margin: 0 12px 14px; padding: 0; border: 0; background: none; box-shadow: none; }
.settings-detail .sx-analysis .mem-grid { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); gap: 8px; }
.settings-detail .sx-analysis .mem-card { grid-column: span 12; padding: 12px 13px; border: 0; border-radius: 11px; background: color-mix(in srgb, var(--text) 4.5%, transparent); box-shadow: none; }
.settings-detail .sx-analysis .mem-card.span-4 { grid-column: span 4; }
@container settings (max-width: 620px) { .settings-detail .sx-analysis .mem-card.span-4 { grid-column: span 12; } }
.settings-detail .sx-analysis :is(.mem-card h4, .mem-card .note, .mem-card .detail, .mem-bar, .mem-legend, .mem-signal, .mem-signal .top b, .exams, .exam .verdict, .exam-head b, .exams .note, .exam-bullet span, .mem-activity) { font-family: var(--read); letter-spacing: 0; text-transform: none; text-shadow: none; }
.settings-detail .sx-analysis .mem-card h4 { margin: 0 0 10px; font-size: 13px; font-weight: 600; color: var(--text); }
.settings-detail .sx-analysis :is(.note, .detail, .mem-legend, .exams .note) { font-size: 12px; line-height: 1.5; color: var(--text-2); }
.settings-detail .sx-analysis .mem-signal .top b, .settings-detail .sx-analysis .exam-head b { font-size: 12.5px; font-weight: 500; color: var(--text); }
.settings-detail .sx-analysis .mem-bar { font-size: 12px; color: var(--text); }
.settings-detail .sx-analysis .mem-bars .track i, .settings-detail .sx-analysis .mem-split i.search { background: #3fb6d9; box-shadow: none; }
.settings-detail .sx-analysis .exam { padding: 10px 0; border: 0; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); background: none; }
.settings-detail .sx-analysis .exam .verdict { padding: 2px 8px; border: 0; border-radius: 7px; font-size: 11.5px; background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text-2); }
.settings-detail .sx-analysis .exam.passed .verdict { background: color-mix(in srgb, var(--phosphor) 16%, transparent); color: var(--phosphor); }
.settings-detail .sx-analysis .exam button { height: 28px; padding: 0 12px; border: 0; border-radius: 8px; background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text); font-family: var(--read); font-size: 12px; letter-spacing: 0; text-transform: none; box-shadow: none; cursor: pointer; }
.settings-detail .sx-analysis .exam button.primary { background: var(--phosphor); color: var(--phosphor-ink); }

/* Appearance: the same blocks, the preview first. */
.sx-look { display: grid; gap: 14px; }
.sx-preview .sx-rows { padding: 0 14px 14px; }
.sx-preview .look-preview { padding: 6px 12px 14px; border-radius: 11px; background: color-mix(in srgb, var(--bg) 70%, transparent); }
.sx-look .sx-block > .sx-rows > :is(.paper-box, .custom-swatches) { padding: 0 16px 16px; }
.sx-look .sx-head .custom-current { align-self: center; font-size: 12.5px; color: var(--text-2); }
.sx-look .sx-row .custom-seg { border: 0; border-radius: 10px; padding: 2px; gap: 2px; background: color-mix(in srgb, var(--text) 7%, transparent); }
.sx-look .sx-row:not(.stack) .custom-seg { display: inline-grid; grid-auto-flow: column; grid-auto-columns: minmax(64px, auto); grid-template-columns: none; }
.sx-look .sx-row .custom-seg .seg-option { min-height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12.5px; }
.sx-look .sx-row .custom-seg .seg-option[aria-checked="true"] { background: var(--surface, var(--panel)); box-shadow: 0 1px 2px rgba(0, 0, 0, .22), inset 0 1px 0 rgba(255, 255, 255, .06); }

/* The sheet is as wide as you pull it, the way a server's view is: a grip on its edge. */
.settings-sheet { width: var(--sheet-w, min(580px, 64%)); max-width: calc(100% - 120px); min-width: 360px; }
.settings-sheet.full { width: auto; max-width: none; min-width: 0; }
.settings-grip { position: absolute; top: 0; bottom: 0; left: 0; z-index: 2; width: 14px; display: grid; place-items: center; cursor: ew-resize; touch-action: none; }
.settings-grip::after { content: ''; width: 3px; height: 46px; border-radius: 999px; background: var(--line-2); opacity: 0; transition: opacity calc(150ms * var(--motion-scale)), height calc(150ms * var(--motion-scale)); }
.settings-sheet:hover .settings-grip::after { opacity: .6; }
.settings-grip:hover::after, .settings-sheet.dragging .settings-grip::after { opacity: 1; height: 64px; background: var(--phosphor); }
.settings-sheet.dragging { animation: none; transition: none; user-select: none; }

/* The search sinks when it is being written in, as the composer does. */
.settings-search { transition: box-shadow var(--motion-fast) var(--ease-out), background-color var(--motion-fast) var(--ease-out); box-shadow: inset 0 1px 2px rgba(0, 0, 0, .14); }
.settings-search:focus-within { background: color-mix(in srgb, var(--text) 4%, transparent); box-shadow: inset 0 4px 12px rgba(0, 0, 0, .42), inset 0 1px 3px rgba(0, 0, 0, .3); }
:root[data-scheme="light"] .settings-search:focus-within { box-shadow: inset 0 4px 12px rgba(20, 30, 20, .16), inset 0 1px 3px rgba(20, 30, 20, .14); }
.settings-sheet { display: flex; overflow: hidden; padding: 0; }
.settings-scroll { flex: 1; min-width: 0; overflow: auto; padding: 16px 20px 26px; }
.sx-meta code { padding: 0; border: 0; background: none; box-shadow: none; }
.settings-quick-row.agent .who { font-family: var(--read); font-size: 12.5px; letter-spacing: 0; text-transform: none; }
/* The analysis shares its pieces with the core, where they speak in the console's capitals.
   Here they read as sentences, at a size that can be read. */
.settings-detail .sx-analysis :is(.mem-strip-head b, .mem-strip-head span, .mem-axis span, summary b, summary .caret, th, td, .mem-signal .top b, .mem-bar .name, .mem-bar .value, .mem-legend b, .exams > .note, .exam-head b, .exam-head .verdict, .exam-bullet span, .exam > .note:not(.about), .exam .actions button, .exam .actions .note) {
  display: inline-block; font-family: var(--read); font-size: 11.5px; letter-spacing: 0; text-transform: lowercase; text-shadow: none;
}
.settings-detail .sx-analysis :is(.mem-strip-head b, .mem-strip-head span, .mem-axis span, summary b, summary .caret, th, td, .mem-signal .top b, .mem-bar .name, .exams > .note, .exam-head b, .exam-head .verdict, .exam-bullet span, .exam > .note:not(.about), .exam .actions button, .exam .actions .note)::first-letter { text-transform: uppercase; }
.settings-detail .sx-analysis .mem-strip-head b, .settings-detail .sx-analysis .mem-bar .name { color: var(--text); }
.settings-detail .sx-analysis .mem-signal .top b, .settings-detail .sx-analysis .exam-head b { font-size: 12.5px; font-weight: 500; }
/* The review's questions are written in sentence case; lowering them would turn «IA» into «ia». */
.settings-detail .sx-analysis .exam-head b { text-transform: none; }
.settings-detail .sx-analysis .exams .said { font-family: var(--read); font-size: 12.5px; line-height: 1.5; }
.settings-detail .sx-analysis .mem-cols i:not(.zero) { background: color-mix(in srgb, #3fb6d9 70%, transparent); }
.settings-detail .sx-analysis .mem-cols i.now { background: #3fb6d9; }
.settings-detail .sx-analysis .exams { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0; }
.settings-detail .sx-analysis .exams > .note { display: block; margin-bottom: 4px; }
.settings-detail .sx-analysis .exam { display: grid; gap: 6px; padding: 12px 0; border: 0; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); border-radius: 0; background: none; }
.settings-detail .sx-analysis .exam-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }

/* ==========================================================================================
   KEYS, ACCENT AND QUIET TEXT · 6 OCT, NIGHT
   ========================================================================================== */
/* A key is a raised thing: a flat face, no lit edge and no shaded lip (those read as eyebrows),
   and the depth told by what is under it — a tight contact shadow and a soft one below. Over it,
   it lifts a hair; pressed, it goes down and the shadow goes inside. An open panel stays down. */
:root {
  --key-rest: 0 1px 0 rgba(0, 0, 0, .5), 0 1px 2px rgba(0, 0, 0, .38), 0 3px 7px -3px rgba(0, 0, 0, .45);
  --key-over: 0 1px 0 rgba(0, 0, 0, .5), 0 2px 4px rgba(0, 0, 0, .38), 0 7px 14px -6px rgba(0, 0, 0, .5);
  --key-down: inset 0 1px 3px rgba(0, 0, 0, .5), inset 0 0 0 .5px rgba(0, 0, 0, .3);
}
:root[data-scheme="light"] {
  --key-rest: 0 1px 0 rgba(20, 40, 60, .1), 0 1px 2px rgba(20, 40, 60, .12), 0 3px 7px -3px rgba(20, 40, 60, .16);
  --key-over: 0 1px 0 rgba(20, 40, 60, .1), 0 2px 4px rgba(20, 40, 60, .12), 0 7px 14px -6px rgba(20, 40, 60, .2);
  --key-down: inset 0 1px 3px rgba(20, 40, 60, .2), inset 0 0 0 .5px rgba(20, 40, 60, .08);
}
:root .shell .bar > :is(.tree-button, .mother-button), :root .shell > .chats-button, .sx-btn, .settings-back {
  background-image: none;
  box-shadow: var(--key-rest);
  transform: none;
  transition: box-shadow calc(140ms * var(--motion-scale)) var(--ease-out), transform calc(140ms * var(--motion-scale)) var(--ease-out), background-color calc(140ms * var(--motion-scale)) var(--ease-out);
}
:root .shell .bar > :is(.tree-button, .mother-button):hover, :root .shell > .chats-button:hover, .sx-btn:hover:not(:disabled), .settings-back:hover {
  box-shadow: var(--key-over);
  transform: translateY(-.5px);
}
:root .shell .bar > :is(.tree-button, .mother-button):active, :root .shell > .chats-button:active, .sx-btn:active:not(:disabled), .settings-back:active {
  box-shadow: var(--key-down) !important;
  transform: translateY(1px);
}
:root .shell .bar > :is(.tree-button, .mother-button)[aria-pressed="true"], :root .shell > .chats-button[aria-pressed="true"] {
  box-shadow: var(--key-down);
  transform: translateY(1px);
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button), :root[data-scheme="light"] .shell > .chats-button { background-color: #ffffff; }
:root:not([data-scheme="light"]) .shell .bar > :is(.tree-button, .mother-button) { background-color: color-mix(in srgb, #ffffff 7%, var(--surface)); }
:root .shell > .chats-button svg { filter: none; }
/* The settings keys stand on the card: a face a shade off it, the same depth. */
.sx-btn { background: color-mix(in srgb, #ffffff 7%, var(--surface, var(--panel))); }
.sx-btn:hover:not(:disabled) { background: color-mix(in srgb, #ffffff 10%, var(--surface, var(--panel))); }
:root[data-scheme="light"] .sx-btn { background: #ffffff; }
:root[data-scheme="light"] .sx-btn:hover:not(:disabled) { background: #ffffff; }
/* The accent key is the accent and nothing else: no shine on its face. */
.sx-btn.primary, .sx-btn.primary:hover:not(:disabled) { background: var(--phosphor); color: var(--phosphor-ink); }
.sx-btn.danger, .sx-btn.danger:hover:not(:disabled) { background: color-mix(in srgb, var(--danger) 16%, var(--surface, var(--panel))); color: var(--danger); }
.sx-btn:disabled { box-shadow: none; }

/* Back is a small round key beside the title. */
.settings-detail-title { gap: 10px; }
.settings-back { display: grid; place-items: center; width: 28px; height: 28px; flex: none; padding: 0; border: 0; border-radius: 50%; background: color-mix(in srgb, #ffffff 7%, var(--surface, var(--panel))); color: var(--text-2); cursor: pointer; }
:root[data-scheme="light"] .settings-back { background: #ffffff; }
.settings-back:hover { color: var(--text); }
.settings-back .settings-back-icon { width: 14px; height: 14px; transform: rotate(90deg); }
.settings-back:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 70%, transparent); outline-offset: 2px; }

/* The accent reaches all of AJUSTES: switches, chips, picks, the found mark, not only buttons. */
:root[data-accent] #settings { --phosphor: var(--acc); --phosphor-ink: var(--acc-ink); --accent: var(--acc); --accent-ink: var(--acc-ink); }

/* Titles carry the weight; what explains them is set the way a reply reads, light and calm. */
#settings :is(.sx-hint, .sx-head p, .sx-intro, .sx-foot, .sx-meta span, .settings-line, .settings-section > header span, .sx-stat .sub, .sx-stat .k, .sx-ripe p, .custom-note, .settings-reading) { font-weight: var(--read-weight, 300); }
#settings :is(.sx-row > .sx-words b, .settings-quick-row > span:first-child) { font-weight: 450; }

/* A mode chosen moves at once and stays; the row only waits while it saves. */
.sx-seg button { transition: background-color calc(160ms * var(--motion-scale)) var(--ease-out), color calc(160ms * var(--motion-scale)) var(--ease-out), box-shadow calc(160ms * var(--motion-scale)) var(--ease-out); }
.sx-seg.busy { pointer-events: none; }
.sx-seg.busy button[aria-checked="false"] { opacity: .7; }

/* A command and a key inside an agent's card are part of the card, not a terminal dropped in it. */
.sx-slot .mother-cmd { position: relative; margin: 0; padding: 10px 40px 10px 12px; border: 0; border-radius: 10px; background: color-mix(in srgb, var(--text) 5%, transparent); box-shadow: inset 0 1px 2px rgba(0, 0, 0, .14); }
.sx-slot .mother-cmd pre { margin: 0; white-space: pre-wrap; font-family: var(--mono); font-size: 11.5px; line-height: 1.6; color: var(--text); background: none; text-shadow: none; }
.sx-slot .mother-cmd pre .comment, .sx-slot .mother-cmd pre :is(.c, .note) { color: var(--text-2); }
.sx-slot .mother-cmd .copy { position: absolute; top: 7px; right: 7px; display: grid; place-items: center; width: 26px; height: 26px; border: 0; border-radius: 8px; background: color-mix(in srgb, #ffffff 7%, var(--surface, var(--panel))); color: var(--text-2); box-shadow: var(--key-rest); cursor: pointer; }
:root[data-scheme="light"] .sx-slot .mother-cmd .copy { background: #ffffff; }
.sx-slot .key-form { display: grid; gap: 10px; margin: 0; padding: 12px; border: 0; border-radius: 10px; background: color-mix(in srgb, var(--text) 4%, transparent); }
.sx-slot .key-form label { display: grid; gap: 6px; }
.sx-slot .key-form .k { font-family: var(--read); font-size: 12px; font-weight: 450; letter-spacing: 0; text-transform: none; color: var(--text); }
.sx-slot .key-form :is(input, select) { height: 32px; padding: 0 10px; border: 0; border-radius: 9px; background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text); font-family: var(--mono); font-size: 12.5px; box-shadow: inset 0 1px 2px rgba(0, 0, 0, .16); }
.sx-slot .key-form :is(input, select):focus { outline: none; box-shadow: inset 0 3px 9px rgba(0, 0, 0, .3), 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 40%, transparent); }
.sx-slot .key-row { display: flex; align-items: center; gap: 12px; }
.sx-slot .key-row button { height: 30px; padding: 0 13px; border: 0; border-radius: 9px; background: var(--phosphor); color: var(--phosphor-ink); font-family: var(--read); font-size: 12.5px; font-weight: 550; letter-spacing: 0; text-transform: lowercase; box-shadow: var(--key-rest); cursor: pointer; }
.sx-slot .key-row button::first-letter { text-transform: uppercase; }
.sx-slot .key-row button:active { box-shadow: var(--key-down); transform: translateY(1px); }
.sx-slot :is(.key-link, .key-note, .key-said) { font-family: var(--read); font-size: 12px; font-weight: var(--read-weight, 300); letter-spacing: 0; text-transform: none; color: var(--text-2); }
.sx-slot .key-link { display: inline-block; color: var(--phosphor); text-decoration: none; text-transform: lowercase; }
.sx-slot .key-link::first-letter { text-transform: uppercase; }
.sx-slot .key-note, .sx-slot .key-said { margin: 0; }
.sx-slot > .sx-hint { margin: 0; }
.sx-slot .login-log { border-radius: 10px; background: color-mix(in srgb, var(--text) 5%, transparent); border: 0; font-size: 11.5px; }

/* Appearance: the preview stays in view while the colours below it change. */
.sx-look > .sx-preview { position: sticky; top: -16px; z-index: 3; box-shadow: var(--bevel), var(--float); }
.sx-preview .sx-head { padding-bottom: 8px; }
.sx-preview .look-preview { max-height: 232px; overflow: hidden; }
.sx-preview .look-preview .row { margin-top: 6px; }
.sx-look .sx-row .custom-swatches { padding: 2px 0 0; }
.sx-look .paper-tune { border: 0; border-radius: 11px; background: color-mix(in srgb, var(--text) 4%, transparent); }
.sx-look .tune-row { font-family: var(--read); font-size: 12.5px; font-weight: 450; letter-spacing: 0; text-transform: none; color: var(--text); }
.sx-look .tune-value { font-variant-numeric: tabular-nums; color: var(--text-2); letter-spacing: 0; }
.sx-look .paper-tune .custom-seg { border: 0; border-radius: 10px; padding: 2px; background: color-mix(in srgb, var(--text) 7%, transparent); }
.sx-look .paper-tune .custom-seg .seg-option { min-height: 28px; border-radius: 8px; font-size: 12.5px; }
.sx-look .paper-tune .custom-seg .seg-option[aria-checked="true"] { background: var(--surface, var(--panel)); box-shadow: 0 1px 2px rgba(0, 0, 0, .22); }
/* The chosen option is a small raised key in its track, without a lit edge. */
.sx-seg button[aria-checked="true"], .sx-look .custom-seg .seg-option[aria-checked="true"], .settings-seg button.on { box-shadow: var(--key-rest); }

/* The gear in the Finder's and the servers' heads: their settings, one click away. */
.surface-gear { display: inline-grid; place-items: center; width: 28px; height: 28px; flex: none; padding: 0; border: 0; border-radius: 8px; background: transparent; color: var(--text-2); cursor: pointer; transition: background-color var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out); }
.surface-gear svg { width: var(--ico-sm); height: var(--ico-sm); }
.surface-gear:hover { color: var(--text); background: color-mix(in srgb, var(--text) 8%, transparent); }
.surface-gear:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 70%, transparent); outline-offset: 1px; }

/* MU/TH/UR · a condition, remedy first (C1). The terminal stays — phosphor, tags in mono — but
   what is read is set in the reading face, the remedy is the one lit block with its keys inside,
   the why is folded, and saying it did not work is the last line. */
.mother-card { gap: 10px; padding: 14px 16px 12px; }
.mother-card h4 { font-family: var(--read); font-size: 15px; font-weight: 600; letter-spacing: 0; text-transform: none; line-height: 1.35; color: #eaffdf; }
.mother-card .fix { display: grid; gap: 10px; padding: 11px 13px 12px; border-left: 3px solid var(--ph); background: color-mix(in srgb, var(--ph) 9%, transparent); }
.mother-card .fix p.remedy { margin: 0; padding: 0; border: 0; background: none; box-shadow: none; font-family: var(--read); font-size: 13.5px; font-weight: 400; line-height: 1.55; letter-spacing: 0; color: #eaffdf; }
.mother-card .fix p.remedy b { display: block; margin-bottom: 4px; font-family: var(--mono); font-size: 10px; font-weight: 500; letter-spacing: .2em; color: var(--ph); }
.mother-card .fix .actions .act, .mother-card .fix .actions .mother-goto { height: 30px; padding: 0 13px; border: 0; border-radius: 6px; background: var(--ph); color: #031203; font-family: var(--mono); font-size: 10.5px; font-weight: 600; letter-spacing: .12em; box-shadow: 0 1px 0 rgba(0, 0, 0, .6), 0 2px 6px -2px rgba(0, 0, 0, .6); cursor: pointer; transition: transform calc(120ms * var(--motion-scale)) var(--ease-out), box-shadow calc(120ms * var(--motion-scale)) var(--ease-out); }
.mother-card .fix .actions :is(.act, .mother-goto) + :is(.act, .mother-goto) { background: color-mix(in srgb, var(--ph) 16%, transparent); color: var(--ph); }
.mother-card .fix .actions :is(.act, .mother-goto):hover { transform: translateY(-.5px); }
.mother-card .fix .actions :is(.act, .mother-goto):active { transform: translateY(1px); box-shadow: inset 0 1px 3px rgba(0, 0, 0, .5); }
.mother-card .fix .actions .note { flex-basis: 100%; font-family: var(--read); font-size: 11.5px; letter-spacing: 0; color: var(--ph-dim); text-transform: none; }
.mother-card .fix .actions .note::first-letter { text-transform: uppercase; }
.mother-card .per-agent b { font-family: var(--mono); font-size: 10px; letter-spacing: .14em; color: var(--agent, var(--ph)); }
.mother-card .why > summary { display: flex; align-items: center; gap: 8px; font-family: var(--mono); font-size: 10px; letter-spacing: .2em; color: var(--ph-dim); cursor: pointer; list-style: none; }
.mother-card .why > summary::-webkit-details-marker { display: none; }
.mother-card .why > summary::before { content: '▸'; font-size: 9px; transition: transform calc(140ms * var(--motion-scale)) var(--ease-out); }
.mother-card .why[open] > summary::before { transform: rotate(90deg); }
.mother-card .why > summary:hover { color: var(--ph); }
.mother-card .why > p { margin: 8px 0 0; font-family: var(--read); font-size: 13px; font-weight: 300; line-height: 1.6; letter-spacing: 0; color: rgba(210, 255, 190, .85); }
.mother-card .report { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding-top: 9px; border-top: 1px dashed color-mix(in srgb, var(--ph) 22%, transparent); }
.mother-card .report > span { font-family: var(--mono); font-size: 10px; letter-spacing: .16em; color: var(--ph-dim); }
.mother-card .report .act.quiet { height: 26px; padding: 0 11px; border: 1px solid color-mix(in srgb, var(--ph) 45%, transparent); border-radius: 6px; background: transparent; color: var(--ph); font-family: var(--mono); font-size: 10px; letter-spacing: .14em; cursor: pointer; }
.mother-card .report .act.quiet:hover { background: color-mix(in srgb, var(--ph) 12%, transparent); }

/* ==========================================================================================
   MODULES · a board of tiles, like AJUSTES
   ------------------------------------------------------------------------------------------
   The console dialog keeps its machinery (beside, split, window) and wears the room: a sheet of
   the room's glass, tiles of two sizes, and a module's card opening in a sheet over the board.
   ========================================================================================== */
.mods-board { flex: 1; min-width: 0; overflow: auto; display: grid; gap: 14px; align-content: start; padding: 18px 20px 24px; container: mods / inline-size; }
.mods-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
@container mods (max-width: 760px) { .mods-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@container mods (max-width: 380px) { .mods-grid { grid-template-columns: minmax(0, 1fr); } .mods-tile.wide { grid-column: auto; } }
.mods-tile { display: grid; gap: 4px; align-content: start; min-width: 0; min-height: 118px; padding: 13px 14px; border-radius: 16px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); cursor: pointer; outline: none; transition: box-shadow var(--motion-fast) var(--ease-out), transform var(--motion-fast) var(--ease-out); }
.mods-tile.wide { grid-column: span 2; }
.mods-tile:hover { box-shadow: var(--bevel), var(--float); transform: translateY(-1px); }
.mods-tile:focus-visible { box-shadow: var(--bevel), 0 0 0 2px color-mix(in srgb, var(--phosphor) 55%, transparent); }
.mods-tile:not(.on):not(.make) .settings-icon { filter: saturate(.35); opacity: .8; }
.mods-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; }
.mods-name { display: flex; align-items: center; gap: 6px; font-size: 14px; font-weight: 600; }
.mods-dev { padding: 1px 6px; border-radius: 6px; font-size: 10.5px; font-weight: 550; background: color-mix(in srgb, #f2c94c 18%, transparent); color: #d9a90f; }
.mods-line { font-size: 12.5px; font-weight: var(--read-weight, 300); line-height: 1.4; color: var(--text-2); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.mods-tile.make { background: transparent; box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--text) 14%, transparent); }
.mods-tile.make:hover { background: color-mix(in srgb, var(--text) 3%, transparent); box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 45%, transparent); }
.mods-warn { justify-self: start; height: 30px; padding: 0 12px; border: 0; border-radius: 9px; background: color-mix(in srgb, #f2c94c 16%, transparent); color: #d9a90f; font-family: var(--read); font-size: 12.5px; cursor: pointer; }
:root[data-scheme="light"] :is(.mods-warn, .mods-dev) { color: #7a5c00; }
.mods-sheet .settings-detail-title, .module-window-title { flex-wrap: wrap; }
.mods-float { margin-left: auto; height: 28px; font-size: 12px; }

/* A module's card in the sheet or in its window: the same floors, in the room's blocks. */
.mods-detail .module-card { display: grid; gap: 0; max-width: none; padding: 0; border: 0; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); overflow: hidden; color: var(--text); font-family: var(--read); letter-spacing: 0; text-shadow: none; }
.mods-detail .module-card.off > *:not(.actions) { opacity: 1; }
.mods-detail .module-card > * { padding: 13px 16px; }
.mods-detail .module-card > * + * { border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); }
.mods-detail .module-card h4 { font-family: var(--read); font-size: 14.5px; font-weight: 600; letter-spacing: 0; text-transform: none; }
.mods-detail .module-card :is(p, ul, li, .summary) { font-family: var(--read); font-size: 13px; font-weight: var(--read-weight, 300); line-height: 1.55; letter-spacing: 0; text-transform: none; color: var(--text); }
.mods-detail .module-card :is(.state, .vendor, .detail, .note, .update, .card-block h5, .ollama-status, .actions .toggle, .confirm .warn, i) { font-family: var(--read); font-size: 12px; letter-spacing: 0; text-transform: lowercase; color: var(--text-2); font-style: normal; }
.mods-detail .module-card :is(.state, .vendor, .detail, .note, .update, .card-block h5, .confirm .warn)::first-letter { text-transform: uppercase; }
.mods-detail .module-card .confirm :is(.warn, .note).as-written { text-transform: none; }
.mods-detail .module-card .state.on { color: var(--phosphor); }
.mods-detail .module-card .card-block h5 { display: inline-block; font-size: 12.5px; font-weight: 600; color: var(--text); }
.mods-detail .module-card .version b { font-family: var(--mono); font-size: 12px; color: var(--text); }
.mods-detail .module-card :is(.actions, .version) button, .mods-detail .module-card .card-panel button { height: 30px; padding: 0 13px; border: 0; border-radius: 9px; background: color-mix(in srgb, #ffffff 7%, var(--surface, var(--panel))); color: var(--text); font-family: var(--read); font-size: 12.5px; font-weight: 550; letter-spacing: 0; text-transform: lowercase; text-shadow: none; box-shadow: var(--key-rest); cursor: pointer; }
.mods-detail .module-card :is(.actions, .version, .card-panel) button::first-letter { text-transform: uppercase; }
:root[data-scheme="light"] .mods-detail .module-card :is(.actions, .version, .card-panel) button { background: #ffffff; }
.mods-detail .module-card :is(.actions, .version, .card-panel) button.primary { background: var(--phosphor); color: var(--phosphor-ink); }
.mods-detail .module-card :is(.actions, .version, .card-panel) button:active { box-shadow: var(--key-down); transform: translateY(1px); }
.mods-detail .module-card .version .check { width: 30px; padding: 0; }
.mods-detail .module-card .remove-module { color: var(--danger) !important; background: color-mix(in srgb, var(--danger) 14%, var(--surface, var(--panel))) !important; }
.mods-detail .module-card :is(select, input:not([type="checkbox"])) { height: 32px; padding: 0 10px; border: 0; border-radius: 9px; background: color-mix(in srgb, var(--text) 6%, transparent); color: var(--text); font-family: var(--read); font-size: 13px; letter-spacing: 0; box-shadow: inset 0 1px 2px rgba(0, 0, 0, .16); }
.mods-detail .module-card input[type="checkbox"] { accent-color: var(--phosphor); }
.mods-detail .module-card .confirm { border: 0; border-radius: 10px; background: color-mix(in srgb, #f2c94c 10%, transparent); }
.mods-detail .module-card .card-fold { border: 0; }
.mods-detail .module-card .card-fold > summary { font-family: var(--read); font-size: 13px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text); }
.mods-detail .module-card .card-fold > summary :is(b, span, .caret) { font-family: var(--read); letter-spacing: 0; text-transform: lowercase; }
.mods-detail .module-card .card-fold > summary b::first-letter { text-transform: uppercase; }
.mods-detail .module-card .metric b { font-family: var(--read); font-weight: 650; color: var(--text); }
.mods-detail .module-card .metric span { font-family: var(--read); letter-spacing: 0; text-transform: none; color: var(--text-2); }
.mods-detail .module-card .mother-cmd { border: 0; border-radius: 10px; background: color-mix(in srgb, var(--text) 5%, transparent); }
.mods-detail .module-card .mother-cmd pre { color: var(--text); text-shadow: none; }

/* A module floating as its own window. */
dialog.module-window { width: 520px; height: 600px; padding: 0; color: var(--text); background: color-mix(in srgb, var(--bg-2) 94%, transparent); -webkit-backdrop-filter: blur(22px) saturate(1.2); backdrop-filter: blur(22px) saturate(1.2); }
dialog.module-window[open] { display: flex; flex-direction: column; }
dialog.module-window.entering { animation: window-in calc(440ms * var(--motion-scale)) var(--ease-glide); }
.module-window-head { display: flex; align-items: center; gap: 10px; padding: 10px 12px 10px 14px; border-bottom: 1px solid var(--line); cursor: grab; }
.module-window-title { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; }
.module-window-title b { font-size: 14px; font-weight: 600; }
.module-window-body { flex: 1; min-height: 0; overflow: auto; padding: 14px; }

/* Create your module: a guide in steps, over the board. */
dialog.module-guide { width: min(620px, calc(100vw - 32px)); max-height: min(780px, calc(100dvh - 48px)); padding: 0; border: 0; border-radius: 18px; color: var(--text); background: var(--bg-2); box-shadow: var(--bevel), 0 30px 80px -30px rgba(0, 0, 0, .7); overflow: hidden; }
dialog.module-guide[open] { display: flex; flex-direction: column; }
dialog.module-guide::backdrop { background: rgba(0, 0, 0, .4); backdrop-filter: blur(3px); }
.module-guide-head { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px 12px 20px; border-bottom: 1px solid var(--line); }
.module-guide-close { width: 28px; height: 28px; border: 0; border-radius: 50%; background: color-mix(in srgb, #ffffff 7%, var(--surface, var(--panel))); color: var(--text-2); font-size: 16px; box-shadow: var(--key-rest); cursor: pointer; }
.module-guide-body { overflow: auto; display: grid; gap: 14px; padding: 18px 20px 22px; }
.guide-steps { display: grid; gap: 10px; margin: 0; padding: 0; list-style: none; counter-reset: guide; }
.guide-steps > li { counter-increment: guide; position: relative; display: grid; gap: 8px; justify-items: start; padding: 13px 16px 14px 52px; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); }
.guide-steps > li::before { content: counter(guide); position: absolute; left: 16px; top: 13px; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; font-size: 12.5px; font-weight: 650; background: color-mix(in srgb, var(--phosphor) 16%, transparent); color: var(--phosphor); }
.guide-steps > li > b { font-size: 14px; font-weight: 600; }
.guide-steps > li > p { margin: 0; font-size: 12.5px; font-weight: var(--read-weight, 300); line-height: 1.5; color: var(--text-2); }
.guide-where { display: grid; grid-template-columns: auto 1fr; gap: 4px 10px; align-items: baseline; font-size: 12px; color: var(--text-2); }
.guide-where code { font-family: var(--mono); font-size: 11.5px; color: var(--text); }
:root[data-accent] :is(#modules, #module-guide, .module-window) { --phosphor: var(--acc); --phosphor-ink: var(--acc-ink); --accent: var(--acc); --accent-ink: var(--acc-ink); }
.mods-detail .module-card .state { padding: 2px 8px; border-radius: 7px; font-size: 12px; font-weight: 550; text-transform: none; background: color-mix(in srgb, var(--text) 8%, transparent); }
.mods-detail .module-card .state::before { display: none; }
.mods-detail .module-card .state.on { background: color-mix(in srgb, var(--phosphor) 16%, transparent); }
.mods-detail .module-card :is(.intents-table, .intents-head, .intents-live, .intents-pair) { font-family: var(--read); font-size: 12px; letter-spacing: 0; text-shadow: none; color: var(--text); }
.mods-detail .module-card .intents-table > span { text-transform: lowercase; }
.mods-detail .module-card .intents-table > span:first-child, .mods-detail .module-card .intents-table > span:nth-child(4n + 1) { display: inline-block; }
.mods-detail .module-card .intents-table > span:nth-child(4n + 1)::first-letter { text-transform: uppercase; }
.mods-detail .module-card .intents-table > span:not(:nth-child(4n + 1)) { color: var(--text-2); }
.mods-detail .module-card .intents-head { font-weight: 600; }
.mods-detail .module-card .card-fold > summary { display: flex; align-items: center; gap: 8px; }
.mods-detail .module-card .ollama-status { font-size: 12.5px; text-transform: none; }
.mods-detail .module-card .ollama-status dd { color: var(--text); }
.mods-detail .module-card .card-toggles { display: flex; flex-wrap: wrap; gap: 8px 18px; }
.mods-detail .module-card .card-toggles label { display: inline-flex; align-items: center; gap: 7px; font-family: var(--read); font-size: 12.5px; letter-spacing: 0; text-transform: lowercase; color: var(--text); }
.mods-detail .module-card .card-toggles label > span:last-child, .mods-detail .module-card .card-toggles label { text-transform: none; }
.guide-where code { padding: 0; border: 0; background: none; box-shadow: none; }
.mods-detail .module-card .metric span { display: block; font-size: 11.5px; text-transform: lowercase; }
.mods-detail .module-card .metric span::first-letter { text-transform: uppercase; }

/* ==========================================================================================
   ROUND OF 6 OCT, LATE NIGHT: MODULES AS SMALL APPS, KEYS LIT FROM ABOVE, THE LIVE LIGHT
   ========================================================================================== */
/* (7) A window carried keeps its own colour: AJUSTES, MODULES and a module's window are the
   room's bg-2, not the white panel the other windows wear while they are held. */
dialog.surface.window:is(.settings-window, .module-window).lifted { background-color: var(--bg-2) !important; }

/* (3) Every tile the same size; its mark in the accent, badge and all; off, it waits in grey. */
.mods-tile { min-height: 112px; }
.mods-tile .settings-icon, .mods-detail .settings-detail-title .settings-icon, .module-window-title .settings-icon { --cat: var(--phosphor); }
.mods-tile:not(.on):not(.make) .settings-icon { --cat: var(--text-2); filter: none; opacity: 1; }
.mods-app { justify-self: start; margin-top: 6px; padding: 2px 8px; border-radius: 7px; font-size: 11.5px; font-weight: 500; color: var(--phosphor); background: color-mix(in srgb, var(--phosphor) 12%, transparent); }
:root[data-scheme="light"] .mods-app { color: color-mix(in srgb, var(--phosphor) 80%, #000); }

/* (5) What explains a title reads like the conversation: the reading face at a normal weight, in
   an ink that holds on glass and on white alike. */
:is(#settings, #modules, #module-guide, .module-window) :is(.sx-hint, .sx-head p, .sx-intro, .sx-foot, .sx-meta span, .settings-line, .settings-section > header span, .sx-stat .sub, .sx-stat .k, .sx-ripe p, .custom-note, .settings-reading, .mods-line, .guide-steps > li > p, .guide-where, .settings-quick-row .state) {
  font-family: var(--read); font-weight: 400; color: color-mix(in srgb, var(--text) 66%, transparent);
}
:is(#settings, #modules, #module-guide, .module-window) .mods-detail .module-card :is(p, ul, li, .summary) { font-weight: 400; }

/* (8) The window's own name carries weight: AJUSTES, MÓDULOS and the guide, on one line with their keys. */
.module-window-title b { font-size: 14.5px; font-weight: 650; }

/* (4) An accent key is the accent, wherever it stands and in either theme. */
:root .sx-btn.primary, :root[data-scheme] .sx-btn.primary, :root[data-scheme] .sx-btn.primary:hover:not(:disabled) { background: var(--phosphor); color: var(--phosphor-ink); }
.module-guide-body { gap: 16px; }
.guide-steps > li { padding: 14px 16px 15px 54px; }
.guide-steps > li .sx-btn { margin-top: 2px; }
#module-guide .sx-block .sx-rows { display: grid; }

/* (9) Keys: no line round them, ever — not over them, not pressed, not focused by the pointer.
   The light falls from above: a face a shade brighter at the top than at the bottom, and the
   depth told by the shadow under it. */
:root .shell .bar > :is(.tree-button, .mother-button), :root .shell .bar > :is(.tree-button, .mother-button):is(:hover, :focus, :active, [aria-pressed="true"]),
:root .shell > .chats-button, :root .shell > .chats-button:is(:hover, :focus, :active, [aria-pressed="true"]) { border-color: transparent !important; outline: none; }
:root .shell .bar > :is(.tree-button, .mother-button):focus-visible, :root .shell > .chats-button:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 60%, transparent); outline-offset: 2px; }
:root:not([data-scheme="light"]) .shell .bar > :is(.tree-button, .mother-button), :root:not([data-scheme="light"]) .shell > .chats-button, :root:not([data-scheme="light"]) :is(.sx-btn:not(.primary):not(.danger), .settings-back, .module-guide-close) {
  background-image: linear-gradient(180deg, rgba(255, 255, 255, .075), rgba(255, 255, 255, .015) 70%, rgba(0, 0, 0, .04));
}
:root[data-scheme="light"] .shell .bar > :is(.tree-button, .mother-button), :root[data-scheme="light"] .shell > .chats-button, :root[data-scheme="light"] :is(.sx-btn:not(.primary):not(.danger), .settings-back, .module-guide-close) {
  background-image: linear-gradient(180deg, #ffffff, #f3f4f0);
}
:root .shell .bar > :is(.tree-button, .mother-button):is(:active, [aria-pressed="true"]), :root .shell > .chats-button:is(:active, [aria-pressed="true"]), :is(.sx-btn, .settings-back):active { background-image: none; }

/* (10) The path in the bar: the project first and heavier, the conversation after it and lighter,
   and on the conversation the light that says the room is live — a green dot that breathes. Its
   word comes up under the pointer. */
.bar-left #project { color: var(--text); font-weight: 600; }
.bar-left .project.chat-here { color: var(--text-2); font-weight: 400; }
.bar-left .connection { position: relative; align-self: flex-start; margin: 9px 0 0 -2px; padding: 4px; text-transform: none; cursor: default; }
.bar-left .connection :is(.connection-icon .bar-glyph, .connection-label) { display: none; }
.bar-left .connection .connection-dot { width: 7px; height: 7px; background: var(--text-3); box-shadow: none; }
.bar-left .connection[data-state="live"] .connection-dot { background: #34d058; animation: state-pulse 2.6s ease-in-out infinite; }
.bar-left .connection[data-state="reconnecting"] .connection-dot { background: var(--warn); animation: state-pulse 1.1s ease-in-out infinite; }
.bar-left .connection:is([data-state="offline"], [data-state="closed"], [data-state="disconnected"]) .connection-dot { background: var(--danger, #e5484d); animation: none; }
/* The project's state is a dot that breathes, nothing more (2026-10-14): from its size to a little
   larger and back, in the colour of the state. No glow around it. */
@keyframes state-pulse { 0%, 100% { transform: scale(.85); } 50% { transform: scale(1.15); } }
:root.just-arrived .bar-left .connection[data-state="live"] .connection-dot { animation: state-pulse 2.6s ease-in-out infinite; }
.bar-left .connection::after { content: attr(data-said); position: absolute; top: calc(100% + 8px); left: 50%; translate: -50% 0; padding: 4px 9px; border-radius: 8px; font-family: var(--read); font-size: 12px; font-weight: 500; white-space: nowrap; color: var(--text); background: var(--surface, var(--panel)); box-shadow: var(--key-rest); opacity: 0; pointer-events: none; transition: opacity var(--motion-fast) var(--ease-out); z-index: 60; }
.bar-left .connection:hover::after { opacity: 1; }
.bar-left .connection::first-letter { text-transform: none; }
@media (prefers-reduced-motion: reduce) { .bar-left .connection .connection-dot { animation: none !important; opacity: 1; } }

/* (1) A module as a small app: its card and, for Ash, the whole economy, in the room's blocks. */
.module-window-body { display: grid; gap: 14px; align-content: start; }
.module-app { display: grid; gap: 12px; }
.module-app :is(.card-block, .economy-strip) { padding: 13px 16px; border: 0; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); color: var(--text); font-family: var(--read); letter-spacing: 0; text-shadow: none; }
.module-app .card-block.wide { overflow-x: auto; }
.module-app .economy-strip { display: grid; grid-template-columns: repeat(auto-fill, minmax(118px, 1fr)); gap: 10px; }
.module-app .economy-stat { display: grid; gap: 2px; }
.module-app .economy-stat b { font-size: 20px; font-weight: 650; color: var(--text); }
.module-app :is(.economy-stat span, .card-head span, th, .ash-block b, .ash-agent > b, .ash-side) { display: inline-block; font-family: var(--read); font-size: 12px; letter-spacing: 0; text-transform: lowercase; color: color-mix(in srgb, var(--text) 66%, transparent); }
.module-app :is(.economy-stat span, .card-head span, th, .ash-block b, .ash-agent > b, .ash-side)::first-letter { text-transform: uppercase; }
.module-app .card-head { display: flex; align-items: center; gap: 8px; margin: 0 0 8px; }
.module-app .card-head span { font-size: 13.5px; font-weight: 600; color: var(--text); }
.module-app .card-head .pixel-icon { color: var(--phosphor); }
.module-app .economy-headline { font-size: 28px; font-weight: 650; color: var(--text); }
.module-app :is(p, .note, .unit-note, .ash-verdict, .ash-waiting) { margin: 6px 0 0; font-family: var(--read); font-size: 12.5px; font-weight: 400; line-height: 1.5; letter-spacing: 0; text-transform: none; color: color-mix(in srgb, var(--text) 66%, transparent); }
.module-app table { width: 100%; border-collapse: collapse; font-family: var(--read); font-size: 12px; }
.module-app :is(th, td) { padding: 6px 8px; text-align: right; border-bottom: 1px solid color-mix(in srgb, var(--text) 7%, transparent); color: var(--text); }
.module-app tr > :first-child { text-align: left; }
.module-app :is(.ash-blocks, .ash-compare) { display: grid; gap: 6px; padding: 13px 16px; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--bevel), var(--float-sm); }
.module-app :is(.ash-block, .ash-bar) { display: grid; grid-template-columns: minmax(80px, 140px) 1fr auto; align-items: center; gap: 10px; font-family: var(--read); font-size: 12px; color: var(--text); }
.module-app :is(.ash-block, .ash-bar) > i { height: 6px; border-radius: 999px; background: var(--phosphor); }
/* The conversation's name is as wide as its words, so the live light sits right after them. */
.bar-left .project.chat-here { flex: 0 1 auto; width: auto; min-width: 0; }
.bar-left .connection { align-self: center; margin: 0 0 0 1px; transform: translateY(-7px); }
.bar-left .connection::after { top: 50%; left: calc(100% + 6px); translate: 0 -50%; padding: 3px 8px; font-size: 11.5px; box-shadow: none; background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text-2); }
.mods-tile:not(.on):not(.make) .settings-icon { --cat: var(--text-2) !important; }
/* Ash's economy in its window: figures over their labels, in grids that follow the window's width. */
.module-app .economy-stat { padding: 10px 12px; border: 0; border-radius: 11px; background: color-mix(in srgb, var(--text) 4.5%, transparent); }
.module-app .economy-stat b, .module-app .economy-headline, .module-app .ash-block > span { font-family: var(--read); font-variant-numeric: tabular-nums; }
.module-app .metrics { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 8px; margin-top: 10px; }
.module-app .metric { display: grid; gap: 2px; padding: 9px 11px; border-radius: 10px; background: color-mix(in srgb, var(--text) 4.5%, transparent); }
.module-app .metric b { font-family: var(--read); font-size: 17px; font-weight: 650; color: var(--text); }
.module-app .metric span { display: block; font-family: var(--read); font-size: 12px; letter-spacing: 0; text-transform: lowercase; color: color-mix(in srgb, var(--text) 66%, transparent); }
.module-app .metric span::first-letter { text-transform: uppercase; }
.module-app .card-head span { display: inline-block; text-transform: lowercase; }
.module-app .card-head span::first-letter { text-transform: uppercase; }
.module-app td, .module-app tbody th { font-variant-numeric: tabular-nums; }
.module-app tbody th { text-transform: none; color: var(--text); font-weight: 600; }
.module-app .ash-blocks, .module-app .ash-compare { padding: 0; box-shadow: none; background: none; margin-top: 8px; }
.module-app .ash-agent { display: grid; gap: 6px; padding-top: 8px; }
.module-app .ash-agent > b { font-weight: 600; color: var(--text); }
.module-guide-body { flex: 1 1 auto; min-height: 0; }
.module-guide-body { grid-auto-rows: max-content; align-content: start; }
.settings-host, .sx-look, .module-window-body { grid-auto-rows: max-content; }

/* ==========================================================================================
   ONE KEY FOR EVERY BUTTON · SOFT UI
   ------------------------------------------------------------------------------------------
   A key is made of the surface it stands on: the same colour, no line, no gradient. It is raised
   by two soft shadows — light from the top left, shade to the bottom right — and pressed, the
   same two shadows go inside it. Every button in the room is this key: the bar's, the
   conversations', AJUSTES', MODULES', a window's own keys, the chosen option of a selector.
   ========================================================================================== */
:root {
  --neu-hi: rgba(255, 255, 255, .06);
  --neu-lo: rgba(0, 0, 0, .62);
  --key-rest: -2px -2px 5px var(--neu-hi), 3px 3px 7px var(--neu-lo);
  --key-over: -3px -3px 7px var(--neu-hi), 4px 4px 10px var(--neu-lo);
  --key-down: inset 2px 2px 5px var(--neu-lo), inset -2px -2px 5px var(--neu-hi);
  --key-track: inset 1.5px 1.5px 4px var(--neu-lo), inset -1.5px -1.5px 4px var(--neu-hi);
}
:root[data-scheme="light"] {
  --neu-hi: rgba(255, 255, 255, .95);
  --neu-lo: rgba(150, 158, 148, .5);
}
:root .shell .bar > :is(.tree-button, .mother-button), :root .shell > .chats-button,
.sx-btn, .settings-back, .module-guide-close, .surface-gear, .mods-detail .module-card :is(.actions, .version, .card-panel) button, .sx-slot .mother-cmd .copy {
  border: 0 !important; background-image: none !important; background-color: var(--surface, var(--panel)) !important;
  box-shadow: var(--key-rest) !important; transform: none !important;
  transition: box-shadow calc(160ms * var(--motion-scale)) var(--ease-out), color calc(160ms * var(--motion-scale)) var(--ease-out) !important;
}
:root .shell .bar > :is(.tree-button, .mother-button) { background-color: var(--surface) !important; }
:root .shell .bar > :is(.tree-button, .mother-button):hover, :root .shell > .chats-button:hover,
:is(.sx-btn, .settings-back, .module-guide-close, .surface-gear):hover:not(:disabled), .mods-detail .module-card :is(.actions, .version, .card-panel) button:hover:not(:disabled) { box-shadow: var(--key-over) !important; }
:root .shell .bar > :is(.tree-button, .mother-button):is(:active, [aria-pressed="true"]), :root .shell > .chats-button:is(:active, [aria-pressed="true"]),
:is(.sx-btn, .settings-back, .module-guide-close, .surface-gear):active:not(:disabled), .mods-detail .module-card :is(.actions, .version, .card-panel) button:active:not(:disabled) { box-shadow: var(--key-down) !important; }
/* The accent key keeps its colour; its relief is the same. */
:root .sx-btn.primary, :root[data-scheme] .sx-btn.primary, :root[data-scheme] .sx-btn.primary:hover:not(:disabled),
:root[data-scheme] .mods-detail .module-card :is(.actions, .version, .card-panel) button.primary { background-color: var(--phosphor) !important; color: var(--phosphor-ink) !important; }
:root[data-scheme] .sx-btn.danger { background-color: var(--surface, var(--panel)) !important; color: var(--danger) !important; }
:is(.sx-btn, .mods-detail .module-card button):disabled { box-shadow: none !important; opacity: .45; }
/* A window's keys: a pressed track, the mode that is on raised inside it. */
.surface-modes { border: 0 !important; background: transparent !important; box-shadow: var(--key-track); padding: 3px; border-radius: 10px; }
.surface-modes .surface-mode { border-radius: 7px; }
.surface-modes .surface-mode[aria-pressed="true"] { background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.surface-modes .surface-mode.close:hover { box-shadow: var(--key-rest); background: var(--surface, var(--panel)); }
/* The selectors: a pressed track, the chosen option raised. */
:is(.sx-seg, .settings-seg, .sx-stepper, .sx-look .custom-seg) { background: transparent !important; box-shadow: var(--key-track); }
:is(.sx-seg button[aria-checked="true"], .settings-seg button.on, .sx-look .custom-seg .seg-option[aria-checked="true"]) { background: var(--surface, var(--panel)) !important; box-shadow: var(--key-rest) !important; }
.sx-stepper button:hover:not(:disabled) { background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
/* Fields are the pressed half of the same material. */
:is(.sx-input, .sx-num, .settings-search) { background: transparent !important; box-shadow: var(--key-track) !important; }
:is(.sx-input:focus, .sx-num:focus-within, .settings-search:focus-within) { box-shadow: var(--key-down), 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 40%, transparent) !important; }

/* ==========================================================================================
   MODULES · the window
   ========================================================================================== */
dialog.mods-window { width: 1040px; height: 720px; container: modswin / inline-size; }
.mods-head .custom-title { flex: none; }
.mods-head .mods-search { flex: 1 1 200px; min-width: 0; max-width: 420px; }
.mods-head .mods-add { flex: none; height: 30px; padding: 0 12px; gap: 4px; }
.mods-head .surface-modes { margin-left: 0; }
#modules-list.mods-body { position: relative; flex: 1; min-height: 0; display: flex; overflow: hidden; container: settings / inline-size; }
@container modswin (max-width: 640px) {
  .mods-head { gap: 8px; padding-left: 14px; }
  .mods-head .mods-add-word { display: none; }
  .mods-head .mods-add { width: 30px; padding: 0; justify-content: center; }
}
@container modswin (max-width: 440px) {
  .mods-head .custom-title { display: none; }
}
@container mods (max-width: 900px) { .mods-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@container mods (max-width: 640px) { .mods-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@container mods (max-width: 360px) { .mods-grid { grid-template-columns: minmax(0, 1fr); } }

/* A module's dashboard: its figures first, in the room's tiles. */
.mods-stats { display: grid; grid-template-columns: repeat(auto-fill, minmax(132px, 1fr)); gap: 10px; margin: 0 0 14px; }
.mods-stat { display: grid; gap: 3px; align-content: start; min-width: 0; padding: 12px 13px; border-radius: 13px; background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.mods-stat .k { font-size: 12px; font-weight: 400; color: color-mix(in srgb, var(--text) 66%, transparent); }
.mods-stat strong { font-size: 18px; font-weight: 650; line-height: 1.2; font-variant-numeric: tabular-nums; color: var(--text); overflow-wrap: anywhere; }
.mods-stat .sub { font-size: 11.5px; color: color-mix(in srgb, var(--text) 58%, transparent); }
/* In the sheet and the window the title already names it and the dashboard says how it is: the
   card's own name line, its state and its console folds step back. */
.mods-detail .module-card .head .top, .mods-detail .module-card > .card-fold { display: none; }
.mods-detail .module-card .head { padding-top: 14px; }
.mods-detail > .sx-block, .module-window-body > .sx-block { margin-top: 14px; }
.mods-detail .sx-row .sx-words .sx-chip { justify-self: start; margin-bottom: 3px; }
.mods-commands { display: flex; flex-wrap: wrap; gap: 8px; padding: 2px 16px 16px; }
.mods-commands code { padding: 5px 10px; border-radius: 8px; font-family: var(--mono); font-size: 12px; color: var(--text); background: transparent; box-shadow: var(--key-track); }
.settings-detail-title .mods-dev { align-self: center; }

/* Appearance: the preview never moves. The sheet stops scrolling as a whole; the preview stays at
   the top and only the choices under it scroll. */
/* Room above the path for the live light and its glow, without letting a long name spill. */
.bar > .bar-left { padding-block: 10px; margin-block: -10px; }

/* ==========================================================================================
   A MODULE'S SHEET · the same hierarchy as AJUSTES
   ========================================================================================== */
/* (9) Appearance scrolls as one: the preview goes with its section. */
.sx-look > .sx-preview { position: static !important; }
.sx-look-controls { display: grid; grid-auto-rows: max-content; gap: 14px; }

/* (4) Figures that read as figures: a bento of tiles, the one the module is about larger. */
.mods-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: minmax(92px, auto); gap: 12px; margin: 0 0 16px; }
.mods-stats.loading { min-height: 92px; }
.mods-stat { display: flex; flex-direction: column; justify-content: space-between; gap: 6px; padding: 14px 16px; border-radius: 16px; background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.mods-stat .k { order: 0; font-size: 12px; font-weight: 500; color: color-mix(in srgb, var(--text) 62%, transparent); }
.mods-stat strong { order: 1; font-size: 24px; font-weight: 700; letter-spacing: -.015em; line-height: 1.1; font-variant-numeric: tabular-nums; color: var(--text); }
.mods-stat .sub { order: 2; font-size: 11.5px; line-height: 1.35; color: color-mix(in srgb, var(--text) 56%, transparent); }
.mods-stat.hero { grid-column: span 2; grid-row: span 2; justify-content: flex-end; }
.mods-stat.hero strong { font-size: 40px; letter-spacing: -.025em; color: var(--phosphor); }
:root[data-scheme="light"] .mods-stat.hero strong { color: color-mix(in srgb, var(--phosphor) 85%, #000); }
.mods-stat.hero .k { margin-bottom: auto; font-size: 13px; }
@container settings (max-width: 560px) { .mods-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); } .mods-stat.hero { grid-row: span 1; } .mods-stat.hero strong { font-size: 32px; } }

/* The version sits with its key, on the row's right. */
.mods-version { padding: 4px 9px; border-radius: 8px; font-family: var(--mono); font-size: 12px; color: var(--text); background: transparent; box-shadow: var(--key-track); }
.mods-detail .sx-row .sx-actions.inline { flex: none; gap: 8px; }

/* (2) What it touches: the tag and the words on one line, the words in the reading weight. */
.sx-row.mods-touch { display: grid; grid-template-columns: 84px minmax(0, 1fr); align-items: baseline; gap: 12px; min-height: 44px; }
.sx-row.mods-touch .sx-chip { justify-self: start; }
.sx-row.mods-touch > span:last-child { font-size: 13.5px; font-weight: 400; line-height: 1.45; color: var(--text); }

/* A module's reading is its own set of cards, not a card inside a card. */
.sx-block.mods-reading { background: none; box-shadow: none; overflow: visible; }
.sx-block.mods-reading > .sx-head { padding: 6px 4px 10px; }
.sx-block.mods-reading > .sx-rows > * { border-top: 0; }

/* (5) Ash's economy as a bento: the six figures in one even row of tiles, then the readings in
   pairs of equal height, the table across. */
.mods-detail .economy-app { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; align-items: stretch; }
.mods-detail .economy-app > :is(.economy-strip, .card-block.wide, p) { grid-column: 1 / -1; }
.mods-detail .economy-app > .card-block { display: flex; flex-direction: column; gap: 4px; margin: 0; padding: 16px 18px; border-radius: 16px; box-shadow: var(--key-rest); }
.mods-detail .economy-app .economy-strip { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; padding: 0; background: none; box-shadow: none; }
.mods-detail .economy-app .economy-stat { display: flex; flex-direction: column; justify-content: space-between; gap: 6px; min-height: 84px; padding: 12px 13px; border-radius: 14px; background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.mods-detail .economy-app .economy-stat b { font-size: 19px; font-weight: 700; }
.mods-detail .economy-app .economy-headline { font-size: 32px; font-weight: 700; letter-spacing: -.02em; color: var(--phosphor); }
:root[data-scheme="light"] .mods-detail .economy-app .economy-headline { color: color-mix(in srgb, var(--phosphor) 85%, #000); }
.mods-detail .economy-app .metrics { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.mods-detail .economy-app .metric { background: transparent; box-shadow: var(--key-track); }
.mods-detail .economy-app .card-head span { font-size: 14px; font-weight: 650; color: var(--text); }
@container settings (max-width: 720px) { .mods-detail .economy-app .economy-strip { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@container settings (max-width: 520px) { .mods-detail .economy-app { grid-template-columns: minmax(0, 1fr); } .mods-detail .economy-app .economy-strip, .mods-detail .economy-app .metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.module-window-body { container: settings / inline-size; }

/* Intenciones' reading: one card per agent, its table in the room's type. */
.mods-detail .mods-intents .card-block { display: grid; gap: 12px; padding: 0; border: 0; background: none; box-shadow: none; }
.mods-detail .mods-intents .card-block > h5 { display: none; }
.mods-detail .mods-reading .intents-agent { display: grid; gap: 10px; padding: 16px 18px; border: 0; border-radius: 16px; background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.mods-detail .mods-reading .intents-head { font-family: var(--read); font-size: 14px; font-weight: 650; letter-spacing: 0; color: var(--text); text-shadow: none; }
.mods-detail .mods-reading .intents-table { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, .7fr) 3ch minmax(0, 2fr); gap: 0; font-family: var(--read); font-size: 12.5px; letter-spacing: 0; }
.mods-detail .mods-reading .intents-table > span { padding: 8px 0; border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent); text-transform: none; color: color-mix(in srgb, var(--text) 66%, transparent); }
.mods-detail .mods-reading .intents-table > span:nth-child(-n + 4) { border-top: 0; }
.mods-detail .mods-reading .intents-table .intent-kind { font-weight: 500; color: var(--text); }
.mods-detail .mods-reading .intents-table .intent-n { text-align: right; padding-right: 12px; font-variant-numeric: tabular-nums; }
.mods-detail .mods-reading :is(.note, p) { margin: 0; font-family: var(--read); font-size: 12.5px; font-weight: 400; letter-spacing: 0; text-transform: none; color: color-mix(in srgb, var(--text) 66%, transparent); }
.mods-detail .mods-reading .actions { display: flex; flex-wrap: wrap; gap: 8px; }
.mods-detail .mods-reading button { height: 30px; padding: 0 13px; border: 0; border-radius: 9px; font-family: var(--read); font-size: 12.5px; font-weight: 550; letter-spacing: 0; text-transform: none; color: var(--text); background: var(--surface, var(--panel)); box-shadow: var(--key-rest); cursor: pointer; }
.mods-detail .mods-reading button.primary { background: var(--phosphor); color: var(--phosphor-ink); }
.mods-detail .mods-reading button:active { box-shadow: var(--key-down); }
.mods-detail .mods-reading button:disabled { opacity: .45; box-shadow: none; }

/* Keys, and a module that installs: their own markup in the room's type. */
.mods-keys .sx-rows, .mods-legacy .sx-rows { padding: 4px 16px 16px; }
.mods-keys :is(.card-block, .card-secret) { display: grid; gap: 8px; border: 0; padding: 0; background: none; }
.mods-keys .card-block > h5 { display: none; }
.mods-keys label.control { display: grid; gap: 6px; font-family: var(--read); font-size: 13px; font-weight: 500; letter-spacing: 0; text-transform: none; color: var(--text); }
.mods-keys input { height: 32px; padding: 0 10px; border: 0; border-radius: 9px; background: transparent; color: var(--text); font-family: var(--mono); font-size: 12.5px; box-shadow: var(--key-track); }
.mods-keys :is(.note, a.note) { font-family: var(--read); font-size: 12px; letter-spacing: 0; text-transform: none; color: color-mix(in srgb, var(--text) 66%, transparent); }
.mods-keys button { height: 30px; padding: 0 13px; border: 0; border-radius: 9px; font-family: var(--read); font-size: 12.5px; letter-spacing: 0; text-transform: none; color: var(--text); background: var(--surface, var(--panel)); box-shadow: var(--key-rest); cursor: pointer; }
.mods-legacy .module-card { box-shadow: none; }

/* (1) MODULES' keys on the right edge, like every other window. */
.mods-head .mods-add { margin-left: auto; }

/* (6) A field sinks when written in, and nothing glows round it. */
:is(.sx-input:focus, .sx-num:focus-within, .settings-search:focus-within) { box-shadow: var(--key-down) !important; outline: none; }
.settings-search svg { color: color-mix(in srgb, var(--text) 55%, transparent) !important; }

/* (8)(10) Selectors: the track has room round its options, the chosen one is raised and heavier. */
:is(.sx-seg, .settings-seg, .sx-look .custom-seg, .sx-stepper) { padding: 4px !important; gap: 4px !important; border-radius: 12px !important; position: relative; }
:is(.sx-seg button, .settings-seg button, .sx-look .custom-seg .seg-option) { min-height: 28px; border-radius: 8px !important; font-weight: 450; transition: color calc(160ms * var(--motion-scale)) var(--ease-out), box-shadow calc(160ms * var(--motion-scale)) var(--ease-out), background-color calc(160ms * var(--motion-scale)) var(--ease-out); }
:is(.sx-seg button[aria-checked="true"], .settings-seg button.on, .sx-look .custom-seg .seg-option[aria-checked="true"]) { font-weight: 700 !important; color: var(--text) !important; }
/* While a finger or the pointer slides across a selector, a raised thumb follows it. */
.seg-thumb { position: absolute; z-index: 0; top: 4px; bottom: 4px; border-radius: 8px; background: var(--surface, var(--panel)); box-shadow: var(--key-rest); pointer-events: none; transition: left calc(140ms * var(--motion-scale)) var(--ease-out), width calc(140ms * var(--motion-scale)) var(--ease-out); }
:is(.sx-seg, .settings-seg, .custom-seg).seg-sliding > :is(button, .seg-option):not(.seg-thumb) { position: relative; z-index: 1; background: transparent !important; box-shadow: none !important; }
.gliding { cursor: grabbing; user-select: none; touch-action: none; }
.gliding > .glide-on { font-weight: 700 !important; color: var(--text) !important; }
/* The figures lay themselves out by the width of the sheet or window they are in. */
.mods-sheet .settings-scroll, .module-window-body { container: sheet / inline-size; }
.mods-stats { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.mods-stat strong { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; overflow-wrap: normal; }
@container sheet (max-width: 700px) {
  .mods-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); grid-auto-rows: minmax(84px, auto); }
  .mods-stat.hero { grid-column: 1 / -1; grid-row: span 1; }
  .mods-stat.hero strong { font-size: 34px; }
  .mods-detail .economy-app .economy-strip { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@container sheet (max-width: 480px) {
  .mods-detail .economy-app { grid-template-columns: minmax(0, 1fr); }
  .mods-detail .economy-app .economy-strip, .mods-detail .economy-app .metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .mods-detail .mods-reading .intents-table { grid-template-columns: minmax(0, 1fr) auto; }
  .mods-detail .mods-reading .intents-table :is(.intent-rung, .intent-n) { display: none; }
}
@container sheet (min-width: 701px) { .mods-detail .economy-app .economy-strip { grid-template-columns: repeat(6, minmax(0, 1fr)); } }

@container sheet (max-width: 700px) { .mods-detail .economy-app { grid-template-columns: minmax(0, 1fr); } }
.mods-detail .economy-app > .card-block { background: var(--surface, var(--panel)); }
.mods-detail .mods-intents .intents-table .intent-kind { text-transform: lowercase; }
.mods-detail .mods-intents .intents-table .intent-kind::first-letter { text-transform: uppercase; }

/* ==========================================================================================
   ONE LIGHT FOR EVERY SURFACE · subtle
   ------------------------------------------------------------------------------------------
   Keys, cards, tiles, figures and blocks share one light: from the top left, soft, and lower than
   before. A key is the small form of it, a card the wide one; pressed and fields sink the same way.
   ========================================================================================== */
:root {
  --neu-hi: rgba(255, 255, 255, .045);
  --neu-lo: rgba(0, 0, 0, .42);
  --key-rest: -1.5px -1.5px 4px var(--neu-hi), 2px 2.5px 6px var(--neu-lo);
  --key-over: -2px -2px 5px var(--neu-hi), 3px 3.5px 8px var(--neu-lo);
  --key-down: inset 2px 2px 4px var(--neu-lo), inset -1.5px -1.5px 3px var(--neu-hi);
  --key-track: inset 1px 1px 2.5px var(--neu-lo), inset -1px -1px 2.5px var(--neu-hi);
  --key-sink: inset 3px 3px 8px var(--neu-lo), inset -2px -2px 6px var(--neu-hi);
  --raise: -2px -2px 8px var(--neu-hi), 3px 4px 14px var(--neu-lo);
  --raise-over: -3px -3px 10px var(--neu-hi), 4px 6px 18px var(--neu-lo);
}
:root[data-scheme="light"] {
  --neu-hi: rgba(255, 255, 255, .9);
  --neu-lo: rgba(120, 130, 118, .26);
}
:is(.sx-block:not(.mods-reading), .settings-card, .mods-tile:not(.make), .mods-stat, .mods-detail .economy-app > .card-block, .mods-detail .economy-app .economy-stat, .mods-intents .intents-agent, .mods-intents .intents-live, .guide-steps > li, .sx-stat) {
  box-shadow: var(--raise) !important;
}
:is(.settings-card, .mods-tile:not(.make)):hover { box-shadow: var(--raise-over) !important; transform: none !important; }
.settings-card.open { box-shadow: var(--raise), 0 0 0 1.5px color-mix(in srgb, var(--phosphor) 45%, transparent) !important; }

/* (4) A field sinks clearly when written in. */
:is(.sx-input:focus, .sx-num:focus-within, .settings-search:focus-within) { box-shadow: var(--key-sink) !important; }

/* (5) The permission modes wear their own colours, chosen or not. */
.sx-seg button.o0 { color: var(--mode-0) !important; } .sx-seg button.o1 { color: var(--mode-1) !important; }
.sx-seg button.o2 { color: var(--mode-2) !important; } .sx-seg button.o3 { color: var(--mode-3) !important; }
.sx-seg button.o4 { color: var(--mode-4) !important; }
.sx-seg button:is(.o0, .o1, .o2, .o3, .o4):not([aria-checked="true"]):not(:disabled) { opacity: .7; }
.sx-seg button:is(.o0, .o1, .o2, .o3, .o4):disabled { opacity: .28; }

/* (6) An agent's key and its sign-in command, in the sheet's own hand. */
.sx-slot .key-form { padding: 14px; border-radius: 12px; background: transparent; box-shadow: var(--key-track); }
.sx-slot .key-form label .k, .sx-slot .key-form label > span:first-child { display: inline-block; font-family: var(--read); font-size: 13px; font-weight: 500; letter-spacing: 0; text-transform: lowercase; color: var(--text); }
.sx-slot .key-form label .k::first-letter, .sx-slot .key-form label > span:first-child::first-letter { text-transform: uppercase; }
.sx-slot .key-form :is(input, select) { border: 0 !important; background: transparent !important; box-shadow: var(--key-track) !important; outline: none; font-family: var(--read); }
.sx-slot .key-form :is(input, select):focus { box-shadow: var(--key-sink) !important; }
.sx-slot .key-form .key-row button { background: var(--phosphor) !important; color: var(--phosphor-ink) !important; box-shadow: var(--key-rest) !important; }
.sx-slot .mother-cmd { background: transparent; box-shadow: var(--key-track); }
.sx-slot > .sx-hint { padding: 4px 2px 0; }

/* (3) Intenciones while a test runs: one card, sentence case, keys at their own size. */
.mods-intents .intents-live { display: grid; gap: 12px; justify-items: start; margin-top: 12px; padding: 16px 18px; border-radius: 16px; background: var(--surface, var(--panel)); }
.mods-intents .intents-live > .note:first-child { display: flex; align-items: center; gap: 8px; font-weight: 500; color: var(--text); }
.mods-intents .intents-live > .note:first-child::before { content: ''; width: 7px; height: 7px; border-radius: 50%; background: #34d058; animation: live-glow 2.4s ease-in-out infinite; }
.mods-intents :is(.intents-live > .note, .card-block > .note, .intents-agent > .note) { display: block; text-transform: lowercase; }
.mods-intents :is(.intents-live > .note, .card-block > .note, .intents-agent > .note)::first-letter { text-transform: uppercase; }
.mods-intents button { width: auto; text-transform: lowercase !important; }
.mods-intents button::first-letter { text-transform: uppercase; }
.mods-intents .intents-live > button { justify-self: start; }

/* (8) The Finder's search is the same pressed field as AJUSTES' and MODULES'. */
.tree-search { padding: 8px 12px 6px; }
.tree-search .tree-find { display: flex; width: 100%; max-width: none; height: 32px; }
.tree-search .tree-find input { width: 100%; height: 30px; padding: 0; border: 0 !important; background: transparent !important; box-shadow: none !important; outline: none; font-family: var(--read); font-size: 13px; color: var(--text); }

/* (11) Bubbles: a surface standing on the canvas, softly raised. */
:root[data-scheme] :is(#messages, .look-preview) .row:is(.assistant, .user, .thinking) .bubble {
  border-radius: 14px;
  box-shadow: 0 1px 1.5px rgba(0, 0, 0, .22), 0 8px 22px -12px rgba(0, 0, 0, .55);
}
:root[data-scheme="light"] :is(#messages, .look-preview) .row:is(.assistant, .user, .thinking) .bubble { box-shadow: 0 1px 1.5px rgba(30, 40, 30, .08), 0 8px 22px -12px rgba(30, 40, 30, .22) !important; }
/* The mark stands clear of the bubble, level with its last line. */
#messages .row:is(.assistant, .thinking) { gap: 14px; }
#messages .row:is(.assistant, .thinking) > .avatar { align-self: end; margin-bottom: 2px; }
.mods-intents .intents-live > .note:first-child { display: block; }
.mods-intents .intents-live > .note:first-child::before { display: inline-block; margin-right: 8px; vertical-align: 1px; }
.sx-slot .key-said:empty { display: none; }

/* ==========================================================================================
   NOTICES · a pill with a dot
   ------------------------------------------------------------------------------------------
   One line over the composer, made of the room's surface and its light. The colour lives in the
   dot alone: green done, amber worth a look, red only for what went wrong, grey a plain note.
   ========================================================================================== */
.toast:not([hidden]) {
  display: inline-flex; align-items: center; gap: 9px;
  padding: 9px 16px 9px 13px; border: 0; border-radius: 20px;
  background: var(--surface, var(--panel)); color: var(--text);
  /* It floats over the canvas (2026-10-14): a rim, a near shadow and a far one, so it reads lifted
     off any wallpaper or thread under it. */
  box-shadow: 0 0 0 .5px color-mix(in srgb, var(--text) 14%, transparent), inset 0 1px 0 rgb(255 255 255 / .06), 0 2px 4px rgba(0, 0, 0, .24), 0 12px 28px -6px rgba(0, 0, 0, .5), 0 28px 60px -18px rgba(0, 0, 0, .45);
  font-family: var(--read); font-size: 13px; font-weight: 450; line-height: 1.4; text-align: left;
  max-width: min(560px, calc(100% - 32px)); width: max-content;
}
.toast.note { color: var(--text); }
.toast .toast-from { display: none; }
.toast .toast-dot { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--text-3); }
.toast[data-tone="done"] .toast-dot { background: #34c759; box-shadow: 0 0 0 3px rgba(52, 199, 89, .16); }
.toast[data-tone="look"] .toast-dot { background: #e0a23c; box-shadow: 0 0 0 3px rgba(224, 162, 60, .18); }
.toast[data-tone="news"] .toast-dot { background: var(--madre-green); box-shadow: 0 0 0 3px color-mix(in srgb, var(--madre-green) 22%, transparent); }
/* The one key a notice may carry (the Market's news): small, the room's green, at its end. */
.toast .toast-act { flex: none; margin-left: 4px; padding: 4px 11px; border: 0; border-radius: 99px; background: color-mix(in srgb, var(--madre-green) 16%, transparent); color: var(--madre-green); font: inherit; font-size: 12.5px; font-weight: 650; cursor: pointer; }
.toast .toast-act:hover { background: color-mix(in srgb, var(--madre-green) 26%, transparent); }
.toast[data-tone="wrong"] .toast-dot { background: var(--danger); box-shadow: 0 0 0 3px color-mix(in srgb, var(--danger) 18%, transparent); }

/* The model's mark in the conversation is flat: one solid tint of the agent's colour, no light and
   no shadow, and the provider's logo larger and in the agent's full ink so it reads at a glance. */
#messages .row > .avatar:not(.gradient) {
  background-image: none !important; box-shadow: none !important;
  background-color: color-mix(in srgb, var(--agent) 22%, var(--bg)) !important;
  color: color-mix(in srgb, var(--agent) 55%, #ffffff) !important;
}
:root[data-scheme="light"] #messages .row > .avatar:not(.gradient) {
  background-color: color-mix(in srgb, var(--agent) 14%, #ffffff) !important;
  color: color-mix(in srgb, var(--agent) 88%, #000000) !important;
}
#messages .row > .avatar.gradient { box-shadow: none !important; }
#messages .row > .avatar svg { width: 64%; height: 64%; opacity: 1; }

:root[data-scheme="light"] .toast:not([hidden]) { box-shadow: 0 0 0 .5px rgba(20, 30, 20, .08), 0 2px 4px rgba(20, 30, 20, .1), 0 12px 28px -6px rgba(20, 30, 20, .22), 0 28px 60px -18px rgba(20, 30, 20, .2); }

/* ==========================================================================================
   MU/TH/UR · the remedies, as a window of the room
   ------------------------------------------------------------------------------------------
   Of the terminal only the name is left, in mono, as the title. A symptom is written in the head;
   the list filters on one side and the remedy reads on the other, in AJUSTES' blocks. Narrow, the
   remedy comes first and the list follows it.
   ========================================================================================== */
dialog.mother-window { width: 1080px; height: 740px; container: motherwin / inline-size; }
.mother-bar { gap: 10px; }
.mother-bar .custom-title { flex: none; }
.mother-find-form { flex: 1 1 220px; min-width: 0; max-width: 440px; margin: 0; }
.mother-find-form .mother-find { width: 100%; max-width: none; }
.mother-bar .mother-os { flex: none; }
.mother-tools { display: flex; align-items: center; gap: 6px; margin-left: auto; }
.mother-tools .tour-button { font-family: var(--read); font-size: 14px; font-weight: 600; }
.mother-status { margin: 0; padding: 8px 20px; border-bottom: 1px solid var(--line); font-family: var(--read); font-size: 12.5px; color: color-mix(in srgb, var(--text) 66%, transparent); }
.mother-body { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(280px, 380px) minmax(0, 1fr); }
.mother-list { min-height: 0; overflow: auto; display: grid; grid-template-columns: minmax(0, 1fr); grid-auto-rows: max-content; gap: 12px; padding: 14px 12px 18px 16px; border-right: 1px solid var(--line); }
.mother-detail { min-height: 0; overflow: auto; display: grid; grid-auto-rows: max-content; gap: 14px; padding: 16px 20px 24px; container: sheet / inline-size; }
@container motherwin (max-width: 760px) {
  .mother-body { display: flex; flex-direction: column; overflow: auto; }
  .mother-detail { order: 0; overflow: visible; padding-bottom: 6px; }
  .mother-list { order: 1; overflow: visible; border-right: 0; border-top: 1px solid var(--line); }
  .mother-bar .mother-os { display: none; }
}
@container motherwin (max-width: 520px) { .mother-bar .custom-title, .mother-tools { display: none; } }

/* The filters: a row of keys, the chosen one raised and heavier, each with its count. */
.remedy-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.remedy-chip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border: 0; border-radius: 8px; background: transparent; color: color-mix(in srgb, var(--text) 70%, transparent); font-family: var(--read); font-size: 12.5px; font-weight: 450; box-shadow: var(--key-track); cursor: pointer; }
.remedy-chip span { font-size: 11.5px; font-variant-numeric: tabular-nums; color: color-mix(in srgb, var(--text) 50%, transparent); }
.remedy-chip.on { background: var(--surface, var(--panel)); color: var(--text); font-weight: 650; box-shadow: var(--key-rest); }
/* The list: one line per condition or record, its tone a dot, the chosen one raised. */
.remedy-rows { display: grid; grid-template-columns: minmax(0, 1fr); gap: 2px; }
.remedy-row { display: flex; align-items: center; gap: 10px; width: 100%; min-height: 40px; padding: 8px 10px; border: 0; border-radius: 10px; background: transparent; color: var(--text); font-family: var(--read); text-align: left; cursor: pointer; }
.remedy-row:hover { background: color-mix(in srgb, var(--text) 5%, transparent); }
.remedy-row.on { background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.remedy-row:focus-visible { outline: 2px solid color-mix(in srgb, var(--phosphor) 60%, transparent); outline-offset: 1px; }
.remedy-dot { flex: none; width: 8px; height: 8px; border-radius: 50%; background: var(--text-3); }
.remedy-dot.tone-wrong { background: var(--danger); }
.remedy-dot.tone-look { background: #e0a23c; }
.remedy-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 450; }
.remedy-row.on .remedy-title { font-weight: 600; }
.remedy-agent { flex: none; font-family: var(--read); font-size: 11.5px; font-weight: 500; color: var(--agent, var(--text-2)); }
.remedy-code { flex: none; padding: 0; border: 0; background: none; font-family: var(--mono); font-size: 11px; color: color-mix(in srgb, var(--text) 50%, transparent); }
.remedy-empty { padding: 8px 10px; }
.remedy-foot { display: flex; flex-wrap: wrap; gap: 8px; padding-top: 4px; }

/* A remedy in three weights: the title, one quiet line that places it (severity · agent · code),
   and what to do in the reading ink. The keys that do it follow as rows. */
.mother-hint { margin: 0 2px; font-family: var(--read); font-size: 12.5px; color: color-mix(in srgb, var(--text) 66%, transparent); }
.remedy .sx-head { padding-bottom: 10px; }
.remedy .sx-head .sx-words { gap: 5px; }
.remedy .sx-head h3 { font-size: 16.5px; font-weight: 650; line-height: 1.35; }
.remedy-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 0; font-family: var(--read); font-size: 12px; line-height: 1.4; color: color-mix(in srgb, var(--text) 62%, transparent); }
.remedy-meta > * + *::before { content: '·'; margin: 0 7px; color: color-mix(in srgb, var(--text) 40%, transparent); font-family: var(--read); }
.remedy-sev { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; }
.remedy-sev::after { content: none; }
.remedy-sev.tone-wrong { color: var(--danger); }
.remedy-sev.tone-look { color: #b07a0c; }
:root[data-scheme="dark"] .remedy-sev.tone-look { color: #e0a23c; }
.remedy-meta .remedy-agent { font-size: 12px; font-weight: 600; color: color-mix(in srgb, var(--agent, var(--text)) 70%, var(--text)); }
.remedy-meta .remedy-code { font-size: 11px; }
.remedy-what { margin: 0; padding: 0 16px 14px; font-family: var(--read); font-size: 14px; line-height: 1.6; color: var(--text); }
.sx-chip.wrong { background: color-mix(in srgb, var(--danger) 14%, transparent); color: var(--danger); }
.sx-chip.look { background: color-mix(in srgb, #e0a23c 18%, transparent); color: #c98a12; }
:root[data-scheme="light"] .sx-chip.look { color: #7a5c00; }
.sx-chip.calm { background: color-mix(in srgb, var(--text) 8%, transparent); color: color-mix(in srgb, var(--text) 70%, transparent); }
.remedy-terminal .sx-rows { display: grid; gap: 10px; padding: 0 16px 14px; }
.remedy-terminal .mother-cmd, .remedy-record .mother-cmd { position: relative; margin: 0; padding: 10px 40px 10px 12px; border: 0; border-radius: 10px; background: transparent; box-shadow: var(--key-track); }
.remedy-terminal .mother-cmd pre { margin: 0; padding: 0; white-space: pre-wrap; font-family: var(--mono); font-size: 12px; line-height: 1.6; color: var(--text); background: none; text-shadow: none; }
.remedy-terminal .mother-cmd .c { color: color-mix(in srgb, var(--text) 55%, transparent); }
.remedy-terminal .mother-cmd .copy { top: 7px; right: 7px; width: 26px; height: 26px; border: 0; border-radius: 8px; color: color-mix(in srgb, var(--text) 66%, transparent); background: var(--surface, var(--panel)); box-shadow: var(--key-rest); }
.remedy-terminal .per-agent { margin: 4px 0 0; font-family: var(--read); font-size: 12.5px; }
.remedy-terminal .per-agent b { color: var(--agent, var(--text)); font-weight: 600; }
.remedy-why > p { margin: 0 16px 14px; font-family: var(--read); font-size: 13px; line-height: 1.6; color: color-mix(in srgb, var(--text) 75%, transparent); }
.remedy-report .sx-head, .remedy-record .sx-head { align-items: center; }
.remedy-record .remedy-error { margin: 0 16px 14px; padding: 10px 12px; max-height: 220px; overflow: auto; border-radius: 10px; box-shadow: var(--key-track); white-space: pre-wrap; overflow-wrap: anywhere; font-family: var(--mono); font-size: 12px; line-height: 1.55; color: var(--text); background: transparent; }
:root[data-accent] #mother { --phosphor: var(--acc); --phosphor-ink: var(--acc-ink); --accent: var(--acc); --accent-ink: var(--acc-ink); }

/* MU/TH/UR's trace beats under the pointer: a pulse runs along the line, the line itself dims
   under it, the way a monitor sweeps. Still when motion is reduced. */
.mother-button .ic-beat { opacity: 0; stroke-dasharray: .26 1; stroke-dashoffset: 1.26; }
.mother-button:hover .ic-beat, .mother-button:focus-visible .ic-beat { opacity: 1; animation: mother-beat calc(1300ms * var(--motion-scale)) cubic-bezier(.45, 0, .2, 1) infinite; }
.mother-button:hover .ic-k, .mother-button:focus-visible .ic-k { opacity: .38; transition: opacity calc(200ms * var(--motion-scale)) ease; }
@keyframes mother-beat { 0% { stroke-dashoffset: 1.26; } 70%, 100% { stroke-dashoffset: 0; } }
@media (prefers-reduced-motion: reduce) { .mother-button:hover .ic-beat, .mother-button:focus-visible .ic-beat { animation: none; opacity: 0; } .mother-button:hover .ic-k { opacity: 1; } }

/* Who a message went to keeps its agent's hue but is inked against the material it sits on: the
   pure agent colour sank into some wallpapers. Weight carries it the rest of the way. */
:is(#messages, .look-preview) .user:not(.expendable) .stamp .to { font-weight: 600; color: color-mix(in srgb, var(--agent, var(--text)) 58%, var(--text)) !important; }

/* A card's quick rows breathe: a selector keeps air above and below inside its row instead of
   filling it edge to edge, and a label that wraps to two lines keeps a reading line height. */
.settings-quick-row { min-height: 44px; padding-block: 8px; }
.settings-quick-row > span:first-child { line-height: 1.4; }
.settings-quick-row:has(> :is(.settings-seg, .sx-seg, .custom-seg)) { padding-block: 9px; }
.settings-quick-row.agent { min-height: 38px; padding-block: 6px; }

/* The options of a rail never fade their own background in or out: the one tab travels instead. */
:is(.sx-seg button, .settings-seg button, .custom-seg .seg-option) { transition: color calc(160ms * var(--motion-scale)) var(--ease-out), opacity calc(160ms * var(--motion-scale)) var(--ease-out) !important; }
.seg-thumb { transition: left calc(180ms * var(--motion-scale)) var(--ease-out), width calc(180ms * var(--motion-scale)) var(--ease-out); }
.custom-seg { position: relative; }

/* A key that still holds: beside the mode, in its colour, with how long is left and a × to close it. */
.picker .grace-chip { --g: var(--mode-3); margin-left: 6px; display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 4px 0 8px; border: 0; border-radius: 999px; background: color-mix(in srgb, var(--g) 14%, transparent); color: color-mix(in srgb, var(--g) 70%, var(--text)); font-family: var(--read); font-size: 11px; font-weight: 500; cursor: pointer; }
.picker .grace-chip.m4 { --g: var(--mode-4); }
.picker .grace-chip b { font-family: var(--mono); font-size: 10px; font-weight: 700; }
.picker .grace-chip .left { font-variant-numeric: tabular-nums; opacity: .8; }
.picker .grace-chip i { display: grid; place-items: center; width: 14px; height: 14px; border-radius: 50%; font-style: normal; font-size: 11px; line-height: 1; opacity: .7; }
.picker .grace-chip:hover i { opacity: 1; background: color-mix(in srgb, var(--g) 22%, transparent); }

/* PERMISSIONS: the phrase field and its key on one line; the ceiling table reads like the agents' list. */
.perm-phrase { display: flex; gap: 8px; width: 100%; }
.perm-phrase .sx-input { flex: 1; }
.perm-who .sx-row .sx-words b { color: color-mix(in srgb, var(--agent, var(--text)) 70%, var(--text)); }

/* The answer on a wallpaper: a tint whiter than the room's small print, so a reply never reads as
   one of the room's lines, with a lit top edge. It floats on a soft, low shadow — no rim of light
   around it, no coloured edges. (No blur behind it: see the conversation's rule above.) */
:root[data-wallpaper]:not([data-wallpaper="default"]) #messages .row:is(.assistant, .thinking) .bubble {
  background-color: color-mix(in srgb, var(--bubble) 92%, rgba(255, 255, 255, .14)) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 1px 2px rgba(0, 0, 0, .18), 0 12px 30px -16px rgba(0, 0, 0, .5) !important;
}
:root[data-scheme="light"][data-wallpaper]:not([data-wallpaper="default"]) #messages .row:is(.assistant, .thinking) .bubble {
  background-color: rgba(255, 255, 255, .92) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 1px 2px rgba(20, 30, 25, .07), 0 12px 30px -16px rgba(20, 30, 25, .3) !important;
}

/* ==========================================================================================
   ALERTS OF THE ROOM — a narrow sheet, centred: the glyph of what is at stake, the title, one
   sentence, a sunk field when a key is asked for, and two keys across. Used by the room's
   questions (unsaved changes and the like) and by the key for #3 CONTROL and #4 AIRLOCK. The
   console's own questions keep the console.
   ========================================================================================== */
dialog.room-ask:not(.console) { width: min(320px, calc(100vw - 32px)); }
dialog.room-ask:not(.console)::backdrop { background: color-mix(in srgb, var(--bg) 46%, transparent); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
dialog.room-ask:not(.console) .room-ask-card { justify-items: center; gap: 10px; padding: 22px 20px 18px; border: 0; border-radius: 18px; background: var(--surface, var(--panel)); text-align: center; box-shadow: 0 1px 2px rgba(0, 0, 0, .2), 0 22px 48px -20px rgba(0, 0, 0, .55); }
:root[data-scheme="light"] dialog.room-ask:not(.console) .room-ask-card { box-shadow: 0 1px 2px rgba(20, 30, 25, .08), 0 22px 48px -22px rgba(20, 30, 25, .35); }
dialog.room-ask:not(.console) .room-ask-icon { --tone: var(--phosphor); display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: 2px; border-radius: 13px; background: color-mix(in srgb, var(--tone) 16%, transparent); color: var(--tone); }
dialog.room-ask:not(.console) .room-ask-icon[hidden] { display: none; }
dialog.room-ask:not(.console) .room-ask-icon svg { width: var(--ico-lg); height: var(--ico-lg); }
dialog.room-ask[data-kind="danger"] .room-ask-icon { --tone: var(--danger); }
dialog.room-ask[data-kind="key"] .room-ask-icon, dialog.key-ask .room-ask-icon { --tone: var(--mode-3); }
dialog.key-ask.m4 .room-ask-icon { --tone: var(--mode-4); }
dialog.room-ask:not(.console) .room-ask-title { margin: 0; font-family: var(--read); font-size: 16px; font-weight: 650; letter-spacing: 0; line-height: 1.3; text-transform: none; color: var(--text); }
dialog.room-ask:not(.console) .room-ask-body { margin: 0; font-size: 13.5px; line-height: 1.5; color: color-mix(in srgb, var(--text) 72%, transparent); }
dialog.room-ask:not(.console) .room-ask-field { width: 100%; grid-template-columns: minmax(0, 1fr); gap: 4px; margin-top: 4px; padding: 0; border: 0; justify-items: stretch; }
dialog.room-ask:not(.console) .room-ask-field .k { font-family: var(--read); font-size: 11.5px; letter-spacing: 0; text-transform: none; color: color-mix(in srgb, var(--text) 55%, transparent); }
dialog.room-ask:not(.console) .room-ask-field input { height: 38px; padding: 0 12px; border-radius: 10px; background: transparent; box-shadow: var(--key-track); text-align: center; font-size: 13.5px; letter-spacing: .02em; caret-color: var(--phosphor); }
dialog.room-ask:not(.console) .room-ask-field input:focus { box-shadow: var(--key-sink, var(--key-track)); }
dialog.room-ask:not(.console) .room-ask-field[hidden] { display: none; }
dialog.room-ask:not(.console) .room-ask-actions { width: 100%; display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); gap: 8px; margin-top: 8px; }
dialog.room-ask:not(.console) .room-ask-choice { height: 38px; padding: 0 12px; border: 0; border-radius: 10px; background: var(--surface, var(--panel)); color: var(--text); font-family: var(--read); font-size: 13.5px; font-weight: 550; letter-spacing: 0; text-transform: none; box-shadow: var(--key-rest); }
dialog.room-ask:not(.console) .room-ask-choice:hover { color: var(--text); box-shadow: var(--raise-over, var(--key-rest)); }
dialog.room-ask:not(.console) .room-ask-choice:active { box-shadow: var(--key-down); }
dialog.room-ask:not(.console) .room-ask-choice.primary { background: var(--phosphor); color: var(--phosphor-ink); }
dialog.room-ask:not(.console) .room-ask-choice.danger { background: var(--danger); color: #fff; }
dialog.room-ask:not(.console) .room-ask-choice.danger:hover { background: var(--danger); }
.key-form { display: grid; gap: 6px; width: 100%; }
.key-reply { min-height: 18px; margin: 0; font-family: var(--read); font-size: 12.5px; color: color-mix(in srgb, var(--text) 62%, transparent); }
.key-reply.denied { color: var(--danger); }
.key-reply.granted { color: var(--phosphor); font-weight: 600; }
.key-card.shake { animation: override-shake .35s ease; }
@media (prefers-reduced-motion: reduce) { .key-card.shake { animation: none; } }
/* The key, quieter: one sentence of what it allows, a smaller one of what keeps it safe, the
   ceiling note when there is one, and a field whose label says what to type. */
dialog.key-ask .room-ask-body { color: var(--text); font-size: 14px; }
/* «Don't ask again…» under the memory gate: a quiet link to Settings › Permissions › Memory access. */
.key-skip { display: block; margin: 4px auto 0; padding: 4px 8px; border: 0; border-radius: 8px; background: none; font: 500 12px/1.3 var(--sans); color: var(--text-2); cursor: pointer; text-decoration: underline; text-decoration-color: color-mix(in srgb, var(--text-2) 40%, transparent); text-underline-offset: 3px; }
.key-skip:hover, .key-skip:focus-visible { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); outline: 0; }
.key-safe { margin: -4px 0 0; font-family: var(--read); font-size: 12.5px; line-height: 1.45; color: color-mix(in srgb, var(--text) 58%, transparent); }
.key-raise { margin: 0; padding: 4px 10px; border-radius: 999px; background: color-mix(in srgb, var(--mode-3) 14%, transparent); color: color-mix(in srgb, var(--mode-3) 70%, var(--text)); font-family: var(--read); font-size: 12px; font-weight: 550; }
dialog.key-ask.m4 .key-raise { background: color-mix(in srgb, var(--mode-4) 14%, transparent); color: color-mix(in srgb, var(--mode-4) 70%, var(--text)); }
.key-raise[hidden] { display: none; }
dialog.key-ask .room-ask-field { margin-top: 6px; gap: 6px; }
dialog.key-ask .room-ask-field .k { font-size: 12.5px; font-weight: 550; color: color-mix(in srgb, var(--text) 72%, transparent); }
dialog.key-ask .room-ask-field input { font-family: var(--read); font-size: 15px; font-weight: 550; letter-spacing: .01em; }
.key-reply:empty { display: none; }
dialog.key-ask .room-ask-actions { margin-top: 10px; }

/* The board's three columns share two rows: their headings, then their cards. A heading that wraps
   to two lines moves every column's cards down with it, so the cards always start on one line. */
.settings-board { grid-template-rows: auto auto; }
.settings-section { grid-row: span 2; grid-template-rows: subgrid; gap: 10px; }
.settings-section > header { align-self: end; }
.settings-cards { display: grid; gap: 10px; align-content: start; min-width: 0; }
@container settings (max-width: 820px) {
  .settings-board { grid-template-rows: none; }
  .settings-section { grid-row: auto; grid-template-rows: none; grid-template-columns: minmax(0, 1fr); }
  .settings-cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
/* PERMISSIONS: the key's rail runs under its words, the whole width, every option on one line. */
.perm-keys .sx-row.stack .sx-control { width: 100%; }
.perm-keys .sx-row.stack .sx-seg { display: flex; width: 100%; }
.perm-keys .sx-seg button { flex: 1 1 0; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
dialog.nostromo-key .room-ask-icon { --tone: #e5484d; }
.key-reply.denied .line { display: block; }
.key-reply.denied .strike { display: block; margin-top: 4px; font-family: var(--mono); font-size: 10.5px; letter-spacing: .08em; color: color-mix(in srgb, var(--danger) 75%, var(--text)); }

/* ==========================================================================================
   NOSTROMO IN THE ROOM'S LANGUAGE — the map stays the ship's (dark space, the sun, the dwarfs);
   what frames it speaks like every other window: the name in small mono, the reading in
   sentences, the kinds as dots with words, and soft keys. Nothing glows.
   ========================================================================================== */
:is(#nostromo, .mv) .nostromo-head { grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "title sub actions" "legend legend legend"; gap: 10px 16px; padding: 14px 20px 12px; border-bottom: 1px solid rgba(255, 255, 255, .08); background: rgba(12, 12, 14, .72); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); }
:is(#nostromo, .mv) .nostromo-head > .mother-title { align-self: center; font-family: var(--mono); font-size: 13px; font-weight: 700; letter-spacing: .22em; color: #f2f1ee; text-shadow: none; }
#nostromo .nostromo-head > .mother-sub { align-self: center; font-family: var(--read); font-size: 12.5px; letter-spacing: 0; color: rgba(242, 241, 238, .62); text-transform: lowercase; }
#nostromo .nostromo-head > .mother-sub::first-letter { text-transform: uppercase; }
/* The Project map wears the same head (salas-mac.css, .mv-head); its line is not shouted, so it is
   not lowered either. */
.mv .nostromo-head > .mother-sub { align-self: center; min-width: 0; font-family: var(--read); font-size: 12.5px; letter-spacing: 0; color: rgba(242, 241, 238, .62); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
:is(#nostromo, .mv) .nostromo-head > .nostromo-legend { justify-content: flex-start; gap: 14px; }
:is(#nostromo, .mv) .nostromo-legend .k { gap: 6px; font-family: var(--read); font-size: 12px; letter-spacing: 0; }
:is(#nostromo, .mv) .nostromo-legend .k i { display: inline-block; color: rgba(242, 241, 238, .78); text-transform: lowercase; }
:is(#nostromo, .mv) .nostromo-legend .k i::first-letter { text-transform: uppercase; }
:is(#nostromo, .mv) .nostromo-actions { gap: 8px; }
:is(#nostromo, .mv) .nostromo-actions .mother-close { height: 30px; padding: 0 12px; border: 0; border-radius: 10px; background: rgba(255, 255, 255, .08); color: #f2f1ee; font-family: var(--read); font-size: 12.5px; font-weight: 550; letter-spacing: 0; box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 1px 2px rgba(0, 0, 0, .4); }
#nostromo .nostromo-actions .mother-close, .mv .nostromo-actions .mv-recenter { text-transform: lowercase; }
:is(#nostromo, .mv) .nostromo-actions .mother-close::first-letter { text-transform: uppercase; }
:is(#nostromo, .mv) .nostromo-actions .mother-close:hover { background: rgba(255, 255, 255, .14); }
:is(#nostromo, .mv) .nostromo-actions .mother-close[aria-pressed="true"] { background: #f2f1ee; color: #111; }
#nostromo .nostromo-help { left: 20px; bottom: 14px; font-family: var(--read); font-size: 11.5px; letter-spacing: 0; color: rgba(242, 241, 238, .42); }
#nostromo .nostromo-empty { font-family: var(--read); letter-spacing: 0; text-transform: lowercase; color: rgba(242, 241, 238, .6); }
#nostromo .nostromo-empty::first-letter { text-transform: uppercase; }
/* A memory's card and the questions to ask: dark glass panels, the kind as a coloured dot and a
   word, labels in sentences, figures in small mono, and the one destructive key a soft red. */
#nostromo .nostromo-card { top: 84px; right: 20px; padding: 16px 16px 14px; border: 0; border-radius: 16px; background: rgba(22, 22, 25, .86); -webkit-backdrop-filter: blur(18px); backdrop-filter: blur(18px); box-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 18px 40px -18px rgba(0, 0, 0, .8); font-family: var(--read); }
#nostromo .nostromo-card.asks { left: 20px; right: auto; }
#nostromo .nostromo-card .kind { display: inline-flex; align-items: center; gap: 7px; font-family: var(--read); font-size: 12.5px; font-weight: 600; letter-spacing: 0; text-transform: none; color: #f2f1ee; }
#nostromo .nostromo-card:not(.asks) .kind::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--kind, #f2f1ee); }
#nostromo .nostromo-card header .mother-close { width: 26px; height: 26px; padding: 0; border: 0; border-radius: 50%; background: rgba(255, 255, 255, .08); color: #f2f1ee; font-size: 13px; }
#nostromo .nostromo-card header .mother-close:hover { background: rgba(255, 255, 255, .16); }
#nostromo .nostromo-card .text { font-family: var(--read); font-size: 14.5px; line-height: 1.5; color: #f2f1ee; }
#nostromo .nostromo-card .meta { gap: 5px 14px; font-family: var(--read); font-size: 12px; letter-spacing: 0; }
#nostromo .nostromo-card .meta dt { color: rgba(242, 241, 238, .5); text-transform: lowercase; }
#nostromo .nostromo-card .meta dt::first-letter { text-transform: uppercase; }
#nostromo .nostromo-card .meta dd { font-family: var(--mono); font-size: 11.5px; color: rgba(242, 241, 238, .86); }
/* The zone: its word on a mark in the zone's own colour — lit when it travels into turns, amber in
   the med bay, grey once jettisoned — and its meaning in a sentence under it. NOSTROMO is dark in
   both themes, so the colours are the dark theme's and do not follow the light one. */
#nostromo .nostromo-card .meta dd.zone { display: grid; justify-items: start; gap: 4px; }
#nostromo .nostromo-card .zone-word { --zone: #9bff66; padding: 2px 8px; border-radius: 999px; font-weight: 600; font-size: 10.5px; letter-spacing: .1em; color: var(--zone); background: color-mix(in srgb, var(--zone) 16%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--zone) 42%, transparent); }
#nostromo .nostromo-card .zone-bridge .zone-word { --zone: #d2ffb8; }
#nostromo .nostromo-card .zone-medbay .zone-word { --zone: #ffd166; }
#nostromo .nostromo-card .zone-jettisoned .zone-word { --zone: rgba(242, 241, 238, .55); }
#nostromo .nostromo-card .zone-note { font-family: var(--read); font-size: 12px; line-height: 1.4; letter-spacing: 0; text-transform: none; color: rgba(242, 241, 238, .62); }
#nostromo .nostromo-card .zone.archived::after { content: none; }
#nostromo .nostromo-card .wire h6 { font-family: var(--read); font-size: 12px; font-weight: 600; letter-spacing: 0; color: rgba(242, 241, 238, .72); text-transform: none; }
#nostromo .nostromo-card .exchange { font-family: var(--read); font-size: 12.5px; letter-spacing: 0; color: rgba(242, 241, 238, .72); }
#nostromo .nostromo-card .wire-row { border-radius: 9px; }
#nostromo .nostromo-card .wire-row .what { font-family: var(--read); font-size: 12.5px; color: rgba(242, 241, 238, .88); }
#nostromo .nostromo-card .wire-row b { font-size: 10.5px; color: rgba(242, 241, 238, .55); }
#nostromo .nostromo-card .forget { height: 36px; border: 0; border-radius: 10px; background: color-mix(in srgb, #e5484d 18%, transparent); color: #ff8a8c; font-family: var(--read); font-size: 13px; font-weight: 600; letter-spacing: 0; text-transform: lowercase; }
#nostromo .nostromo-card .forget::first-letter { text-transform: uppercase; }
#nostromo .nostromo-card .forget:hover { background: color-mix(in srgb, #e5484d 28%, transparent); }
#nostromo .nostromo-card .forget.confirm { background: #e5484d; color: #fff; animation: none; }
#nostromo .nostromo-card .foot { font-family: var(--read); font-size: 11.5px; letter-spacing: 0; color: rgba(242, 241, 238, .45); text-transform: lowercase; }
#nostromo .nostromo-card .foot::first-letter { text-transform: uppercase; }
.settings-cards { align-items: start; }

/* ---------- Four more wallpapers: Biznaga, Oceano, Quila, Xico ----------
   The same layers as the others — a flat veil, or a mesh of the photograph's own colours — with
   veils, tints and corners taken from each picture. */
:root {
  --wp-biznaga: linear-gradient(rgb(13 11 9 / min(.96, calc(.68 * var(--veil-k, 1)))), rgb(13 11 9 / min(.97, calc(.78 * var(--veil-k, 1))))), url("/assets/wallpapers/biznaga.webp?v=3") 50% 50% / cover no-repeat, #0d0b09;
  --wp-oceano: linear-gradient(rgb(12 10 10 / min(.96, calc(.68 * var(--veil-k, 1)))), rgb(12 10 10 / min(.97, calc(.78 * var(--veil-k, 1))))), url("/assets/wallpapers/oceano.webp?v=3") 50% 50% / cover no-repeat, #0c0a0a;
  --wp-quila: linear-gradient(rgb(13 13 13 / min(.96, calc(.68 * var(--veil-k, 1)))), rgb(13 13 13 / min(.97, calc(.78 * var(--veil-k, 1))))), url("/assets/wallpapers/quila.webp?v=3") 50% 50% / cover no-repeat, #0d0d0d;
  --wp-xico: linear-gradient(rgb(16 12 12 / min(.96, calc(.68 * var(--veil-k, 1)))), rgb(16 12 12 / min(.97, calc(.78 * var(--veil-k, 1))))), url("/assets/wallpapers/xico.webp?v=3") 50% 50% / cover no-repeat, #100c0c;
}
:root[data-scheme="light"] {
  --wp-biznaga: linear-gradient(rgb(247 245 245 / min(.96, calc(.52 * var(--veil-k, 1)))), rgb(247 245 245 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/biznaga.webp?v=3") 50% 50% / cover no-repeat, #f1efee;
  --wp-oceano: linear-gradient(rgb(246 245 245 / min(.96, calc(.52 * var(--veil-k, 1)))), rgb(246 245 245 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/oceano.webp?v=3") 50% 50% / cover no-repeat, #f1efef;
  --wp-quila: linear-gradient(rgb(247 247 247 / min(.96, calc(.52 * var(--veil-k, 1)))), rgb(247 247 247 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/quila.webp?v=3") 50% 50% / cover no-repeat, #f1f2f1;
  --wp-xico: linear-gradient(rgb(248 246 246 / min(.96, calc(.52 * var(--veil-k, 1)))), rgb(248 246 246 / min(.97, calc(.64 * var(--veil-k, 1))))), url("/assets/wallpapers/xico.webp?v=3") 50% 50% / cover no-repeat, #f4f0f0;
}
:is(:root:not([data-scheme="light"]), .look-preview[data-scheme="dark"])[data-wp-style="mesh"] {
  --wp-biznaga: radial-gradient(75% 65% at 12% 8%, rgb(31 29 30 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(53 44 37 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(29 21 17 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(13 11 9 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(13 11 9 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/biznaga.webp?v=3") 50% 50% / cover no-repeat, #0d0b09;
  --wp-oceano: radial-gradient(75% 65% at 12% 8%, rgb(32 29 34 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(65 44 37 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(18 18 19 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(12 10 10 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(12 10 10 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/oceano.webp?v=3") 50% 50% / cover no-repeat, #0c0a0a;
