:is(:root:not([data-scheme="light"]), .look-preview[data-scheme="dark"])[data-wp-style="mesh"] { --wp-urbania: radial-gradient(75% 65% at 12% 8%, rgb(27 27 26 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(65% 75% at 92% 28%, rgb(32 32 29 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 72%), radial-gradient(85% 65% at 42% 102%, rgb(28 28 27 / min(.95, calc(.9 * var(--veil-k, 1)))), transparent 74%), linear-gradient(rgb(11 10 10 / min(.9, calc(.56 * var(--veil-k, 1)))), rgb(11 10 10 / min(.9, calc(.56 * var(--veil-k, 1))))), url("/assets/wallpapers/urbania.webp?v=3") 50% 50% / cover no-repeat, #0b0a0a; }
