dialog#core .mother-title { font-family: var(--read); font-size: 17px; font-weight: 650; letter-spacing: -.005em; color: var(--text); }
dialog#core .mother-sub { flex: 1; min-width: 0; font-family: var(--read); font-size: 12.5px; letter-spacing: 0; color: var(--text-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
dialog#core .mother-actions { display: inline-flex; gap: 8px; }
dialog#core .mother-close { height: 30px; padding: 0 13px; border: 0; border-radius: 9px; font-family: var(--read); font-size: 12.5px; font-weight: 550; letter-spacing: 0; text-transform: none; color: var(--text); background: var(--surface, var(--panel)); box-shadow: var(--key-rest); cursor: pointer; }
dialog#core .mother-close:hover { box-shadow: var(--key-over, var(--key-rest)); color: var(--phosphor); }
