.empty-suggest-gains { display: grid; gap: 5px; margin: 0; padding: 0; list-style: none; }
.empty-suggest-gains li { position: relative; padding-left: 14px; font-size: 12.5px; line-height: 1.45; color: var(--text-2); }
.empty-suggest-gains li::before { content: ''; position: absolute; left: 1px; top: .6em; width: 5px; height: 5px; border-radius: 50%; background: var(--phosphor); }
.empty-suggest-note { margin: 0; font-size: 11.5px; line-height: 1.45; color: var(--text-3); }
.empty-suggest-acts { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 2px; }
.empty-suggest-acts button { font: inherit; font-size: 12.5px; font-weight: 600; border-radius: 10px; padding: 6px 12px; cursor: pointer; transition: background-color var(--motion-fast) var(--ease-out), color var(--motion-fast) var(--ease-out); }
.empty-suggest-open { border: 0; color: var(--phosphor-ink, #0b0b0b); background: var(--phosphor); }
.empty-suggest-open:hover { background: color-mix(in srgb, var(--phosphor) 86%, var(--text)); }
.empty-suggest-no { border: 0; color: var(--text-2); background: transparent; }
.empty-suggest-no:hover { color: var(--text); background: color-mix(in srgb, var(--text) 7%, transparent); }

/* ---------- The welcome of MADRE 1.0 (public/tour.js, 2026-10-11) ----------
   The bonjour: the whole window, the pulse of MADRE beating, one greeting and one choice. The
   chapters: the material of What's new (.wn-sheet), chapters on the left, one view per chapter on
   the right — a short scene, a line, three sentences, its gestures and «Take me there». */
.tour-window, .tour-gesture-window, .tour-bonjour, .tour-hint, .tour-pill { --tour-acc: var(--s-acc, var(--acc, var(--phosphor))); --tour-bishop: #5c255e; }
dialog.tour-bonjour { position: fixed; inset: 0; width: 100vw; height: 100dvh; max-width: none; max-height: none; margin: 0; padding: 24px 16px; box-sizing: border-box; border: 0; color: var(--text); background: color-mix(in srgb, var(--bg) 82%, transparent); -webkit-backdrop-filter: blur(26px) saturate(1.3); backdrop-filter: blur(26px) saturate(1.3); }
dialog.tour-bonjour[open] { display: grid; place-items: center; animation: tour-veil-in calc(520ms * var(--motion-scale, 1)) ease both; }
dialog.tour-bonjour::backdrop { background: transparent; }
@keyframes tour-veil-in { from { opacity: 0; } }
.tour-bonjour-stage, .tour-bonjour-done { display: grid; justify-items: center; gap: 14px; max-width: 560px; text-align: center; font-family: var(--read); }
.tour-bonjour-stage > *, .tour-bonjour-done > * { animation: tour-rise calc(620ms * var(--motion-scale, 1)) cubic-bezier(.2, .8, .2, 1) both; }
.tour-bonjour-stage > :nth-child(2), .tour-bonjour-done > :nth-child(2) { animation-delay: calc(160ms * var(--motion-scale, 1)); }
.tour-bonjour-stage > :nth-child(3), .tour-bonjour-done > :nth-child(3) { animation-delay: calc(300ms * var(--motion-scale, 1)); }
.tour-bonjour-stage > :nth-child(n+4), .tour-bonjour-done > :nth-child(n+4) { animation-delay: calc(420ms * var(--motion-scale, 1)); }
@keyframes tour-rise { from { opacity: 0; transform: translateY(10px); } }
.tour-hello-mark { width: 150px; height: 58px; margin-bottom: 6px; color: var(--tour-acc); }
.tour-hello-mark svg { width: 150px; }
.tour-hello { margin: 0; font-size: clamp(38px, 7vw, 64px); font-weight: 700; letter-spacing: -.03em; line-height: 1.02; }
.tour-bonjour-done .tour-hello { font-size: clamp(30px, 5vw, 46px); }
.tour-hello-says { margin: 0; max-width: 46ch; font-size: 16px; line-height: 1.55; color: var(--text-2); }
.tour-hello-note { margin: 0; max-width: 52ch; font-size: 13px; line-height: 1.5; color: var(--text-3); }
.tour-hello-note code, .tour-points code { font-family: var(--mono); font-size: .92em; padding: 1px 5px; border-radius: 5px; background: color-mix(in srgb, var(--text) 8%, transparent); color: var(--text); }
.tour-hello-acts { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 10px; }
.tour-bonjour .madre-loader { min-width: 240px; }
.tour-btn { font: inherit; font-family: var(--read); font-size: 13.5px; font-weight: 600; padding: 9px 16px; border: 0; border-radius: 11px; cursor: pointer; color: var(--text); background: color-mix(in srgb, var(--text) 8%, transparent); transition: background-color var(--motion-fast, 160ms) ease, transform var(--motion-fast, 160ms) ease; }
.tour-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--text) 13%, transparent); }
.tour-btn:active:not(:disabled) { transform: scale(.97); }
.tour-btn:disabled { opacity: .5; cursor: default; }
.tour-btn.primary { color: var(--acc-ink, var(--phosphor-ink, #0b0b0b)); background: var(--tour-acc); }
.tour-btn.primary:hover:not(:disabled) { background: color-mix(in srgb, var(--tour-acc) 86%, var(--text)); }
.tour-btn.quiet { background: transparent; color: var(--text-2); }
.tour-btn.quiet:hover:not(:disabled) { color: var(--text); background: color-mix(in srgb, var(--text) 7%, transparent); }
.tour-btn.small { font-size: 12.5px; padding: 6px 12px; border-radius: 9px; }

.tour-sheet { height: min(640px, 100%); }
.tour-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 16px; align-items: start; padding: 20px 22px 12px; }
.tour-head-words { display: grid; gap: 4px; }
.tour-head h2 { margin: 0; font-size: 22px; font-weight: 650; letter-spacing: -.015em; }
.tour-close { display: grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 50%; color: var(--text-2); background: color-mix(in srgb, var(--text) 7%, transparent); cursor: pointer; }
.tour-close svg { width: var(--ico-sm); height: var(--ico-sm); }
.tour-close:hover { color: var(--text); background: color-mix(in srgb, var(--text) 12%, transparent); }
.tour-body { display: grid; grid-template-columns: 210px minmax(0, 1fr); flex: 1 1 auto; min-height: 0; border-top: 1px solid color-mix(in srgb, var(--text) 9%, transparent); }
.tour-window .tour-nav { display: grid; align-content: start; gap: 2px; margin: 0; padding: 10px 8px; list-style: none; overflow-y: auto; border-right: 1px solid color-mix(in srgb, var(--text) 9%, transparent); }
.tour-window .tour-nav li { display: block; margin: 0; padding: 0; }
.tour-nav-key { display: flex; align-items: center; gap: 10px; width: 100%; padding: 7px 10px; border: 0; border-radius: 9px; font: inherit; font-family: var(--read); font-size: 13px; text-align: left; color: var(--text-2); background: transparent; cursor: pointer; }
.tour-nav-key:hover { color: var(--text); background: color-mix(in srgb, var(--text) 6%, transparent); }
